window.SITE_COURSES=window.SITE_COURSES||{};SITE_COURSES["wahi-almanam"]={"lessons":[{"id":"wahi-sharh-001","title":"مقدمة المؤلف: لماذا كُتب هذا الشرح؟","summary":"مقدمة شرح «النحو الصغير»: غرض المؤلف من الكتاب، وطريقته في الشرح، ودعاؤه بالبركة.","section":"شرح الكتاب: المقدمة","segments":[{"body":["افتتح المؤلف الشيخ سليمان العيوني شرحه بحمد الله والصلاة والسلام على رسوله، وهذا أدب أهل العلم: لا يبدؤون كلامًا إلا بذكر الله.","ثم أخبرنا عن كتابه فقال ما معناه: هذا كتاب «النحو الصغير»، وهو شرح مختصر؛ وكان غرضي فيه أن يكون كتابًا موجزًا واضحًا يناسب المبتدئين.","لاحظ الكلمات: «شرح مختصر» أي: ليس كتابًا طويلًا يتعب القارئ. «موجز واضح» أي: قليل الكلام كثير الفائدة سهل الفهم. «يناسب المبتدئين» أي: صُنع لمن يبدأ تعلم النحو من الصفر، فلا يحتاج معه إلى علم سابق.","ثم قال إنه مع هذا الاختصار لا يلتزم به دائمًا؛ فأحيانًا يزيد إيضاحًا أو يضرب مثالًا إذا احتاج الطالب إلى ذلك؛ لأن المقصود الأكبر هو الفهم لا الاختصار وحده.","ثم أخبر أنه راجع الكتاب وعرضه على بعض المتخصصين والطلاب، فانتفعوا به. ثم ختم بدعاء الله أن يجعل فيه البركة وأن ينفع به."],"examples":["غرض الكتاب: شرح مختصر موجز واضح يناسب المبتدئين.","طريقة المؤلف: إذا احتاج الطالب زاد إيضاحًا أو ضرب مثالًا.","راجع الكتاب وعرضه على متخصصين وطلاب قبل نشره.","دعا الله أن يجعل فيه البركة وأن ينفع به.","المؤلف: أ.د. سليمان بن عبدالعزيز بن عبدالله العيوني.","البدء بالحمد والصلاة على الرسول: أدب أهل العلم في أول كتبهم."],"questions":[{"question":"غرض المؤلف من كتابه كما أخبر بنفسه:","options":["أن يكون شرحًا مختصرًا موجزًا واضحًا يناسب المبتدئين","أن يكون أطول كتب النحو","أن يكون للمتخصصين فقط","أن يجمع كل أقوال النحويين"],"answer":0,"explanation":"قال المؤلف: كان غرضي أن يكون كتابًا موجزًا واضحًا يناسب المبتدئين؛ فهو مصنوع لمن يبدأ من الصفر."},{"question":"إذا احتاج الموضع إلى بيان زائد فالمؤلف:","options":["يزيد إيضاحًا أو يضرب مثالًا ولو خرج عن الاختصار","يتركه بلا بيان","يحيل على كتب غيره فقط","يحذف المسألة"],"answer":0,"explanation":"المؤلف لا يلتزم الاختصار دائمًا؛ بل يزيد إيضاحًا أو يضرب مثالًا عند الحاجة؛ لأن المقصود فهم الطالب."},{"question":"بداية المؤلف لكتابه:","options":["حمد الله والصلاة والسلام على رسوله","ذكر اسمه ونسبه","حكاية من طفولته","قائمة المراجع"],"answer":0,"explanation":"افتتح بالحمد والصلاة والسلام على سيد المرسلين وآله وصحبه؛ وهو أدب أهل العلم في تصدير كتبهم."},{"question":"قبل نشر الكتاب فعل المؤلف:","options":["راجعه وعرضه على متخصصين وطلاب فانتفعوا به","طبعه فور كتابته","أخفاه عن الناس","حرق مسوداته"],"answer":0,"explanation":"قال: راجعته ثم عرضته على بعض المتخصصين والطلاب؛ فالمراجعة والعرض على أهل الاختصاص من تمام العمل."},{"question":"ختم المؤلف مقدمته بـ:","options":["دعاء الله أن يجعل في الكتاب البركة وأن ينفع به","الشكر للمطبعة","التنبيه على حقوق الطبع","رقم الطبعة"],"answer":0,"explanation":"قال: وأسأل الله أن يجعل فيه البركة وأن ينفع به؛ فنسب النفع إلى الله وطلبه منه."}]},{"body":["ما فائدة قراءة مقدمة الكتاب؟ المقدمة مثل المفتاح: تعرف منها لماذا كُتب الكتاب، ولمن كُتب، وكيف تدرسه.","هذا الكتاب شرح لمتن «النحو الصغير»؛ والمتن هو المتن الأصلي المختصر، والشرح هو الكلام الذي يفك عبارات المتن ويوضحها ويضرب لها الأمثلة.","وأنت قد درست قبل هذه الدروس منظومة «وحي المنام» وهي نظم لقواعد هذا الكتاب في مئة بيت؛ فالنظم يجمع القاعدة في ألفاظ قليلة، والشرح يفصّلها ويفقّهها، وكل واحد منهما يعين على الآخر.","فطريقتك في الدروس القادمة: اقرأ الفكرة، ثم تأمل الأمثلة، ثم أجب عن الأسئلة؛ فإن أخطأت فارجع إلى الفقرة التي فيها الجواب؛ فهذا طريق الثبات."],"examples":["المتن: المتن الأصلي المختصر من الكتاب.","الشرح: بيان المتن وإيضاحه وضرب الأمثلة له.","النظم: القواعد نفسها مصوغة في أبيات شعرية للحفظ.","النظم والشرح يتعاونان: هذا للحفظ وهذا للفهم.","المقدمة مفتاح الكتاب: لماذا كُتب ولمن وكيف يُدرس.","طريقة الدراسة: فكرة ثم أمثلة ثم أسئلة ثم مراجعة."],"questions":[{"question":"العلاقة بين المتن والشرح:","options":["المتن أصل مختصر والشرح بيان وإيضاح له","الشرح أصل والمتن تابع له","لا علاقة بينهما","المتن للحفظ فقط والشرح للطباعة"],"answer":0,"explanation":"المتن كلام موجز يجمع القواعد، والشرح يفك عباراته ويوضحها بالأمثلة؛ فالشرح خادم للمتن."},{"question":"منظومة «وحي المنام» التي درستها:","options":["نظم لقواعد الكتاب في مئة بيت","كتاب آخر لا علاقة له","شرح مطول","تمرينات محلولة"],"answer":0,"explanation":"وحي المنام نظم الشيخ سليمان العيوني لقواعد النحو الصغير في مئة بيت؛ ودروس الشرح الآن تفصيل لما أوجزه النظم."},{"question":"فائدة الجمع بين النظم والشرح:","options":["النظم للحفظ والجمع، والشرح للفهم والتفصيل","لا فائدة","النظم للكبار والشرح للصغار","كلاهما للحفظ فقط"],"answer":0,"explanation":"النظم يجمع القاعدة في ألفاظ قليلة تحفظ، والشرح يفصلها ويضرب الأمثلة لتفهم؛ فتمسك بالحفظ والفهم معًا."},{"question":"أفضل طريقة لدراسة هذه الدروس:","options":["فكرة ثم أمثلة ثم أسئلة ثم مراجعة موضع الخطأ","الحفظ دون فهم","قراءة الأسئلة فقط","تخطي الأمثلة"],"answer":0,"explanation":"الفكرة تبني الفهم، والمثال يثبتها، والسؤال يكشف موضع الضعف؛ فمن أخطأ رجع إلى الفقرة وثبت."},{"question":"لمن صُنع هذا الشرح بالدرجة الأولى؟","options":["للمبتدئين في علم النحو","للمحققين فقط","للمعلمين دون الطلاب","لحفاظ المتون فقط"],"answer":0,"explanation":"قال المؤلف: يناسب المبتدئين؛ فأسلوبه مبسط وأمثلته قريبة، ولا يحتاج الدارس معه إلى علم سابق."}]}]},{"id":"wahi-sharh-002","title":"خريطة علم النحو: أحكام الكلمة وأحكام الكلام","summary":"النحو يدرس أحكام الكلمة وأحكام الكلام؛ وهذه خريطة الكتاب كله في صفحتين.","section":"شرح الكتاب: التمهيد","segments":[{"body":["قال المؤلف: اعلم -وفقني الله وإياك- أن النحو يدرس: أحكامَ الكلمة وأحكامَ الكلام. فالنحو مكوَّن من جزأين كبيرين.","ما الكلمة؟ اللفظة الواحدة مثل: محمد، ويكتب، وعلى. وما الكلام؟ اللفظ المركب من كلمتين أو أكثر يفيد معنى تامًّا، مثل: محمدٌ كريم، وصلى أنسٌ.","فالجزء الأول يدرس الكلمة وحدها: أنواع الكلمة (اسم وفعل وحرف)، وتقسيم الفعل (ماض ومضارع وأمر)، وتقسيم الاسم (نكرة ومعرفة).","والجزء الثاني يدرس الكلام أي: الجمل؛ وقواعده كثيرة رتبها المؤلف في أبواب، كل باب يدرس صورة من صور الجمل أو نوعًا من أنواع الإعراب.","فهذه الصفحة خريطة الكتاب: احفظها تجد كل باب جديد تعرف مكانه منها."],"examples":["الكلمة: اللفظة الواحدة مثل: محمد، ويكتب، وعلى.","الكلام: لفظ مركب من كلمتين فأكثر يفيد معنى تامًّا.","الجزء الأول: أحكام الكلمة: أنواعها وتقسيماتها.","الجزء الثاني: أحكام الكلام: الجمل وأبوابها.","تقسيم الفعل: ماض ومضارع وأمر.","تقسيم الاسم: نكرة ومعرفة."],"questions":[{"question":"علم النحو يدرس:","options":["أحكام الكلمة وأحكام الكلام","أحكام التجويد","البلاغة والعروض","تاريخ اللغة"],"answer":0,"explanation":"قال المؤلف: النحو يدرس أحكام الكلمة وأحكام الكلام؛ فهو مكون من جزأين كبيرين."},{"question":"الكلام هو:","options":["لفظ مركب من كلمتين أو أكثر يفيد معنى تامًّا","اللفظة الواحدة","الحرف المفرد","الصوت فقط"],"answer":0,"explanation":"الكلام مركب من كلمتين فأكثر ويفيد معنى تامًّا نحو: محمد كريم؛ أما الكلمة فواحدة مفردة."},{"question":"الجزء الأول من النحو يدرس:","options":["أقسام الكلمة: أنواعها، وتقسيم الفعل، وتقسيم الاسم","الجمل فقط","علامات الترقيم","الإملاء"],"answer":0,"explanation":"يدرس في الجزء الأول: أنواع الكلمة (اسم وفعل وحرف)، وتقسيم الفعل (ماض ومضارع وأمر)، وتقسيم الاسم (نكرة ومعرفة)."},{"question":"الجزء الثاني من النحو يدرس:","options":["أحكام الكلام: الجمل وأبوابها","المفردات","الأصوات","الخط العربي"],"answer":0,"explanation":"الجزء الثاني: أحكام الكلام، وهي كثيرة، رتبها المؤلف في أبواب: الجملة الفعلية والاسمية، والمرفوعات والمنصوبات والمجرورات والتوابع، وإعراب المضارع."},{"question":"من هذه الخريطة تعرف أن باب «الفاعل» ينتمي إلى:","options":["أحكام الكلام: الجملة الفعلية","أحكام الكلمة","الحروف","المقدمات"],"answer":0,"explanation":"الجملة الفعلية لها صورتان: فعل مبني للمعلوم وفاعل، وفعل مبني للمجهول ونائب فاعل؛ فباب الفاعل من أحكام الكلام."}]},{"body":["خريطة الجمل كما رسمها المؤلف: الجملة الفعلية لها صورتان: فعل مبني للمعلوم وفاعل، نحو: صلى أنسٌ، وتدرس في باب الفاعل؛ وفعل مبني للمجهول ونائب فاعل، نحو: قُرئ الكتابُ، وتدرس في باب نائب الفاعل.","والجملة الاسمية لها أربع صور، أولها: كون ركنيها مرفوعين، نحو: محمدٌ كريمٌ، وتدرس في باب المبتدأ والخبر؛ والصور الثلاث الباقية تدرس في أبواب كان وإن وظن وأخواتها.","ثم تأتي أبواب المنصوبات: المفعولات الخمسة، والحال، والتمييز، والمستثنى، والمنادى؛ ثم المجرورات وهما: المسبوق بحرف جر، والمضاف إليه؛ ثم التوابع: النعت والمعطوف والتوكيد والبدل.","وتُختم الخريطة بإعراب الفعل المضارع: رفعًا ونصبًا وجزمًا؛ يُجزم إذا سُبق بجازم وجوازمه خمسة، ويُنصب إذا سبق بناصب ونواصبه أربعة (الأصلية)، ويرفع إذا لم يسبق بناصب ولا جازم."],"examples":["صلى أنسٌ: جملة فعلية: فعل مبني للمعلوم + فاعل.","قُرئ الكتابُ: جملة فعلية: فعل مبني للمجهول + نائب فاعل.","محمدٌ كريمٌ: جملة اسمية ركناها مرفوعان: مبتدأ وخبر.","المنصوبات: المفعولات الخمسة والحال والتمييز والمستثنى والمنادى.","المجرورات: المسبوق بحرف جر والمضاف إليه.","التوابع: النعت والمعطوف والتوكيد والبدل."],"questions":[{"question":"الجملة الفعلية صورتاها:","options":["مبني للمعلوم وفاعل، ومبني للمجهول ونائب فاعل","مبتدأ وخبر","مفردة ومركبة","مثبتة ومنفية فقط"],"answer":0,"explanation":"صورتان: فعل مبني للمعلوم مع فاعل نحو: صلى أنس؛ وفعل مبني للمجهول مع نائب فاعل نحو: قرئ الكتاب."},{"question":"«محمدٌ كريمٌ» تدرس في باب:","options":["المبتدأ والخبر","الفاعل","الحال","التوكيد"],"answer":0,"explanation":"هي جملة اسمية ركناها مرفوعان: محمد مبتدأ، وكريم خبر؛ وهي الصورة الأولى من صور الجملة الاسمية."},{"question":"عدد صور الجملة الاسمية في خريطة الكتاب:","options":["أربع صور","صورتان","خمس صور","صورة واحدة"],"answer":0,"explanation":"أربع صور: الأولى المبتدأ والخبر، والباقي في أبواب كان وأخواتها وإن وأخواتها وظن وأخواتها."},{"question":"التوابع التي ذكرها المؤلف في خريطته:","options":["النعت والمعطوف والتوكيد والبدل","الحال والتمييز","المبتدأ والخبر","الفاعل ونائبه"],"answer":0,"explanation":"التوابع أربعة: النعت والمعطوف والتوكيد والبدل؛ وسيأتي لكل منها باب."},{"question":"الفعل المضارع يرفع إذا:","options":["لم يسبق بناصب ولا جازم","سبق بحرف جر","كان ماضيًا","وقع بعد إن"],"answer":0,"explanation":"يُجزم إذا سبق بجازم، ويُنصب إذا سبق بناصب، ويُرفع إذا لم يسبق بناصب ولا جازم؛ فالرفع أصله."}]}]},{"id":"wahi-sharh-003","title":"باب أنواع الكلمة: الاسم وعلاماته","summary":"الكلمة ثلاثة أنواع: اسم وفعل وحرف؛ والاسم كل كلمة تقبل التنوين أو (أل) أو النداء أو حرف جر.","section":"شرح الكتاب: أنواع الكلمة","segments":[{"body":["قال المؤلف: اعلم -رحمني الله وإياك- أن الكلمة ثلاثة أنواع: اسم، وفعل، وحرف. فكل كلمة في لغة العرب لا تخرج عن هذه الثلاثة.","كيف تعرف الاسم؟ الاسم: كل كلمة تقبل التنوين، أو تقبل (أل)، أو تقبل النداء، أو يدخل عليها حرف جر.","التنوين: ضمة أو فتحة أو كسرة زائدة في آخر الاسم تنطق نونًا ساكنة: مسجدٌ، مسجدًا، مسجدٍ. و(أل): أداة التعريف: المسجد. والنداء: أن تنادي به: يا محمدُ. وحرف الجر: مثل في ومن وإلى: في المسجدِ.","فإذا رأيت كلمة تقبل واحدة من هذه الأربع فهي اسم. نحو: الله، ومحمد، ومسجد، وساجد، وسجود؛ وكاف الخطاب في كتابُك، وهذا، والذي، وأنا، وهو.","تنبيه من المؤلف: ليست كل الأسماء سواء في العلامات؛ فبعض الأسماء يقبل كل علامات الاسم مثل: ساجد، وبعضها يقبل بعضها دون بعض مثل: كاف الخطاب، وهذا؛ فلا يقال: كافٌ بالتنوين، ولا: يا هذا في النداء الصحيح."],"examples":["مسجدٌ: اسم؛ يقبل التنوين: مسجدٌ مسجدًا مسجدٍ.","المسجد: اسم؛ قبل (أل) فصار معرفة.","يا محمدُ: اسم؛ قبل النداء.","في المسجدِ: اسم؛ دخل عليه حرف جر.","ساجدٌ: اسم يقبل كل العلامات الأربع.","كتابُك: كاف الخطاب اسم يقبل بعض العلامات دون بعض."],"questions":[{"question":"أنواع الكلمة ثلاثة:","options":["اسم وفعل وحرف","ماض ومضارع وأمر","نكرة ومعرفة وضمير","مبتدأ وخبر وفاعل"],"answer":0,"explanation":"قال المؤلف: الكلمة ثلاثة أنواع: اسم وفعل وحرف؛ ولا تخرج كلمة عربية عنها."},{"question":"الاسم كل كلمة تقبل:","options":["التنوين أو (أل) أو النداء أو حرف الجر","قد والسين","لم ولما","النصب فقط"],"answer":0,"explanation":"علامات الاسم الأربع: التنوين، و(أل)، والنداء، ودخول حرف الجر؛ يكفي قبول واحدة منها."},{"question":"التنوين هو:","options":["نون ساكنة زائدة تلحق آخر الاسم لفظًا لا كتابة ولا وقفًا","نون أصلية من بناء الكلمة","ضمة آخر الفعل","تشديد النون"],"answer":0,"explanation":"التنوين نون ساكنة زائدة: مسجدٌ، ومسجدًا، ومسجدٍ؛ يثبت لفظًا في الوصل لا في الوقف."},{"question":"في «يا محمدُ» العلامة الدالة على أن «محمد» اسم:","options":["قبول النداء","قبول (لم)","قبول (قد)","الجزم"],"answer":0,"explanation":"ناديناه بـ(يا) فقبل النداء؛ والنداء من علامات الاسم؛ فمحمد اسم."},{"question":"لماذا قال المؤلف إن بعض الأسماء يقبل بعض العلامات دون بعض؟","options":["لأن مثل كاف الخطاب وهذا لا يقبلان كل العلامات الأربع","لأن العلامات أخطأت","لأن التنوين أقوى من أل","لأن النداء ألغي"],"answer":0,"explanation":"مثل: ساجد يقبل الأربع كلها، أما كاف الخطاب وهذا فلا يُنوَّنان ولا يُدخَل عليهما حرف جر؛ فالقبول التام ليس شرطًا في تسمية الكلمة اسمًا."}]},{"body":["درّب نفسك: خذ كلمة وجرّب عليها العلامات الأربع. كلمة: «قلم»: نقول قلمٌ بالتنوين: اسم. والقلمُ: قبل (أل): اسم. يا قلمُ في المخاطبة المعنوية: قبل النداء. بالقلمِ: قبل حرف الجر. فهو اسم من كل وجه.","كلمة: «كتب»: هل تقول كتبٌ بالتنوين؟ لا. هل تقول الكتبُ؟ لا. يا كتب؟ لا. بكتبٍ؟ لا. فليس اسمًا؛ إنه فعل، وسيأتي بابه.","كلمة: «من» حرف الجر: لا تنوين ولا أل ولا نداء ولا جر يدخل عليه؛ فليس اسمًا ولا فعلًا؛ فهو حرف، وسيأتي بابه.","فائدة: علامات الاسم باب للتمييز بينه وبين الفعل والحرف، لكن لا يشترط قبولها كلها؛ بل يكفي قبول واحدة منها ليثبت الاسم، كما قدم المؤلف."],"examples":["قلمٌ: قبل التنوين فهو اسم.","القلمُ: قبل (أل) فهو اسم.","بالقلمِ: قبل حرف الجر فهو اسم.","كتبَ: لا يقبل شيئًا من علامات الاسم فهو فعل.","من: لا تقبل علامات الاسم ولا الفعل فهي حرف.","يكفي قبول علامة واحدة ليثبت أن الكلمة اسم."],"questions":[{"question":"كلمة «قلمٌ» اسم لأنها:","options":["قبلت التنوين","قبلت (قد)","قبلت (لم)","جاءت فعلًا"],"answer":0,"explanation":"قلمٌ بالتنوين صحيحة؛ والتنوين علامة من علامات الاسم؛ فهو اسم."},{"question":"كلمة «كتبَ» لا تكون اسمًا لأنها:","options":["لا تقبل التنوين ولا (أل) ولا النداء ولا حرف الجر","لأنها قصيرة","لأنها ثلاثية","لأنها ماضية"],"answer":0,"explanation":"جرّب العلامات الأربع: لا تقبل واحدة منها؛ فليست اسمًا؛ وستعرفها فعلًا بعلامات الفعل الآتية."},{"question":"«الكتابُ» دلت على أن «كتاب» اسم بعلامة:","options":["قبول (أل)","الجزم","التشديد","الهمزة"],"answer":0,"explanation":"دخلت عليه (أل) فصار الكتاب؛ وقبول (أل) علامة من علامات الاسم."},{"question":"«بمسجدٍ» دلت على أن «مسجد» اسم بعلامة:","options":["دخول حرف الجر عليه","النصب","الرفع","التشديد"],"answer":0,"explanation":"الباء حرف جر دخل على مسجد؛ ودخول حرف الجر علامة من علامات الاسم."},{"question":"هل يشترط أن يقبل الاسم علاماته الأربع كلها؟","options":["لا؛ يكفي قبول واحدة منها","نعم؛ الأربع لازمة","ثلاث فقط","علامتان فقط"],"answer":0,"explanation":"بعض الأسماء يقبل بعض العلامات دون بعض ككاف الخطاب وهذا؛ فالقبول الكامل ليس شرطًا."}]}]},{"id":"wahi-sharh-004","title":"الفعل وأقسامه الثلاثة وعلاماته","summary":"الفعل ثلاثة أقسام: ماض ومضارع وأمر؛ وله علامات: قد والسين وسوف ولم ولما ولا الناهية وتاء التأنيث الساكنة وياء المخاطبة.","section":"شرح الكتاب: أنواع الكلمة","segments":[{"body":["بعد الاسم يأتي النوع الثاني: الفعل. قال المؤلف: والفعل ثلاثة أقسام: ماض، ومضارع، وأمر.","الماضي: ما دل على حدث وقع وانقضى في الزمن الماضي: سجدَ، ودحرجَ، وانطلقَ، واستخرجَ.","والمضارع: ما دل على حدث يقع الآن أو يتجدد أو سيقع: يذهبُ، ويكتبُ، ويتعلمُ. سمي مضارعًا لأنه يشبه الاسم في قبول التغير.","والأمر: ما دل على طلب الحدث: اسجدْ، واكتبْ، وتعالَ. وتقول للمخاطبة: اسجدي، وصلِّي، وتعالي، وكوني.","فالزمن هو الفاصل بين الماضي والمضارع، والطلب هو علامة الأمر."],"examples":["سجدَ: فعل ماض؛ حدث وقع وانقضى.","استخرجَ: فعل ماضٍ رباعي.","يذهبُ: فعل مضارع؛ حدث حاضر أو متجدد.","يكتبُ: فعل مضارع.","اسجدْ: فعل أمر؛ طلب السجود.","اسجدي: فعل أمر للمخاطبة بياء المخاطبة."],"questions":[{"question":"أقسام الفعل:","options":["ماض ومضارع وأمر","ثلاثي ورباعي","صحيح ومعتل","متعد ولازم فقط"],"answer":0,"explanation":"الفعل ثلاثة أقسام: ماض ومضارع وأمر؛ كما ذكر المؤلف في باب أنواع الكلمة."},{"question":"الفعل الماضي يدل على:","options":["حدث وقع وانقضى في الزمن الماضي","حدث سيقع","طلب حدث","حدث دائم لا ينقطع"],"answer":0,"explanation":"الماضي: ما دل على حدث في الزمن الماضي نحو: سجد، وانطلق، واستخرج."},{"question":"«يذهبُ» فعل:","options":["مضارع","ماض","أمر","اسم"],"answer":0,"explanation":"يذهب دل على حدث حاضر أو متجدد؛ فهو مضارع؛ وسُمي مضارعًا لمشابهته الاسم في قبول التغير."},{"question":"«اسجدي» فعل:","options":["أمر للمخاطبة","ماض","مضارع","اسم فاعل"],"answer":0,"explanation":"اسجدي طلب السجود من المؤنثة المخاطبة بياء المخاطبة؛ فهو فعل أمر."},{"question":"الفارق بين المضارع والأمر:","options":["المضارع خبر عن حدث حاضر أو آت، والأمر طلب الحدث","لا فرق","الأمر للماضي","المضارع للطلب"],"answer":0,"explanation":"يذهب: خبر عن الذهاب؛ واذهب: طلب الذهاب؛ فالمضارع إخبار والأمر طلب."}]},{"body":["كيف تعرف الفعل؟ له علامات يذكرها المؤلف: قد، والسين، وسوف، ولم، ولمّا، ولا الناهية، وتاء التأنيث الساكنة، وياء المخاطبة.","قد: قد سجدَ. السين وسوف: سيذهبُ، وسوف يذهبُ. لم ولمّا ولا الناهية: لم يذهبْ، ولمّا يذهبْ، ولا تذهبْ.","تاء التأنيث الساكنة: سجدَتْ، وصلَّتْ؛ فهي لا تدخل إلا على الأفعال. وياء المخاطبة: اسجدي، وكوني، وتعالي.","فإذا قبلت الكلمة واحدة من هذه العلامات فهي فعل. مثل: قد كتبَ: قبل قد فهو فعل؛ واسجدي: قبلت ياء المخاطبة فهي فعل أمر.","والحروف لا تقبل شيئًا من علامات الاسم ولا من علامات الفعل؛ وبذلك يتميز كل نوع من الأنواع الثلاثة بعلاماته."],"examples":["قد سجدَ: قبل (قد) فهو فعل.","سيذهبُ: قبل السين فهو فعل مضارع.","سوف يتعلمُ: قبل (سوف) فهو فعل مضارع.","لم يكتبْ: قبل (لم) فهو فعل.","سجدَتْ: قبلت تاء التأنيث الساكنة فهو فعل.","تعالي: قبلت ياء المخاطبة فهي فعل أمر."],"questions":[{"question":"من علامات الفعل:","options":["قد والسين وسوف ولم ولما ولا الناهية وتاء التأنيث الساكنة وياء المخاطبة","أل والتنوين","حروف الجر","يا النداء"],"answer":0,"explanation":"علامات الفعل كما في الشرح: قد، والسين، وسوف، ولم، ولمّا، ولا الناهية، وتاء التأنيث الساكنة، وياء المخاطبة."},{"question":"تاء التأنيث الساكنة تدخل على:","options":["الأفعال فقط","الأسماء فقط","الحروف فقط","كل الكلمات"],"answer":0,"explanation":"تاء التأنيث الساكنة من علامات الفعل: سجدت وصلت؛ فمن قبلها فهو فعل."},{"question":"«سوف يتعلم» العلامة الدالة على الفعل:","options":["سوف","أل","التنوين","يا"],"answer":0,"explanation":"سوف حرف استقبال لا يدخل إلا على المضارع؛ فقبول الكلمة له علامة على أنها فعل."},{"question":"ياء المخاطبة في «اسجدي» تدل على:","options":["فعل أمر موجه للمؤنثة المخاطبة","اسم مؤنث","حرف جر","مضارع للغائب"],"answer":0,"explanation":"اسجدي: فعل أمر اتصلت به ياء المخاطبة؛ مثل: صلي، وتعالي، وكوني."},{"question":"الحروف لا تقبل علامات الاسم ولا الفعل؛ فهذا يفيد:","options":["تمييز الحرف من النوعين الآخرين","أن الحرف ليس كلمة","أن الحرف اسم","أن الحرف فعل"],"answer":0,"explanation":"كل نوع له علاماته: الاسم علاماته الأربع، والفعل علاماته الثماني، والحرف لا يقبل شيئًا منها؛ فتميزت الأنواع الثلاثة."}]}]},{"id":"wahi-sharh-005","title":"الحرف وعلاماته","summary":"الحرف كل كلمة لا تقبل علامات الاسم ولا علامات الفعل؛ مثل: هل، ولم، ومن، ولام الأمر، وحروف الجر والعطف والنداء والجواب.","section":"شرح الكتاب: أنواع الكلمة","segments":[{"body":["النوع الثالث من الكلمة: الحرف. قال المؤلف: والحرف: كل كلمة لا تقبل ما سبق؛ أي: لا تقبل علامات الاسم ولا علامات الفعل.","أمثلته: هل، ولم، ومن، ولام الأمر، وجميع حروف الجر، والعطف، والنداء، والجواب، وغيرها.","جرّب على حرف: «من»: هل يقبل التنوين: منٌّ؟ لا. ولا (أل): المن؟ لا. ولا النداء: يا من؟ لا. ولا حرف جر يدخل عليه: بمن؟ لا. ولا قد ولا السين ولا لم. إذن هو حرف.","ومعنى الحرف في نفسه ضعيف حتى يقرن بغيره: «من» وحدها لا تكمل معنى؛ لكن «من المسجد» تم المعنى؛ فالحرف صُنع ليربط بين الكلم ويوصل المعاني بعضها ببعض.","فالحرف لا يقبل: التنوين، ولا (أل)، ولا النداء، ولا دخول حروف الجر، ولا تاء التأنيث الساكنة، ولا (لم)، ولا ياء المخاطبة؛ كما عددها المؤلف."],"examples":["هل: حرف استفهام؛ لا يقبل شيئًا من العلامات.","من: حرف جر؛ يربط الاسم بما قبله: من المسجد.","لام الأمر: حرف يدخل على المضارع.","الواو: حرف عطف.","يا: حرف نداء.","نعم وبلى: حرفا جواب."],"questions":[{"question":"الحرف هو:","options":["كل كلمة لا تقبل علامات الاسم ولا علامات الفعل","كل كلمة تدل على زمن","كل كلمة تقبل التنوين","كل كلمة تدل على حدث"],"answer":0,"explanation":"قال المؤلف: الحرف كل كلمة لا تقبل ما سبق؛ فلا تقبل علامات الاسم ولا علامات الفعل؛ مثل: هل ومن ولام الأمر."},{"question":"من أمثلة الحروف التي ذكرها المؤلف:","options":["هل، ولم، ومن، ولام الأمر، وحروف الجر والعطف والنداء والجواب","محمد ومسجد","سجد ويذهب","الذي والتي"],"answer":0,"explanation":"عدد المؤلف: هل، ولم، ومن، ولام الأمر، وجميع حروف الجر والعطف والنداء والجواب وغيرها."},{"question":"لماذا لا يتم معنى الحرف وحده غالبًا؟","options":["لأنه صُنع للربط بين الكلم وإيصال المعاني","لأنه ليس كلمة","لأنه محذوف الأصل","لأنه لا يُنطق"],"answer":0,"explanation":"من وحدها لا تتميم معنى؛ لكن من المسجد تم المعنى؛ فوظيفة الحرف ربط الكلم وإيصال المعاني بعضها ببعض."},{"question":"حرف الجر «في» لا يكون اسمًا لأنه:","options":["لا يقبل التنوين ولا (أل) ولا النداء ولا يدخل عليه حرف جر","لأنه قصير","لأنه حرفان","لأنه يدخل على الأسماء"],"answer":0,"explanation":"في لا تقبل شيئًا من علامات الاسم الأربع ولا من علامات الفعل؛ فهو حرف جر."},{"question":"«يا» في «يا محمدُ» نوعها:","options":["حرف نداء","اسم","فعل أمر","ضمير"],"answer":0,"explanation":"يا لا تقبل علامات الاسم ولا الفعل؛ فهي حرف من حروف النداء، ومحمد بعدها اسم منادى."}]},{"body":["تمرين تطبيقي: ميز الكلمات التالية: كتبَ، وعلى، ومدرسةٌ. كتبَ: قبلت قد: قد كتبَ: فعل. على: لا تقبل شيئًا: حرف. مدرسةٌ: قبلت التنوين: اسم.","وللحروف أبواب ستمر بك: حروف الجر، وحروف العطف، وحروف النداء، وحروف الاستفهام، وحروف الجواب، وحروف النصب والجزم للمضارع؛ فالحرف وإن صغر فأبوابه كثيرة وعمله عظيم.","تنبيه: بعض الكلمات تحتاج إلى جملة ليظهر نوعها: «لم» قبل الفعل: لم يذهبْ: حرف. وقد يأتي اللفظ الواحد اسمًا في موضع وحرفًا في آخر نحو بعض الظروف، فينظر إلى استعماله.","وهكذا تمت الأنواع الثلاثة: الاسم له علاماته الأربع، والفعل له علاماته الثماني، والحرف لا علامة له، ومعرفة النوع أول خطوة في الإعراب؛ لأن إعراب الاسم غير إعراب الفعل، والحرف لا يعرب غالبًا بل يبنى."],"examples":["كتبَ: فعل؛ قبل قد: قد كتبَ.","على: حرف؛ لا يقبل علامة منها.","مدرسةٌ: اسم؛ قبلت التنوين.","حروف الجر: من، وإلى، وعن، وعلى، وفي، والباء، والكاف، واللام.","حروف العطف: الواو، والفاء، وثم، وأو، وبل، ولكن.","معرفة نوع الكلمة أول خطوة في الإعراب."],"questions":[{"question":"أول خطوة في إعراب أي كلمة:","options":["معرفة نوعها: اسم أو فعل أو حرف","عد حروفها","معرفة وزنها","معرفة معناها فقط"],"answer":0,"explanation":"لأن إعراب الاسم غير إعراب الفعل، والحرف يبنى غالبًا؛ فالتمييز بين الأنواع الثلاثة باب الإعراب الأول."},{"question":"«لم» في «لم يكتبْ» نوعها:","options":["حرف جزم ونفي","اسم","فعل ماض","ضمير"],"answer":0,"explanation":"لم لا تقبل علامات الاسم ولا شيئًا يخصها؛ وهي حرف نفي وجزم يدخل على المضارع."},{"question":"حروف العطف منها:","options":["الواو والفاء وثم وأو","من وإلى وعن","هل وهمزة","قد وسوف"],"answer":0,"explanation":"الواو والفاء وثم وأو وبل ولكن من حروف العطف؛ تعطف الكلمات والجمل بعضها على بعض."},{"question":"حروف الجر التي ذكرها المؤلف مثل:","options":["من، وجميع حروف الجر","هل، ولم","قد، وسوف","يا، وأيا"],"answer":0,"explanation":"ذكر المؤلف في أمثلة الحروف: من وجميع حروف الجر والعطف والنداء والجواب."},{"question":"الفرق الأساس بين الحرف والاسم:","options":["الاسم يقبل علامة من علاماته، والحرف لا يقبل شيئًا منها","الاسم أطول من الحرف","الحرف ينتهي بسكون دائمًا","لا فرق"],"answer":0,"explanation":"الاسم يقبل التنوين أو أل أو النداء أو حرف جر؛ والحرف يمتنع عنها جميعًا؛ وهذا هو الميزان."}]}]},{"id":"wahi-sharh-006","title":"باب المعرفة والنكرة","summary":"الاسم ينقسم إلى نكرة ومعرفة؛ النكرة كل اسم يقبل (أل)، والمعرفة ما لا يقبلها، والتنكير والتعريف خاصان بالأسماء.","section":"شرح الكتاب: المعرفة والنكرة","segments":[{"body":["قال المؤلف في باب المعرفة والنكرة: الاسم يُقسم إلى نكرة ومعرفة. فالتنكير والتعريف خاصان بالأسماء؛ فلا يوصف بهما الأفعال ولا الحروف.","النكرة: كل اسم يقبل (أل)؛ نحو: الله?? لا — بل نحو: رجل، ومسجد، وساجد، وسجود؛ تقول: الرجل، والمسجد، والساجد، والسجود؛ فقبولها (أل) دليل تنكيرها.","فمعنى نكرة: اسم يدل على شيء غير معين: رجل = أي رجل كان؛ فإذا أدخلت (أل) صار معينًا: الرجل = رجل بعينه تعرفه.","والمعرفة: اسم لا يقبل (أل)؛ لأنه معين بنفسه لا يحتاج إلى أداة تعريف: محمد، وهذا، وهو، والذي، وأنا.","فالميزان العملي سهل: أدخل (أل) على الاسم؛ فإن صح الدخول فهو نكرة، وإن لم يصح فهو معرفة."],"examples":["رجل: نكرة؛ تقبل أل: الرجل.","مسجد: نكرة؛ تقبل أل: المسجد.","سجود: نكرة؛ تقبل أل: السجود.","محمد: معرفة؛ لا يقبل أل.","هذا: معرفة؛ لا يقبل أل.","هو: معرفة؛ ضمير لا يقبل أل."],"questions":[{"question":"الاسم يُقسم إلى:","options":["نكرة ومعرفة","مذكر ومؤنث","مفرد وجمع","صحيح ومعتل"],"answer":0,"explanation":"قال المؤلف: الاسم يُقسم إلى نكرة ومعرفة؛ والتنكير والتعريف خاصان بالأسماء دون الأفعال والحروف."},{"question":"النكرة عند المؤلف:","options":["كل اسم يقبل (أل)","كل اسم لا يقبل (أل)","كل ضمير","كل علم"],"answer":0,"explanation":"النكرة: كل اسم يقبل (أل) نحو: رجل ومسجد وساجد وسجود؛ تقول: الرجل والمسجد."},{"question":"المعرفة عند المؤلف:","options":["اسم لا يقبل (أل)","اسم يقبل التنوين","اسم يقبل النداء فقط","اسم يقبل (قد)"],"answer":0,"explanation":"المعرفة اسم معين بنفسه لا يحتاج إلى أل: محمد، وهذا، وهو، والذي؛ فلا يصح دخول أل عليه."},{"question":"«رجلٌ» نكرة لأنها:","options":["تقبل (أل) فتقول: الرجل","علم لشخص","ضمير","اسم إشارة"],"answer":0,"explanation":"رجل يدل على أي رجل غير معين، ويقبل أل: الرجل؛ فهو نكرة."},{"question":"لا توصف الأفعال والحروف بالنكرة والمعرفة؛ لأن:","options":["التنكير والتعريف خاصان بالأسماء","الأفعال أطول","الحروف أسماء","الأفعال لا تعرب"],"answer":0,"explanation":"نص المؤلف: فالتنكير والتعريف خاصان بالأسماء؛ فلا يوصف بهما الأفعال ولا الحروف."}]},{"body":["تدريب: ميز النكرة من المعرفة: «كتاب»: تقبل أل: الكتاب: نكرة. «أنا»: لا تقبل: معرفة. «مكة»: لا تقول المكة: معرفة. «معلم»: تقبل: المعلم: نكرة.","النكرة في اللغة اسم لغير المعين، والمعرفة اسم للمعين؛ فالنكرة عامة والمعرفة خاصة؛ ولهذا كانت المعرفة أقوى دلالة.","فائدة الباب: كثير من الأحكام تتفرع على معرفة كون الاسم نكرة أو معرفة: فالمبتدأ يكون معرفة غالبًا، وأحكام النداء والنعت تختلف باختلافهما؛ فأتقن هذا الباب.","والمعرفة أنواع ستة تأتي في الدرس القادم بالتفصيل: الضمير، والعلم، واسم الإشارة، والاسم الموصول، والمعرف بأل، والمضاف إلى معرفة."],"examples":["كتاب: نكرة؛ الكتاب.","أنا: معرفة؛ ضمير متكلم.","مكة: معرفة؛ علم بلدة.","معلم: نكرة؛ المعلم.","النكرة: اسم لغير المعين؛ والمعرفة: اسم للمعين.","المعرفة أقوى دلالة من النكرة لأنها خاصة."],"questions":[{"question":"«مكة» معرفة لأنها:","options":["علم لبلدة معينة لا يقبل (أل)","تقبل التنوين","نكرة عامة","اسم موصول"],"answer":0,"explanation":"مكة اسم خاص بمسماه لا يقبل أل؛ فهو علم، والعلم من أنواع المعرفة."},{"question":"الفرق بين النكرة والمعرفة في الدلالة:","options":["النكرة لغير المعين والمعرفة للمعين","النكرة للجمع","المعرفة للمفرد","لا فرق"],"answer":0,"explanation":"رجل: أي رجل (نكرة)، ومحمد: رجل معين (معرفة)؛ فالنكرة عامة والمعرفة خاصة."},{"question":"من فوائد تمييز النكرة من المعرفة:","options":["تتفرع عليه أحكام كالمبتدأ والنداء والنعت","لا فائدة له","فائدته في الرسم فقط","للشعر فقط"],"answer":0,"explanation":"أحكام كثيرة تبنى على هذا التقسيم؛ فالمبتدأ معرفة غالبًا، والنعت يتبع منعوته تنكيرًا وتعريفًا."},{"question":"«أنا» معرفة لأنها:","options":["ضمير متكلم معين لا يقبل (أل)","تقبل أل","نكرة","علم بلدة"],"answer":0,"explanation":"الضمائر كلها معرفة لأنها معينة؛ وأنا ضمير للمتكلم لا يقبل أل."},{"question":"أنواع المعرفة عند المؤلف عددها:","options":["ستة","ثلاثة","أربعة","ثمانية"],"answer":0,"explanation":"ستة أنواع: الضمير، والعلم، واسم الإشارة، والاسم الموصول، والمعرف بأل، والمضاف إلى معرفة؛ وتفصيلها في الدرس القادم."}]}]},{"id":"wahi-sharh-007","title":"أنواع المعرفة الستة","summary":"المعرفة ستة أنواع: الضمير، والعلم، واسم الإشارة، والاسم الموصول، والمعرف بـ(أل)، والمضاف إلى معرفة.","section":"شرح الكتاب: المعرفة والنكرة","segments":[{"body":["النوع الأول: الضمير، وهو ضربان: ضمائر منفصلة وهي ستة عشر ضميرًا: للرفع: أنا، وأنتَ، وهو، وفروعها في التثنية والجمع والتأنيث؛ وللنصب: إيايَ، وإياكَ، وإياه، وفروعها.","وضمائر متصلة وهي ثمانية: خمسة للرفع سماها المؤلف (تَوَانِي): تاء المتكلم، وألف الاثنين، وواو الجماعة، وياء المخاطبة، ونون النسوة؛ وثلاثة للنصب والجر: ياء المتكلم، وكاف المخاطب، وهاء الغائب؛ وواحد للرفع والنصب والجر: نا المتكلمين.","النوع الثاني: العلم، وهو الاسم الخاص بمسماه؛ ومنه: أسماء الله: الله، والرحمن، والرحيم، والعزيز؛ وأسماء الملائكة: جبريل، وإسرافيل، ومالك؛ وأسماء الناس: زيد، ومحمد، وهند، وعائشة.","ومن العلم أيضًا: أسماء البلدان والدول والمدن: مكة، والرياض، ومصر، والعراق، وفرنسا؛ وأسماء الكواكب: زُحَل، وعُطَارِد؛ وأسماء الشهور: المحرم، وصفر، وشوال؛ وجميع الأسماء الخاصة بمسمياتها: أُحُد، والفُضْوَاء، وذو الفِقَار.","فالعلم يدل على معين بعينه وضع لهذا الاسم؛ فلا يحتاج إلى أل ولا غيرها ليعرف."],"examples":["أنا وأنتَ وهو: ضمائر منفصلة للرفع.","إياي وإياك وإياه: ضمائر منفصلة للنصب.","تاء المتكلم وألف الاثنين وواو الجماعة وياء المخاطبة ونون النسوة: (تواني) ضمائر متصلة للرفع.","الله والرحمن والرحيم والعزيز: من أسمائه تعالى وهي أعلام.","جبريل وإسرافيل ومالك: أسماء الملائكة وهي أعلام.","مكة والرياض ومصر والعراق وفرنسا: أعلام بلدان ودول ومدن."],"questions":[{"question":"الضمائر المنفصلة عددها:","options":["ستة عشر ضميرًا","خمسة","ثمانية","ثلاثة"],"answer":0,"explanation":"المنفصلة ستة عشر: للرفع: أنا وأنتَ وهو وفروعها، وللنصب: إياي وإياك وإياه وفروعها، في التثنية والجمع والتأنيث."},{"question":"ضمائر (تواني) هي:","options":["تاء المتكلم وألف الاثنين وواو الجماعة وياء المخاطبة ونون النسوة","ياء المتكلم وكاف المخاطب وهاء الغائب","أنا ونحن وهو","إياي وإياك"],"answer":0,"explanation":"(تواني) كلمة جامعة لأول حروف الضمائر الخمسة المتصلة بالرفع: تاء المتكلم، وواو الجماعة وألف الاثنين، ونون النسوة، وياء المخاطبة."},{"question":"العلم هو:","options":["الاسم الخاص بمسماه","كل اسم يقبل أل","كل ضمير","كل نكرة"],"answer":0,"explanation":"العلم: الاسم الخاص بمسماه نحو: محمد ومكة وجبريل؛ يدل على معين بعينه."},{"question":"من أعلام الشهور التي ذكرها المؤلف:","options":["المحرم وصفر وشوال","الربيع والخريف","السبت والأحد","الصيف والشتاء"],"answer":0,"explanation":"من العلم أسماء الشهور نحو: المحرم، وصفر، وشوال؛ وكذلك أسماء الكواكب نحو: زحل وعطارد."},{"question":"الضمائر المتصلة للنصب والجر:","options":["ياء المتكلم وكاف المخاطب وهاء الغائب","تاء المتكلم ونون النسوة","ألف الاثنين","إياك وإياه"],"answer":0,"explanation":"ثلاثة للنصب والجر: ياء المتكلم: كتابي؛ وكاف المخاطب: كتابك؛ وهاء الغائب: كتابه؛ ونا المتكلمين للرفع والنصب والجر."}]},{"body":["النوع الثالث: اسم الإشارة؛ نحو: هذا، وهذه، وهذانِ، وهاتانِ، وهؤلاء؛ يشير به إلى معين تراه أو تحضر صورته في الذهن.","النوع الرابع: الاسم الموصول؛ نحو: الذي، والتي، واللذانِ، واللتانِ، واللذينَ، واللائي، واللواتي؛ وسمي موصولًا لأنه لا يتم معناه حتى يوصل بجملة بعده: الذي حضرَ.","النوع الخامس: المعرف بـ(أل)، وهو الاسم الذي إذا نُزعت منه (أل) عاد نكرة؛ نحو: القلم، والكرسي، والثياب، والدولة، والمطار، والسوق؛ فأصلها: قلم وكرسي وثياب، فلما دخلت أل عُرفت.","النوع السادس: المضاف إلى معرفة؛ نحو: قلمي، وقلمُ محمدٍ، وقلمُ الطالبِ، وقلمُ هذا، وقلمُ الذي عندي؛ فالقلم نكرة، فلما أضيف إلى معرفة صار معرفة.","فهذه ستة أبواب للمعرفة: ضمير، وعلم، وإشارة، وموصول، وأل، وإضافة إلى معرفة؛ وكل اسم معرفة لا يخرج عنها."],"examples":["هذا وهذه وهذان وهاتان وهؤلاء: أسماء إشارة.","الذي والتي واللذان واللتان واللذين واللائي واللواتي: أسماء موصولة.","القلم والكرسي والمطار والسوق: معرفة بأل؛ تنزع أل تعود نكرة.","قلمي وقلم محمد وقلم الطالب: مضاف إلى معرفة.","قلم هذا وقلم الذي عندي: مضاف إلى اسم إشارة وإلى موصول: معرفة.","أحُد والفضواء وذو الفقار: أعلام خاصة بمسمياتها."],"questions":[{"question":"اسم الإشارة مثل:","options":["هذا وهذه وهؤلاء","الذي والتي","أنا وهو","من وما"],"answer":0,"explanation":"أسماء الإشارة: هذا، وهذه، وهذانِ، وهاتانِ، وهؤلاء؛ تدل على معين مشار إليه."},{"question":"الاسم الموصول سمي موصولًا لأن:","options":["معناه لا يتم حتى يوصل بجملة بعده","يتصل بحرف الجر","يكتب موصولًا بغيره في الرسم","لا ينقطع صوته"],"answer":0,"explanation":"الذي لا يفيد معنى تامًّا وحده؛ تقول: الذي حضرَ؛ فلزم وصله بجملة بعده، فسمي موصولًا."},{"question":"المعرف بـ(أل) هو:","options":["الاسم الذي إذا نزعت منه (أل) عاد نكرة","كل علم","كل ضمير","كل مضاف"],"answer":0,"explanation":"القلم: تنزع أل يعود: قلم نكرة؛ فهو معرف بأل؛ مثل: الكرسي، والثياب، والدولة، والمطار، والسوق."},{"question":"«قلمُ الطالبِ» معرفة من باب:","options":["المضاف إلى معرفة","العلم","المعرف بأل","اسم الإشارة"],"answer":0,"explanation":"قلم نكرة، لكنه أضيف إلى معرفة (الطالب) فاكتسب التعريف منها؛ ومثله: قلمي، وقلم هذا، وقلم الذي عندي."},{"question":"«زُحَل وعُطَارِد» من أعلام:","options":["الكواكب","الشهور","البلدان","الملائكة"],"answer":0,"explanation":"من أنواع العلم أسماء الكواكب نحو: زحل وعطارد؛ وقد عدها المؤلف في النوع الثاني من المعرفة."}]}]},{"id":"wahi-sharh-008","title":"باب المعرب والمبني: التعريفان","summary":"المعرب: كل كلمة يتغير آخرها لتغير إعرابها؛ والمبني: كل كلمة لا يتغير آخرها بل تلزم حالة واحدة.","section":"شرح الكتاب: المعرب والمبني","segments":[{"body":["باب جديد: المعرب والمبني. قال المؤلف: الكلمة تنقسم إلى معرب ومبني.","المعرب: كل كلمة يتغير آخرها لتغير إعرابها. مثل: محمدٌ، ويذهبُ. تقول: محمدٌ يذهبُ في الرفع، وإنَّ محمدًا لن يذهبَ في النصب، وسلمتُ على محمدٍ في الجر، ولم يذهبْ في الجزم. انظر إلى آخر الكلمة: تغير من ضمة إلى فتحة إلى كسرة إلى سكون؛ هذا هو الإعراب.","فالمعرب كالمتقلب يبدل حاله بحسب موقعه من الجملة: مرة مرفوع ومرة منصوب ومرة مجرور ومرة مجزوم.","والمبني: كل كلمة لا يتغير آخرها لتغير إعرابها، بل تلزم حالة واحدة. مثل: هذا، وذهبَ. تقول: هذا ذهبَ، وإنَّ هذا قد ذهبَ، وسلمتُ على هذا، وما ذهبَ. فآخر الكلمة على حال واحدة لا يتبدل.","فالمبني كالثابت لا يتحرك آخره مهما تغير موقعه في الكلام."],"examples":["محمدٌ يذهبُ / إن محمدًا لن يذهبَ / على محمدٍ / لم يذهبْ: آخر يتغير: معرب.","هذا ذهبَ / إن هذا قد ذهبَ / على هذا / ما ذهبَ: آخر ثابت: مبني.","المعرب: يتغير آخره لتغير إعرابه.","المبني: يلزم آخره حالة واحدة.","الرفع والنصب والجر والجزم: أحوال تتبدل على المعرب.","المعرب كالمتقلب، والمبني كالثابت."],"questions":[{"question":"المعرب هو:","options":["كل كلمة يتغير آخرها لتغير إعرابها","كل كلمة ثابتة الآخر","كل حرف","كل ماضٍ"],"answer":0,"explanation":"المعرب: كل كلمة يتغير آخرها لتغير إعرابها نحو: محمد ويذهب؛ يتبدل آخرهما بالرفع والنصب والجر والجزم."},{"question":"المبني هو:","options":["كل كلمة لا يتغير آخرها بل تلزم حالة واحدة","كل كلمة يتغير آخرها","كل اسم","كل مضارع"],"answer":0,"explanation":"المبني: كل كلمة لا يتغير آخرها لتغير إعرابها بل تلزم حالة واحدة نحو: هذا، وذهب."},{"question":"مثال المعرب من كلام المؤلف:","options":["محمدٌ ويذهبُ","هذا وذهبَ","من وهل","الذي"],"answer":0,"explanation":"محمدٌ يذهبُ في الرفع، ومحمدًا يذهبَ في النصب، ومحمدٍ في الجر، ولم يذهبْ في الجزم؛ فالآخر يتغير."},{"question":"مثال المبني:","options":["هذا وذهبَ","محمد ويكتب","كتاب ومدرسة","يتعلم"],"answer":0,"explanation":"هذا وذهب تلزم حالة واحدة في كل المواقع: هذا ذهب، وإن هذا قد ذهب، وما ذهب؛ فهي مبنية."},{"question":"تغير آخر الكلمة من ضمة إلى فتحة إلى كسرة يسمى:","options":["إعرابًا","بناءً","تنوينًا","إمالة"],"answer":0,"explanation":"الإعراب: تغير أواخر الكلم لتغير العوامل الداخلة عليها؛ وهو خاص بالمعرب."}]},{"body":["لا يكفي أن تعرف التعريفين؛ بل لا بد من حصر ما هو مبني وما هو معرب؛ فقال المؤلف: أقول في إجمال حصرهما:","الحروف، والأفعال الماضية، وأفعال الأمر: كلها مبنية. وأما الأسماء والأفعال المضارعة فبعضها معرب وبعضها مبني.","فاحفظ هذا الإجمال: الماضي والأمر والحروف: مبنية دائمًا، لا تبحث لها عن إعراب متغير. والأسماء: أكثرها معرب، وبعضها مبني كالضمائر وأسماء الإشارة والموصولات. والمضارع: معرب في الغالب، ويبنى في موضعين سيأتيان.","ثم يأتي التفصيل: الحروف مبنية على حركات أواخرها؛ فبعضها على السكون: مِنْ، وقَدْ، ولَنْ، ويا؛ وبعضها على الفتح: سَوْفَ، وواو العطف، وهمزة الاستفهام؛ وبعضها على الكسر: لام الجر، وباء الجر، ولام الأمر؛ وبعضها على الضم: مُنْذُ."],"examples":["الحروف: كلها مبنية.","الأفعال الماضية: كلها مبنية.","أفعال الأمر: كلها مبنية.","الأسماء: بعضها معرب وبعضها مبني.","الأفعال المضارعة: بعضها معرب وبعضها مبني.","منْ وقدْ ولنْ ويا: حروف مبنية على السكون."],"questions":[{"question":"في إجمال الحصر: المبني دائمًا:","options":["الحروف والأفعال الماضية وأفعال الأمر","الأسماء كلها","المضارع كله","الضمائر فقط"],"answer":0,"explanation":"قال المؤلف: الحروف والأفعال الماضية وأفعال الأمر كلها مبنية؛ وأما الأسماء والمضارعات فبعضها معرب وبعضها مبني."},{"question":"الأسماء:","options":["بعضها معرب وبعضها مبني","كلها معربة","كلها مبنية","كلها منصوبة"],"answer":0,"explanation":"الأسماء أكثرها معرب كمحمد وكتاب، وبعضها مبني كالضمائر وأسماء الإشارة والموصولات."},{"question":"الحروف تبنى على:","options":["حركات أواخرها: سكون أو فتح أو كسر أو ضم","السكون فقط","الفتح فقط","التنوين"],"answer":0,"explanation":"الحروف مبنية على حركات أواخرها؛ منها المبني على السكون: من وقد ولن ويا؛ وعلى الفتح: سوف وواو العطف وهمزة الاستفهام؛ وعلى الكسر: لام الجر وباء الجر ولام الأمر؛ وعلى الضم: منذ."},{"question":"من الحروف المبنية على الكسر:","options":["لام الجر وباء الجر ولام الأمر","سوف وهمزة الاستفهام","من وقد","منذ"],"answer":0,"explanation":"لام الجر وباء الجر ولام الأمر مبنية على الكسر؛ كما في تفصيل المؤلف لبناء الحروف."},{"question":"المضارع يكون مبنيًا:","options":["في موضعين سيأتي بيانهما، ومعربًا فيما سواهما","دائمًا مبنيًا","لا يبنى أبدًا","إذا كان ماضيًا"],"answer":0,"explanation":"المضارع معرب في الغالب، ويبنى في موضعين: اتصال نون التوكيد ونون النسوة؛ وسيأتي تفصيله في بابه."}]}]},{"id":"wahi-sharh-009","title":"بناء الفعل الماضي","summary":"الفعل الماضي مبني: على الفتح الظاهر، أو الفتح المقدر في ثلاثة مواضع: إذا كان آخره ألفًا، أو اتصلت به واو الجماعة، أو اتصل به ضمير رفع متحرك.","section":"شرح الكتاب: المعرب والمبني","segments":[{"body":["قال المؤلف: والفعل الماضي مبني. على أي شيء يبنى؟ على الفتح في الجملة؛ وللتفصيل صورتان: فتح ظاهر، وفتح مقدر.","الفتح الظاهر: أن ترى الفتحة على آخر الفعل وتنطقها: سجدَ، ودحرجَ، وانطلقَ، واستخرجَ؛ فكل واحد منها آخره فتحة مسموعة.","والفتح المقدر: فتحة موجودة في الحقيقة لكنها لا تظهر ولا تسمع لمانع؛ وهذا في ثلاثة مواضع.","الموضع الأول: إذا كان آخر الفعل ألفًا: دعا، وصلى، واهتدى، واستسقى؛ فالألف لا تقبل حركة فيتعذر ظهور الفتحة عليها، فنقول: مبني على فتح مقدر منع من ظهوره التعذر.","الموضع الثاني: أن تتصل به واو الجماعة: سجدوا، ودحرجوا، وانطلقوا، واستخرجوا؛ فلو فتحنا الواو لقلنا سجدَوا فيتصل حرفان متحركان فثقل، فمنع من ظهور الفتحة الثقل.","الموضع الثالث: أن يتصل به ضمير رفع متحرك: تاء الفاعل، أو نا المتكلمين، أو نون النسوة: سجدتُ، وسجدنَ، وسجدنا؛ فلو فتحنا لقيل سجدَتْ وثقل الأمر لالتقاء الساكنين، فقدر الفتح منعًا من ظهوره الثقل."],"examples":["سجدَ ودحرجَ وانطلقَ واستخرجَ: ماضٍ مبني على الفتح الظاهر.","دعا وصلى واهتدى واستسقى: مبني على فتح مقدر منع من ظهوره التعذر (آخره ألف).","سجدوا وانطلقوا: مبني على فتح مقدر منع من ظهوره الثقل (اتصال واو الجماعة).","سجدتُ: مبني على فتح مقدر (اتصال تاء الفاعل).","سجدنا: مبني على فتح مقدر (اتصال نا المتكلمين).","سجدنَ: مبني على فتح مقدر (اتصال نون النسوة)."],"questions":[{"question":"الفعل الماضي يبنى على:","options":["الفتح ظاهرًا أو مقدرًا","الضم دائمًا","الكسر دائمًا","السكون دائمًا"],"answer":0,"explanation":"الماضي مبني على الفتح: ظاهر نحو سجد، أو مقدر في ثلاثة مواضع."},{"question":"«دعا» مبني على فتح مقدر؛ والمانع من ظهوره:","options":["التعذر لأن آخره ألفًا","الثقل","التنوين","لا مانع"],"answer":0,"explanation":"الألف لا يقبل الحركات؛ فتعذر ظهور الفتحة على آخر (دعا) و(صلى) و(استسقى)، فقدرت."},{"question":"«سجدوا» مبني على فتح مقدر؛ والمانع:","options":["الثقل لاتصال واو الجماعة","التعذر","الإعلال","التسكين"],"answer":0,"explanation":"لو ظهر الفتح لقيل سجدَوا فيتحرك حرفان متتاليان فيثقل؛ فمنع من ظهوره الثقل."},{"question":"ضمير الرفع المتحرك الذي إذا اتصل بالماضي أوجب تقدير الفتح:","options":["تاء الفاعل، ونا المتكلمين، ونون النسوة","كاف المخاطب","هاء الغائب","ياء المتكلم"],"answer":0,"explanation":"سجدتُ وسجدنا وسجدنَ: الفتح مقدر منع من ظهوره الثقل لالتقاء الساكنين لو ظهر."},{"question":"«سجدَ» مبني على:","options":["الفتح الظاهر","الفتح المقدر","السكون","الضم"],"answer":0,"explanation":"سجد ودحرج وانطلق واستخرج: الفتحة ظاهرة مسموعة على آخرها؛ فهي مبنية على الفتح الظاهر."}]},{"body":["لماذا نتعلم البناء؟ لأنك ستقول في الإعراب: مبني على كذا، فلا بد أن تعرف على ماذا يبنى كل فعل.","وقاعدة الماضي سهلة: الأصل فيه الفتح؛ فإن رأيت فتحة فهو ظاهر، وإن لم ترها فانظر: هل آخره ألف؟ فالتعذر. هل اتصلت واو الجماعة؟ فالثقل. هل اتصلت تاء أو نا أو نون النسوة؟ فالثقل.","تدريب: كتبَ: فتح ظاهر. كتبوا: فتح مقدر منع من ظهوره الثقل. كتبتُ: فتح مقدر. رمى: فتح مقدر منع من ظهوره التعذر. كتبنَ: فتح مقدر.","ولطيفة: نون النسوة سماها المؤلف ضمير رفع متحرك لأنها تتحرك بالفتح: سجدنَ؛ فهي من ضمائر الرفع، ولاتصالها بالماضي يقدر الفتح."],"examples":["كتبَ: مبني على الفتح الظاهر.","كتبوا: مبني على فتح مقدر منع من ظهوره الثقل.","كتبتُ: مبني على فتح مقدر منع من ظهوره الثقل.","رمى: مبني على فتح مقدر منع من ظهوره التعذر.","كتبنَ: مبني على فتح مقدر منع من ظهوره الثقل.","قرأنا: مبني على فتح مقدر منع من ظهوره الثقل."],"questions":[{"question":"الأصل في بناء الماضي:","options":["الفتح","الضم","الكسر","السكون"],"answer":0,"explanation":"الفعل الماضي مبني على الفتح؛ ظاهرًا نحو سجد، أو مقدرًا في مواضعه الثلاثة."},{"question":"«رمى» مبني على فتح مقدر منع من ظهوره:","options":["التعذر","الثقل","التقاء الساكنين فقط","لا شيء"],"answer":0,"explanation":"آخره ألف لا تقبل الحركة؛ فتعذر ظهور الفتحة عليه؛ مثل: دعا وصلى واهتدى."},{"question":"«كتبتُ» الفتح في آخر (كتب):","options":["مقدر منع من ظهوره الثقل لاتصال تاء الفاعل","ظاهر","محذوف","منقلب كسرة"],"answer":0,"explanation":"اتصلت تاء الفاعل المتحركة؛ فلو ظهر الفتح لقيل كتبَتْ وثقل؛ فقدر الفتح."},{"question":"من صور ضمير الرفع المتحرك المتصل بالماضي:","options":["سجدتُ وسجدنا وسجدنَ","كتابي وكتابك","له وبه","إياي وإياك"],"answer":0,"explanation":"تاء الفاعل ونا المتكلمين ونون النسوة: ضمائر رفع متحركة؛ إذا اتصلت بالماضي قدر الفتح على آخره."},{"question":"الفائدة العملية من دراسة بناء الماضي:","options":["تعرف ما تقوله عند إعرابه: مبني على فتح ظاهر أو مقدر مع المانع","لا فائدة","للحفظ فقط","لمعرفة عدد حروفه"],"answer":0,"explanation":"عند إعراب الماضي تقول: مبني على الفتح الظاهر، أو المقدر منع من ظهوره التعذر أو الثقل؛ وهذا نصف إعرابه."}]}]},{"id":"wahi-sharh-010","title":"بناء فعل الأمر","summary":"فعل الأمر مبني على مثل حالة مضارعه في الجزم: حذف النون، أو حذف حرف العلة، أو السكون، أو الفتح إذا اتصلت به نون التوكيد.","section":"شرح الكتاب: المعرب والمبني","segments":[{"body":["قال المؤلف: وفعل الأمر مبني على مثل حالة مضارعه في الجزم. هذه قاعدة جميلة: انظر إلى مضارع الفعل كيف يجزم، وابنِ الأمر على مثل ذلك.","الصورة الأولى: يبنى على حذف النون إذا كان مضارعه من الأفعال الخمسة: اسجدوا، واسجدا، واسجدي؛ فمضارعها: يسجدون، ويسجدان، وتسجدين؛ وإذا جزمت حذفت نونها: لم يسجدوا؛ فبني الأمر على مثل ذلك: اسجدوا.","الصورة الثانية: يبنى على حذف حرف العلة إذا كان مضارعه معتل الآخر: ادعُ، واقضِ، واخشَ؛ فمضارعها: يدعو، ويقضي، ويخشى؛ وإذا جزمت حذف حرف علتها: لم يدعُ؛ فبني الأمر على مثله.","الصورة الثالثة: يبنى على السكون فيما سوى ذلك: اسجدْ، واذهبْ، وتخرجْ، وانطلقْ، واستخرجْ؛ فمضارعها صحيح الآخر يجزم بالسكون: لم يذهبْ.","الصورة الرابعة: يبنى على الفتح إذا اتصلت به نون التوكيد: اسجدَنَّ؛ فنون التوكيد توجب الفتح على ما قبلها."],"examples":["اسجدوا واسجدا واسجدي: أمر مبني على حذف النون (مضارعه من الأفعال الخمسة).","ادعُ: أمر مبني على حذف حرف العلة (مضارعه: يدعو).","اقضِ واخشَ: أمر مبني على حذف حرف العلة.","اسجدْ واذهبْ وانطلقْ: أمر مبني على السكون.","استخرجْ: أمر مبني على السكون.","اسجدَنَّ: أمر مبني على الفتح لاتصال نون التوكيد."],"questions":[{"question":"فعل الأمر يبنى على:","options":["مثل حالة مضارعه في الجزم","الفتح دائمًا","الضم دائمًا","حذف النون دائمًا"],"answer":0,"explanation":"قاعدة المؤلف: فعل الأمر مبني على مثل حالة مضارعه في الجزم؛ فانظر إلى جزم المضارع وابنِ الأمر على مثله."},{"question":"«اسجدوا» مبني على:","options":["حذف النون","السكون","الفتح","حذف حرف العلة"],"answer":0,"explanation":"مضارعه يسجدون من الأفعال الخمسة يجزم بحذف النون؛ فبني الأمر على مثل ذلك: اسجدوا، واسجدا، واسجدي."},{"question":"«ادعُ» مبني على حذف حرف العلة؛ لأن مضارعه:","options":["معتل الآخر: يدعو","من الأفعال الخمسة","صحيح الآخر","رباعي"],"answer":0,"explanation":"يدعو معتل الآخر بالواو؛ يجزم بحذف حرف العلة: لم يدعُ؛ فالأمر يبنى على مثله: ادعُ، واقضِ، واخشَ."},{"question":"«اذهبْ» مبني على:","options":["السكون","حذف النون","حذف حرف العلة","الفتح"],"answer":0,"explanation":"يذهب صحيح الآخر وليس من الأفعال الخمسة؛ يجزم بالسكون: لم يذهبْ؛ فالأمر مبني على السكون: اذهبْ."},{"question":"«اسجدَنَّ» مبني على الفتح لأن:","options":["اتصلت به نون التوكيد","مضارعه معتل","مضارعه من الخمسة","لا سبب"],"answer":0,"explanation":"إذا اتصلت نون التوكيد بفعل الأمر بني على الفتح: اسجدنَّ؛ كما نص المؤلف."}]},{"body":["لماذا هذه القاعدة محكمة؟ لأن الأمر مصنوع من المضارع؛ تحذف حرف المضارعة وتبني ما بقي؛ فكان من العدل أن يلزم ما يلزم المضارع عند جزمه.","تدريب: أريد أمرًا من «يكتب»: مضارعه صحيح يجزم بالسكون: لم يكتبْ؛ فالأمر: اكتبْ. من «يرمي»: معتل يجزم بحذف حرف العلة: لم يرمِ؛ فالأمر: ارمِ. من «يلعبون»: من الخمسة: يلعبوا... فالأمر: العبوا.","وتقول للمخاطبة في الأمر: اسجدي، وصلي، وتعالي، وكوني؛ كلها مبنية على حذف النون لأن مضارعها من الأفعال الخمسة: تسجدين، وتصلين، وتتعالين، وتكونين.","فاحفظ الصور الأربع: حذف نون، وحذف حرف علة، وسكون، وفتح مع نون التوكيد؛ ومعها لا يعسر عليك إعراب أي فعل أمر."],"examples":["يكتب → اكتبْ: مبني على السكون.","يرمي → ارمِ: مبني على حذف حرف العلة.","يلعبون → العبوا: مبني على حذف النون.","اسجدي وصلي وتعالي وكوني: أمر للمخاطبة مبني على حذف النون.","اكتبَنَّ: مبني على الفتح لنون التوكيد.","صور بناء الأمر أربع: حذف نون، وحذف علة، وسكون، وفتح."],"questions":[{"question":"أمر المخاطبة «اسجدي» مبني على:","options":["حذف النون لأن مضارعه (تسجدين) من الأفعال الخمسة","السكون","الضم","حذف حرف العلة"],"answer":0,"explanation":"تسجدين من الأفعال الخمسة تجزم بحذف النون؛ فالأمر منها للمخاطبة: اسجدي، مبني على حذف النون."},{"question":"لصنع الأمر من «يقضي» نقول:","options":["اقضِ: مبني على حذف حرف العلة","اقضْ: بالسكون","اقضُ: بالضم","اقضَ: بالفتح"],"answer":0,"explanation":"يقضي معتل الآخر بالياء؛ يجزم بحذفها: لم يقضِ؛ فالأمر مبني على مثل ذلك: اقضِ."},{"question":"علة بناء الأمر على مثل جزم مضارعه:","options":["الأمر مصنوع من المضارع فيلزم ما يلزمه عند الجزم","مجرد اتفاق","سهولة النطق فقط","لا علة"],"answer":0,"explanation":"تحذف حرف المضارعة وتبقي الباقي على صورة الجزم؛ فجاء الأمر موافقًا لجزم مضارعه في كل صوره."},{"question":"من «انطلقَ» الأمر «انطلقْ» مبني على:","options":["السكون","حذف النون","الفتح","حذف حرف العلة"],"answer":0,"explanation":"ينطلق مضارع صحيح الآخر ليس من الخمسة؛ يجزم بالسكون: لم ينطلقْ؛ فالأمر: انطلقْ مبني على السكون."},{"question":"عدد صور بناء فعل الأمر التي ذكرها المؤلف:","options":["أربع صور","صورتان","ثلاث صور","خمس صور"],"answer":0,"explanation":"أربع: حذف النون، وحذف حرف العلة، والسكون، والفتح إذا اتصلت نون التوكيد."}]}]},{"id":"wahi-sharh-011","title":"إعراب المضارع وبناءه، والأسماء المبنية","summary":"المضارع معرب إلا إذا اتصلت به نون التوكيد أو نون النسوة؛ ومن الأسماء المبنية: الموصولات وأسماء الاستفهام والشرط والظروف المركبة.","section":"شرح الكتاب: المعرب والمبني","segments":[{"body":["قال المؤلف: والفعل المضارع معرب؛ نحو: خالدٌ يذهبُ، ولن يذهبَ، ولم يذهبْ، والرجال يذهبون، ولن يذهبوا، ولم يذهبوا. فتراه يتغير آخره: ضمة ففتحة فسكون فثبوت نون فحذفها.","لكنه يبنى في موضعين: إذا اتصلت به نون التوكيد فيبنى على الفتح: لَيَفْعَلَنَّ؛ وإذا اتصلت به نون النسوة فيبنى على السكون: الطالبات يكتبْنَ، ويُكرِمْنَ الضيفَ.","ونون النسوة فاعل للمضارع، والجملة في محل رفع أو نصب أو جزم بحسب العامل: الطالباتُ يكتبْنَ (رفع)، وكَنْ يُهْمِلْنَ (نصب)، وم يُهْمِلْنَ أي لم يهملن (جزم).","فقسّم المؤلف الأسماء والمضارع: بعضها معرب وبعضها مبني، ثم فصل حصر المبني من الأسماء.","من الأسماء المبنية: الأسماء الموصولة وهي المبنية كلها: الذي، والتي، والذين، واللاتي، واللائي، واللواتي؛ أما المثنى اللذان واللتان فمعربان إعراب المثنى."],"examples":["خالد يذهبُ، لن يذهبَ، لم يذهبْ: مضارع معرب.","الرجال يذهبون، لن يذهبوا، لم يذهبوا: مضارع معرب.","ليفعلنَّ: مضارع مبني على الفتح لاتصال نون التوكيد.","الطالبات يكتبْنَ: مضارع مبني على السكون لاتصال نون النسوة.","يُكرمنَ الضيفَ: يكرمن في محل رفع، ونون النسوة فاعل مبني.","الذي والتي والذين واللاتي واللائي واللواتي: موصولات مبنية."],"questions":[{"question":"الفعل المضارع أصله:","options":["معرب يتغير آخره بالرفع والنصب والجزم","مبني دائمًا","مجزوم دائمًا","منصوب دائمًا"],"answer":0,"explanation":"المضارع معرب: يذهبُ، لن يذهبَ، لم يذهبْ؛ ويبنى في موضعين فقط: نون التوكيد ونون النسوة."},{"question":"المضارع يبنى على الفتح إذا اتصلت به:","options":["نون التوكيد","نون النسوة","واو الجماعة","ألف الاثنين"],"answer":0,"explanation":"إذا اتصلت نون التوكيد المثقلة أو المخففة بالمضارع بني على الفتح: ليفعلنَّ."},{"question":"المضارع يبنى على السكون إذا اتصلت به:","options":["نون النسوة","نون التوكيد","تاء التأنيث","ياء المتكلم"],"answer":0,"explanation":"إذا اتصلت نون النسوة بالمضارع بني على السكون: الطالبات يكتبن؛ ونون النسوة فاعل مبني على الفتح في محل رفع."},{"question":"في «لم يُهمِلْنَ» (الطالبات) الفعل:","options":["مبني على السكون لاتصال نون النسوة، والجملة في محل جزم بـ(لم)","معرب مجزوم بالسكون","مبني على الفتح","معرب منصوب"],"answer":0,"explanation":"المضارع مع نون النسوة مبني؛ فلا يقال مجزوم بالسكون، بل: مبني على السكون، والجملة في محل جزم بـ(لم)."},{"question":"الموصولان المعربان إعراب المثنى:","options":["اللذان واللتان","الذي والتي","الذين","اللائي"],"answer":0,"explanation":"الموصولات كلها مبنية إلا المثنى: اللذان واللتان؛ فهما معربان إعراب المثنى: يرفعان بالألف وينصبان ويجران بالياء."}]},{"body":["ومن الأسماء المبنية: أسماء الاستفهام عدا (أي)؛ أي: من، وما، ومتى، وأين، وكيف، وكم؛ نحو: من أبوك؟ وإلى من تنسب؟ وأين تذهب؟ وإلى أين تذهب؟ أما (أي) فمعربة بالحركات الأصلية: أيُّ أبوك؟ وإلى أيٍّ تنسب؟ وأيًّا تحب؟","ومنها: أسماء الشرط عدا (أي)؛ أي: من، وما، ومهما، ومتى، وأين، وكيفما، وحيثما؛ فهي مبنية؛ وأما (أي) فمعربة كما تقدم.","ومنها: الظروف المركبة: تبنى على فتح الجزأين، مثل: صباحَ مساءَ.","فلاحظ القاعدة الجامعة: أسماء الاستفهام والشرط مبنية إلا (أي)؛ فهي معربة فيهما بالحركات الأصلية: ترفع بالضمة، وتنصب بالفتحة، وتجر بالكسرة.","وهكذا علمت أن المبني من الأسماء أقسام: ضمائر، وإشارات، وموصولات، واستفهامات، وشروط، وظروف مركبة؛ وما عداها من الأسماء فهو معرب."],"examples":["من أبوك؟: (من) اسم استفهام مبني في محل رفع مبتدأ.","إلى من تنسب؟: (من) مبني في محل جر بـ(إلى).","أين تذهب؟ وإلى أين تذهب؟: (أين) مبنية في المحلّين.","أيُّ أبوك؟: (أي) معربة مرفوعة بالضمة.","إلى أيٍّ تنسب؟ وأيًّا تحب؟: (أي) معربة مجرورة ومنصوبة.","صباحَ مساءَ: ظرف مركب مبني على فتح الجزأين."],"questions":[{"question":"أسماء الاستفهام المبنية:","options":["من وما ومتى وأين وكيف وكم","أي فقط","كلها معربة","هل والهمزة"],"answer":0,"explanation":"أسماء الاستفهام مبنية عدا (أي): من، وما، ومتى، وأين، وكيف، وكم؛ وأي معربة بالحركات الأصلية."},{"question":"«أي» في الاستفهام والشرط:","options":["معربة بالحركات الأصلية","مبنية على السكون","مبنية على الفتح","حرف"],"answer":0,"explanation":"أي معربة: أيُّ أبوك؟ (رفع بالضمة)، وإلى أيٍّ تنسب؟ (جر بالكسرة)، وأيًّا تحب؟ (نصب بالفتحة)."},{"question":"«من» في «من أبوك؟» تعرب:","options":["اسم استفهام مبني في محل رفع مبتدأ","مبتدأ مرفوع بالضمة","حرف جر","فاعل"],"answer":0,"explanation":"من مبنية؛ فلا توصف بعلامة رفع، بل تبنى ويذكر محلها: في محل رفع مبتدأ."},{"question":"الظروف المركبة تبنى على:","options":["فتح الجزأين","سكون الجزأين","كسر الجزأين","ضم الجزأين"],"answer":0,"explanation":"الظرف المركب مبني على فتح الجزأين نحو: صباحَ مساءَ."},{"question":"أسماء الشرط المبنية:","options":["من وما ومهما ومتى وأين وكيفما وحيثما","إن وإذما","أي فقط","لو ولولا"],"answer":0,"explanation":"أسماء الشرط مبنية عدا (أي)؛ وإن وإذما حرفان مبنيان؛ وأي معربة بالحركات الأصلية."}]}]},{"id":"wahi-sharh-012","title":"الإعراب: ما يدخله وأركانه الثلاثة","summary":"الإعراب لا يدخل على كل الكلمات؛ بل على الأسماء والأفعال المضارعة المعربة فقط؛ وله ثلاثة أركان: نوعه، وحركة بنائه، وحكمه الإعرابي.","section":"شرح الكتاب: الإعراب وعلاماته","segments":[{"body":["قال المؤلف: الإعراب لا يدخل على كل الكلمات؛ بل يدخل على الأسماء والأفعال المضارعة فقط؛ ولا يدخل على الحروف، ولا على الفعل الماضي، ولا على فعل الأمر؛ لأنها مبنية.","فكل الأسماء المعربة يدخلها الرفع أو النصب أو الجر؛ نحو: محمدٌ (رفع) يكرم الصيفَ (نصب) بحضارةٍ (جر)؛ وهذا (رفع) يكرم سريرَه (نصب) بالذي أحب (جر).","وكل الأفعال المضارعة المعربة يدخلها الرفع أو النصب أو الجزم؛ نحو: أجتهدُ (رفع)، ولم أُهملْ (جزم)، وكي أتعلمَ (نصب)؛ والطالبات يجتهدْنَ (رفع)، ولم يهملْنَ (جزم)، وكَنْ يهملْنَ (نصب).","ثم بين المؤلف أن للإعراب ثلاثة أركان لا يتم إلا بها: بيان نوعه، وبيان حركة بنائه، وبيان حكمه الإعرابي.","نوع الإعراب: أن تقول: مرفوع، أو منصوب، أو مجرور، أو مجزوم. حركة البناء: أن تقول: علامة رفعه الضمة، أو علامة نصبه الفتحة، ونحوها. والحكم الإعرابي: موقعه من الجملة: فاعل، أو مفعول به، أو مبتدأ، ونحوها."],"examples":["محمدٌ يكرم: مرفوع؛ وعلامة رفعه الضمة.","الصيفَ: منصوب؛ وعلامة نصبه الفتحة.","بحضارةٍ: مجرور؛ وعلامة جره الكسرة.","أجتهدُ: مضارع مرفوع بالضمة.","لم أُهملْ: مضارع مجزوم بالسكون.","كي أتعلمَ: مضارع منصوب بالفتحة."],"questions":[{"question":"الإعراب يدخل على:","options":["الأسماء والأفعال المضارعة المعربة فقط","كل الكلمات","الحروف فقط","الماضي والأمر"],"answer":0,"explanation":"لا يدخل الإعراب على الحروف والماضي والأمر لأنها مبنية؛ بل يدخل على الأسماء والمضارعات المعربة."},{"question":"أركان الإعراب الثلاثة:","options":["نوعه، وحركة بنائه، وحكمه الإعرابي","لفظه وكتابته ونطقه","رفعه ونصبه وجره","أصله وفرعه وحكمه"],"answer":0,"explanation":"ثلاثة: بيان نوعه (مرفوع/منصوب/مجرور/مجزوم)، وبيان حركة بنائه (علامته)، وبيان حكمه الإعرابي (موقعه: فاعل، مفعول به...)."},{"question":"«الصيفَ» في «يكرم الصيفَ»:","options":["مفعول به منصوب وعلامة نصبه الفتحة","فاعل مرفوع","مجرور","مجزوم"],"answer":0,"explanation":"الصيف مفعول به: حكمه الإعرابي؛ منصوب: نوع إعرابه؛ علامة نصبه الفتحة: حركة بنائه؛ فتمت الأركان الثلاثة."},{"question":"الحروف لا يدخلها الإعراب لأنها:","options":["مبنية تلزم حالة واحدة","لأنها قصيرة","لأنها أسماء","لأنها معربة"],"answer":0,"explanation":"الحروف والماضي والأمر مبنية؛ والمبني لا يتغير آخره؛ فلا يدخله رفع ولا نصب ولا جر ولا جزم."},{"question":"ما يدخل الفعل المضارع المعرب:","options":["الرفع أو النصب أو الجزم","الجر","الرفع والنصب والجر","الجزم فقط"],"answer":0,"explanation":"المضارع يدخله الرفع والنصب والجزم دون الجر؛ فلا يجر الفعل أبدًا."}]},{"body":["الحكم الإعرابي عند المؤلف: إن كان معربًا قيل: مرفوع وعلامة رفعه الضمة، أو منصوب وعلامة نصبه الفتحة، أو مجرور وعلامة جره الكسرة، أو مجزوم وعلامة جزمه السكون.","وإن كان مبنيًا قيل -بحسب الحكم الإعرابي-: في محل رفع مبني على كذا، أو في محل نصب مبني على كذا، أو في محل جر مبني على كذا.","فلاحظ الفرق: المعرب يوصف بالعلامة (الضمة والفتحة...)، والمبني يوصف بالمحل (في محل رفع...)؛ لأن المبني ثابت لا حركة متغيرة له، فنخبر عن موقعه لا عن تغيره.","مثال المؤلف: يُكرِمْنَ: فعل مضارع في محل رفع مبني على السكون لاتصاله بنون النسوة؛ ونون النسوة: فاعل في محل رفع مبني على الفتح؛ وجملة (يكرمن) خبر المبتدأ في محل رفع. وهذا: مفعول به في محل نصب مبني على السكون.","فمتى قلت «في محل»؟ مع كل مبني له حكم إعرابي: ضمير، أو اسم إشارة، أو موصول، أو اسم شرط واستفهام مبني، أو فعل مبني."],"examples":["مرفوع وعلامة رفعه الضمة: صيغة إعراب المعرب المرفوع.","هذا: مفعول به في محل نصب مبني على السكون.","يكرمنَ: مضارع في محل رفع مبني على السكون لاتصاله بنون النسوة.","نون النسوة: فاعل في محل رفع مبني على الفتح.","الضمائر تبنى وتذكر محلها: في محل رفع أو نصب أو جر.","المعرب: يوصف بعلامته؛ والمبني: يوصف بمحله."],"questions":[{"question":"الفرق بين إعراب المعرب والمبني:","options":["المعرب يوصف بعلامته، والمبني يوصف بمحله","لا فرق","المبني يوصف بالضمة","المعرب يوصف بالمحل فقط"],"answer":0,"explanation":"المعرب: مرفوع وعلامة رفعه الضمة؛ والمبني: في محل رفع مبني على كذا؛ لأن المبني لا علامة متغيرة له."},{"question":"«نون النسوة» في إعراب المؤلف:","options":["فاعل في محل رفع مبني على الفتح","معربة مرفوعة بالضمة","حرف لا محل له","مفعول به"],"answer":0,"explanation":"نون النسوة ضمير فاعل مبني على الفتح في محل رفع؛ يتصل بالمضارع فيبنيه على السكون."},{"question":"متى نقول «في محل رفع»؟","options":["مع كل مبني له حكم إعرابي","مع كل معرب","مع الحروف فقط","مع الماضي فقط"],"answer":0,"explanation":"المبني ذو الحكم الإعرابي يذكر محله: الضمير واسم الإشارة والموصول والمبني من الاستفهام والشرط والفعل المبني."},{"question":"«يكرمنَ» (الطالبات) في إعراب المؤلف:","options":["فعل مضارع في محل رفع مبني على السكون لاتصاله بنون النسوة","مضارع مرفوع بالضمة","مضارع مجزوم","ماض مبني"],"answer":0,"explanation":"اتصلت نون النسوة فبني الفعل على السكون؛ ويذكر محل الجملة: في محل رفع؛ لأنه لم يسبق بناصب ولا جازم."},{"question":"علامة إعراب «بحضارةٍ»:","options":["الكسرة لأنه مجرور","الضمة","الفتحة","السكون"],"answer":0,"explanation":"بحضارة: الباء حرف جر، وحضارة اسم مجرور وعلامة جره الكسرة الظاهرة."}]}]},{"id":"wahi-sharh-013","title":"فصل في علامات الإعراب: الأصلية والفرعية","summary":"علامات الإعراب: أصلية وهي الحركات: الضمة للرفع، والفتحة للنصب، والكسرة للجر، والسكون للجزم؛ وفرعية: الألف والواو والياء والنون والحذف.","section":"شرح الكتاب: الإعراب وعلاماته","segments":[{"body":["فصل في علامات الإعراب. العلامات الأصلية أربع، وهي الحركات: الضمة علامة الرفع، والفتحة علامة النصب، والكسرة علامة الجر، والسكون علامة الجزم.","فالمفرد الصحيح وجمع التكسير وجمع المؤنث السالم تعرب بالحركات: جاء ولدٌ، وأكرمتُ ولدًا، وسلمتُ على ولدٍ، ولم يدعُ... الرجالُ يكرمون الرجالَ بعد الرجالِ.","والعلامات الفرعية: حروف أو حذف تنوب عن الحركات في كلمات مخصوصة: فالمثنى يرفع بالألف وينصب ويجر بالياء: كان الخطانِ متقاطعَيْنِ.","وجمع المذكر السالم يرفع بالواو وينصب ويجر بالياء: يصلي المسلمون ويحب الله المسلمين وسلمت على المسلمين.","وعلة النيابة: أن هذه الكلمات لها أحوال تمنع ظهور الحركة أو تستدعي حرفًا؛ فنابت الحروف أو الحذف عن الحركات فيها."],"examples":["جاء ولدٌ: رفع بالضمة (علامة أصلية).","أكرمت ولدًا: نصب بالفتحة (علامة أصلية).","سلمت على ولدٍ: جر بالكسرة (علامة أصلية).","الخطانِ متقاطعَيْنِ: المثنى يرفع بالألف وينصب ويجر بالياء.","المسلمون والمسلمين: جمع المذكر السالم يرفع بالواو وينصب ويجر بالياء.","المعلمات: جمع المؤنث السالم يرفع بالضمة وينصب ويجر بالكسرة."],"questions":[{"question":"علامات الإعراب الأصلية:","options":["الضمة للرفع، والفتحة للنصب، والكسرة للجر، والسكون للجزم","الألف والواو والياء","التنوين","حذف النون"],"answer":0,"explanation":"الأصلية هي الحركات الأربع؛ وما سواها من ألف وواو وياء ونون وحذف فهو فرعي ينوب عنها."},{"question":"المثنى يرفع بـ:","options":["الألف","الضمة","الواو","النون"],"answer":0,"explanation":"المثنى يرفع بالألف وينصب ويجر بالياء: كان الخطان متقاطعين؛ الخطان: اسم كان مرفوع بالألف."},{"question":"جمع المذكر السالم علاماته:","options":["الواو للرفع، والياء للنصب والجر","الضمة والفتحة والكسرة","الألف للرفع","النون للنصب"],"answer":0,"explanation":"يصلي المسلمون (رفع بالواو)، ويحب الله المسلمين (نصب بالياء)، وسلمت على المسلمين (جر بالياء)."},{"question":"جمع المؤنث السالم ينصب ويجر بـ:","options":["الكسرة","الفتحة","الياء","الألف"],"answer":0,"explanation":"جمع المؤنث السالم يرفع بالضمة وينصب ويجر بالكسرة: المعلماتُ كرِمْنَ، وأكرمتُ المعلماتِ، وسلمتُ على المعلماتِ."},{"question":"سماها المؤلف فرعية لأنها:","options":["تنوب عن الحركات الأصلية في كلمات مخصوصة","أضعف من الأصلية","جاءت متأخرة تاريخيًا","لا تستعمل"],"answer":0,"explanation":"الحروف والحذف تنوب عن الحركات في المثنى والجمع والأفعال الخمسة والمعتل؛ فهي فروع للعلامات الأصلية."}]},{"body":["الأفعال الخمسة: ترفع بثبوت النون، وتنصب وتجزم بحذف النون: يفعلان، وتفعلان، ويفعلون، وتفعلون، وتفعلِ للمخاطبة.","ومن العلامات المقدرة: ما كان آخره ألفًا أو واوًا أو ياء قبل ياء المتكلم: جاء الفتى: فاعل مرفوع وعلامة رفعه الضمة المقدرة منع من ظهورها التعذر؛ وأكرمت الفتى: مفعول به منصوب وعلامة نصبه الفتحة المقدرة.","والمضارع المعتل الآخر: علامة رفعه ضمة مقدرة، وعلامة نصبه فتحة ظاهرة، وعلامة جزمه حذف حرف العلة: الرجل يخشى، ولن يخشى، ولم يخشَ.","والممنوع من الصرف: يمنع من التنوين فيجر بالفتحة بدل الكسرة: يضيء إبراهيم مصابيحَ جميلةً في مساجدَ كثيرةٍ؛ مساجد: مجرور وعلامة جره الفتحة.","فجمعت علامات الرفع أربع: الضمة والواو والألف وثبوت النون؛ وعلامات النصب خمس: الفتحة والألف والكسرة والياء وحذف النون؛ وعلامات الجر ثلاث: الكسرة والياء والفتحة؛ وعلامات الجزم ثلاث: السكون وحذف حرف العلة وحذف النون."],"examples":["يفعلان وتفعلان ويفعلون وتفعلون وتفعلِ: الأفعال الخمسة ترفع بثبوت النون.","لم يذهبوا: منصوبة أو مجزومة بحذف النون.","جاء الفتى: الضمة مقدرة منع من ظهورها التعذر لآخره ألف.","الرجل لم يخشَ: مجزوم وعلامة جزمه حذف حرف العلة.","في مساجدَ: مجرور بالفتحة لأنه ممنوع من الصرف.","علامات النصب خمس: الفتحة والألف والكسرة والياء وحذف النون."],"questions":[{"question":"الأفعال الخمسة ترفع بـ:","options":["ثبوت النون","الضمة","الواو","الألف"],"answer":0,"explanation":"الأفعال الخمسة: يفعلان وتفعلان ويفعلون وتفعلون وتفعلِ ترفع بثبوت النون وتنصب وتجزم بحذفها."},{"question":"«الفتى» في «جاء الفتى» علامة رفعه:","options":["الضمة المقدرة منع من ظهورها التعذر","الضمة الظاهرة","الألف","الواو"],"answer":0,"explanation":"آخره ألف لا تقبل الحركة؛ فعلامته ضمة مقدرة منع من ظهورها التعذر؛ ونصبه فتحة مقدرة."},{"question":"المضارع المعتل الآخر علامة جزمه:","options":["حذف حرف العلة","السكون","حذف النون","الكسرة"],"answer":0,"explanation":"الرجل لم يخشَ: مجزوم وعلامة جزمه حذف حرف العلة؛ ونصبه بالفتحة الظاهرة: لن يخشى."},{"question":"الممنوع من الصرف يجر بـ:","options":["الفتحة","الكسرة","الياء","التنوين"],"answer":0,"explanation":"الممنوع من الصرف يمنع من التنوين ويجر بالفتحة: في مساجدَ كثيرةٍ؛ مساجد: مجرور وعلامة جره الفتحة."},{"question":"عدد علامات الرفع التي جمعها الدرس:","options":["أربع: الضمة والواو والألف وثبوت النون","ثلاث","خمس","اثنتان"],"answer":0,"explanation":"الرفع أربع علامات؛ والنصب خمس؛ والجر ثلاث؛ والجزم ثلاث؛ وهي جامعة أبواب العلامات."}]}]},{"id":"wahi-sharh-014","title":"الجزء الثاني: أحكام الكلام والجملة الفعلية","summary":"بالكلمات تتكون الجمل وهي نوعان: فعلية واسمية؛ والجملة الفعلية أركانها: الفعل والفاعل أو نائبه.","section":"شرح الكتاب: أحكام الكلام","segments":[{"body":["بدأ المؤلف الجزء الثاني فقال: اعلم -فهمني الله وإياك- أنه بالكلمات تتكون الجمل، وهي نوعان: فعلية واسمية؛ وأحكام الكلام كثيرة مرتبها في أبواب.","الجملة الفعلية: التي يتقدم فيها الفعل: صلى أنسٌ، وقُرئ الكتابُ. والجملة الاسمية: المبدوءة بالاسم: محمدٌ جالسٌ، وأنا أصلي.","أركان الجملة الفعلية: الفعل، ثم الفاعل إن كان مبنيًا للمعلوم: صلى أنس؛ أو نائب الفاعل إن كان مبنيًا للمجهول: قُرئ الكتاب.","فالفاعل: الاسم المرفوع الذي أُسند إليه الفعل؛ أي: الذي وقع منه الفعل: قام أنسٌ؛ سواء فعله بنفسه: قام، أو لم يفعله لكنه قام به: مات أنس.","ولكل باب تفصيله: الفاعل، ونائب الفاعل؛ وستأتي أبوابهما في الدروس القادمة بأمثلتها وإعرابها."],"examples":["صلى أنسٌ: جملة فعلية: فعل + فاعل.","قُرئ الكتابُ: جملة فعلية: فعل مبني للمجهول + نائب فاعل.","محمد جالس: جملة اسمية مبدوءة بالاسم.","أنا أصلي في المسجد: جملة اسمية حقيقة.","الفاعل: اسم مرفوع أُسند إليه الفعل: قام أنس.","مات أنس: فاعل وإن لم يفعل الفعل بنفسه؛ قام به الفعل."],"questions":[{"question":"الجمل نوعان:","options":["فعلية واسمية","ماضية ومضارعة","طويلة وقصيرة","خبرية وإنشائية فقط"],"answer":0,"explanation":"بالكلمات تتكون الجمل وهي نوعان: فعلية يتقدمها الفعل، واسمية تبدأ بالاسم."},{"question":"الجملة الفعلية أركانها:","options":["الفعل والفاعل أو نائبه","المبتدأ والخبر","الحرف والفعل","النعت والمنعوت"],"answer":0,"explanation":"فعل مبني للمعلوم وفاعل نحو: صلى أنس؛ أو فعل مبني للمجهول ونائب فاعل نحو: قرئ الكتاب."},{"question":"الفاعل هو:","options":["الاسم المرفوع الذي أُسند إليه الفعل","الاسم المنصوب","الحرف الداخل على الفعل","الخبر"],"answer":0,"explanation":"الفاعل: الذي أسند إليه الفعل؛ سواء فعله: قام أنس، أو قام به: مات أنس؛ وكلاهما فاعل مرفوع."},{"question":"«قُرئ الكتابُ» جملة فعلية ركنها الثاني «الكتاب»:","options":["نائب فاعل","فاعل","مفعول به","مبتدأ"],"answer":0,"explanation":"الفعل قرئ مبني للمجهول؛ فالاسم المرفوع بعده نائب فاعل؛ وتفصيله في باب نائب الفاعل."},{"question":"الجملة الاسمية تبدأ بـ:","options":["الاسم","الفعل","الحرف","النفي"],"answer":0,"explanation":"الجملة الاسمية: المبدوءة بالاسم حقيقة نحو: محمد جالس، وأنا أصلي في المسجد."}]},{"body":["فرّق بين الجملتين بسرعة: انظر إلى أول الكلام: إن وجدت فعلًا فهي فعلية: كتبَ الطالبُ الدرسَ؛ وإن وجدت اسمًا فهي اسمية: الطالبُ مجتهدٌ.","والجملة الاسمية صورها أربع كما في الخريطة: مرفوعان (مبتدأ وخبر)، وكان وأخواتها، وإن وأخواتها، وظن وأخواتها؛ وكلها تجتمع في المبتدأ والخبر أصلًا ثم دخلت النواسخ فغيرت الأحكام.","والجملة الفعلية لا تخلو من فعل وفاعل ظاهر أو مقدر؛ فإذا حذف الفاعل لدلالة أو لغرض ناب عنه نائب الفاعل.","فهذان النوعان هما مادة أبواب الكتاب كلها: فأبواب المرفوعات تدور على الفاعل ونائبه والمبتدأ والخبر؛ وأبواب المنصوبات على ما يتصل بالفعل من مفعولات وأحوال؛ فافهم النوعين تفهم ما بعدهما."],"examples":["كتب الطالب الدرس: فعلية؛ بدأت بفعل.","الطالب مجتهد: اسمية؛ بدأت باسم.","كان الجو جميلًا: اسمية دخلتها كان.","إن العلم نور: اسمية دخلتها إن.","ظننتُ الجوَ جميلًا: دخلتها ظن.","كل جملة فعلية لا بد فيها من فعل وفاعل ظاهر أو مقدر."],"questions":[{"question":"«كتبَ الطالبُ الدرسَ» جملة:","options":["فعلية لأنها بدأت بفعل","اسمية","حرفية","مبتدأ وخبر"],"answer":0,"explanation":"أولها فعل (كتب) فهي فعلية: فعل + فاعل (الطالب) + مفعول به (الدرس)."},{"question":"صور الجملة الاسمية الأربع تجتمع في:","options":["المبتدأ والخبر أصلًا ثم دخلت النواسخ","الفعل والفاعل","الحال والتمييز","العطف والتوكيد"],"answer":0,"explanation":"الأصل مبتدأ وخبر مرفوعان؛ فإذا دخلت كان أو إن أو ظن تغير الحكم؛ فالأبواب الأربعة مادة واحدة."},{"question":"«ظننتُ الجوَ جميلًا» دخلتها:","options":["ظن فنصبت المبتدأ ورفعت الخبر","كان","إن","لا"],"answer":0,"explanation":"ظن وأخواتها تدخل على الجملة الاسمية فتنصب المبتدأ وترفع الخبر؛ وستأتي في بابها."},{"question":"لا تخلو جملة فعلية من:","options":["فعل وفاعل ظاهر أو مقدر","مبتدأ","حرف جر","خبر"],"answer":0,"explanation":"الجملة الفعلية ركنها الفعل والفاعل؛ فإن حذف الفاعل لغرض ناب نائب الفاعل: قُرئ الكتاب."},{"question":"أبواب المرفوعات في الكتاب تدور على:","options":["الفاعل ونائبه والمبتدأ والخبر","المفعولات","الحروف","النداء"],"answer":0,"explanation":"المرفوعات: الفاعل، ونائب الفاعل، والمبتدأ، والخبر، وما ناب عنها من النواسخ؛ فهي مادة الجملتين."}]}]},{"id":"wahi-sharh-015","title":"باب الفاعل","summary":"الفاعل: الاسم المرفوع الذي أُسند إليه الفعل؛ سواء فعله بنفسه، أو لم يفعله، أو الفعل قام به.","section":"شرح الكتاب: أحكام الكلام","segments":[{"body":["قال المؤلف في باب الفاعل: هو الاسم المرفوع الذي أُسند إليه الفعل؛ أي: أخبر به عنه: قام أنسٌ.","ويكون على ثلاث صور: أن يكون هو الذي فعل الفعل بنفسه: قام أنس، وكتب خالد؛ أو ألا يكون فعله لكن الفعل قام به: مات أنس، ومرض الطفل؛ فالموت قام بأنس وإن لم يفعل أنس شيئًا.","وعلامته في الظاهر: الرفع؛ فكل اسم مرفوع بعد فعله دليل عليه فهو فاعل: جاء محمدٌ، ونجح الطلابُ.","وقد يكون ضميرًا مستترًا: يجتهدُ (فاعله مستتر تقديره هو)، أو ضميرًا متصلًا: يجتهدون (واو الجماعة فاعل)، أو جملة: يعجبني أن تجتهدَ (المصدر المؤول فاعل).","وترتيبه: يتأخر عن فعله غالبًا: صلى أنس؛ وقد يتقدم عليه في جملة اسمية: أنسٌ صلى؛ فأنس مبتدأ والجملة الفعلية خبر."],"examples":["قام أنسٌ: أنس فاعل مرفوع فعل الفعل بنفسه.","مات أنسٌ: فاعل وإن لم يفعل؛ فالفعل قام به.","كتب خالدٌ: خالد فاعل مرفوع بالضمة.","نجح الطلابُ: الطلاب فاعل مرفوع بالواو (جمع مذكر سالم).","يجتهدُ: الفاعل ضمير مستتر تقديره هو.","يجتهدون: واو الجماعة فاعل في محل رفع مبني."],"questions":[{"question":"الفاعل هو:","options":["الاسم المرفوع الذي أُسند إليه الفعل","الاسم المنصوب","الفعل نفسه","الحرف"],"answer":0,"explanation":"الفاعل: اسم مرفوع أسند إليه الفعل؛ سواء فعله بنفسه: قام أنس، أو قام به الفعل: مات أنس."},{"question":"«مات أنسٌ» أنس فاعل مع أنه:","options":["لم يفعل الفعل بل الفعل قام به","فعل الفعل بنفسه","مفعول به","حال"],"answer":0,"explanation":"الفاعل لا يشترط أن يفعل الفعل؛ يكفي إسناد الفعل إليه: مات أنس؛ فالموت قام بأنس."},{"question":"في «نجح الطلابُ» علامة رفع الفاعل:","options":["الواو لأنه جمع مذكر سالم","الضمة","الألف","النون"],"answer":0,"explanation":"الطلاب جمع مذكر سالم يرفع بالواو: نجح الطلابُ؛ فالفاعل مرفوع وعلامة رفعه الواو."},{"question":"الفاعل في «يجتهدُ»:","options":["ضمير مستتر تقديره هو","اسم ظاهر","واو الجماعة","لا فاعل له"],"answer":0,"explanation":"المضارع المفرد الغائب فاعله ضمير مستتر تقديره هو؛ ولا يظهر اسم إلا إذا ذكر: يجتهد خالد."},{"question":"ترتيب الفاعل المعتاد:","options":["يتأخر عن فعله","يتقدم على فعله دائمًا","في أول الجملة دائمًا","بعد الخبر"],"answer":0,"explanation":"الفاعل يتأخر عن فعله غالبًا: صلى أنس؛ فإن تقدم صارت الجملة اسمية: أنس صلى، وأنس مبتدأ."}]},{"body":["تدريبات من الشرح: الفاعل يطابق فعله في التذكير والتأنيث الظاهرين: جاء الرجلُ، وجاءت المرأةُ؛ فالفعل يدل على فاعله بتائه أو صورته.","وإذا كان الفاعل جمع تكسير لغير العاقل جاز تأنيث الفعل وتذكيره: جاءت الأمطارُ، وجاء الأمطارُ؛ لأن جمع التكسير لغير العاقل يعامل معاملة المؤنث.","وموضع الفاعل في الإعراب ثابت: تقول: فاعل مرفوع وعلامة رفعه كذا؛ فهو من منازل الرفع السبع التي حفظتها في النظم.","وتذكر الخريطة: الفاعل هو ركن الجملة الفعلية الثاني بعد الفعل؛ فلا جملة فعلية بلا فاعل ظاهر: كتب خالد، أو مقدر: يكتبُ، أو ضمير متصل: يكتبون.","فأتقن باب الفاعل؛ فهو بابك الأول من أبواب المرفوعات، وعليه يبنى باب نائب الفاعل الذي يليه."],"examples":["جاء الرجلُ وجاءت المرأةُ: الفعل يطابق فاعله في التذكير والتأنيث.","جاءت الأمطارُ أو جاء الأمطارُ: جمع تكسير لغير عاقل يجوز فيه الوجهان.","الفاعل: أول منازل الرفع السبع.","كتب خالد: فاعل ظاهر.","يكتب: فاعل مستتر تقديره هو.","يكتبون: فاعل ضمير متصل (واو الجماعة)."],"questions":[{"question":"الفعل يطابق فاعله في:","options":["التذكير والتأنيث: جاء الرجل، وجاءت المرأة","العدد فقط","الرفع فقط","لا مطابقة"],"answer":0,"explanation":"يظهر في الفعل ما يدل على فاعله: جاء الرجل، وجاءت المرأة بالتاء؛ فالمطابقة في التذكير والتأنيث."},{"question":"جمع التكسير لغير العاقل يجوز في فعله:","options":["التذكير والتأنيث","التأنيث فقط","التذكير فقط","الجمع فقط"],"answer":0,"explanation":"جاءت الأمطار وجاء الأمطار؛ لأن جمع تكسير غير العاقل يعامل معاملة المؤنث الواحد، ويجوز تذكير الفعل."},{"question":"الفاعل من منازل:","options":["الرفع السبع","النصب","الجر","الجزم"],"answer":0,"explanation":"منازل الرفع السبع في النظم: مبتدأ وخبر وفاعل ونائب واسم كان وخبر إن وتابع؛ والفاعل ثالثها."},{"question":"«يكتبون» الفاعل فيها:","options":["واو الجماعة: ضمير متصل مبني في محل رفع","ضمير مستتر تقديره هم","النون","اسم ظاهر"],"answer":0,"explanation":"واو الجماعة ضمير رفع متصل مبني على السكون في محل رفع؛ وهي من ضمائر (تواني)."},{"question":"باب الفاعل يبنى عليه باب:","options":["نائب الفاعل","الحال","التمييز","النداء"],"answer":0,"explanation":"نائب الفاعل هو المفعول به بعد حذف الفاعل وبناء الفعل للمجهول؛ فمن أتقن الفاعل سهل عليه نائبه."}]}]},{"id":"wahi-sharh-016","title":"باب نائب الفاعل","section":"شرح الكتاب: باب نائب الفاعل","order":16,"segments":[{"body":["في هذا الدرس نتعلم بابًا جديدًا اسمه: «نائب الفاعل». كلمة «نائب» معناها: الذي يقوم مقام غيره ويحل محله. فنائب الفاعل اسم جاء مكان الفاعل بعد أن حذفناه.","تعريفه في الكتاب: «هو المفعول به بعد حذف الفاعل وبناء الفعل قبله للمجهول». لنفهمها كلمة كلمة: «المفعول به»: هو الاسم الذي كان منصوبًا بعد الفعل. «بعد حذف الفاعل»: أي بعد أن أزلنا اسم من قام بالفعل. «وبناء الفعل قبله للمجهول»: أي غيّرنا صورة الفعل ليدل على أننا لا نعرف أو لا نريد ذكر من فعله.","مثال يوضح: «قرأ أنسٌ القرآنَ». هنا الفاعل هو «أنس» والمفعول به «القرآن». لو حذفنا الفاعل «أنس» وغيّرنا الفعل، قلنا: «قُرِئَ القرآنُ». فـ«القرآن» كان مفعولًا به منصوبًا، فصار الآن نائب فاعل مرفوعًا: ناب عن الفاعل المحذوف.","لماذا نفعل هذا؟ أحيانًا لا نعرف الفاعل، أو لا يهمنا ذكره، أو نريد إخفاءه. فبدل أن نقول «فعل فلان كذا» نقول «فُعِلَ كذا».","كيف نبني الفعل الماضي للمجهول؟ القاعدة: نضم أوله ونكسر ما قبل آخره. «قَرَأَ» تصبح «قُرِئَ»: ضممنا أوله (القاف) وكسرنا ما قبل آخره (الهمزة). و«دَخَلَ» تصبح «دُخِلَ». و«اسْتَخْرَجَ» تصبح «اسْتُخْرِجَ».","وكيف نبني الفعل المضارع للمجهول؟ القاعدة: نضم أوله ونفتح ما قبل آخره. «يَقْرَأُ» تصبح «يُقْرَأُ». و«يَدْخُلُ» تصبح «يُدْخَلُ». و«يَسْتَخْرِجُ» تصبح «يُسْتَخْرَجُ».","انتبه: فعل الأمر لا يُبنى للمجهول أبدًا. لا نقول في الأمر «اُكْتُبْ» بمعنى المجهول؛ لأن الأمر طلب من شخص معين أن يفعل، فلا بد أن نعرف المخاطب."],"examples":["قرأ أنسٌ القرآنَ ← قُرِئَ القرآنُ (حذفنا الفاعل وبنينا الفعل للمجهول)","كتب التلميذُ الدرسَ ← كُتِبَ الدرسُ","فتح الحارسُ البابَ ← فُتِحَ البابُ","يشرح المعلمُ القواعدَ ← تُشرَحُ القواعدُ","استخرج العمالُ الذهبَ ← اسْتُخْرِجَ الذهبُ","يدخل الجيشُ المدينةَ ← يُدْخَلُ المدينةُ (غير صحيحة) / تُدْخَلُ المدينةُ (صحيحة)"],"questions":[{"question":"ما تعريف نائب الفاعل؟","options":["المفعول به بعد حذف الفاعل وبناء الفعل قبله للمجهول","الاسم الذي قام بالفعل","الفعل المبني للمعلوم","الاسم المنصوب بعد حرف الجر"],"answer":0,"explanation":"نائب الفاعل هو المفعول به بعد أن حذفنا الفاعل وبنينا الفعل للمجهول؛ فيكون مرفوعًا بدل الفاعل."},{"question":"في «قُرِئَ القرآنُ» ما إعراب «القرآنُ»؟","options":["نائب فاعل مرفوع وعلامة رفعه الضمة","مفعول به منصوب","فاعل مرفوع","مبتدأ مرفوع"],"answer":0,"explanation":"«القرآنُ» نائب فاعل مرفوع بالضمة؛ لأن الفعل بُني للمجهول بعد حذف الفاعل «أنس»."},{"question":"كيف نبني الفعل الماضي للمجهول؟","options":["بضم أوله وكسر ما قبل آخره","بفتح أوله وضم ما قبل آخره","بكسر أوله وفتح ما قبل آخره","لا يتغير الفعل الماضي"],"answer":0,"explanation":"الماضي يُبنى للمجهول بضم أوله وكسر ما قبل آخره، نحو: قَرَأَ ← قُرِئَ، ودَخَلَ ← دُخِلَ."},{"question":"كيف نبني الفعل المضارع للمجهول؟","options":["بضم أوله وفتح ما قبل آخره","بضم أوله وكسر ما قبل آخره","بفتح أوله وفتح ما قبل آخره","لا يُبنى المضارع للمجهول"],"answer":0,"explanation":"المضارع يُبنى للمجهول بضم أوله وفتح ما قبل آخره، نحو: يَقْرَأُ ← يُقْرَأُ."},{"question":"أي الأفعال لا يُبنى للمجهول؟","options":["فعل الأمر","الفعل الماضي","الفعل المضارع","الفعل الناقص"],"answer":0,"explanation":"فعل الأمر لا يُبنى للمجهول؛ لأنه طلب موجه لمخاطب معلوم، فلا معنى لجهل فاعله."}]},{"body":["إعراب نائب الفاعل سهل: «فإن كان مرفوعًا فهو مرفوع، وإن كان مبنيًّا فهو في محل رفع». أي: إن كان الاسم معربًا أظهرنا عليه علامة الرفع، وإن كان مبنيًّا (كالضمائر وأسماء الإشارة) قلنا: في محل رفع.","نائب الفاعل يأتي على ثلاث صور - مثل الفاعل تمامًا: أولًا: اسمًا ظاهرًا، نحو: «قُرِئَ القرآنُ». فـ«القرآن» اسم ظاهر نائب فاعل مرفوع بالضمة.","ثانيًا: ضميرًا بارزًا، نحو: «تُقْرَأُنَّ الآياتُ» فنون النسوة نائب فاعل في محل رفع، مبني على الفتح. والضمائر البارزة لا تظهر عليها الحركات فنقدر محلها.","ثالثًا: ضميرًا مستترًا، نحو: «قُرِئَ» بمعنى قُرئ هو. فنائب الفاعل ضمير مستتر تقديره «هو». المستتر يعني المختفي داخل الفعل لا نراه لكننا نفهمه.","تدريب عملي: لتحويل أي جملة إلى المجهول اتبع ثلاث خطوات: ١- احذف الفاعل. ٢- غيّر صورة الفعل: الماضي بضم أوله وكسر ما قبل آخره، والمضارع بضم أوله وفتح ما قبل آخره. ٣- ارفع المفعول به مكان الفاعل.","مثال تطبيقي كامل: «شرّف المعلمُ التلميذَ». الخطوة ١: نحذف «المعلم». الخطوة ٢: «شَرَّفَ» تصبح «شُرِّفَ». الخطوة ٣: «التلميذَ» تصبح «التلميذُ». النتيجة: «شُرِّفَ التلميذُ»، و«التلميذ» نائب فاعل مرفوع بالضمة.","حكم مهم: نائب الفاعل فرع عن الفاعل؛ فكل ما تعرفه عن الفاعل ينطبق عليه في الرفع، والفرق الوحيد أن الفعل قبله مبني للمجهول لا للمعلوم."],"examples":["قُرِئَ القرآنُ: نائب فاعل مرفوع بالضمة (اسم ظاهر)","شُرِّفَ المعلمونَ: نائب فاعل مرفوع بالواو (جمع مذكر سالم)","تُكرَمُ الوالدةُ: نائب فاعل مرفوع بالضمة (فعل مضارع مبني للمجهول)","يُحفَظُ المتقونَ: خطأ؛ الصواب: يُحفَظُ المتقونَ باعتبار الواو... الأصح: «حُفِظَ المتقونَ» نائب فاعل مرفوع بالواو","أُكْرِمْتُ: نائب فاعل ضمير بارز (التاء) في محل رفع","دُفِعَ: نائب فاعل ضمير مستتر تقديره «هو»"],"questions":[{"question":"إذا كان نائب الفاعل اسمًا مبنيًّا فما حكمه؟","options":["يكون في محل رفع","يكون في محل نصب","يكون مرفوعًا بالضمة","لا يجوز أن يكون مبنيًّا"],"answer":0,"explanation":"إن كان مرفوعًا فهو مرفوع، وإن كان مبنيًّا فهو في محل رفع؛ لأن المبني لا تظهر عليه العلامات."},{"question":"ما صور نائب الفاعل الثلاث؟","options":["اسم ظاهر، وضمير بارز، وضمير مستتر","مفرد ومثنى وجمع","معرفة ونكرة ومضاف","ماضٍ ومضارع وأمر"],"answer":0,"explanation":"نائب الفاعل يأتي اسمًا ظاهرًا كـ«القرآن»، وضميرًا بارزًا كالتاء، وضميرًا مستترًا تقديره «هو» - تمامًا مثل الفاعل."},{"question":"في «تُقْرَأُنَّ الآياتُ» ما نائب الفاعل؟","options":["نون النسوة في محل رفع","الآيات","ضمير مستتر تقديره هو","لا يوجد نائب فاعل"],"answer":0,"explanation":"نون النسوة ضمير بارز مبني على الفتح في محل رفع نائب فاعل، و«الآيات» مفعول به منصوب."},{"question":"حوّل «شرب الطفلُ اللبنَ» إلى المجهول:","options":["شُرِبَ اللبنُ","شَرِبَ اللبنُ","شُرِبَ اللبنَ","شَرَّبَ اللبنُ"],"answer":0,"explanation":"نحذف الفاعل «الطفل»، ونبني الماضي للمجهول بضم أوله وكسر ما قبل آخره: شُرِبَ، ونرفع المفعول به: اللبنُ."},{"question":"حوّل «يفتح التلميذُ الكتابَ» إلى المجهول:","options":["يُفتَحُ الكتابُ","يُفتِحُ الكتابُ","فُتِحَ الكتابُ","يَفتَحُ الكتابُ"],"answer":0,"explanation":"المضارع يُبنى للمجهول بضم أوله وفتح ما قبل آخره: يَفتَحُ ← يُفتَحُ، ثم نرفع المفعول به: الكتابُ."}]}]},{"id":"wahi-sharh-017","title":"الجملة الاسمية وصورها","section":"شرح الكتاب: الجملة الاسمية","order":17,"segments":[{"body":["تعريف الجملة الاسمية: «هي الجملة المبدوءة باسم». أي أول كلمة فيها اسم لا فعل. «محمدٌ جالسٌ تحت الشجرة»: بدأت باسم «محمد» فهي جملة اسمية. و«أنا أصلّي في المسجد»: بدأت باسم «أنا» فهي اسمية.","البدء بالاسم قد يكون حقيقة: أن يكون الاسم أول كلمة فعلًا كما في المثالين السابقين. وقد يكون حكمًا: أن يكون الاسم متأخرًا في اللفظ لكنه متقدم في التقدير، نحو: «تحت الشجرةِ محمدٌ جالسٌ»؛ فالأصل «محمد جالس تحت الشجرة»، فهي جملة اسمية حكمًا لأن المبتدأ متقدم في المعنى.","للجملة الاسمية صورتان كبريان: الأولى: الجملة الاسمية الأصلية غير المنسوخة، وتتكون من مبتدأ وخبر مرفوعين، نحو: «محمدٌ كريمٌ». سميناها «غير منسوخة» لأنه لم يدخل عليها شيء يغيّر إعرابها.","الثانية: الجملة الاسمية المنسوخة، وهي التي دخل عليها أحد «نواسخ المبتدأ» الثلاثة فغيّر إعرابها. كلمة «نسخ» هنا معناها: غيّر الحكم.","النواسخ الثلاثة: ١- «كان وأخواتها»: ترفع المبتدأ ويسمى اسمها، وتنصب الخبر ويسمى خبرها، نحو: «كان محمدٌ كريمًا». ٢- «إنَّ وأخواتها»: تنصب المبتدأ ويسمى اسمها، وترفع الخبر ويسمى خبرها، نحو: «إنَّ محمدًا كريمٌ». ٣- «ظننتُ وأخواتها»: تنصب المبتدأ مفعولًا به أولًا وتنصب الخبر مفعولًا به ثانيًا، نحو: «ظننتُ محمدًا كريمًا».","فصور الجملة الاسمية: صورتان إجمالًا: غير منسوخة ومنسوخة. وأربع صور تفصيلًا: مرفوعة الجزأين (محمد كريم)، مرفوعة الأول منصوبة الثاني (كان محمدٌ كريمًا)، منصوبة الأول مرفوعة الثاني (إنَّ محمدًا كريمٌ)، منصوبة الجزأين (ظننتُ محمدًا كريمًا).","وسندرس هذه الصور الأربع بالتفصيل في أربعة أبواب قادمة: المبتدأ والخبر، كان وأخواتها، إن وأخواتها، ظننت وأخواتها."],"examples":["محمدٌ جالسٌ تحت الشجرة: جملة اسمية حقيقة البدء بالاسم","تحت الشجرةِ محمدٌ جالسٌ: جملة اسمية حكمًا (المبتدأ متأخر لفظًا متقدم تقديرًا)","محمدٌ كريمٌ: غير منسوخة - مرفوعة الجزأين","كان محمدٌ كريمًا: منسوخة بكان - مرفوعة الأول منصوبة الثاني","إنَّ محمدًا كريمٌ: منسوخة بإنّ - منصوبة الأول مرفوعة الثاني","ظننتُ محمدًا كريمًا: منسوخة بظن - منصوبة الجزأين"],"questions":[{"question":"ما تعريف الجملة الاسمية؟","options":["الجملة المبدوءة باسم","الجملة المبدوءة بفعل","الجملة التي لا فعل فيها أبدًا","الجملة المنسوخة فقط"],"answer":0,"explanation":"الجملة الاسمية هي التي أولها اسم، حقيقة كـ«محمد جالس» أو حكمًا كـ«تحت الشجرة محمد جالس»."},{"question":"ماذا تعني «منسوخة» في الجملة الاسمية؟","options":["دخل عليها ناسخ فغيّر إعرابها","أنها محذوفة","أنها ملغاة المعنى","أنها منقولة من جملة أخرى"],"answer":0,"explanation":"المنسوخة هي التي دخل عليها أحد النواسخ الثلاثة (كان، إنّ، ظننت وأخواتها) فغيّر رفع جزأيها أو أحدهما."},{"question":"ما النواسخ الثلاثة التي تدخل على الجملة الاسمية؟","options":["كان وأخواتها، إن وأخواتها، ظننت وأخواتها","حروف الجر، أدوات النصب، أدوات الجزم","الفاعل، المفعول، الحال","الماضي، المضارع، الأمر"],"answer":0,"explanation":"نواسخ المبتدأ ثلاثة: كان وأخواتها، وإن وأخواتها، وظننت وأخواتها؛ وكل واحد لها عمل مختلف."},{"question":"ما عمل «كان وأخواتها» في الجملة الاسمية؟","options":["ترفع المبتدأ اسمهَا وتنصب الخبر خبرَها","تنصب المبتدأ وترفع الخبر","تنصبهما معًا","ترفعهما معًا"],"answer":0,"explanation":"كان وأخواتها ترفع المبتدأ ويسمى اسمها، وتنصب الخبر ويسمى خبرها، نحو: كان محمدٌ كريمًا."},{"question":"كم صورة للجملة الاسمية تفصيلًا؟","options":["أربع صور","صورتان","ثلاث صور","خمس صور"],"answer":0,"explanation":"أربع صور: مرفوعة الجزأين، مرفوعة الأول منصوبة الثاني، منصوبة الأول مرفوعة الثاني، منصوبة الجزأين."}]},{"body":["لنثبت الفرق بين النواسخ الثلاثة بجملة واحدة ندخل عليها كل ناسخ: الأصل: «العلمُ نافعٌ» (مبتدأ وخبر مرفوعان).","مع كان: «كان العلمُ نافعًا». رفعت المبتدأ فسمي «اسم كان»، ونصبت الخبر فسمي «خبر كان». لاحظ: اسم كان هو الاسم المرفوع، وخبر كان هو المنصوب.","مع إنّ: «إنَّ العلمَ نافعٌ». نصبت المبتدأ فسمي «اسم إنّ»، ورفعت الخبر فسمي «خبر إنّ». إنّ تعمل عكس كان تمامًا: تنصب الأول وترفع الثاني.","مع ظن: «ظننتُ العلمَ نافعًا». نصبت الاثنين معًا: الأول مفعول به أول، والثاني مفعول به ثان. لأن ظن وأخواتها أفعال تنصب مفعولين أصلهما المبتدأ والخبر.","طريقة سهلة للحفظ: «كان» فعل فهي ترفع ما قبلها (كالفاعل) وتنصب ما بعدها. «إنّ» حرف مشبه بالفعل ينصب ما بعده مباشرة (كالمفعول به) ويرفع الباقي. «ظن» فعل يتعدى لمفعولين فينصبهما.","لماذا سميت هذه الأبواب بأسماء أول أفرادها؟ لأن العلماء يطلقون على الباب اسم أشهر أفراده: فباب «كان» فيه ثلاثة عشر فعلًا، وباب «إنّ» فيه ستة أحرف، وباب «ظننت» فيه أفعال كثيرة كلها تدور على معنى الظن والعلم والحسبان.","تذكير بقاعدة مهمة: الناسخ لا يغيّر معنى الإخبار، بل يضيف معنى جديدًا: كان تفيد الزمن الماضي، وإنّ تفيد التوكيد، وظن تفيد اعتقاد المتكلم."],"examples":["الأصل: العلمُ نافعٌ ← بكان: كان العلمُ نافعًا","الأصل: الجوُّ جميلٌ ← بإنّ: إنَّ الجوَّ جميلٌ","الأصل: الصديقُ مخلصٌ ← بظن: ظننتُ الصديقَ مخلصًا","المؤمنون صادقون ← كان المؤمنون صادقين (خبر منصوب بالياء)","الصلوات الخمس مفروضة ← إنَّ الصلواتِ الخمسَ مفروضةٌ","الطاعةُ خيرٌ ← حسبتُ الطاعةَ خيرًا"],"questions":[{"question":"في «كان العلمُ نافعًا» ما إعراب «العلمُ»؟","options":["اسم كان مرفوع","خبر كان منصوب","مبتدأ مرفوع","مفعول به منصوب"],"answer":0,"explanation":"«العلمُ» اسم كان مرفوع بالضمة؛ لأن كان ترفع المبتدأ ويسمى اسمها وتنصب الخبر."},{"question":"في «إنَّ العلمَ نافعٌ» ما إعراب «نافعٌ»؟","options":["خبر إن مرفوع","اسم إن منصوب","خبر مرفوع للمبتدأ","مفعول به ثان"],"answer":0,"explanation":"«نافعٌ» خبر إنَّ مرفوع بالضمة؛ لأن إنَّ تنصب المبتدأ وترفع الخبر، عكس كان."},{"question":"أي النواسخ تنصب جزأي الجملة الاسمية معًا؟","options":["ظننت وأخواتها","كان وأخواتها","إن وأخواتها","لا ناسخ يفعل ذلك"],"answer":0,"explanation":"ظننت وأخواتها تنصب المبتدأ مفعولًا به أول والخبر مفعولًا به ثانيًا، نحو: ظننتُ محمدًا كريمًا."},{"question":"ما المعنى الذي تفيده «كان» دخولها على الجملة؟","options":["أن الحكم كان في الزمن الماضي","التوكيد","الشك","التمني"],"answer":0,"explanation":"كان تفيد أن الحدث أو الوصف كان في الماضي، مع رفع الاسم ونصب الخبر."},{"question":"أي ناسخ يفيد التوكيد؟","options":["إنَّ وأخواتها","كان وأخواتها","ظننت وأخواتها","ليس بينها ما يفيد التوكيد"],"answer":0,"explanation":"إنَّ حرف توكيد ينصب الاسم ويرفع الخبر؛ وأخواتها أنّ ولعلّ لها معانٍ أخرى ستأتي."}]}]},{"id":"wahi-sharh-018","title":"المبتدأ والخبر: التعريف والحكم","section":"شرح الكتاب: باب المبتدأ والخبر","order":18,"segments":[{"body":["باب المبتدأ والخبر هو أول أبواب الجملة الاسمية. المبتدأ تعريفه: «الاسم الذي لا يحيط به عامل لفظي». لنفهم: «يحيط» أي يسبقه ويعمل فيه. «العامل اللفظي» هو شيء موجود في اللفظ يغيّر إعراب ما بعده. فالاسم الذي لم يسبقه شيء يعمل فيه يكون مبتدأ.","الخبر تعريفه: «الذي أُخبر به عن المبتدأ». أي هو الكلام الذي يخبرنا شيئًا عن المبتدأ ويتم به المعنى. في «محمدٌ كريمٌ»: أخبرنا عن محمد أنه كريم، فـ«كريم» خبر.","المبتدأ لا يكون إلا اسمًا؛ لأن تعريفه قال «الاسم الذي...». أما الخبر فيكون اسمًا وجملةً وشبه جملة كما سيأتي في الدرس التالي.","ما العوامل اللفظية التي إذا سبقت الاسم منعته أن يكون مبتدأ؟ ثلاثة أشياء: ١- الأفعال جميعها (فالاسم بعد الفعل إما فاعل أو مفعول أو نحوهما). ٢- الحروف العاملة كحروف الجر وإنّ وأخواتها (فالاسم بعدها مجرور أو منصوب). ٣- الاسم المضاف (فما بعده مضاف إليه مجرور).","الطريقة العملية: إذا وجدت اسمًا لم يسبقه شيء من هذه الثلاثة فهو عارٍ من العوامل اللفظية، فيكون مبتدأ. وإذا وجدت المبتدأ فابحث عن خبره: اسأل: بماذا أُخبر عنه؟","أمثلة الكتاب: «محمدٌ كريمٌ»: محمد مبتدأ لأنه أول الجملة. «في البيتِ محمودٌ»: محمود مبتدأ لأن ما قبله جار ومجرور ليس عاملًا فيه. «جاء الذي أبوهُ شجاعٌ»: «أبوه» مبتدأ لأن الذي قبله موصول لا يعمل فيه. «جاء محمدٌ يدُهُ على رأسه»: «يده» مبتدأ. «جاء رجلٌ له فضلٌ»: «فضل» مبتدأ.","إعراب المبتدأ والخبر: «فإن كانا معربين فهما مرفوعان»، نحو: «العلمُ نافعٌ»: العلم مبتدأ مرفوع بالضمة، ونافع خبر مرفوع بالضمة. «وإن كانا مبنيين فهما في محل رفع»، نحو: «هذا سيبويهِ»: هذا مبتدأ في محل رفع مبني على السكون، وسيبويه خبر في محل رفع مبني على الكسر (لأنه علم أعجمي)."],"examples":["محمدٌ كريمٌ: «محمد» مبتدأ (عارٍ من العوامل)، «كريم» خبر","في البيتِ محمودٌ: «محمود» مبتدأ متأخر، وشبه الجملة قبله خبر مقدم","جاء الذي أبوه شجاعٌ: «أبوه» مبتدأ و«شجاع» خبره","العلمُ نافعٌ: مبتدأ مرفوع بالضمة + خبر مرفوع بالضمة","هذا سيبويه: مبتدأ في محل رفع مبني على السكون + خبر في محل رفع مبني على الكسر","جاء رجلٌ له فضلٌ: «فضل» مبتدأ والجار والمجرور قبله خبر مقدم"],"questions":[{"question":"ما تعريف المبتدأ؟","options":["الاسم الذي لا يحيط به عامل لفظي","الاسم الذي بعد الفعل","أول كلمة في الكلام مطلقًا","الاسم المرفوع بعد حرف الجر"],"answer":0,"explanation":"المبتدأ هو الاسم العاري من العوامل اللفظية، أي لم يسبقه فعل ولا حرف عامل ولا مضاف يعمل فيه."},{"question":"ما تعريف الخبر؟","options":["الذي أُخبر به عن المبتدأ","الاسم المرفوع دائمًا","الفعل الذي بعد المبتدأ","الجملة الطويلة"],"answer":0,"explanation":"الخبر هو ما أُخبر به عن المبتدأ ويتم به المعنى، ويكون اسمًا أو جملة أو شبه جملة."},{"question":"ما العوامل اللفظية الثلاثة التي تمنع الاسم أن يكون مبتدأ؟","options":["الأفعال جميعها، الحروف العاملة، الاسم المضاف","الضمائر، أسماء الإشارة، الموصولات","الرفع، النصب، الجر","كان، إن، ظن"],"answer":0,"explanation":"ثلاثة: الأفعال كلها، والحروف العاملة كحروف الجر وإن وأخواتها، والاسم المضاف؛ فالاسم بعدها لا يكون مبتدأ."},{"question":"في «في البيتِ محمودٌ» لماذا «محمود» مبتدأ؟","options":["لأن الجار والمجرور قبله ليس عاملًا لفظيًّا فيه","لأنه آخر الجملة","لأنه معرفة","لأن «في» فعل"],"answer":0,"explanation":"الجار والمجرور شبه جملة وليس من العوامل التي تمنع الابتداء؛ فـ«محمود» عارٍ من العوامل اللفظية فيكون مبتدأ."},{"question":"إذا كان المبتدأ والخبر مبنيين فما حكمهما؟","options":["في محل رفع","مرفوعان بالضمة","في محل نصب","لا يجوز أن يكونا مبنيين"],"answer":0,"explanation":"إن كانا معربين فمرفوعان، وإن كانا مبنيين فهما في محل رفع، نحو: هذا سيبويه."}]},{"body":["تدريبات على اكتشاف المبتدأ: القاعدة الذهبية: امشِ في الجملة من أولها، وأول اسم تجده لم يسبقه فعل ولا حرف عامل ولا مضاف فهو المبتدأ، ثم اسأل: ماذا قيل عنه؟ فجوابك هو الخبر.","مثال ١: «الطالبُ المجتهدُ محبوبٌ». أول اسم «الطالب» وقبله شيء؟ لا. فهو مبتدأ. «المجتهد» نعت له. بماذا أخبر؟ «محبوب» خبر مرفوع.","مثال ٢: «الكتبُ النافعةُ زادُ العقلِ». المبتدأ «الكتب» والنعت «النافعة» والخبر «زاد» وهو مضاف و«العقل» مضاف إليه.","لماذا سمي المبتدأ مبتدأ؟ لأننا نبتدئ به الكلام؛ فهو أول ما نذكره في الجملة الاسمية. وسمي الخبر خبرًا لأنه يخبرنا عنه.","ويسمى المبتدأ والخبر معًا: «ركنا الجملة الاسمية»؛ أي عموداها اللذان لا تقوم بدونهما. لا جملة اسمية بلا مبتدأ وخبر.","فرق مهم بين «المبتدأ» و«الفاعل»: كلاهما مرفوع، لكن المبتدأ لم يسبقه عامل أصلًا، والفاعل سبقه فعله. فإن رأيت اسمًا مرفوعًا فاسأل: هل قبله فعل؟ إن نعم فهو فاعل (أو نائبه)، وإن لا فهو مبتدأ (أو اسم ناسخ).","وفرق بين الخبر والنعت: الخبر يتمم جملة مستقلة (محمدٌ كريمٌ)، والنعت وصف تابع لاسم قبله داخل الجملة (جاء محمدٌ الكريمُ). الخبر عمود الجملة، والنعت زينة فيها."],"examples":["الطالبُ المجتهدُ محبوبٌ: مبتدأ + نعت + خبر","الكتبُ النافعةُ زادُ العقلِ: خبر مضاف (زاد) والعقل مضاف إليه","المدرسةُ كبيرةٌ: مبتدأ وخبر بسيطان","الصلاةُ عمودُ الدينِ: مبتدأ وخبر مضاف","اللهُ غفورٌ رحيمٌ: مبتدأ وخبران","البيتُ نظيفٌ: مبتدأ وخبر؛ «جاء البيتُ نظيفًا» هنا نظيفًا حال لأنه سبق بفعل"],"questions":[{"question":"ما الطريقة العملية لاكتشاف المبتدأ؟","options":["أول اسم لا يسبقه فعل ولا حرف عامل ولا مضاف","آخر اسم في الجملة","كل اسم معرفة","كل اسم منصوب"],"answer":0,"explanation":"امشِ من أول الجملة: أول اسم عارٍ من العوامل اللفظية (لم يسبقه فعل ولا حرف عامل ولا مضاف) فهو المبتدأ، ثم ابحث عن خبره."},{"question":"في «الطالبُ المجتهدُ محبوبٌ» ما إعراب «المجتهدُ»؟","options":["نعت مرفوع","خبر مرفوع","مبتدأ ثانٍ","بدل"],"answer":0,"explanation":"«المجتهد» نعت لـ«الطالب» مرفوع؛ لأنه وصف تابع له، والخبر هو «محبوب»."},{"question":"بم سُمي المبتدأ والخبر معًا؟","options":["ركنا الجملة الاسمية","توابع الجملة","نواسخ الكلام","مكملات الجملة"],"answer":0,"explanation":"المبتدأ والخبر ركنا الجملة الاسمية؛ أي عموداها اللذان لا تقوم الجملة بدونهما."},{"question":"ما الفرق بين المبتدأ والفاعل؟","options":["المبتدأ لم يسبقه عامل، والفاعل سبقه فعله","لا فرق بينهما","المبتدأ منصوب والفاعل مرفوع","الفاعل لا يكون إلا ضميرًا"],"answer":0,"explanation":"كلاهما مرفوع؛ لكن المبتدأ عارٍ من العوامل اللفظية، والفاعل اسم رفعه فعلٌ قبله."},{"question":"في «جاء البيتُ نظيفًا» ما إعراب «نظيفًا»؟","options":["حال منصوب","خبر مرفوع","نعت مرفوع","مفعول به"],"answer":0,"explanation":"سبق الجملةَ فعلٌ «جاء» فلا مبتدأ هنا؛ «البيت» فاعل، و«نظيفًا» حال منصوب تبين هيئة البيت وقت المجيء."}]}]},{"id":"wahi-sharh-019","title":"أقسام الخبر الثلاثة","section":"شرح الكتاب: باب المبتدأ والخبر - أقسام الخبر","order":19,"segments":[{"body":["تعلمنا أن المبتدأ لا يكون إلا اسمًا. أما الخبر فيأتي على ثلاثة أقسام: اسمًا مفردًا، وشبه جملة، وجملة. هذا الدرس يفصّلها.","القسم الأول: الخبر المفرد. «المفرد» هنا بمعنى خاص: ما ليس جملة ولا شبه جملة، ولو كان كلمتين مضافتين. أمثلة الكتاب: «القمرُ منيرٌ» خبر مفرد. «القمرُ زينةُ السماءِ»: «زينة» خبر مفرد وهي مضاف، و«السماء» مضاف إليه مجرور. «القمرُ أصغرُ من الشمس»: «أصغر» خبر مفرد. «النجومُ كثيرةٌ»: خبر مفرد.","فلا تغترّ بطول الخبر: «زينة السماء» كلمتان لكنهما ليستا جملة ولا شبه جملة، فالخبر مفرد. والضابط: لو وضعت قبله «هو» لم تقم جملة: «هو زينة السماء» تحتاج إكمالًا؟ في الحقيقة الضابط الأدق: المفرد ما لم يشتمل على فعل ولا جار ومجرور ولا ظرف.","القسم الثاني: خبر شبه الجملة. شبه الجملة = جار ومجرور أو ظرف. نحو: «القمرُ في السماءِ». «في السماء» جار ومجرور، شبيه بالجملة لأنه استغنى بنفسه عن الخبر، لكنه ليس جملة حقيقية لأنه لا فعل فيه ولا مبتدأ. إعرابها: «في» حرف جر، «السماء» مجرور، وشبه الجملة من الجار والمجرور في محل رفع خبر.","مثال آخر بالظرف: «الدرسُ بعدَ الصلاةِ». «بعد» ظرف مكان... بل ظرف زمان مضاف و«الصلاة» مضاف إليه، وشبه الجملة في محل رفع خبر.","القسم الثالث: الخبر الجملة. الجملة نوعان: فعلية واسمية. الفعلية نحو: «القمرُ ينيرُ السماءَ»: «ينير» فعل مضارع مرفوع وفاعله مستتر تقديره «هو» يعود على القمر، و«السماء» مفعول به، وجملة «ينير السماء» في محل رفع خبر. الاسمية نحو: «القمرُ نورُهُ جميلٌ»: «نوره» مبتدأ ثانٍ و«جميل» خبره، وجملة «نوره جميل» في محل رفع خبر عن «القمر».","انتبه: الجملة الواقعة خبرًا لا بد فيها من رابط يعود على المبتدأ: ضمير في الفعلية (ينير: فاعله «هو» = القمر) أو في الاسمية (نورُهُ: الهاء = القمر). هذا الرابط هو الذي يربط الخبر بالمبتدأ."],"examples":["القمرُ منيرٌ: خبر مفرد","القمرُ زينةُ السماءِ: خبر مفرد مضاف (والسماء مضاف إليه)","القمرُ في السماءِ: خبر شبه جملة (جار ومجرور)","الدرسُ بعدَ الصلاةِ: خبر شبه جملة (ظرف)","القمرُ ينيرُ السماءَ: خبر جملة فعلية (فاعلها مستتر «هو» يعود على القمر)","القمرُ نورُهُ جميلٌ: خبر جملة اسمية (الهاء في نوره تعود على القمر)"],"questions":[{"question":"كم قسمًا للخبر؟","options":["ثلاثة: مفرد، وشبه جملة، وجملة","قسمان: اسم وفعل","أربعة أقسام","خمسة أقسام"],"answer":0,"explanation":"الخبر يكون: اسمًا مفردًا (القمر منير)، أو شبه جملة (القمر في السماء)، أو جملة (القمر ينير السماء)."},{"question":"ما معنى «مفرد» في «الخبر المفرد»؟","options":["ما ليس جملة ولا شبه جملة ولو كان مضافًا","كلمة واحدة فقط لا غير","الاسم النكرة","الفعل الماضي"],"answer":0,"explanation":"المفرد هنا ما ليس جملة ولا شبه جملة؛ فـ«زينة السماء» خبر مفرد وإن كان مضافًا لأنه لا فعل فيه ولا حرف جر."},{"question":"ما شبه الجملة؟","options":["الجار والمجرور أو الظرف","الجملة القصيرة","نصف الجملة الفعلية","الفعل والفاعل"],"answer":0,"explanation":"شبه الجملة هي الجار والمجرور (في السماء) أو الظرف (بعد الصلاة)؛ شبيهة بالجملة لاستغنائها عن الخبر."},{"question":"في «القمرُ ينيرُ السماءَ» ما نوع الخبر؟","options":["جملة فعلية في محل رفع خبر","مفرد","شبه جملة","لا خبر فيها"],"answer":0,"explanation":"«ينير السماء» جملة فعلية وقعت خبرًا؛ فاعلها ضمير مستتر تقديره «هو» يعود على المبتدأ «القمر»."},{"question":"ما الذي لا بد منه في الجملة الواقعة خبرًا؟","options":["رابط يعود على المبتدأ","فعل ماضٍ","حرف جر","أداة نفي"],"answer":0,"explanation":"الجملة الخبرية لا بد فيها من رابط يعود على المبتدأ: ضمير مستتر (ينير: هو) أو بارز (نورُهُ: الهاء)."}]},{"body":["تدريب التمييز بين الأقسام الثلاثة: انظر إلى الخبر واسأل: هل فيه فعل؟ إن نعم فهو جملة فعلية. هل هو مبتدأ وخبر؟ فجملة اسمية. هل يبدأ بحرف جر أو ظرف؟ فشبه جملة. غير ذلك فمفرد.","مثال ١: «الطاعةُ طريقُ الجنةِ»: طريق اسم مضاف لا فعل ولا جار → خبر مفرد. مثال ٢: «النعيمُ في الجنةِ»: في الجنة جار ومجرور → شبه جملة. مثال ٣: «العالمُ ينفعُ الناسَ»: ينفع فعل → جملة فعلية. مثال ٤: «العالمُ علمُهُ واسعٌ»: علمه مبتدأ وواسع خبره → جملة اسمية.","لماذا نقول «في محل رفع» للجملة وشبه الجملة؟ لأن الحركات لا تظهر على الجمل كما تظهر على الكلمات؛ فالجملة كتلة واحدة لا تنون ولا تُحرّك آخرها بعلامة الإعراب، فنقول: في محل رفع خبر، أي: مكانها مكان المرفوع.","أما الخبر المفرد فهو كلمة واحدة (أو مضاف) تظهر عليه العلامة مباشرة: «القمرُ منيرٌ»: منير خبر مرفوع وعلامة رفعه الضمة الظاهرة.","حالات خاصة: الخبر قد يتعدد: «اللهُ غفورٌ رحيمٌ» خبران مفردان. وقد يتقدم على المبتدأ وجوبًا أو جوازًا كما في «في البيتِ محمودٌ» حيث تقدمت شبه الجملة خبرًا على المبتدأ؛ وهذا باب طويل سيأتي في موضعه من الكتاب بإذن الله.","الخلاصة: خبرك إما كلمة، أو جار ومجرور/ظرف، أو جملة كاملة. والمبتدأ لا يكون إلا اسمًا. احفظ هذا المثلث: مفرد - شبه جملة - جملة، وتمرن على تصنيف الأخبار في كلامك اليومي: «الطعامُ لذيذٌ» (مفرد)، «المالُ في البنكِ» (شبه جملة)، «الطفلُ يلعبُ» (جملة فعلية)، «الطفلُ لعبتُهُ جميلةٌ» (جملة اسمية)."],"examples":["الطاعةُ طريقُ الجنةِ: مفرد","النعيمُ في الجنةِ: شبه جملة","العالمُ ينفعُ الناسَ: جملة فعلية","العالمُ علمُهُ واسعٌ: جملة اسمية","الطعامُ لذيذٌ: مفرد","الطفلُ لعبتُهُ جميلةٌ: جملة اسمية"],"questions":[{"question":"«المالُ في البنكِ» - ما نوع الخبر؟","options":["شبه جملة","مفرد","جملة فعلية","جملة اسمية"],"answer":0,"explanation":"«في البنك» جار ومجرور = شبه جملة في محل رفع خبر المبتدأ «المال»."},{"question":"«الطفلُ لعبتُهُ جميلةٌ» - ما نوع الخبر؟","options":["جملة اسمية","جملة فعلية","مفرد","شبه جملة"],"answer":0,"explanation":"«لعبتُهُ جميلةٌ» جملة اسمية: مبتدأ «لعبته» (والهاء رابط يعود على الطفل) وخبرها «جميلة»، والجملة في محل رفع خبر."},{"question":"لماذا نقول في الجملة الخبرية «في محل رفع» لا «مرفوعة»؟","options":["لأن العلامات لا تظهر على الجمل فنقدّر لها محلًّا","لأنها منصوبة في الأصل","لأنها مبنية على السكون","لأن الجمل لا تُعرب أبدًا"],"answer":0,"explanation":"الجملة كتلة لا تظهر عليها علامات الإعراب؛ فنقول: في محل رفع، أي مكانها مكان الاسم المرفوع."},{"question":"«اللهُ غفورٌ رحيمٌ» - ماذا فيها؟","options":["خبران مفردان","خبر واحد منصوب","نعتان فقط","شبه جملة"],"answer":0,"explanation":"«غفور» خبر أول مرفوع و«رحيم» خبر ثانٍ مرفوع؛ يجوز تعدد الأخبار للمبتدأ الواحد."},{"question":"صنّف خبر «الطالبُ يقرأُ درسَهُ»:","options":["جملة فعلية في محل رفع خبر","مفرد","شبه جملة","نعت"],"answer":0,"explanation":"«يقرأ درسه» جملة فعلية: فعل مضارع وفاعله مستتر «هو» رابط يعود على الطالب، والجملة في محل رفع خبر."}]}]},{"id":"wahi-sharh-020","title":"كان وأخواتها","section":"شرح الكتاب: باب كان وأخواتها","order":20,"segments":[{"body":["«كان وأخواتها» أول النواسخ التي تدخل على الجملة الاسمية. وهي ثلاثة عشر فعلًا: كان، أصبح، أضحى، أمسى، ظلّ، بات، صار، ليس، ما زال، ما انفكّ، ما فتئ، ما برح، ما دام.","عملها: «ترفع المبتدأ ويُعرب اسمَها، وتنصب الخبر ويُعرب خبرَها». يعني تدخل على المبتدأ والخبر فتبقي الأول مرفوعًا لكن نغيّر اسمه إلى «اسم كان»، وتنصب الثاني ونسميه «خبر كان».","«وأما هي في نفسها تُعرب إعراب الفعل ماضيًا ومضارعًا وأمرًا»: أي أن كان وأخواتها أفعال، فنعربها إعراب الأفعال: الماضي مبني على الفتح، والمضارع مرفوع، والأمر مبني على السكون.","مثال الكتاب المعرب: «كان بلالٌ مؤمنًا»: كان: فعل ماضٍ ناسخ، مبني على الفتح، لا محل له من الإعراب. بلالٌ: اسم كان، مرفوع، وعلامة رفعه الضمة. مؤمنًا: خبر كان، منصوب، وعلامة نصبه الفتحة.","«وما زال صابرًا»: ما: حرف نفي مبني على السكون لا محل له من الإعراب. زال: فعل ماضٍ ناسخ مبني على الفتح لا محل له من الإعراب، واسمها ضمير مستتر تقديره «هو». صابرًا: خبر زال، منصوب، وعلامة نصبه الفتحة.","معاني الأخوات: أصبح وأضحى وأمسى وظل وبات: أفعال تدل على أوقات اليوم (الصباح والضحى والمساء والنهار والليل). صار: بمعنى تحوّل. ليس: للنفي. ما زال وما انفك وما فتئ وما برح وما دام: بمعنى الاستمرار (ما زال = لا يزال مستمرًّا).","أمثلة قرآنية وعامة من الكتاب: «وصار المؤذنُ» أي صار مؤذنًا. «وتصير البناتُ هادياتٍ». «وأضحى شاكرًا». «يا ليتاني كنتُ داعيًا». «ولا تكونوا مُخطئين». كلها ترفع الاسم وتنصب الخبر."],"examples":["كان بلالٌ مؤمنًا: كان فعل ماضٍ ناسخ + اسمها مرفوع + خبرها منصوب","ما زال صابرًا: ما نافية + زال فعل ناسخ اسمها مستتر + خبر منصوب","أصبح الجوُّ صحوًا: أصبح ناسخة والجو اسمها وصحوًا خبرها","ليس العلمُ عائبًا: ليس ناسخة نافية","ما دام المؤمنُ ذاكرًا: ما دام بمعنى الاستمرار","صار الماءُ ثلجًا: صار بمعنى التحول"],"questions":[{"question":"كم عدد أفعال «كان وأخواتها»؟","options":["ثلاثة عشر فعلًا","خمسة أفعال","سبعة أفعال","عشرون فعلًا"],"answer":0,"explanation":"ثلاثة عشر: كان، أصبح، أضحى، أمسى، ظل، بات، صار، ليس، ما زال، ما انفك، ما فتئ، ما برح، ما دام."},{"question":"ما عمل «كان وأخواتها»؟","options":["ترفع المبتدأ اسمَها وتنصب الخبر خبرَها","تنصب المبتدأ وترفع الخبر","تنصبهما","ترفعهما"],"answer":0,"explanation":"ترفع المبتدأ ويسمى اسمها، وتنصب الخبر ويسمى خبرها، نحو: كان بلالٌ مؤمنًا."},{"question":"في «كان بلالٌ مؤمنًا» ما إعراب «كان»؟","options":["فعل ماضٍ ناسخ مبني على الفتح لا محل له من الإعراب","حرف ناسخ","فعل مضارع مرفوع","فعل ماضٍ مبني على الضم"],"answer":0,"explanation":"كان فعل ماضٍ ناسخ؛ الأفعال الماضية مبنية على الفتح لا محل لها من الإعراب، ونعمل عملها فيما بعدها."},{"question":"ما معنى «ما زال»؟","options":["الاستمرار","التحول","النفي المحض","الوقت"],"answer":0,"explanation":"ما زال وما انفك وما فتئ وما برح وما دام تفيد الاستمرار: ما زال صابرًا = لا يزال مستمرًّا في الصبر."},{"question":"ما إعراب «مؤمنًا» في «كان بلالٌ مؤمنًا»؟","options":["خبر كان منصوب وعلامة نصبه الفتحة","اسم كان مرفوع","مفعول به منصوب","حال منصوب"],"answer":0,"explanation":"«مؤمنًا» خبر كان منصوب بالفتحة؛ لأن كان تنصب الخبر بعد أن ترفع المبتدأ اسمًا لها."}]},{"body":["تدريب إعرابي كامل على كان وأخواتها. مثال: «أمسى الطقسُ باردًا». أمسى: فعل ماضٍ ناسخ مبني على الفتح لا محل له من الإعراب. الطقسُ: اسم أمسى مرفوع بالضمة. باردًا: خبر أمسى منصوب بالفتحة.","مع الضمائر: «كنتُ مجتهدًا»: كان فعل ماضٍ ناسخ مبني على السكون لاتصاله بتاء المتكلم، والتاء ضمير بارز مبني على الضم في محل رفع اسم كان، و«مجتهدًا» خبر كان منصوب.","مع المضارع: «يكون الجزاءُ من جنس العملِ»: يكون فعل مضارع ناسخ مرفوع بالضمة، والجزاء اسم يكون مرفوع، و«من جنس العمل» شبه جملة في محل نصب خبر يكون. فخبر الناسخ قد يكون شبه جملة وجملة كالخبر الأصلي.","مع الجموع: «كان المعلمون مخلصين»: كان ناسخة، المعلمون اسم كان مرفوع وعلامة رفعه الواو (جمع مذكر سالم)، مخلصين خبر كان منصوب وعلامة نصبه الياء.","قاعدة مساعدة للحفظ: «كان» فعل ماضٍ أصله، فعاملها عامل الفعل: يرفع ما قبله (كالفاعل) وينصب ما بعده (كالمفعول به)؛ لكننا نسميهما اسمًا وخبرًا لا فاعلًا ومفعولًا، لأنهما أصلًا مبتدأ وخبر.","كيف تميز خبر كان عن المفعول به؟ بالإعادة إلى الأصل: انزع الناسخ، فإن عادت الجملة «مبتدأ + خبر» فهو خبر كان: «كان العلمُ نافعًا» → «العلمُ نافعٌ» جملة اسمية صحيحة. أما «ضرب زيدٌ عمرًا» فإن نزعت الفعل بقي «زيد عمر» بلا معنى، فعمر مفعول به لا خبر.","الخلاصة: كان وأخواتها أفعال ناقصة - سميت ناقصة لأنها لا تكتفي بفاعلها بل تحتاج خبرًا - ترفع الاسم وتنصب الخبر، وتفيد معاني زمنية أو تحولًا أو نفيًا أو استمرارًا."],"examples":["أمسى الطقسُ باردًا: اسم أمسى مرفوع + خبرها منصوب","كنتُ مجتهدًا: التاء اسم كان في محل رفع","يكون الجزاءُ من جنس العمل: خبر يكون شبه جملة في محل نصب","كان المعلمون مخلصين: اسم بالواو وخبر بالياء","ما برحوا قائمين: اسمها واو الجماعة وخبرها منصوب بالياء","ليس الذنبُ صغيرًا: ليس ناسخة نافية"],"questions":[{"question":"أعرب: «أمسى الطقسُ باردًا» - كلمة «الطقسُ»:","options":["اسم أمسى مرفوع وعلامة رفعه الضمة","فاعل مرفوع","خبر أمسى منصوب","مبتدأ مرفوع"],"answer":0,"explanation":"«الطقسُ» اسم أمسى مرفوع بالضمة؛ لأن أمسى من أخوات كان التي ترفع المبتدأ ويسمى اسمها."},{"question":"في «كنتُ مجتهدًا» ما اسم كان؟","options":["تاء المتكلم في محل رفع","مجتهدًا","ضمير مستتر تقديره أنا","كان نفسها"],"answer":0,"explanation":"التاء ضمير بارز مبني على الضم في محل رفع اسم كان، ومجتهدًا خبرها منصوب."},{"question":"هل يأتي خبر كان شبه جملة؟","options":["نعم مثل: يكون الجزاءُ من جنس العمل","لا، مفرد فقط","لا، جملة فعلية فقط","لا، نكرة فقط"],"answer":0,"explanation":"خبر الناسخ يأتي مفردًا وشبه جملة وجملة مثل الخبر الأصلي: «يكون الجزاءُ من جنس العملِ» خبرها شبه جملة في محل نصب."},{"question":"كيف تميز خبر كان من المفعول به؟","options":["انزع الناسخ: إن صحت الجملة مبتدأ وخبر فهو خبر","بالحركة فقط","بالطول","لا فرق بينهما"],"answer":0,"explanation":"أعد الجملة لأصلها: «كان العلم نافعًا» → «العلم نافع» صحيحة فهو خبر؛ أما بعد الأفعال المتعدية فلا يصح ذلك."},{"question":"لماذا سميت كان وأخواتها أفعالًا ناقصة؟","options":["لأنها لا تكتفي بفاعلها بل تحتاج إلى خبر","لأنها قصيرة الحروف","لأنها لا تتصرف","لأنها ناقصة المعنى دائمًا"],"answer":0,"explanation":"سميت ناقصة لأنها لا يتم معناها بمجرد رفع اسمها، بل تحتاج إلى خبر يتمم المعنى: كان بلالٌ مؤمنًا."}]}]},{"id":"wahi-sharh-021","title":"إنَّ وأخواتها","section":"شرح الكتاب: باب إنَّ وأخواتها","order":21,"segments":[{"body":["الناسخ الثاني: «إنَّ وأخواتها». وهي ستة أحرف - وليست أفعالًا ككان: إنّ، أنّ، لكنّ، كأنّ، لعلّ، ليت.","معانيها كما في الكتاب: «إنّ وأنّ» للتوكيد (أي تقوية الكلام وتثبيته). «لكنّ» للاستدراك (تصحيح ما قبلها). «كأنّ» للتشبيه. «لعلّ» للترجي في المحبوب (الطمع في شيء نحبه) وللإخافة في المكروه. «ليت» للتمني (طلب شيء محبوب يصعب حصوله).","عملها: «تنصب المبتدأ ويُعرب اسمَها، وترفع الخبر ويُعرب خبرَها». عكس كان تمامًا: تنصب الأول وترفع الثاني.","«وأما هي في نفسها تُعرب إعراب الحروف»: أي أنها حروف، والحروف مبنية لا محل لها من الإعراب، نضيف وصف عملها: حرف توكيد ينصب اسمه ويرفع خبره.","أمثلة الكتاب المعربة: «إنَّ نورًا جميلةٌ» (الأصل: إن نورَهُ جميلة): إنّ: حرف توكيد ينصب اسمه ويرفع خبره، مبني على الفتح، لا محل له من الإعراب. نورًا: اسم إنّ منصوب بالفتحة. جميلة: خبر إنّ مرفوع بالضمة.","«وكأنَّها بدرٌ»: كأنّ: حرف تشبيه ينصب اسمه ويرفع خبره، مبني على الفتح لا محل له من الإعراب. ها: اسم كأنّ في محل نصب مبني على السكون. بدرٌ: خبر كأنّ مرفوع بالضمة. لاحظ: الضمير اسم كأنّ يكون في محل نصب لأنه مبني.","«وليتَ الصيفَ باردٌ»: ليت: حرف تمنٍّ ينصب اسمه ويرفع خبره، مبني على الفتح لا محل له من الإعراب. الصيفَ: اسم ليت منصوب بالفتحة. باردٌ: خبر ليت مرفوع بالضمة."],"examples":["إنَّ العلمَ نورٌ: إنّ للتوكيد، العلمَ اسمها منصوب، نورٌ خبرها مرفوع","أنَّ الصلاةَ عمادُ الدينِ: أنّ للتوكيد مثل إنّ","ما جاء كسلانُ لكنَّ مجتهدًا: لكنّ للاستدراك","كأنَّ القمرَ مصباحٌ: كأنّ للتشبيه","لعلَّ المطرَ قريبٌ: لعلّ للترجي في المحبوب","ليتَ الصيفَ باردٌ: ليت للتمني"],"questions":[{"question":"كم عدد أحرف «إنَّ وأخواتها»؟","options":["ستة أحرف","ثلاثة عشر","خمسة","أربعة"],"answer":0,"explanation":"ستة: إنّ وأنّ للتوكيد، لكنّ للاستدراك، كأنّ للتشبيه، لعلّ للترجي أو الإخافة، ليت للتمني."},{"question":"ما عمل «إنَّ وأخواتها»؟","options":["تنصب المبتدأ اسمَها وترفع الخبر خبرَها","ترفع المبتدأ وتنصب الخبر","تنصبهما معًا","ترفعهما معًا"],"answer":0,"explanation":"تنصب المبتدأ ويسمى اسمها وترفع الخبر ويسمى خبرها؛ عكس عمل كان."},{"question":"ما معنى «لعلّ»؟","options":["الترجي في المحبوب والإخافة في المكروه","التوكيد","التمني","التشبيه"],"answer":0,"explanation":"لعلّ للترجي في المحبوب (لعل المطر قريب) وللإخافة في المكروه (لعل الامتحان صعب)."},{"question":"ما إعراب «إنّ» نفسها؟","options":["حرف توكيد ينصب اسمه ويرفع خبره مبني على الفتح لا محل له من الإعراب","فعل ماضٍ ناسخ","اسم مرفوع","حرف جر"],"answer":0,"explanation":"إنّ حرف، والحروف مبنية لا محل لها من الإعراب؛ وهي مبنية على الفتح، توصف بعملها: ينصب اسمه ويرفع خبره."},{"question":"في «كأنَّها بدرٌ» ما إعراب «ها»؟","options":["اسم كأنّ في محل نصب مبني على السكون","خبر كأنّ مرفوع","مفعول به","فاعل"],"answer":0,"explanation":"الضمير «ها» اسم كأنّ؛ ولأنه مبني على السكون نقول: في محل نصب، والخبر «بدر» مرفوع بالضمة."}]},{"body":["تدريبات إعرابية متنوعة: «إنَّ المتقينَ في جناتٍ ونهرٍ»: إنّ حرف توكيد مبني على الفتح لا محل له. المتقينَ: اسم إنّ منصوب وعلامة نصبه الياء (جمع مذكر سالم). في جنات: جار ومجرور شبه جملة في محل رفع خبر إنّ.","مع المثنى: «إنَّ المؤمنَينِ فائزانِ»: المؤمنَين اسم إنّ منصوب بالياء (مثنى)، وفائزان خبر إنّ مرفوع بالألف (مثنى). لاحظ: علامة النصب في المثنى والجمع هي الياء، وعلامة الرفع الألف في المثنى والواو في جمع المذكر السالم.","مع كأنّ: «كأنَّ الشمسَ مصباحٌ»: كأنّ حرف تشبيه مبني على الفتح، الشمسَ اسمها منصوب بالفتحة، مصباح خبرها مرفوع بالضمة.","مع لكنّ: «ما فشلَ أحدٌ لكنَّ الكسلَ عدوُّ النجاحِ»: لكنّ حرف استدراك، الكسلَ اسمها منصوب، عدوُّ خبرها مرفوع (وهو مضاف والنجاح مضاف إليه).","قاعدة الحفظ السهلة: إنّ وأخواتها أحرف «مشبهة بالفعل» لأنها تنصب الاسم بعدها كما ينصب الفعل مفعوله. وذاكر بالمقارنة: كان فعل حقيقي يرفع الأول، وإنّ حرف ينصب الأول. والنتيجة معكوسة: كان: رفع + نصب. إنّ: نصب + رفع.","متى نستخدم كل حرف؟ إنّ/أنّ: لتقوية الخبر: «إنَّ الصدقَ نجاةٌ». لكنّ: لتصحيح فهم سامعك: «ما الكسلُ طريقًا لكنَّ الاجتهادَ». كأنّ: لتقريب الصورة: «كأنَّ العلمَ بحرٌ». لعلّ: رجاء أو تخويف. ليت: أمنية بعيدة: «ليتَ الشبابَ يعودُ».","الخلاصة: إنّ وأخواتها حروف ناسخة ستة، تنصب الاسم وترفع الخبر، وتفيد معاني التوكيد والاستدراك والتشبيه والترجي والتمني."],"examples":["إنَّ المتقينَ في جنات: اسم منصوب بالياء وخبر شبه جملة في محل رفع","إنَّ المؤمنَينِ فائزانِ: مثنى: اسم بالياء وخبر بالألف","كأنَّ الشمسَ مصباحٌ: تشبيه","لكنَّ الكسلَ عدوُّ النجاحِ: استدراك","إنَّ الصدقَ نجاةٌ: توكيد","ليتَ الشبابَ يعودُ: تمنٍّ وخبرها جملة فعلية"],"questions":[{"question":"أعرب «المتقينَ» في «إنَّ المتقينَ في جناتٍ»:","options":["اسم إنّ منصوب وعلامة نصبه الياء","اسم إنّ منصوب بالفتحة","خبر إنّ مرفوع بالواو","مبتدأ مرفوع"],"answer":0,"explanation":"المتقين جمع مذكر سالم؛ اسم إنّ منصوب وعلامة نصبه الياء لأنه جمع مذكر سالم، والخبر شبه الجملة بعده في محل رفع."},{"question":"في «إنَّ المؤمنَينِ فائزانِ» ما علامة رفع «فائزان»؟","options":["الألف لأنه مثنى","الضمة","الواو","الفتحة"],"answer":0,"explanation":"فائزان خبر إنّ مرفوع وعلامة رفعه الألف لأنه مثنى؛ والمثنى يرفع بالألف وينصب ويجر بالياء."},{"question":"لماذا تسمى إنّ وأخواتها «الحروف المشبهة بالفعل»؟","options":["لأنها تنصب الاسم بعدها كما ينصب الفعل مفعوله","لأنها أفعال أصلًا","لأنها ترفع الفاعل","لأنها تسبق الأفعال دائمًا"],"answer":0,"explanation":"لأن عملها في نصب الاسم الذي يليها يشبه عمل الفعل في مفعوله، مع أنها حروف مبنية لا أفعال."},{"question":"ما معنى «لكنّ» ومثالها؟","options":["الاستدراك، نحو: ما جاء كسلانُ لكنَّ مجتهدًا","التمني: ليت الشباب يعود","التشبيه: كأن القمر بدر","الترجي: لعل المطر قريب"],"answer":0,"explanation":"لكنّ للاستدراك: تصحيح ما وقع في ذهن السامع؛ تنصب الاسم وترفع الخبر كإخوتها."},{"question":"أي الجمل صحيحة الإعراب؟","options":["إنَّ العلمَ نافعٌ","إنَّ العلمُ نافعٌ","إنَّ العلمَ نافعًا","إنَّ العلمُ نافعًا"],"answer":0,"explanation":"الصواب: إنَّ العلمَ نافعٌ: تنصب إنّ المبتدأ (العلمَ) وترفع الخبر (نافعٌ)."}]}]},{"id":"wahi-sharh-022","title":"لا النافية للجنس","section":"شرح الكتاب: مسألة لا النافية للجنس","order":22,"segments":[{"body":["مسألة مستقلة ملحقة بباب إنّ: «لا النافية للجنس». هي حرف نفي يعمل عمل إنّ: ينصب الاسم ويرفع الخبر. سميت «نافية للجنس» لأنها تنفي الحكم عن الجنس كله: «لا كريمَ مذمومٌ» أي لا يوجد كريم واحد مذموم أبدًا.","قال الكتاب: «تعمل لا النافية للجنس عمل إنّ إلا أن اسمها لا يُنوَّن» - أي لا يقبل التنوين - «بشرط أن يكون اسمها وخبرها نكرتين، وأن تتصل باسمها، وألا يتوسط حرفٌ بينها وبين اسمها، وألا تتكرر». لنفهم الشروط:","الشرط الأول: اسمها وخبرها نكرتان. «لا كريمَ مذمومٌ»: كريم نكرة ومذموم نكرة. فإن كان أحدهما معرفة لم تعمل: «لا الكريمُ مذمومٌ» هنا لا نافية عادية لا عمل لها.","الشرط الثاني: أن تتصل باسمها: تليه مباشرة. والثالث: ألا يتوسط حرف بينها وبين اسمها. والرابع: ألا تتكرر؛ فإن تكررت بطل عمل الثانية: «لا كريمٌ ولا بخيلٌ محبوبٌ» الثانية لا عمل لها.","إعراب أمثلة الكتاب: «لا كريمَ مذمومٌ»: لا النافية للجنس: حرف نفي ينصب اسمه ويرفع خبره، مبني على السكون، لا محل له من الإعراب. كريمَ: اسم لا منصوب بالفتحة. مذمومٌ: خبر لا مرفوع بالضمة.","«لا طلابَ في الفصلِ»: طلابَ: اسم لا منصوب بالفتحة. في الفصل: جار ومجرور وهو شبه جملة خبر لا النافية للجنس في محل رفع.","«لا متوازِنَين متقاطعانِ»: متوازِنين: اسم لا منصوب وعلامة نصبه الياء لأنه مثنى. متقاطعان: خبر لا مرفوع وعلامة رفعه الألف لأنه مثنى. و«لا مؤمنين كذّابونَ»: مؤمنين اسم لا منصوب بالياء، كذّابون خبر لا مرفوع بالواو."],"examples":["لا كريمَ مذمومٌ: اسم لا منصوب + خبر مرفوع","لا طلابَ في الفصلِ: خبرها شبه جملة في محل رفع","لا متوازِنَين متقاطعانِ: مثنى: اسم بالياء وخبر بالألف","لا مؤمنين كذّابونَ: جمع: اسم بالياء وخبر بالواو","لا بخيلَ محبوبٌ: نفي الجنس كله","لا صديقَ كالوفيِّ: نفي الجنس"],"questions":[{"question":"ما عمل «لا النافية للجنس»؟","options":["تنصب الاسم وترفع الخبر كعمل إنّ","ترفع الاسم وتنصب الخبر","تنفي بلا عمل إعرابي","تجزم الفعل المضارع"],"answer":0,"explanation":"تعمل عمل إنّ: تنصب الاسم ويسمى اسمها وترفع الخبر ويسمى خبرها، بشروط خاصة."},{"question":"لماذا سميت «نافية للجنس»؟","options":["لأنها تنفي الحكم عن الجنس كله","لأنها تنفي الأفعال","لأنها تلي الأجناس","لأنها جنس من الحروف"],"answer":0,"explanation":"لأنها تنفي الحكم عن كل أفراد الجنس: لا كريمَ مذمومٌ = لا يوجد كريم مذموم البتة."},{"question":"ما شرط عمل لا النافية للجنس في الاسم والخبر؟","options":["أن يكونا نكرتين","أن يكونا معرفتين","أن يكون الاسم مفردًا","أن يكون الخبر جملة"],"answer":0,"explanation":"من شروط عملها أن يكون اسمها وخبرها نكرتين؛ فإن كان أحدهما معرفة لم تعمل وكانت نافية مهملة."},{"question":"ما إعراب «لا» النافية للجنس نفسها؟","options":["حرف نفي ينصب اسمه ويرفع خبره مبني على السكون لا محل له من الإعراب","فعل ناسخ","اسم منصوب","حرف جر"],"answer":0,"explanation":"هي حرف مبني على السكون لا محل له من الإعراب، يوصف بعمله: ينصب اسمه ويرفع خبره."},{"question":"ما الذي يميز اسم لا النافية للجنس شكلًا؟","options":["لا يُنوَّن","يكون معرفة بأل","يكون جمعًا دائمًا","يكون مبنيًّا"],"answer":0,"explanation":"اسم لا النافية للجنس لا يُنوَّن أبدًا: نقول «لا كريمَ» ولا نقول «لا كريمًا» بالتنوين."}]},{"body":["تدريب: كيف تفرق بين لا النافية للجنس ولا النافية العادية؟ انظر بعد لا: إن كان اسمًا نكرة مباشرة فهي نافية للجنس واسمها منصوب بلا تنوين: «لا مشغولَ بخيرٍ». وإن كان بعدها فعل فهي نافية عادية: «لا يغيبُ المؤمنُ». وإن كان بعدها معرفة فعادية: «لا الكسلُ ينفعُ».","إعراب متنوع مع الأسماء الخمسة: «لا أبَ له عن دينه حائلٌ»: الأسماء الخمسة (أب، أخ، حم، فو، ذو) تنصب بالألف وترفع بالواو وتجر بالياء. فالأسماء الخمسة قد تقع اسمَ لا وتنصب بالألف.","مع النعت: «لا رجلَ كريمٌ يُذمُّ»: رجل اسم لا منصوب، كريم نعت له منصوب، والجملة الفعلية خبرها في محل رفع. النعت يتبع المنعوت في النصب.","ملاحظة مهمة: خبر لا قد يتقدم على اسمها: «لا في البيتِ أحدٌ»: في البيت شبه جملة خبر مقدم في محل رفع، وأحد اسم لا مؤخر منصوب. التقديم جائز هنا.","الفرق بين إنّ ولا في الشكل: اسم إنّ يُنوَّن (إنَّ كريمًا ممدودٌ) واسم لا لا يُنوَّن (لا كريمَ مذمومٌ). هذه علامة سريعة تميز البابين في النظر.","الخلاصة: لا النافية للجنس حرف نفي يعمل عمل إنّ ينصب الاسم ويرفع الخبر، بشروط: اسمها وخبرها نكرتان، تتصل باسمها، لا حرف يتوسط، ولا تتكرر. واسمها لا يُنوَّن."],"examples":["لا مشغولَ بخيرٍ: نافية للجنس، اسمها منصوب بلا تنوين","لا يغيبُ المؤمنُ: لا نافية عادية (بعدها فعل)","لا في البيتِ أحدٌ: خبر مقدم شبه جملة واسم مؤخر منصوب","لا أبَ له حائلٌ: اسم لا من الأسماء الخمسة منصوب بالألف","لا رجلَ كريمٌ يُذمُّ: النعت يتبع الاسم في النصب","لا كريمٌ ولا بخيلٌ محبوبٌ: تكررت لا فبطل عملها"],"questions":[{"question":"كيف تفرق بين لا النافية للجنس ولا العادية؟","options":["إن لحقها اسم نكرة مباشرة فهي نافية للجنس","لا فرق بينهما","العادية تنصب الاسم","نافية الجنس تليها الأفعال"],"answer":0,"explanation":"إن جاء بعدها اسم نكرة متصل بها فهي نافية للجنس تنصبه؛ وإن جاء بعدها فعل أو معرفة فهي نافية عادية لا عمل لها."},{"question":"في «لا في البيتِ أحدٌ» ما إعراب «أحدٌ»؟","options":["اسم لا النافية للجنس منصوب مؤخر","مبتدأ مرفوع","فاعل مرفوع","خبر مقدم"],"answer":0,"explanation":"تقدم الخبر (شبه الجملة في البيت) على الاسم: أحد اسم لا النافية للجنس منصوب بالفتحة مؤخرًا، وهذا جائز."},{"question":"ماذا يحدث إذا تكررت لا النافية للجنس؟","options":["يبطل عملها ويصح تنوين ما بعدها","يعمل كلاهما","تصبح جازمة","ينصب الاسم تنوينًا"],"answer":0,"explanation":"من شروط عملها ألا تتكرر؛ فإن تكررت بطل عملها: لا كريمٌ ولا بخيلٌ محبوبٌ - بالتنوين."},{"question":"«لا متوازِنَين متقاطعانِ» - ما علامتا الإعراب؟","options":["اسمها منصوب بالياء وخبرها مرفوع بالألف","كلاهما بالضمة","اسمها بالفتحة وخبرها بالضمة","كلاهما بالياء"],"answer":0,"explanation":"متوازنين مثنى اسم لا منصوب بالياء، ومتقاطعان مثنى خبر لا مرفوع بالألف؛ فالمثنى يرفع بالألف وينصب بالياء."},{"question":"لماذا لا يُنوَّن اسم لا النافية للجنس؟","options":["لأن لا تتصل به اتصالًا يمنع التنوين وهذه صفتها الدائمة","لأنه معرفة","لأنه مبني","لأنه ممنوع من الصرف"],"answer":0,"explanation":"اسم لا النافية للجنس لا يُنوَّن أبدًا وهذه علامته المميزة عن اسم إنّ الذي يُنوَّن."}]}]},{"id":"wahi-sharh-023","title":"ظننت وأخواتها","section":"شرح الكتاب: باب ظننت وأخواتها","order":23,"segments":[{"body":["الناسخ الثالث: «ظننت وأخواتها». وهي أفعال كثيرة تنقسم في معناها ثلاثة أقسام: أولًا: «ظنّ ومعناها: وجد وخال» أي بمعنى اعتقد. ثانيًا: «علم ومعناها: رأى ووجد وألفى». ثالثًا: «حَسِبَ ومعناها: جعل واتخذ».","أمثلتها: باب اليقين أو الظن الراجح: ظنّ، خال، حسب، زعم، علم، وجد، ألفى، رأى، جعل، اتخذ، ونحوها. كلها أفعال تعتمد على اعتقاد المتكلم.","عملها: «تنصب المبتدأ مفعولًا به أولًا، وتنصب الخبر ويُعرب مفعولًا به ثانيًا». أي تحوّل المبتدأ والخبر إلى مفعولين منصوبين. لأنها أفعال متعدية لمفعولين أصلهما المبتدأ والخبر.","«وأما هي في نفسها تُعرب إعراب الفعل ماضيًا ومضارعًا وأمرًا. وهي لا تدل على المبتدأ والخبر حتى تستوفي فاعلها»: أي أنها أفعال كاملة تحتاج فاعلًا ثم مفعولين.","مثال الكتاب المعرب: «ظنَّ قيسٌ معاذًا مسافرًا»: ظنّ: فعل ماضٍ ينصب مفعولين، مبني على الفتح، لا محل له من الإعراب. قيسٌ: فاعل مرفوع بالضمة. معاذًا: مفعول به أول منصوب بالفتحة. مسافرًا: مفعول به ثانٍ منصوب بالفتحة.","«وعلمتُ اللهَ عظيمًا»: علمت فعل ماضٍ مبني على الفتح، والتاء فاعل في محل رفع، والله مفعول أول منصوب، وعظيمًا مفعول ثانٍ منصوب. «ورأيتُ ليلى العذراءَ» الأصل: رأيت ليلى عاشقةً... والمعنى: اعتقدت.","كيف تعرف أن المفعولين أصلهما مبتدأ وخبر؟ اختبار سهل: ضع قبل المفعول الأول «كان» فإن صح المعنى فهما أصلًا مبتدأ وخبر: «ظننت العلمَ نافعًا» → «كان العلمُ نافعٌ» → صح. إذن هما مبتدأ وخبر أصلًا."],"examples":["ظنَّ قيسٌ معاذًا مسافرًا: فعل + فاعل + مفعول أول + مفعول ثانٍ","علمتُ اللهَ عظيمًا: التاء فاعل والله مفعول أول وعظيمًا مفعول ثانٍ","رأيتُ الطالبَ مجتهدًا: رأى هنا بمعنى ظنّ","حسبتُ الصدقَ منجاةً: حسب بمعنى اعتقد","وجدتُ الصبرَ مفتاحَ الفرجِ: وجد بمعنى علم","خالَ زيدٌ عمرًا مسافرًا: خال بمعنى ظن"],"questions":[{"question":"ما عمل «ظننت وأخواتها»؟","options":["تنصب المبتدأ مفعولًا أول والخبر مفعولًا ثانيًا","ترفع المبتدأ وتنصب الخبر","تنصب المبتدأ وترفع الخبر","ترفعهما معًا"],"answer":0,"explanation":"تنصب المبتدأ مفعولًا به أولًا وتنصب الخبر مفعولًا به ثانيًا؛ لأنها أفعال تنصب مفعولين أصلهما المبتدأ والخبر."},{"question":"ما الأقسام الثلاثة لمعاني أفعال الظن؟","options":["ظن بمعنى وجد وخال، علم بمعنى رأى ووجد وألفى، حسب بمعنى جعل واتخذ","ماضٍ ومضارع وأمر","رفع ونصب وجر","يقين وشك ونفي فقط"],"answer":0,"explanation":"ثلاثة أقسام: ما بمعنى الظن (ظن وخال)، وما بمعنى العلم (علم ورأى ووجد وألفى)، وما بمعنى الحسبان والجعل."},{"question":"في «ظنَّ قيسٌ معاذًا مسافرًا» ما إعراب «قيسٌ»؟","options":["فاعل مرفوع بالضمة","مفعول به أول","اسم ظن مرفوع","مبتدأ مرفوع"],"answer":0,"explanation":"قيس فاعل مرفوع بالضمة؛ لأن ظن وأخواتها أفعال كاملة لها فاعل ثم تنصب مفعولين."},{"question":"كيف تختبر أن المفعولين أصلهما مبتدأ وخبر؟","options":["أدخل «كان» قبل الأول فإن صح المعنى فهما أصلًا مبتدأ وخبر","انزع الفعل كله","بدّل مكانيهما","اجعلهما مرفوعين دائمًا"],"answer":0,"explanation":"ضع كان قبل المفعول الأول: «ظننت العلم نافعًا» ← «كان العلم نافع» صحيحة؛ إذن أصلهما مبتدأ وخبر."},{"question":"لماذا لا تدل أفعال الظن على شيء حتى تستوفي فاعلها؟","options":["لأنها أفعال كاملة التصرف تحتاج فاعلًا قبل مفعوليها","لأنها حروف","لأنها ناقصة ككان","لأنها مبنية للمجهول"],"answer":0,"explanation":"هي أفعال كاملة (ليست ناقصة ككان) فتحتاج فاعلًا يقوم بها، ثم تنصب مفعولين أصلهما المبتدأ والخبر."}]},{"body":["تدريب إعرابي موسع: «علمتُ الصدقَ خيرًا»: علمت: فعل ماضٍ مبني على الفتح لا محل له من الإعراب. التاء: ضمير بارز مبني على الضم في محل رفع فاعل. الصدقَ: مفعول به أول منصوب بالفتحة. خيرًا: مفعول به ثانٍ منصوب بالفتحة.","مع الضمائر مفعولًا: «ظننتُكَ صادقًا»: الكاف مفعول به أول في محل نصب (مبني على الفتح)، وصادقًا مفعول ثانٍ منصوب بالفتحة. الضمير إذا وقع مفعولًا أول نقول: في محل نصب.","مع المضارع: «أظنُّ الاجتهادَ طريقَ النجاحِ»: أظن فعل مضارع مرفوع بالضمة، والفاعل مستتر تقديره «أنا»، الاجتهادَ مفعول أول، طريقَ مفعول ثانٍ (وهو مضاف والنجاح مضاف إليه).","مع المثنى والجمع: «علمتُ المؤمنَينِ صادقَينِ»: المؤمنَين مفعول أول منصوب بالياء (مثنى)، صادقَين مفعول ثانٍ منصوب بالياء (مثنى). و«حسبتُ المجتهدين فائزينَ»: كلاهما منصوب بالياء (جمع مذكر سالم).","الفرق بين الثلاثة نواسخ في جدول ذهني: كان: ترفع الأول وتنصب الثاني وتسميهما اسمًا وخبرًا. إنّ: تنصب الأول وترفع الثاني وتسميهما اسمًا وخبرًا. ظن: تنصبهما وتسميهما مفعولين لأنها فعل كامل له فاعل.","لماذا سمي مفعولا ظن «أول» و«ثاني» ولم يسمَّيا اسمًا وخبرًا؟ لأن ظن وأخواتها أفعال تامة تحتاج فاعلًا، فالمنصوبان بعدها مفعولان للفعل لا اسم وخبر لناسخ ناقص. لكن أصلهما مبتدأ وخبر كما أثبت الاختبار بكان.","الخلاصة: ظننت وأخواتها أفعال اعتقاد ووجدان وجعل، تنصب المبتدأ والخبر مفعولين: الأول مرفوع الأصل، والثاني كذلك؛ وتُعرب نفسها إعراب الأفعال."],"examples":["علمتُ الصدقَ خيرًا: مفعولان منصوبان بالفتحة","ظننتُكَ صادقًا: الكاف مفعول أول في محل نصب","أظنُّ الاجتهادَ طريقَ النجاحِ: مضارع ومفعول ثانٍ مضاف","علمتُ المؤمنَينِ صادقَينِ: مثنى منصوب بالياء","حسبتُ المجتهدين فائزينَ: جمع منصوب بالياء","وجدتُ الحقَّ غالبًا: وجد بمعنى علم"],"questions":[{"question":"أعرب «صادقًا» في «ظننتُكَ صادقًا»:","options":["مفعول به ثانٍ منصوب بالفتحة","مفعول به أول","حال منصوب","خبر ظن مرفوع"],"answer":0,"explanation":"الكاف مفعول أول في محل نصب (لأنه مبني)، وصادقًا مفعول به ثانٍ منصوب بالفتحة."},{"question":"في «علمتُ المؤمنَينِ صادقَينِ» ما علامة نصب المفعولين؟","options":["الياء لأنهما مثنى","الفتحة","الكسرة","الألف"],"answer":0,"explanation":"المثنى يُنصب ويُجر بالياء؛ فالمؤمنَين مفعول أول وصادقَين مفعول ثانٍ كلاهما منصوب بالياء."},{"question":"لماذا يسمى منصوبا ظن «مفعولين» لا «اسمًا وخبرًا»؟","options":["لأن ظن وأخواتها أفعال تامة لها فاعل فتنصب مفعولين","لأنها حروف","لأنها ناقصة","لأنهما مرفوعان أصلًا"],"answer":0,"explanation":"ظن وأخواتها أفعال كاملة تستوفي فاعلها ثم تنصب مفعولين؛ أما كان وإن فنواسخ ناقصة تسميهما اسمًا وخبرًا."},{"question":"أي جملة صحيحة؟","options":["حسبتُ الصدقَ منجاةً","حسبتُ الصدقُ منجاةً","حسبتُ الصدقُ منجاةٌ","حسبتُ الصدقَ منجاةٌ"],"answer":0,"explanation":"الصواب: حسبتُ الصدقَ منجاةً؛ لأن ظن وأخواتها تنصب المفعولين معًا: الأول والثاني بالفتحة."},{"question":"ما معنى «وجدتُ الصبرَ مفتاحَ الفرجِ»؟","options":["علمتُ الصبرَ مفتاحَ الفرج","تمنيتُ الصبر","شبهتُ الصبر","أنكرتُ الصبر"],"answer":0,"explanation":"وجد هنا بمعنى علم؛ من أفعال الظن التي تنصب مفعولين: الصبرَ مفعول أول، ومفتاحَ مفعول ثانٍ مضاف."}]}]},{"id":"wahi-sharh-024","title":"مكملات الجملتين والمفعول به","section":"شرح الكتاب: القسم الثالث: مكملات الجملتين - باب المفعول به","order":24,"segments":[{"body":["بعد دراسة أحكام الكلمة وأركان الجملتين، نأتي إلى «القسم الثالث: مكملات الجملتين». المكملات هي أجزاء زائدة تأتي «بعد اكتمال ركني الجملة» لتكمل المعنى وتزيده بيانًا. الجملة بدونها صحيحة، لكنها معها أتم فائدة.","المكملات ثلاثة أشربة (أصناف): ١- منصوبات: وهي المفاعيل الخمسة، والحال، والتمييز، والمستثنى، والمنادى. ٢- مجرورات: وهي المجرور بالحرف والمجرور بالإضافة. ٣- توابع: وهي النعت، والمعطوف، والتوكيد، والبدل.","نبدأ بالشرب الأول: المكملات المنصوبات، وأولها المفاعيل. المفاعيل خمسة: المفعول به، والمفعول فيه، والمفعول له، والمفعول معه، والمفعول المطلق. وكلها حكمها النصب: إن كانت معربة فمنصوبة، وإن كانت مبنية ففي محل نصب.","باب المفعول به - تعريفه: «الاسم الذي يبيّن الذي وقع الفعلُ عليه». مثال: «قرأتُ الكتابَ»: الكتاب مفعول به؛ لأنه اسم بيّن الذي وقعت القراءة عليه. «قرأتُه»: الهاء مفعول به لأنها بيّنت الذي وقعت القراءة عليه.","ضابطه العملي: «أنه جواب قولنا: على ماذا وقع الفعل؟». اسأل بالسؤال: قرأتُ على ماذا وقعت القراءة؟ الجواب: الكتاب. فالجواب هو المفعول به.","أمثلة الكتاب المعربة: «نصر اللهُ المسلمينَ»: المسلمين مفعول به منصوب وعلامة نصبه الياء (جمع مذكر سالم). «وأكرمتُكَ»: الكاف مفعول به في محل نصب مبني على الفتح (ضمير متصل). «وأحبُّ نورًا»: نورًا مفعول به منصوب بالفتحة. «وانظر أخاكَ»: أخاك مفعول به منصوب وعلامة نصبه الألف (من الأسماء الخمسة).","إعرابه باختصار: مفعول به منصوب - بالفتحة للمفرد وجمع التكسير وجمع المؤنث السالم، وبالياء للمثنى وجمع المذكر السالم، وبالألف للأسماء الخمسة، والضمائر والمبنيات في محل نصب."],"examples":["قرأتُ الكتابَ: الكتاب مفعول به يبين الذي وقعت القراءة عليه","نصر اللهُ المسلمينَ: مفعول به منصوب بالياء","أكرمتُكَ: الكاف مفعول به في محل نصب","أحبُّ نورًا: مفعول به منصوب بالفتحة","انظر أخاكَ: مفعول به منصوب بالألف (الأسماء الخمسة)","حفظتُ القرآنَ: مفعول به منصوب بالفتحة"],"questions":[{"question":"ما المكملات؟","options":["أجزاء تأتي بعد اكتمال ركني الجملة لتكمل المعنى","أركان الجملة الأساسية","النواسخ الثلاثة","حروف الجر"],"answer":0,"explanation":"المكملات زيادات تأتي بعد تمام المبتدأ والخبر أو الفعل والفاعل، تكمل المعنى وتزيده بيانًا."},{"question":"ما أشربة المكملات الثلاثة؟","options":["منصوبات ومجرورات وتوابع","مرفوعات ومنصوبات ومجرورات","أسماء وأفعال وحروف","مبتدأ وخبر وفاعل"],"answer":0,"explanation":"ثلاثة: منصوبات (المفاعيل والحال والتمييز والمستثنى والمنادى)، ومجرورات (بالحرف وبالإضافة)، وتوابع (نعت وعطف وتوكيد وبدل)."},{"question":"ما المفاعيل الخمسة؟","options":["به وفيه وله ومعه والمطلق","الفاعل ونائبه والمبتدأ والخبر والحال","الظرف والحال والتمييز والنداء والاستثناء","كان وإن وظن ولا وما"],"answer":0,"explanation":"خمسة: المفعول به، وفيه (الظرف)، وله، ومعه، والمطلق؛ وكلها منصوبة."},{"question":"ما تعريف المفعول به؟","options":["الاسم الذي يبيّن الذي وقع الفعل عليه","الاسم الذي قام بالفعل","الاسم المرفوع بعد الفعل","كل اسم منصوب"],"answer":0,"explanation":"المفعول به اسم يبيّن من أو ما الذي وقع عليه الفعل، نحو: قرأتُ الكتابَ."},{"question":"ما ضابط المفعول به العملي؟","options":["جواب: على ماذا وقع الفعل؟","جواب: من فعل؟","جواب: متى وقع الفعل؟","جواب: لماذا وقع الفعل؟"],"answer":0,"explanation":"اسأل: على ماذا (أو على من) وقع الفعل؟ فالجواب هو المفعول به: نصر الله المسلمين - وقع النصر على من؟ المسلمين."}]},{"body":["تدريب إعرابي متدرج: مثال ١: «كتبَ التلميذُ الواجبَ»: الواجب مفعول به منصوب بالفتحة. مثال ٢: «كرَّمَ المديرُ الطالباتِ»: الطالبات مفعول به منصوب بالكسرة نيابة عن الفتحة (جمع مؤنث سالم).","قاعدة جمع المؤنث السالم: يُنصب ويُجر بالكسرة: «رأيتُ المسلماتِ» منصوب بالكسرة. هذه علامة فرعية خاصة به.","مثال ٣: «سافر أخوكَ»: أخوك فاعل مرفوع بالواو (الأسماء الخمسة ترفع بالواو). و«رأيتُ أخاكَ»: أخاك مفعول به منصوب بالألف. و«سلمتُ على أخيكَ»: أخيك مجرور بالياء. لاحظ الواو والألف والياء: ثلاث حركات تدل على الرفع والنصب والجر.","المفعول به قد يتقدم على الفاعل بل على الفعل: «القرآنَ قرأتُ»: القرآن مفعول به مقدم منصوب بالفتحة. وقد يتقدم وجوبًا في مواضع معروفة. تقديمه يفيد الاهتمام به والاختصاص أحيانًا.","فرق بين الفاعل والمفعول به: الفاعل من قام بالفعل (مرفوع)، والمفعول به من وقع عليه الفعل (منصوب). في «علَّم المعلمُ التلميذَ»: المعلم قام بالتعليم فهو فاعل، والتلميذ وقع عليه التعليم فهو مفعول به.","بعض الأفعال تتعدى إلى مفعولين أو ثلاثة: «أعطى المديرُ الطالبَ جائزةً»: الطالب مفعول أول، جائزة مفعول ثانٍ. و«أخبرتُكَ الخبرَ»: الكاف مفعول أول، الخبر مفعول ثانٍ. وكلاهما منصوب.","الخلاصة: المفعول به أهم المفاعيل وأكثرها استعمالًا: اسم منصوب يجيب عن سؤال «على ماذا/من وقع الفعل؟»، علامته الفتحة غالبًا."],"examples":["كرَّم المديرُ الطالباتِ: منصوب بالكسرة (جمع مؤنث سالم)","رأيتُ المسلماتِ: مفعول به منصوب بالكسرة","سافر أخوكَ / رأيتُ أخاكَ / سلمتُ على أخيكَ: واو وألف وياء الأسماء الخمسة","القرآنَ قرأتُ: مفعول به مقدم منصوب","أعطى المديرُ الطالبَ جائزةً: مفعولان منصوبان","أخبرتُكَ الخبرَ: الكاف مفعول أول في محل نصب والخبر مفعول ثانٍ"],"questions":[{"question":"ما علامة نصب جمع المؤنث السالم؟","options":["الكسرة نيابة عن الفتحة","الفتحة دائمًا","الياء","الألف"],"answer":0,"explanation":"جمع المؤنث السالم يُنصب ويُجر بالكسرة: رأيتُ المسلماتِ - مفعول به منصوب بالكسرة."},{"question":"أعرب «أخاكَ» في «رأيتُ أخاكَ»:","options":["مفعول به منصوب وعلامة نصبه الألف لأنه من الأسماء الخمسة","فاعل مرفوع بالواو","مضاف إليه مجرور","مبتدأ"],"answer":0,"explanation":"أخاك من الأسماء الخمسة؛ يُرفع بالواو ويُنصب بالألف ويُجر بالياء: هنا مفعول به منصوب بالألف والكاف مضاف إليه."},{"question":"هل يجوز تقديم المفعول به على الفعل؟","options":["نعم نحو: القرآنَ قرأتُ","لا أبدًا","فقط إذا كان ضميرًا","فقط في الشعر"],"answer":0,"explanation":"يجوز تقديم المفعول به على الفعل والفاعل جوازًا: القرآنَ قرأتُ - مفعول به مقدم منصوب بالفتحة."},{"question":"في «أعطى المديرُ الطالبَ جائزةً» كم مفعولًا به؟","options":["اثنان: الطالبَ وجائزةً","واحد فقط","ثلاثة","لا يوجد"],"answer":0,"explanation":"أعطى فعل متعدٍّ لمفعولين: الطالب مفعول أول منصوب، وجائزة مفعول ثانٍ منصوب بالفتحة."},{"question":"ما الفرق بين الفاعل والمفعول به؟","options":["الفاعل من قام بالفعل مرفوع، والمفعول من وقع عليه الفعل منصوب","كلاهما مرفوع","كلاهما منصوب","الفاعل بعد المفعول دائمًا"],"answer":0,"explanation":"الفاعل اسم مرفوع يدل على من قام بالفعل، والمفعول به اسم منصوب يدل على من وقع عليه الفعل."}]}]},{"id":"wahi-sharh-025","title":"المفعول فيه (ظرف الزمان وظرف المكان)","section":"شرح الكتاب: باب المفعول فيه","order":25,"segments":[{"body":["الباب الثاني من المفاعيل: «المفعول فيه» ويسمى أيضًا الظرف. تعريفه: «الاسم الذي يدل على زمان الفعل أو مكانه». سمي مفعولًا فيه لأن الفعل يقع «في» الزمان أو «في» المكان، لا على الظرف نفسه.","وهو نوعان: ظرف زمان وظرف مكان. ظرف الزمان: «اسم زمان يبيّن زمان الفعل ويكون بمعنى (في)». وضابطه: «جواب قولنا: متى وقع الفعل؟». اسأل متى؟ فالجواب ظرف زمان.","أمثلة ظرف الزمان من الكتاب: «صلّتْ مؤمنةٌ ليلًا»: ليلًا ظرف زمان منصوب بالفتحة، بمعنى: صلّت في الليل. «وصام المسلمون رمضانَ»: صاموا في رمضان. «وجاءتْ رندٌ قبلَ العصرِ»: جاءت في هذا الزمن الذي هو قبل العصر.","«وسنسافر إذا طلعتِ الشمسُ»: بمعنى سنسافر في وقت طلوع الشمس؛ و«إذا» ظرف زمان في محل نصب مبني على السكون (لأنها مبنية فنقدّر لها محلًّا).","ظرف المكان: «اسم مكان يبيّن مكان الفعل ويكون بمعنى (في)». وضابطه: «جواب قولنا: أين وقع الفعل؟». اسأل أين؟ فالجواب ظرف مكان.","أمثلة ظرف المكان من الكتاب: «نام العادلُ تحتَ الشجرةِ»: تحت ظرف مكان منصوب (وهو مضاف والشجرة مضاف إليه)، بمعنى: نام في هذا المكان. «وصلّيتُ خلفَ الإمامِ»: خلف ظرف مكان منصوب. «واجلس حيثُ شئتَ»: حيث ظرف مكان في محل نصب مبني على الضم.","إذن الظرف كله بمعنى «في»: نام تحت الشجرة = نام في هذا المكان. صاموا رمضان = صاموا في رمضان. هذه هي العلامة الكبرى: إذا صح أن تضع «في» قبله فهو ظرف."],"examples":["صلّت مؤمنةٌ ليلًا: ظرف زمان منصوب بالفتحة","صام المسلمون رمضانَ: ظرف زمان بمعنى في رمضان","سنسافر إذا طلعت الشمس: إذا ظرف زمان مبني في محل نصب","نام العادلُ تحتَ الشجرةِ: ظرف مكان منصوب مضاف","صليتُ خلفَ الإمامِ: ظرف مكان بمعنى في مكان خلف الإمام","اجلس حيثُ شئتَ: حيث ظرف مكان مبني في محل نصب"],"questions":[{"question":"ما تعريف المفعول فيه؟","options":["الاسم الذي يدل على زمان الفعل أو مكانه","الاسم الذي وقع عليه الفعل","الاسم الذي قام بالفعل","الاسم الذي يبين سبب الفعل"],"answer":0,"explanation":"المفعول فيه (الظرف) اسم يدل على زمان الفعل أو مكانه ويكون بمعنى «في»."},{"question":"ما نوعا المفعول فيه؟","options":["ظرف زمان وظرف مكان","مفرد وجمع","معرب ومبني","لازم ومتعدٍّ"],"answer":0,"explanation":"نوعان: ظرف الزمان (يجيب: متى وقع الفعل؟) وظرف المكان (يجيب: أين وقع الفعل؟)."},{"question":"ما ضابط ظرف الزمان؟","options":["جواب: متى وقع الفعل؟","جواب: أين وقع الفعل؟","جواب: لماذا وقع الفعل؟","جواب: على ماذا وقع الفعل؟"],"answer":0,"explanation":"ظرف الزمان جواب سؤال «متى؟»: صام المسلمون رمضان - متى صاموا؟ في رمضان."},{"question":"ما ضابط ظرف المكان؟","options":["جواب: أين وقع الفعل؟","جواب: متى وقع الفعل؟","جواب: كيف وقع الفعل؟","جواب: من فعل؟"],"answer":0,"explanation":"ظرف المكان جواب سؤال «أين؟»: نام تحت الشجرة - أين نام؟ في مكان تحت الشجرة."},{"question":"ما العلامة الكبرى للظرف؟","options":["أن يصح وضع «في» قبله","أن يكون مفردًا","أن يكون معرفة","أن يكون مبنيًّا"],"answer":0,"explanation":"كل ظرف بمعنى «في»: صاموا رمضان = في رمضان، ونام تحت الشجرة = في هذا المكان؛ فإن صحت «في» فهو ظرف."}]},{"body":["إعراب الظرف المعرب: «ظرف زمان (أو مكان) منصوب وعلامة نصبه الفتحة». وغالبًا يأتي مضافًا: «تحتَ الشجرةِ»: تحت ظرف مكان منصوب بالفتحة وهو مضاف، والشجرة مضاف إليه مجرور بالكسرة.","والظرف المبني: نقول «في محل نصب»: «إذا» مبنية على السكون في محل نصب ظرف زمان، و«حيث» مبنية على الضم في محل نصب ظرف مكان. المبنيات لا تظهر عليها الحركات فنقدّر المحل.","أشهر ألفاظ ظرف الزمان: يوم، ليلة، صباحًا، مساءً، حين، وقت، ساعة، أوان، إذ، إذا، بينا، بينما، شهر، سنة، أسبوع، دهر. مثال: «سافرتُ يومَ الجمعةِ»: يوم ظرف زمان منصوب مضاف.","أشهر ألفاظ ظرف المكان: فوق، تحت، أمام، خلف، يمين، شمال، بين، حول، عند، لدى، حيث. مثال: «وقفتُ أمامَ البابِ»: أمام ظرف مكان منصوب مضاف.","كيف تفرق بين الظرف والمفعول به؟ المفعول به وقع الفعل عليه (قرأت الكتاب)، والظرف وقع الفعل فيه (قرأت ليلًا). الضابط: الظرف يصح معه «في» والمفعول به لا يصح: لا نقول «قرأت في الكتاب» بمعنى المفعولية... بل نقول قرأت الكتاب.","وكيف تفرق بين الظرف والجار والمجرور؟ «صليتُ في المسجدِ»: في المسجد جار ومجرور متعلق بالفعل، وليس مفعولًا فيه لأنه ليس منصوبًا. الظرف منصوب بلا حرف جر: «صليتُ مكانًا هادئًا»... والأصل أن الظرف اسم مكان أو زمان منصوب بمعنى في.","الخلاصة: المفعول فيه نوعان: زمان (متى؟) ومكان (أين؟)، منصوب دائمًا، معناه «في»، وكثير من ألفاظه مضافة لما بعدها."],"examples":["سافرتُ يومَ الجمعةِ: ظرف زمان منصوب مضاف","وقفتُ أمامَ البابِ: ظرف مكان منصوب مضاف","درستُ ساعةً: ظرف زمان منصوب بالفتحة","جلس المعلمُ بينَ الطلابِ: ظرف مكان منصوب","انتظرْه حينَ يأتي: حين ظرف زمان منصوب","المؤمنون صابرون دهرًا: ظرف زمان منصوب"],"questions":[{"question":"أعرب «تحتَ» في «نام العادلُ تحتَ الشجرةِ»:","options":["ظرف مكان منصوب بالفتحة وهو مضاف","حرف جر","مفعول به منصوب","خبر مرفوع"],"answer":0,"explanation":"تحت ظرف مكان منصوب بالفتحة وهو مضاف، والشجرة مضاف إليه مجرور؛ والمعنى: نام في مكان تحت الشجرة."},{"question":"لماذا نقول في «إذا» و«حيث»: في محل نصب؟","options":["لأنهما مبنيتان لا تظهر عليهما علامة النصب","لأنهما مرفوعتان","لأنهما حرفا جر","لأنهما أفعال"],"answer":0,"explanation":"إذا وحيث ظرفان مبنيان (على السكون والضم)؛ والمبني لا تظهر عليه العلامة فنقول: في محل نصب."},{"question":"كيف تفرق بين الظرف والمفعول به؟","options":["الظرف وقع الفعل فيه (يصح معه في) والمفعول به وقع عليه","لا فرق","الظرف مرفوع","المفعول به زماني فقط"],"answer":0,"explanation":"المفعول به وقع الفعل عليه (قرأت الكتاب)، والظرف وقع الفعل في زمانه أو مكانه (قرأت ليلًا = في الليل)."},{"question":"أي الألفاظ من أظرف المكان؟","options":["فوق وتحت وأمام وخلف","يوم وليلة وساعة","إذ وإذا وبينما","متى وأين فقط"],"answer":0,"explanation":"فوق وتحت وأمام وخلف وبين وحول وعند وحيث أظرف مكان؛ أما يوم وليلة وساعة فأظرف زمان."},{"question":"أعرب «يومَ» في «سافرتُ يومَ الجمعةِ»:","options":["ظرف زمان منصوب بالفتحة وهو مضاف","مفعول به","حال","مضاف إليه"],"answer":0,"explanation":"يوم ظرف زمان منصوب بالفتحة وهو مضاف، والجمعة مضاف إليه مجرور؛ المعنى: سافرت في يوم الجمعة."}]}]},{"id":"wahi-sharh-026","title":"المفعول له","section":"شرح الكتاب: باب المفعول له","order":26,"segments":[{"body":["الباب الثالث: «المفعول له» ويسمى أيضًا المفعول لأجله. تعريفه في الكتاب: «الاسم الذي يبيّن علة وقوع الفعل وسببه». العلة يعني: السبب الذي من أجله حدث الفعل.","ضابطه: «أنه جواب قولنا: لماذا وُقع الفعل؟». اسأل لماذا فعل هذا؟ فالجواب هو المفعول له.","أمثلة الكتاب: «جاء زهيرٌ طلبًا للعلمِ»: لماذا جاء؟ طلبًا للعلم. «واجلسْ رجاءَ المنفعةِ»: لماذا أجلس؟ رجاء المنفعة. «وتركتُه حياءً»: لماذا تركته؟ حياءً منه.","فالطلب علة المجيء، والرجاء علة الجلوس، والحياء علة الترك. وإعراب الثلاثة: «مفعول له منصوب وعلامة نصبه الفتحة».","اللم في «المفعول له» هي لام التعليل: بمعنى «من أجل». جاء طلبًا للعلم = جاء من أجل طلب العلم. هذه اللام ضابط ثانٍ: إن صح أن تضع «من أجل» أو «لام التعليل» قبل الاسم المنصوب فهو مفعول له.","شروط المفعول له عند النحويين: أن يكون مصدرًا (لفظ يدل على حدث لا على شيء محسوس: طلب، رجاء، حياء)، وأن يكون نكرة (غير معرّف بأل ولا مضاف لمعرفة... ويجوز إضافته كطلبًا للعلم)، وأن يقع بعد الفعل الذي علل به.","مقارنة سريعة بالمفاعيل السابقة: المفعول به يجيب «على ماذا؟»، والمفعول فيه يجيب «متى/أين؟»، والمفعول له يجيب «لماذا؟». ثلاثة أسئلة تفرق بين ثلاثة مفاعيل: قرأتُ الكتابَ ليلًا طلبًا للعلم: الكتاب به، ليلًا فيه، طلبًا له."],"examples":["جاء زهيرٌ طلبًا للعلم: طلبًا مفعول له (علة المجيء)","اجلس رجاءَ المنفعة: رجاء مفعول له (علة الجلوس)","تركتُه حياءً: حياء مفعول له (علة الترك)","سافرتُ ابتغاءَ الرزقِ: ابتغاء مفعول له","درستُ حبًّا للمعرفةِ: حبًّا مفعول له","قمتُ إعظامًا للمعلمِ: إعظامًا مفعول له"],"questions":[{"question":"ما تعريف المفعول له؟","options":["الاسم الذي يبيّن علة وقوع الفعل وسببه","الاسم الذي وقع عليه الفعل","الاسم الدال على زمان الفعل","الاسم الذي يشارك الفاعل"],"answer":0,"explanation":"المفعول له اسم يبيّن لماذا وقع الفعل: جاء طلبًا للعلم - الطلب علة المجيء."},{"question":"ما ضابط المفعول له؟","options":["جواب: لماذا وقع الفعل؟","جواب: متى وقع الفعل؟","جواب: على ماذا وقع الفعل؟","جواب: مع من وقع الفعل؟"],"answer":0,"explanation":"اسأل: لماذا وقع الفعل؟ فالجواب مفعول له: تركته حياءً - لماذا تركته؟ حياءً."},{"question":"ما معنى اللام في «المفعول له»؟","options":["لام التعليل بمعنى من أجل","لام الجر فقط","لام التوكيد","لام الأمر"],"answer":0,"explanation":"سمي مفعولًا «له» لأنه يصح قبله لام التعليل: جاء طلبًا = جاء لطلب العلم = من أجله."},{"question":"أعرب «رجاءَ» في «اجلس رجاءَ المنفعةِ»:","options":["مفعول له منصوب وعلامة نصبه الفتحة","مفعول به منصوب","حال منصوب","ظرف زمان"],"answer":0,"explanation":"رجاء مفعول له منصوب بالفتحة؛ لأنه مصدر نكرة يبيّن علة الجلوس، والمنفعة مضاف إليه مجرور."},{"question":"أي الأسماء يصلح مفعولًا له؟","options":["المصدر النكرة الدال على علة","كل اسم معرفة","كل اسم مكان","الضمائر فقط"],"answer":0,"explanation":"المفعول له يكون مصدرًا نكرة يدل على علة وسبب: طلبًا، رجاء، حياء، حبًّا؛ لا يكون اسم عين ككتاب أو رجل."}]},{"body":["تدريب إعرابي: «أذاكرُ دروسي رغبةً في التفوقِ»: أذاكر فعل مضارع مرفوع وفاعله مستتر «أنا»، دروسي مفعول به (والياء مضاف إليه)، رغبةً مفعول له منصوب بالفتحة (وهو مضاف و«في» حرف جر والتفوق مجرور بحرف الجر).","المفعول له والحال قد يلتبسان: كلاهما مصدر نكرة منصوب بعد فعل. الفرق: المفعول له علة وسبب (لماذا؟) والحال بيان هيئة (كيف؟): «جاء طلبًا للعلم» علة؛ «جاء راكضًا» هيئة. والحال غالبًا مشتق وصف (راكض، ضاحك) والمفعول له مصدر علة (طلب، رجاء).","أمثلة قرآنية للتثبيت: قال تعالى: «وَمَا خَلَقْتُ الْجِنَّ وَالْإِنسَ إِلَّا لِيَعْبُدُونِ» - اللام لام التعليل والمصدر المؤول في محل جر، والمعنى: لأجل العبادة. ونقول في العامية الفصيحة: «قام احترامًا» = قام من أجل الاحترام.","تدريب على السؤال: في كل جملة اسأل: «قرأ الطالبُ الدرسَ ليلًا إخلاصًا لله»: قرأ: فعل. الطالب: فاعل. الدرس: على ماذا؟ مفعول به. ليلًا: متى؟ مفعول فيه. إخلاصًا: لماذا؟ مفعول له. جملة واحدة جمعت ثلاثة مفاعيل!","«زارني أخي يومَ الجمعةِ سيرًا على الأقدامِ شوقًا إليّ»: زار: فعل. الياء: مفعول به. أخي: فاعل. يوم: متى؟ ظرف زمان. سيرًا: كيف؟ حال. شوقًا: لماذا؟ مفعول له. وهكذا ترتب الأسئلة: من؟ ماذا؟ متى؟ أين؟ كيف؟ لماذا؟","الخلاصة: المفعول له مصدر نكرة منصوب يجيب «لماذا؟» ويصح معه «من أجل»: طلبًا للعلم، رجاء المنفعة، حياء، شوقًا، إخلاصًا."],"examples":["أذاكر دروسي رغبةً في التفوق: رغبة مفعول له منصوب","قام احترامًا: احترامًا مفعول له","قرأ الطالب الدرس ليلًا إخلاصًا لله: ثلاثة مفاعيل في جملة","صام ابتغاءَ الأجر: ابتغاء مفعول له مضاف","اجتهد خوفًا من الرسوب: خوفًا مفعول له","تصدق طمعًا في الأجر: طمعًا مفعول له"],"questions":[{"question":"أعرب «إخلاصًا» في «قرأ الطالبُ الدرسَ ليلًا إخلاصًا لله»:","options":["مفعول له منصوب بالفتحة","حال منصوب","مفعول به","ظرف زمان"],"answer":0,"explanation":"إخلاصًا مصدر نكرة يجيب لماذا قرأ؟ إخلاصًا لله؛ فهو مفعول له منصوب بالفتحة وهو مضاف."},{"question":"ما الفرق بين المفعول له والحال؟","options":["المفعول له يجيب لماذا (علة) والحال يجيب كيف (هيئة)","لا فرق بينهما","الحال علة والمفعول له هيئة","المفعول له ظرف"],"answer":0,"explanation":"كلاهما منصوب؛ لكن المفعول له علة الفعل (طلبًا للعلم) والحال بيان هيئة صاحبه (جاء راكضًا)."},{"question":"أي الجمل فيها مفعول له؟","options":["سافر ابتغاءَ الرزقِ","سافر يومَ الخميسِ","سافر مع أخيهِ","سافر سفرًا طويلًا"],"answer":0,"explanation":"سافر ابتغاء الرزق: ابتغاء مصدر يبين علة السفر فهو مفعول له؛ يوم ظرف، مع أخيه جار ومجرور، سفرًا مفعول مطلق."},{"question":"أعرب «حياءً» في «تركتُه حياءً»:","options":["مفعول له منصوب بالفتحة","حال منصوب","مفعول مطلق","تمييز منصوب"],"answer":0,"explanation":"حياءً مصدر نكرة يبيّن علة الترك: لماذا تركته؟ حياءً؛ فهو مفعول له منصوب بالفتحة."},{"question":"ما الذي يجمع المفعولَ له واللام؟","options":["يصح إدخال لام التعليل عليه: جاء طلبًا = جاء لطلب","أنه يجر باللام دائمًا","أنه يلي اللام حتمًا","لا علاقة بينهما"],"answer":0,"explanation":"يصح وضع لام التعليل قبل المفعول له: تركته حياءً = تركته لحياء / من أجل الحياء؛ ولهذا سمي مفعولًا له."}]}]},{"id":"wahi-sharh-027","title":"المفعول معه","section":"شرح الكتاب: باب المفعول معه","order":27,"segments":[{"body":["الباب الرابع: «المفعول معه». تعريفه: «الاسم الذي يقع بعد واو بمعنى (مع) يبيّن الذي فُعل الفعل بمعيّته (أي: بصحبته)». مفتاح الباب: واو تأتي بمعنى «مع». تسمى «واو المعية».","أمثلة الكتاب: «استذكرتُ والمصباحَ»: أي فعلت الاستذكار مع مصاحبة المصباح وبمعيته. «سافر أخي والحقيبةَ»: سافر ومعه الحقيبة. «ركضتُ والسورَ»: ركضت مع السور. «سرتُ والقمرَ»: مشيت مع القمر. «سارتِ القافلةُ والصحراءَ»: سارت مع الصحراء.","إعرابها كلها: مفعول معه منصوب وعلامة نصبه الفتحة، والواو: حرف معية مبني على الفتح لا محل له من الإعراب.","واو المعية ليست واو العطف: واو العطف تشارك ما قبلها في الإعراب (جاء زيدٌ وعمروٌ: عمرو معطوف مرفوع)، وواو المعية بمعنى «مع» وما بعدها منصوب دائمًا (جاء زيدٌ وعمرَوَ بمعنى مع عمر). الاختبار: إن صح وضع «مع» مكان الواو فهي واو معية وما بعدها مفعول معه.","وهو نوعان كما في الكتاب: الأول: «المفعول معه الذي لم يفعل الفعل»، نحو: «لقيتُ والشاطئَ»: الشاطئ لم يلقَ شيئًا؛ هو مجرد مصاحب للمكان. الثاني: «المفعول معه الذي فعل الفعل ولكن بلا قصد»... أي أن الفعل وقع عليه مصاحبة لا قصدًا به.","في المثال الأول: الشاطئ اسم جماد لا يفعل، فالمعية مكانية: لقيت الشخص مع الشاطئ أي عنده. النوع الثاني: أن يكون معك من يفعل الفعل نفسه لكن فعله غير مقصود لذاته في التعبير.","الخلاصة: كل اسم منصوب بعد واو بمعنى «مع» فهو مفعول معه: سرتُ والقمرَ = سرت مع القمر."],"examples":["استذكرتُ والمصباحَ: مفعول معه (المصباح مصاحب للاستذكار)","سافر أخي والحقيبةَ: مفعول معه","سرتُ والقمرَ: سرت مع القمر","ركضتُ والسورَ: ركضت مع السور","سارت القافلةُ والصحراءَ: سارت مع الصحراء","لقيتُه والشاطئَ: مفعول معه لم يفعل الفعل"],"questions":[{"question":"ما تعريف المفعول معه؟","options":["اسم يقع بعد واو بمعنى «مع» يبيّن من فُعل الفعل بمعيّته","اسم يقع بعد واو العطف","الاسم الذي وقع عليه الفعل","اسم يدل على مكان الفعل"],"answer":0,"explanation":"المفعول معه اسم منصوب بعد واو بمعنى «مع»: سرتُ والقمرَ = سرت مع القمر."},{"question":"ما اسم الواو في باب المفعول معه؟","options":["واو المعية","واو العطف","واو الحال","واو القسم"],"answer":0,"explanation":"واو المعية: حرف معية مبني على الفتح لا محل له من الإعراب، بمعنى «مع»."},{"question":"كيف تفرق بين واو المعية وواو العطف؟","options":["إن صح وضع «مع» مكانها ونُصب ما بعدها فهي معية","لا فرق بينهما","واو العطف تنصب","واو المعية ترفع"],"answer":0,"explanation":"واو المعية بمعنى «مع» وما بعدها منصوب (سرت والقمرَ)؛ وواو العطف يتبع ما بعدها ما قبله في الإعراب (جاء زيد وعمرو)."},{"question":"أعرب «القمرَ» في «سرتُ والقمرَ»:","options":["مفعول معه منصوب وعلامة نصبه الفتحة","معطوف مرفوع","مفعول به","ظرف مكان"],"answer":0,"explanation":"الواو بمعنى مع، فالقمر مفعول معه منصوب بالفتحة: سرت مع القمر."},{"question":"ما نوعا المفعول معه؟","options":["الذي لم يفعل الفعل، والذي فعله بلا قصد","المعرب والمبني","الزماني والمكاني","الظاهر والمستتر"],"answer":0,"explanation":"نوعان: مفعول معه لم يفعل الفعل (لقيته والشاطئ)، ومفعول معه فعل الفعل لكن بلا قصد إليه بالذات."}]},{"body":["تدريب إعرابي: «مشيتُ والطريقَ»: مشيت فعل ماضٍ مبني على السكون لاتصاله بتاء المتكلم، والتاء فاعل، الواو حرف معية مبني على الفتح، الطريقَ مفعول معه منصوب بالفتحة.","مع الضمائر: «سرتُ وإيّاهُ»: الواو حرف معية، وإيّاه ضمير منفصل مبني في محل نصب مفعول معه. الضمائر المنفصلة (إيّاي، إيّاك، إيّاه...) تصلح مفعولًا معه لأنها في محل نصب.","مع المثنى والجمع: «سافرتُ وصديقَيّ»: صديقي مفعول معه منصوب بالياء (مثنى) حذفت نونه للإضافة والياء مضاف إليه. و«ركبتُ السيارةَ والحقائبَ»: الحقائب مفعول معه منصوب بالكسرة (جمع مؤنث سالم).","تنبيه مهم: لا يشترط أن يكون المفعول معه عاقلًا: القمر والصحراء والمصباح أشياء، لكن العربية تجعلها مصاحبة للفعل. المعية هنا مصاحبة زمانية أو مكانية: سرت مع القمر = والقمر يسير معي في السماء.","أخطاء شائعة: أن تعرب ما بعد واو المعية معطوفًا. الاختبار الحاسم: اسأل: هل فعل الثانيُ الفعلَ نفسه استقلالًا؟ إن نعم فعطف: «جاء زيدٌ وعمروٌ» عمر جاء فعلًا. وإن كان مجرد مصاحب فمفعول معه: «سرتُ والقمرَ» القمر لا يمشي مشيي.","الخلاصة: المفعول معه: واو + اسم منصوب بمعنى «مع». إعراب الواو: حرف معية مبني على الفتح لا محل له من الإعراب. والاسم بعدها: مفعول معه منصوب."],"examples":["مشيتُ والطريقَ: مفعول معه منصوب بالفتحة","سرتُ وإيّاهُ: ضمير منفصل في محل نصب مفعول معه","ركبتُ السيارةَ والحقائبَ: جمع مؤنث سالم منصوب بالكسرة","سافرتُ وصديقَيّ: مثنى منصوب بالياء","جاء زيدٌ وعمروٌ: هنا واو عطف وعمرو معطوف مرفوع","نمتُ والنجومَ: نمت مع النجوم - مفعول معه"],"questions":[{"question":"أعرب الواو في «مشيتُ والطريقَ»:","options":["حرف معية مبني على الفتح لا محل له من الإعراب","حرف عطف","حرف جر","حرف نفي"],"answer":0,"explanation":"الواو هنا بمعنى «مع» فهي حرف معية مبني على الفتح لا محل له من الإعراب، وما بعدها مفعول معه منصوب."},{"question":"«سرتُ وإيّاهُ» - ما إعراب «إيّاه»؟","options":["ضمير منفصل مبني في محل نصب مفعول معه","مفعول به منصوب","معطوف مرفوع","مضاف إليه"],"answer":0,"explanation":"الضمائر المنفصلة إياي وإياك وإياه مبنية في محل نصب؛ هنا وقعت بعد واو المعية فهي مفعول معه في محل نصب."},{"question":"في «جاء زيدٌ وعمروٌ» لماذا «عمرو» معطوف وليس مفعولًا معه؟","options":["لأن عمرًا قام بالمجيء استقلالًا كزيد","لأنه مرفوع فقط","لأن الواو حرف جر","لأن زيدًا نكرة"],"answer":0,"explanation":"عمر جاء بنفسه كما جاء زيد، فالواو للعطف وعمرو معطوف على الفاعل مرفوع؛ أما المعية فمجرد مصاحبة."},{"question":"هل يشترط في المفعول معه أن يكون عاقلًا؟","options":["لا؛ يكون شيئًا كالقمر والصحراء","نعم عاقلًا فقط","نعم إنسانًا فقط","لا؛ حيوانًا فقط"],"answer":0,"explanation":"لا يشترط العقل: سرت والقمر، وسارت القافلة والصحراء؛ المعية مصاحبة زمانية أو مكانية."},{"question":"ما الاختبار الحاسم بين العطف والمعية؟","options":["هل فعل الثاني الفعل نفسه استقلالًا؟ فإن نعم فعطف وإلا فمعية","الحركة فقط","طول الكلمة","التعريف والتنكير"],"answer":0,"explanation":"اسأل: هل الثاني فعل الفعل بنفسه؟ جاء زيد وعمرو: نعم → عطف. سرت والقمر: القمر مصاحب فقط → مفعول معه منصوب."}]}]},{"id":"wahi-sharh-028","title":"المفعول المطلق","section":"شرح الكتاب: باب المفعول المطلق","order":28,"segments":[{"body":["الباب الخامس والأخير من المفاعيل: «المفعول المطلق». تعريفه: «المصدر المنصوب بعد فعله». سمي مطلقًا لأنه غير مقيد بمعنى من معاني المفاعيل الأربعة السابقة.","ما المصدر؟ قال الكتاب: «المصدر هو التصريف الثالث للفعل»: كقولك: ضرب يضرب ضربًا، ودعا يدعو دعاءً، وجلس يجلس جلوسًا، وأخرج يخرج إخراجًا، وانطلق ينطلق انطلاقًا، واستخرج يستخرج استخراجًا. أي هو الاسم الدال على الحدث نفسه مأخوذ من الفعل.","إذن المفعول المطلق = مصدر من نفس فعل الجملة، منصوب بعده: «دعوتُ اللهَ دعاءً»: دعاء مصدر الفعل دعا، منصوب، مفعول مطلق.","فوائده ثلاث كما في الكتاب: ١- بيان النوع: «دعوتُ اللهَ دعاءَ المضطرِّ» و«دعوتُ الله دعاءً خاشعًا»: بينت نوع الدعاء بإضافته أو وصفه. ٢- بيان العدد: «دعوتُ الله دعوتينِ» و«دعوتُ الله ثلاثةَ أدعيةٍ»: بينت عدد المرات. ٣- التوكيد: «دعوتُ الله دعاءً» و«حفظتُ القرآن حفظًا» و«أكرمتُه إكرامًا»: أكدت وقوع الفعل.","إعرابه: مفعول مطلق منصوب وعلامة نصبه الفتحة (أو الياء للمثنى: دعوتين).","ملاحظة: في بيان النوع قد يكون المصدر موصوفًا (دعاءً خاشعًا) أو مضافًا (دعاء المضطر) أو محذوفًا وبقي صفته: «دعوتُ خاشعًا» بمعنى دعاءً خاشعًا - فالصفة هنا نائبة عن المصدر تسمى «نائب المفعول المطلق» وتعرب مفعولًا مطلقًا أيضًا.","وفي بيان العدد قد يأتي العدد نفسه مكان المصدر: «دعوتُ ثلاثةَ أدعيةٍ»: ثلاثة مفعول مطلق (نائب عنه) منصوب، وأدعية تمييز مجرور... والتفصيل في بابه."],"examples":["دعوتُ الله دعاءً: مفعول مطلق مؤكد","دعوتُ الله دعاءَ المضطرِّ: مفعول مطلق مبين للنوع بالإضافة","دعوتُ الله دعاءً خاشعًا: مبين للنوع بالوصف","دعوتُ الله دعوتين: مبين للعدد (مثنى منصوب بالياء)","حفظتُ القرآن حفظًا: توكيد","أكرمتُه إكرامًا: توكيد"],"questions":[{"question":"ما تعريف المفعول المطلق؟","options":["المصدر المنصوب بعد فعله","كل مصدر في الجملة","الاسم الذي وقع عليه الفعل","الظرف الزماني"],"answer":0,"explanation":"المفعول المطلق مصدر منصوب يأتي بعد فعل من لفظه: دعوت دعاءً، حفظت حفظًا."},{"question":"ما المصدر؟","options":["التصريف الثالث للفعل الدال على الحدث نفسه","الفعل الماضي","اسم الفاعل","الفعل المضارع"],"answer":0,"explanation":"المصدر هو التصريف الثالث للفعل: ضرب يضرب ضربًا؛ يدل على الحدث مجردًا من الزمن."},{"question":"كم فائدة للمفعول المطلق؟","options":["ثلاث: بيان النوع وبيان العدد والتوكيد","فائدة واحدة","فائدتان","أربع فوائد"],"answer":0,"explanation":"ثلاث فوائد: بيان النوع (دعاءً خاشعًا)، وبيان العدد (دعوتين)، والتوكيد (دعاءً مجردًا)."},{"question":"أي الجمل فيها مفعول مطلق مؤكد؟","options":["أكرمتُه إكرامًا","أكرمتُه إكرامًا عظيمًا","أكرمتُه مرتين","أكرمتُ الضيفَ"],"answer":0,"explanation":"أكرمته إكرامًا: المصدر مجرد بلا وصف ولا عدد ففائدته التوكيد؛ أما الموصوف فلبيان النوع والمعدود لبيان العدد."},{"question":"أعرب «دعوتين» في «دعوتُ الله دعوتينِ»:","options":["مفعول مطلق منصوب وعلامة نصبه الياء لأنه مثنى","مفعول به منصوب","تمييز منصوب","حال منصوب"],"answer":0,"explanation":"دعوتين مصدر مثنى يبين عدد الدعوات؛ مفعول مطلق منصوب بالياء لأنه مثنى."}]},{"body":["تدريب إعرابي شامل: «جلس الطفلُ جلوسَ المتأدبِ»: جلس فعل ماضٍ، الطفل فاعل، جلوس مفعول مطلق منصوب بالفتحة وهو مضاف (بيان النوع بالإضافة)، المتأدب مضاف إليه مجرور.","«صمتُ يومَينِ صمتَ المتعبدِ»: يومين ظرف زمان منصوب بالياء، وصمتَ مفعول مطلق منصوب مضاف لبيان النوع.","نائب المفعول المطلق: أحيانًا يحذف المصدر ويناب عنه: ١- صفته: «ضربته شديدًا» أي ضربًا شديدًا. ٢- عدده: «ضربته ثلاثًا» أي ثلاث ضربات. ٣- مرادفه (لفظ بمعناه): «قعدتُ جلوسًا» قعد وجلس مرادفان. كلها تُعرب مفعولًا مطلقًا.","كيف تفرق بين المفعول المطلق والمفعول به؟ المطلق مصدر من لفظ الفعل يؤكد أو يبين (ضربت ضربًا)، والمفعول به اسم عين وقع عليه الفعل (ضربت زيدًا). الضابط: لو سألت «على من؟» أجاب المفعول به؛ والمطلق لا يجيب عن سؤال بل يؤكد فعله.","وبينه وبين المفعول له: المطلق من لفظ الفعل نفسه (دعوت دعاءً)، والمفعول له علة من غير لفظه غالبًا (دعوت رجاءً). وإن اجتمعا: «دعوت دعاءً رجاءَ الإجابةِ».","الخلاصة: المفعول المطلق = مصدر منصوب من جنس الفعل: مجرّد فتوكيد، موصوف أو مضاف فبيان نوع، معدود فبيان عدد. وبه تمت المفاعيل الخمسة: به، فيه، له، معه، مطلق."],"examples":["جلس الطفلُ جلوسَ المتأدبِ: مفعول مطلق مضاف لبيان النوع","ضربتُه شديدًا: صفة نائبة عن المفعول المطلق","ضربتُه ثلاثًا: عدد نائب عن المفعول المطلق","قعدتُ جلوسًا: مرادف نائب عن المفعول المطلق","صمتُ يومين صمتَ المتعبد: ظرف + مفعول مطلق","فرحتُ فرحًا شديدًا: مفعول مطلق موصوف"],"questions":[{"question":"ما «نائب المفعول المطلق»؟","options":["ما ينوب عن المصدر المحذوف: صفته أو عدده أو مرادفه","الفاعل","الظرف","المضاف إليه"],"answer":0,"explanation":"إذا حذف المصدر ناب عنه: صفته (ضربته شديدًا)، أو عدده (ضربته ثلاثًا)، أو مرادفه (قعدت جلوسًا)؛ وتعرب مفعولًا مطلقًا."},{"question":"كيف تفرق بين المفعول المطلق والمفعول به؟","options":["المطلق مصدر من لفظ الفعل، وبه اسم عين وقع عليه الفعل","كلاهما مصدر","لا فرق","المطلق مرفوع"],"answer":0,"explanation":"المطلق: ضربت ضربًا - مصدر مؤكد من لفظ الفعل؛ به: ضربت زيدًا - اسم من وقع عليه الفعل يجيب «على من؟»."},{"question":"«فرحتُ فرحًا شديدًا» - ما فائدة المفعول المطلق هنا؟","options":["بيان النوع بالوصف","التوكيد فقط","بيان العدد","لا فائدة"],"answer":0,"explanation":"فرحًا شديدًا: المصدر موصوف ففائدته بيان نوع الفرح؛ لو جرد (فرحت فرحًا) لكان توكيدًا."},{"question":"أعرب «ثلاثًا» في «ضربتُه ثلاثًا»:","options":["مفعول مطلق منصوب (عدد نائب عن المصدر)","مفعول به","حال","تمييز"],"answer":0,"explanation":"ثلاثًا عدد نائب عن المصدر المحذوف: أي ثلاث ضربات؛ يعرب مفعولًا مطلقًا منصوبًا بالفتحة."},{"question":"أي جملة جمعت مفعولًا مطلقًا ومفعولًا له؟","options":["دعوتُ الله دعاءً رجاءَ الإجابة","دعوتُ الله يومَ الجمعة","دعوتُ اللهَ والمؤمنينَ","دعوتُ دعاءَ المضطر"],"answer":0,"explanation":"دعاءً مفعول مطلق (مصدر من لفظ الفعل)، ورجاء الإجابة مفعول له (علة الدعاء): اجتمع المطلق والله في جملة."}]}]},{"id":"wahi-sharh-029","title":"الحال","section":"شرح الكتاب: باب الحال","order":29,"segments":[{"body":["بعد المفاعيل الخمسة نأتي إلى ثاني المنصوبات من المكملات: «الحال». ويقابله وصف آخر اسمه «النعت»، والفرق بينهما مفتاح هذا الباب كله.","تعريف الحال: «وصف نكرة يبيّن حال صاحبه المعرفة زمن الفعل». لنأخذها كلمة كلمة: «وصف»: كلمة تصف شيئًا (ضاحك، راكب). «نكرة»: غير معرفة بأل ولا علم. «يبيّن حال صاحبه»: يوضح هيئة من تكلمنا عنه. «المعرفة»: صاحب الحال يكون معرفة غالبًا. «زمن الفعل»: الحال وصف مؤقت وقت وقوع الفعل لا دائم.","ضابط الحال: «أن تضع قبله عبارة (حالة كونِه)». جاء أوسٌ ضاحكًا = جاء أوس حالة كونه ضاحكًا. صحّت العبارة، إذن ضاحكًا حال.","تعريف النعت بالمقابلة: «وصف يبيّن صفة من صفات صاحبه، ويوافقه في التعريف أو التنكير». النعت يصف الشيء وصفًا لازمًا له (السيارة الجديدة: صفتها أنها جديدة). ضابطه: «أن تضع قبله عبارة (الموصوف بأنه)»: جاء أوس الضاحك = الموصوف بأنه ضاحك.","القاعدة الذهبية من الكتاب: «فإذا وافق الوصفُ الموصوفَ تعريفًا أو تنكيرًا صار الوصف نعتًا»، نحو: «جاء أوسٌ الضاحكُ» (كلاهما معرفة) و«جاء رجلٌ ضاحكٌ» (كلاهما نكرة). «وإذا خالفه - أي خالف الوصف الموصوف في التعريف والتنكير - صار الوصف حالًا»، نحو: «جاء أوسٌ ضاحكًا»: أوس معرفة وضاحكًا نكرة، فهي حال.","ولذلك يُقلب الحال نعتًا عند تعريفه، والأمثلة توضح: «اشتريتُ السيارةَ جديدةً» (حال: اشتريتها وهي في حال الجدة) و«اشتريتُ السيارةَ الجديدةَ» (نعت: وصفتها بأنها الجديدة). «أكلتُ الطعامَ طازجًا» (حال) و«أكلتُ الطعامَ الطازجَ» (نعت). «مررتُ بهندٍ متحجبةً» (حال) و«مررتُ بهندٍ المتحجبةِ» (نعت).","الفرق الإعرابي الكبير: «الحال يلزم النصب على كل حال، والنعت تابع للموصوف في إعرابه رفعًا ونصبًا وجرًا». فالحال منصوب دائمًا، والنعت يتغير بتغير موصوفه: جاء أوس الضاحكُ (مرفوع)، رأيت أوسَ الضاحكَ (منصوب)، مررت بأوسٍ الضاحكِ (مجرور)."],"examples":["جاء أوسٌ ضاحكًا: حال منصوب (وصف نكرة لصاحب معرفة)","جاء أوسٌ الضاحكُ: نعت مرفوع تبع موصوفه","جاء رجلٌ ضاحكٌ: نعت مرفوع (نكرة تبع نكرة)","اشتريتُ السيارةَ جديدةً: حال منصوب / الجديدةَ: نعت منصوب","أكلتُ الطعامَ طازجًا: حال / الطعامَ الطازجَ: نعت","مررتُ بهندٍ متحجبةً: حال منصوب / بهندٍ المتحجبةِ: نعت مجرور"],"questions":[{"question":"ما تعريف الحال؟","options":["وصف نكرة يبيّن حال صاحبه المعرفة زمن الفعل","وصف يوافق موصوفه في التعريف","اسم مرفوع دائمًا","مصدر منصوب بعد فعله"],"answer":0,"explanation":"الحال وصف نكرة يبيّن هيئة صاحبه (المعرفة غالبًا) وقت وقوع الفعل: جاء أوس ضاحكًا."},{"question":"ما ضابط الحال؟","options":["أن تضع قبله عبارة «حالة كونِه»","أن تضع قبله «الموصوف بأنه»","أن يكون معرفة","أن يكون مرفوعًا"],"answer":0,"explanation":"ضابط الحال أن يصح قبله «حالة كونه»: جاء أوس ضاحكًا = حالة كونه ضاحكًا؛ وضابط النعت «الموصوف بأنه»."},{"question":"متى يكون الوصف نعتًا ومتى يكون حالًا؟","options":["إن وافق موصوفه تعريفًا أو تنكيرًا فنعت، وإن خالفه فحال","إن كان مفردًا فنعت","إن كان مبنيًّا فحال","لا فرق"],"answer":0,"explanation":"الموافقة في التعريف أو التنكير تصنع النعت (جاء أوس الضاحك / جاء رجل ضاحك)؛ والمخالفة تصنع الحال (جاء أوس ضاحكًا)."},{"question":"ما إعراب الحال على كل حال؟","options":["منصوب دائمًا","يتبع صاحبه","مرفوع دائمًا","مجرور دائمًا"],"answer":0,"explanation":"الحال يلزم النصب على كل حال؛ والنعت تابع للموصوف رفعًا ونصبًا وجرًا."},{"question":"في «أكلتُ الطعامَ طازجًا» ما إعراب «طازجًا»؟","options":["حال منصوب وعلامة نصبه الفتحة","نعت منصوب","مفعول به ثانٍ","تمييز"],"answer":0,"explanation":"طازجًا وصف نكرة خالف موصوفه (الطعام معرفة) في التعريف فهو حال منصوب: أكلته حالة كونه طازجًا."}]},{"body":["صاحب الحال: هو الاسم الذي تبين الحال هيئتَه. ويأتي ثلاث صور: اسمًا ظاهرًا كما سبق (جاء أوسٌ ضاحكًا: صاحب الحال أوس). وضميرًا بارزًا نحو: «جئتُ ضاحكًا» (صاحب الحال تاء المتكلم) و«اذهبوا مسرعينَ» (صاحب الحال واو الجماعة). وضميرًا مستترًا نحو: «أوسٌ جاء ضاحكًا» (صاحب الحال فاعل جاء المستتر تقديره «هو») و«اذهبْ مسرعًا» (صاحب الحال فاعل اذهب المستتر تقديره «أنت»).","أما المنعوت (الموصوف بالنعت) فلا يكون إلا اسمًا ظاهرًا كما سبق: جاء أوس الضاحك، وجاء رجل ضاحك. لا يقال في النعت ضمير صاحب؛ لأن الضمير لا يُنعت مباشرة.","وهما - أي الحال والنعت - يأتيان: اسمًا مفردًا كما سبق (ضاحكًا). وشبه جملة نحو: «جاء أوسٌ على قدميهِ» (شبه الجملة حال من أوس في محل نصب) و«جاء رجلٌ على قدميهِ» (شبه الجملة نعت لرجل في محل رفع).","ويأتيان جملةً نحو: «جاء أوسٌ يسبّحُ» (جملة فعلية حال في محل نصب: فاعلها مستتر «هو» يعود على أوس)، و«جاء أوسٌ لسانُهُ يسبّحُ» (جملة اسمية حال: لسانه مبتدأ ويسبح خبره والهاء تعود على أوس)، و«جاء أوسٌ وهو يسبّحُ» (الواو واو الحال). ومثله في النعت: «جاء رجلٌ يسبّحُ» (جملة فعلية نعت في محل رفع) و«جاء رجلٌ لسانُه يسبّحُ» (جملة اسمية نعت في محل رفع).","واو الحال: واو تدخل على الجملة الاسمية الواقعة حالًا، مبنية على الفتح لا محل لها من الإعراب: «جاء وهو يسبح»: الواو واو حال، هو مبتدأ في محل رفع، يسبح خبره، والجملة حال في محل نصب.","تدريب شامل: «عاد الجيشُ منتصرًا»: منتصرًا حال منصوب بالفتحة، صاحبها الجيش. «عاد الجيشُ المنتصرُ»: نعت مرفوع بالضمة. الأولى: عاد في حال الانتصار (مؤقت). الثانية: وصف الجيش الدائم بالانتصار.","الخلاصة: الحال نكرة منصوبة تبين هيئة وقت الفعل (حالة كونه)، والنعت تابع يوافق موصوفه (الموصوف بأنه). وكلاهما يأتي مفردًا وشبه جملة وجملة."],"examples":["جئتُ ضاحكًا: صاحب الحال تاء المتكلم","اذهبْ مسرعًا: صاحب الحال مستتر تقديره أنت","جاء أوسٌ على قدميه: شبه جملة حال في محل نصب","جاء رجلٌ على قدميه: شبه جملة نعت في محل رفع","جاء أوسٌ وهو يسبّح: واو الحال + جملة اسمية حال","عاد الجيشُ منتصرًا: حال / الجيشُ المنتصرُ: نعت"],"questions":[{"question":"ما صور صاحب الحال الثلاث؟","options":["اسم ظاهر وضمير بارز وضمير مستتر","مفرد ومثنى وجمع","نكرة ومعرفة ومضاف","ماضٍ ومضارع وأمر"],"answer":0,"explanation":"صاحب الحال: ظاهر (جاء أوس ضاحكًا)، بارز (جئت ضاحكًا)، مستتر (اذهب مسرعًا - تقديره أنت)."},{"question":"لماذا لا يكون المنعوت ضميرًا؟","options":["لأن الضمير لا يُنعت مباشرة، فالمنعوت اسم ظاهر فقط","لأن الضمير نكرة","لأن النعت حال","لأن الضمير معرب"],"answer":0,"explanation":"المنعوت لا يكون إلا اسمًا ظاهرًا: جاء أوس الضاحك، جاء رجل ضاحك؛ أما صاحب الحال فيجوز أن يكون ضميرًا."},{"question":"في «جاء أوسٌ وهو يسبّح» ما إعراب الواو؟","options":["واو الحال مبنية على الفتح لا محل لها من الإعراب","واو العطف","واو المعية","واو القسم"],"answer":0,"explanation":"واو دخلت على جملة اسمية واقعة حالًا: الواو واو حال مبنية على الفتح، وهو مبتدأ، ويسبح خبره، والجملة حال في محل نصب."},{"question":"ما الفرق بين «عاد الجيشُ منتصرًا» و«عاد الجيشُ المنتصرُ»؟","options":["الأولى حال مؤقتة منصوبة والثانية نعت لازم مرفوع","لا فرق","كلتاهما حال","كلتاهما نعت"],"answer":0,"explanation":"منتصرًا حال: عاد في حال الانتصار؛ المنتصر نعت: وصف لازم للجيش يوافقه في التعريف والإعراب."},{"question":"في «جاء أوسٌ لسانُهُ يسبّحُ» ما إعراب الجملة؟","options":["جملة اسمية في محل نصب حال","جملة فعلية خبر","نعت مرفوع","استئنافية لا محل لها"],"answer":0,"explanation":"لسانه مبتدأ والهاء مضاف إليه يعود على أوس، ويسبح خبره؛ والجملة الاسمية في محل نصب حال من أوس."}]}]},{"id":"wahi-sharh-030","title":"التمييز","section":"شرح الكتاب: باب التمييز","order":30,"segments":[{"body":["ثالث المنصوبات من المكملات: «التمييز». تعريفه: «اسم نكرة يُفسَّر به ما قبله، على معنى (مِن)». اسمه من التمييز أي التبيين: يزيل الإبهام ويوضح المقصود.","ضابطه: «أن تضع قبله (مِن) أو (مِن جهة)». فإن صحّت «من» فهو تمييز.","وهو نوعان: الأول: «تمييز مفرد: وهو ما كان تفسيره بمفرد، وهو الذي توضع قبله (من)». مثال الكتاب: «مضى عشرون رجلًا»: عشرون عدد مبهم، رجلًا فسّرته وبينته = عشرون من الرجال. إعرابها: تمييز منصوب بالفتحة. «وتصدّقْ بصاعٍ أرزًا»: بصاع مبهم، أرزًا فسّره = بصاع من الأرز.","فالتمييز المفرد يلي الأعداد والمقادير (الكيل والوزن والمساحة): عشرون رجلًا، صاعٌ أرزًا، كيلو أرزًا... ينزع إبهام العدد والمقدار.","الثاني: «تمييز نسبة: وهو ما كان تفسيره بنسبة فعل إلى اسم، وهو الذي توضع قبله (من جهة)». أمثلة الكتاب: «طاب المؤمنُ نفسًا»: أي طاب من جهة النفس. «وركّت حتانُ خلقًا»: أي من جهة الخلق. «واشتمألت البضعُ شيئًا»... والمعروف: «وازدادَ الرجلُ عقلًا». «وسيبويهِ أقدمُ من الكسائيِّ وفاةً»: أي من جهة الوفاة.","فتمييز النسبة ينسب الفعل إلى جزء من الذات: ما الذي طاب من المؤمن؟ نفسه. ما الذي ازداد؟ عقله. وهو يوضح الجهة التي وقع فيها الحكم.","إعراب التمييز كله: «تمييز منصوب وعلامة نصبه الفتحة» - مفردًا كان أو نسبة. وهو دائمًا اسم نكرة منصوب."],"examples":["مضى عشرون رجلًا: تمييز مفرد منصوب (عشرون من الرجال)","تصدّق بصاعٍ أرزًا: تمييز مفرد (صاع من الأرز)","طاب المؤمنُ نفسًا: تمييز نسبة (من جهة النفس)","ازداد الرجلُ عقلًا: تمييز نسبة (من جهة العقل)","سيبويه أقدم من الكسائي وفاةً: تمييز نسبة (من جهة الوفاة)","اشتريتُ كيلو لحمًا: تمييز مفرد بعد مقدار"],"questions":[{"question":"ما تعريف التمييز؟","options":["اسم نكرة يُفسَّر به ما قبله على معنى «من»","اسم معرفة يوضح الفاعل","مصدر منصوب بعد فعله","وصف يوافق موصوفه"],"answer":0,"explanation":"التمييز اسم نكرة منصوب يزيل إبهام ما قبله: مضى عشرون رجلًا = عشرون من الرجال."},{"question":"ما ضابط التمييز؟","options":["أن تضع قبله «من» أو «من جهة»","أن تضع قبله «حالة كونه»","أن تضع قبله «الموصوف بأنه»","أن يكون معرفة"],"answer":0,"explanation":"ضابطه وضع «من» (للمفرد) أو «من جهة» (للنسبة) قبله: عشرون رجلًا = عشرون من الرجال."},{"question":"ما نوعا التمييز؟","options":["تمييز مفرد وتمييز نسبة","معرب ومبني","ظاهر ومستتر","زماني ومكاني"],"answer":0,"explanation":"نوعان: مفرد يفسَّر بمفرد وتوضع قبله «من» (عشرون رجلًا)، ونسبة توضع قبله «من جهة» (طاب المؤمن نفسًا)."},{"question":"ما الذي يتبعه التمييز المفرد غالبًا؟","options":["الأعداد والمقادير المبهمة","الأفعال الناقصة","حروف الجر","الضمائر"],"answer":0,"explanation":"التمييز المفرد يلي الأعداد (عشرون رجلًا) والمقادير (صاع أرزًا، كيلو لحمًا) فيزيل إبهامها."},{"question":"ما إعراب التمييز دائمًا؟","options":["منصوب وعلامة نصبه الفتحة","مرفوع","مجرور","يتبع ما قبله"],"answer":0,"explanation":"التمييز منصوب دائمًا: تمييز منصوب وعلامة نصبه الفتحة، مفردًا كان أم نسبة."}]},{"body":["تدريب إعرابي: «عندي عشرةُ كتبٍ» - خطأ شائع! الصواب: «عندي عشرةُ كتابٍ»؟ لا: التمييز بعد الأعداد يكون مجرورًا بالإضافة في العدد المركب... انتبه: تمييز العدد البسيط من 3-10 يكون جمعًا مجرورًا (ثلاثة كتب)، ومن 11-99 مفردًا منصوبًا (عشرون كتابًا)، ومئة وألف تمييزهما مفرد مجرور (مئة كتاب).","في هذا الباب نتكلم عن التمييز المنصوب بعد الأعداد من أحد عشر إلى تسعة وتسعين وبعد المقادير: «قرأتُ خمسةَ عشرَ درسًا»: درسًا تمييز منصوب بالفتحة.","تمييز النسبة تدريبات: «اشتدَّ الرجلُ عودًا»: اشتد فعل ماضٍ، الرجل فاعل، عودًا تمييز منصوب بالفتحة - أي اشتد من جهة العود (الجسم). «طابتْ نفسي عملًا»: أي من جهة العمل.","الفرق بين التمييز والحال: الحال يجيب «كيف؟» ويصح قبله «حالة كونه» (جاء راكبًا)، والتمييز يجيب «ماذا/في أي جهة؟» ويصح قبله «من» أو «من جهة» (طاب نفسًا). الحال يبين هيئة، والتمييز يبين ماهية وجهة.","والفرق بينه وبين المفعول به: المفعول به وقع الفعل عليه (أكلتُ تمرًا)، والتمييز يفسر مبهمًا قبله (عندي صاعٌ تمرًا). جرب: «أكلتُ صاعًا تمرًا»: صاع مفعول به، تمرًا تمييز يفسّر الصاع - اجتمعا في جملة واحدة!","الخلاصة: التمييز نكرة منصوبة بعد مبهم (عدد أو مقدار أو حكم) تزيل إبهامه: مفرد بـ«من» ونسبة بـ«من جهة». وبه نكون أتممنا ثلاثة من المنصوبات المكملة: المفاعيل، الحال، التمييز؛ ويبقى المستثنى والمنادى في الدفعة القادمة بإذن الله."],"examples":["قرأتُ خمسةَ عشرَ درسًا: تمييز مفرد منصوب","اشتدَّ الرجلُ عودًا: تمييز نسبة منصوب","أكلتُ صاعًا تمرًا: مفعول به + تمييز","ثلاثةُ كتبٍ: تمييز العدد 3-10 مجرور بالإضافة","مئةُ كتابٍ: تمييز المئة مفرد مجرور","عندي صاعٌ أرزًا وكيلو لحمًا: تمييزان مفردان منصوبان"],"questions":[{"question":"ما إعراب «درسًا» في «قرأتُ خمسةَ عشرَ درسًا»؟","options":["تمييز منصوب وعلامة نصبه الفتحة","مفعول به","مضاف إليه مجرور","حال منصوب"],"answer":0,"explanation":"درسًا تمييز منصوب بالفتحة؛ لأنه فسّر العدد المركب «خمسة عشر» = خمسة عشر من الدروس."},{"question":"ما تمييز الأعداد من ثلاثة إلى عشرة؟","options":["جمع مجرور بالإضافة","مفرد منصوب","مفرد مجرور","جمع منصوب"],"answer":0,"explanation":"الأعداد 3-10 تمييزها جمع مجرور: ثلاثة كتب؛ ومن 11-99 مفرد منصوب: عشرون كتابًا؛ ومئة وألف مفرد مجرور."},{"question":"أعرب «عودًا» في «اشتدَّ الرجلُ عودًا»:","options":["تمييز نسبة منصوب بالفتحة","حال منصوب","مفعول به","نعت"],"answer":0,"explanation":"عودًا تمييز نسبة منصوب: اشتد الرجل من جهة العود؛ الضابط صحة «من جهة» قبله."},{"question":"ما الفرق بين التمييز والحال؟","options":["التمييز يصح قبله «من/من جهة» والحال «حالة كونه»","لا فرق","الحال مفرد فقط","التمييز معرفة"],"answer":0,"explanation":"الحال يبين الهيئة (جاء راكبًا = حالة كونه راكبًا)؛ والتمييز يبين الماهية أو الجهة (طاب نفسًا = من جهة النفس)."},{"question":"في «أكلتُ صاعًا تمرًا» ما إعراب «صاعًا» و«تمرًا»؟","options":["صاعًا مفعول به وتمرًا تمييز","صاعًا تمييز وتمرًا مفعول به","كلاهما مفعول به","كلاهما تمييز"],"answer":0,"explanation":"صاعًا مفعول به (وقع الأكل عليه) وتمرًا تمييز يفسر الصاع المبهم = صاع من التمر؛ اجتمعا في جملة."}]}]},{"id":"wahi-sharh-031","title":"المستثنى: التعريف والأركان والأدوات","section":"شرح الكتاب: باب المستثنى","order":31,"segments":[{"body":["رابع المنصوبات من المكملات: «المستثنى». تعريفه: «اسم يقع بعد أداة استثناء». الاستثناء في اللغة: الإخراج - أي نخرج شيئًا من حكم الجملة: «سافر الإخوةُ إلا وهبًا» = كلهم سافروا لكن وهبًا خارج منهم.","للاستثناء ثلاثة أركان (أعمدة لا يقوم بدونها): ١- المستثنى منه: وهو الأصل الذي نخرج منه (الإخوة). ٢- أداة الاستثناء (إلا). ٣- المستثنى: وهو المخرج من الحكم (وهبًا).","أدوات الاستثناء كما عدّها الكتاب: أ- «إلا» وهي حرف. ب- «غير وسوى» وهما اسمان. ج- «عدا وخلا وحاشا» ويجوز كونها حروف جرّ وأفعالًا ماضية.","مثال الأركان مجتمعة: «نجح الطلابُ (المستثنى منه) إلا (أداة الاستثناء) المهملَ (المستثنى)». درّب عينك على رؤية الثلاثة في كل جملة استثناء.","«غير وسوى» اسمان يعربان إعراب المستثنى وما بعدهما مضاف إليه: «سافر الإخوةُ غيرَ وهبٍ»: غير مستثنى منصوب وهو مضاف، ووهب مضاف إليه مجرور. و«ساوى» تأتي في التثنية «سوى» والجمع «أَسْوِيَة»... والشائع «سوى».","«عدا وخلا وحاشا» لها حالتان: إن جعلتها حرف جر جررتَ ما بعدها: «سافر الإخوةُ عدا وهبٍ» (وهب مجرور بحرف الجر). وإن جعلتها فعلًا ماضيًا نصبتَ ما بعدها مفعولًا به: «سافر الإخوةُ عدا وهبًا»، وفاعلها ضمير مستتر تقديره «هو»، والمعنى: أَعْدَى وهبًا أي أخرجه.","إذن أدوات الاستثناء سبع: إلا، غير، سوى، عدا، خلا، حاشا، ويضاف إليها «لا يكون» و«يكون غير» في الاستثناء المفرغ، لكن حفظ الأساسيات الست يكفيك الآن."],"examples":["سافر الإخوةُ إلا وهبًا: مستثنى منه + أداة + مستثنى","نجح الطلابُ إلا المهملَ: أركان الاستثناء الثلاثة","سافر الإخوةُ غيرَ وهبٍ: غير مستثنى منصوب مضاف","حضر القومُ سوى زيدٍ: سوى مستثنى مضاف","سافر الإخوةُ عدا وهبٍ: عدا حرف جر ووهب مجرور","سافر الإخوةُ عدا وهبًا: عدا فعل ماضٍ ووهب مفعول به"],"questions":[{"question":"ما تعريف المستثنى؟","options":["اسم يقع بعد أداة استثناء","اسم يقع بعد حرف جر","اسم منصوب بعد فعل","اسم يقع بعد واو المعية"],"answer":0,"explanation":"المستثنى اسم يقع بعد أداة استثناء: سافر الإخوة إلا وهبًا؛ والاستثناء إخراج الشيء من الحكم."},{"question":"ما أركان الاستثناء الثلاثة؟","options":["المستثنى منه وأداة الاستثناء والمستثنى","الفعل والفاعل والمفعول","المبتدأ والخبر والناسخ","النعت والمنعوت والحال"],"answer":0,"explanation":"ثلاثة: المستثنى منه (الإخوة)، وأداة الاستثناء (إلا)، والمستثنى (وهبًا)."},{"question":"ما أدوات الاستثناء كما في الكتاب؟","options":["إلا وغير وسوى وعدا وخلا وحاشا","الواو والفاء وثم","كان وإن وظن","من وإلى وعن"],"answer":0,"explanation":"إلا: حرف؛ وغير وسوى: اسمان؛ وعدا وخلا وحاشا: تجوز فيها حروفية الجر وفعلية الماضي."},{"question":"ما حكم «غير» و«سوى»؟","options":["اسمان يعربان إعراب المستثنى وما بعدهما مضاف إليه","حرفا جر","فعلان ماضيان","أداة نفي"],"answer":0,"explanation":"غير وسوى اسمان: يعربان إعراب ما بعد إلا (مستثنى منصوب غالبًا) ويكونان مضافين، وما بعدهما مضاف إليه مجرور."},{"question":"ما الحالتان لـ«عدا وخلا وحاشا»؟","options":["حروف جر أو أفعال ماضية","أسماء معرفة","أدوات نصب","أدوات جزم"],"answer":0,"explanation":"يجوز فيها أن تكون حروف جر (سافروا عدا وهبٍ - مجرور) أو أفعالًا ماضية فاعلها مستتر (عدا وهبًا - مفعول به)."}]},{"body":["تدريب: حدد الأركان: «قرأ الطلابُ الدرسَ إلا خالدٌ». المستثنى منه: الطلاب. الأداة: إلا. المستثنى: خالد. والدرس مفعول به لا دخل له بالاستثناء.","«غير» تُعرب إعرابَ ما بعد إلا بالتسوية: قال الكتاب: «والاسم المستثنى بغير وسوى يُعرب مضافًا إليه، وتُعرب غير وسوى إعرابَ ما بعد إلا في حالاته الثلاث». أي أينما جاءت إلا وما بعدها جاءت غير مكانها بنفس الإعراب.","أمثلة الكتاب الثلاثة على غير: «سافر الإخوةُ غيرُ وهبٍ»: هنا غير بدل من واو الجماعة مرفوع (كأنك قلت: ما سافر الإخوة إلا وهب - فوهب بدل مرفوع... سنفصّل الأحوال في الدرس التالي). «وما سافروا غيرَ وهبٍ»: غير مستثنى منصوب. «وما سافر غيرُ وهبٍ»: غير فاعل مرفوع.","معنى هذا: غير تأخذ حكم الموضع: إن كان الاستثناء تامًّا مثبتًا فمنصوبة، وإن كان منفيًّا فعلى البدلية، وإن كان ناقصًا فبحسب موقعها.","تنبيه: «إلا» نفسها حرف مبني على الفتح لا محل له من الإعراب، يوصف: أداة استثناء. و«غير» اسم معرب، لذا نقول لها إعرابًا (منصوب/مرفوع/في محل رفع...) ولا نقول ذلك لإلا.","تدريب على عدا: «خرج الجيشُ عدا المرضى» - المرضى مجرور (عدا حرف جر). و«خرج الجيشُ عدا المرضى» بنصب المرضى - (عدا فعل ماضٍ فاعله مستتر والمرضى مفعول به). كلتاهما صحيحة.","الخلاصة: الاستثناء ثلاثة أركان وست أدوات: إلا حرف، غير وسوى اسمان مضافان، عدا وخلا وحاشا بين الجر والفعلية. والدرس التالي: أحكام المستثنى الأربعة."],"examples":["قرأ الطلابُ الدرسَ إلا خالدٌ: الأركان الثلاثة + مفعول به","سافر الإخوةُ غيرُ وهبٍ: غير بدل مرفوع","ما سافروا غيرَ وهبٍ: غير مستثنى منصوب","ما سافر غيرُ وهبٍ: غير فاعل مرفوع","خرج الجيشُ عدا المرضى: عدا حرف جر","خرج الجيشُ عدا المرضى بنصبها: عدا فعل ماضٍ"],"questions":[{"question":"حدد أركان الاستثناء في «قرأ الطلابُ الدرسَ إلا خالدٌ»:","options":["الطلاب مستثنى منه، إلا أداة، خالد مستثنى","الدرس مستثنى منه","إلا مستثنى","خالد أداة"],"answer":0,"explanation":"المستثنى منه: الطلاب؛ الأداة: إلا؛ المستثنى: خالد؛ والدرس مفعول به خارج الاستثناء."},{"question":"كيف تُعرب «غير»؟","options":["إعراب ما بعد إلا في حالاته، وما بعدها مضاف إليه","حرف مبني دائمًا","مفعول به دائمًا","فاعل دائمًا"],"answer":0,"explanation":"غير اسم معرب يأخذ حكم موضعه: منصوبة في التام المثبت، وعلى البدلية في المنفي، وبحسب الموقع في الناقص؛ وما بعدها مضاف إليه."},{"question":"في «ما سافر غيرُ وهبٍ» ما إعراب «غير»؟","options":["فاعل مرفوع","مستثنى منصوب","مفعول به","مبتدأ"],"answer":0,"explanation":"الاستثناء هنا ناقص (لا مستثنى منه) فنعرب بحسب الموقع: غير فاعل مرفوع، ووهب مضاف إليه."},{"question":"ما إعراب «إلا» نفسها؟","options":["حرف استثناء مبني على الفتح لا محل له من الإعراب","اسم منصوب","فعل ماضٍ","حرف جر"],"answer":0,"explanation":"إلا حرف استثناء مبني على الفتح لا محل له من الإعراب؛ بخلاف غير فهي اسم معرب."},{"question":"أي الجمل صحيحة في «عدا»؟","options":["كلتاهما: خرج الجيش عدا المرضى (جرًّا) وعدا المرضى (نصبًا)","الجر فقط","النصب فقط","لا تصح عدا أداة استثناء"],"answer":0,"explanation":"عدا يجوز فيها الوجهان: حرف جر فيجر ما بعدها، أو فعل ماضٍ فاعله مستتر فينصب ما بعدها مفعولًا به."}]}]},{"id":"wahi-sharh-032","title":"أحكام المستثنى الأربعة","section":"شرح الكتاب: باب المستثنى - الأحكام","order":32,"segments":[{"body":["للمستثنى في الاستثناء الكامل أحكام أربعة يحددها شيئان: هل الجملة تامة أم ناقصة؟ وهل هي مثبتة أم منفية؟ فلنفهم المصطلحين أولًا.","«التام»: تام الأركان - أي فيه مستثنى منه وأداة ومستثنى. «الناقص»: ناقص المستثنى منه - ليس في الجملة أصل يخرج منه المستثنى.","«المثبت»: غير المسبوق بنفي أو نهي أو استفهام (سافر الإخوة إلا وهبًا). «المنفي»: مسبوق بنفي أو نهي أو استفهام (ما سافر الإخوة إلا وهب).","الحكم الأول: الاستثناء التام المثبت: «ويجب فيه نصب المستثنى». أمثلة الكتاب: «سافر الإخوةُ إلا وهبًا»: مستثنى منصوب بالفتحة. «الطلابُ ناجحون إلا المهملينَ»: مستثنى منصوب بالياء (جمع مذكر سالم).","الحكم الثاني: الاستثناء التام المنفي: «ويجوز فيه في المستثنى وجهان: أ- كونه بدلًا من المستثنى منه، ب- وكونه مستثنى منصوبًا». أمثلة الكتاب: «ما سافر الإخوةُ إلا وهبٌ (بدل مرفوع)» و«إلا وهبًا (مستثنى منصوب)». «لم ينجح الطلابُ إلا المجتهدونَ (بدل مرفوع)» و«إلا المجتهدينَ (مستثنى منصوب)».","معنى البدلية هنا: ما سافر الإخوةُ إلا وهبٌ = لم يسافر أحدٌ لكن وهب سافر؛ فوهب «بدل» من الإخوة: أُثبت له ما نُفي عنهم. والوجه الثاني يبقيه مستثنى منصوبًا كأصله.","الحكم الثالث: الاستثناء الناقص (وهو ناقص المستثنى منه): «ويعرب فيه المستثنى بحسب ما قبل إلا». أي انظر إلى الجملة كأن إلا ليست فيها وأعرب الاسم على موقعه: «ما سافر إلا وهبٌ»: فاعل، كقولك: سافر وهبٌ. «ما سافر وهبٌ إلا ليلًا»: ظرف زمان، كقولك: سافر وهب ليلًا. «ما سافر وهبٌ إلا خائفًا»: حال، كقولك: سافر وهب خائفًا."],"examples":["سافر الإخوةُ إلا وهبًا: تام مثبت - وجوب النصب","الطلابُ ناجحون إلا المهملينَ: مستثنى منصوب بالياء","ما سافر الإخوةُ إلا وهبٌ: تام منفي - بدل مرفوع","ما سافر الإخوةُ إلا وهبًا: تام منفي - مستثنى منصوب","ما سافر إلا وهبٌ: ناقص - فاعل","ما سافر وهبٌ إلا ليلًا: ناقص - ظرف زمان"],"questions":[{"question":"ما الاستثناء التام؟","options":["ما كملت أركانه الثلاثة (فيه مستثنى منه)","ما ليس فيه أداة","ما ليس فيه مستثنى","المنفي فقط"],"answer":0,"explanation":"التام: تام الأركان أي فيه مستثنى منه وأداة ومستثنى: سافر الإخوة إلا وهبًا."},{"question":"ما حكم المستثنى في الاستثناء التام المثبت؟","options":["وجوب النصب","وجوب الرفع","جواز الوجهين","الإعراب بحسب الموقع"],"answer":0,"explanation":"التام المثبت يجب فيه نصب المستثنى: سافر الإخوة إلا وهبًا - بالفتحة، وإلا المهملين - بالياء للجمع."},{"question":"ما الوجهان في الاستثناء التام المنفي؟","options":["البدل من المستثنى منه أو المستثنى المنصوب","الرفع فقط أو الجر فقط","النصب أو الجزم","لا وجهان"],"answer":0,"explanation":"التام المنفي يجوز فيه: ما سافر الإخوة إلا وهبٌ (بدل مرفوع)، أو إلا وهبًا (مستثنى منصوب)."},{"question":"ما حكم المستثنى في الاستثناء الناقص؟","options":["يُعرب بحسب ما قبل إلا على موقعه","يُنصب وجوبًا","يُرفع وجوبًا","يكون بدلًا دائمًا"],"answer":0,"explanation":"الناقص (بلا مستثنى منه) يعرب بحسب موقعه: ما سافر إلا وهبٌ (فاعل)، إلا ليلًا (ظرف)، إلا خائفًا (حال)."},{"question":"كيف تعرف أن الاستثناء منفي؟","options":["يسبقه نفي أو نهي أو استفهام","يسبقه فعل أمر","يكون آخر الجملة","يكون مستثناه جمعًا"],"answer":0,"explanation":"المنفي ما سبق بنفي (ما سافر) أو نهي (لا تسافر) أو استفهام (هل سافر)؛ والمثبت خلافه."}]},{"body":["جدول الأحكام الأربعة للحفظ: ١- تام مثبت → نصب وجوبًا (جاء القوم إلا زيدًا). ٢- تام منفي → بدل أو نصب (ما جاء القوم إلا زيدٌ/زيدًا). ٣- ناقص → بحسب الموقع (ما جاء إلا زيدٌ - فاعل). ٤- تذكير بالمستثنى بغير: يتبع هذه الأحكام نفسها.","تدريب ١: «قام المصلون إلا معذورًا»: تام مثبت (لا نفي) → مستثنى منصوب بالفتحة وجوبًا.","تدريب ٢: «لا يفلحُ المفرطون إلا التائبينَ/التائبونَ»: تام منفي (سبق بلا النافية) → وجهان: التائبين مستثنى منصوب بالياء، أو التائبون بدل مرفوع بالواو.","تدريب ٣: «ما في البيتِ إلا كتابٌ»: ناقص (لا مستثنى منه - ليس قبلها اسم صالح أن يكون أصلًا... بل «ما في البيت» نفي) → نعرب كتاب على موقعه بعد «في البيت»: خبر مقدم؟ الأدق: «ما في البيت إلا كتابٌ» كتاب خبر مؤخر مرفوع (الأصل: كتاب في البيت).","تدريب ٤: «ما ضربتُ إلا زيدًا»: ناقص؛ الموقع بعد فعل متعدٍّ يحتاج مفعولًا → زيدًا مفعول به منصوب (الأصل: ضربت زيدًا).","فائدة بلاغية: البدل في التام المنفي يفيد الحصر أحيانًا: «ما نجح إلا المجتهدُ» = النجاح خاص بالمجتهد لا غيره. لهذا يكثر هذا الأسلوب في القرآن: «ما لهم به من علمٍ إلا اتباعَ الظنِّ».","الخلاصة: اسأل سؤالين: هل في الجملة مستثنى منه؟ (تام/ناقص). هل قبلها نفي أو نهي أو استفهام؟ (منفي/مثبت). ثم طبّق: تام مثبت: نصب. تام منفي: بدل أو نصب. ناقص: بحسب الموقع."],"examples":["قام المصلون إلا معذورًا: تام مثبت منصوب وجوبًا","لا يفلح المفرطون إلا التائبين: تام منفي - مستثنى منصوب","لا يفلح المفرطون إلا التائبون: تام منفي - بدل مرفوع","ما في البيت إلا كتابٌ: ناقص - خبر مرفوع","ما ضربتُ إلا زيدًا: ناقص - مفعول به","ما لهم به من علم إلا اتباع الظن: أسلوب حصر"],"questions":[{"question":"أعرب «معذورًا» في «قام المصلون إلا معذورًا»:","options":["مستثنى منصوب وجوبًا","بدل مرفوع","فاعل","حال"],"answer":0,"explanation":"الاستثناء تام (فيه المصلون مستثنى منه) مثبت (لا نفي) فيجب النصب: مستثنى منصوب بالفتحة."},{"question":"أعرب «التائبون» في «لا يفلح المفرطون إلا التائبون»:","options":["بدل مرفوع وعلامة رفعه الواو","مستثنى منصوب وجوبًا","فاعل","مبتدأ"],"answer":0,"explanation":"تام منفي يجوز فيه البدلية: التائبون بدل من المفرطين مرفوع بالواو؛ ويجوز: إلا التائبين - مستثنى منصوب."},{"question":"أعرب «زيدًا» في «ما ضربتُ إلا زيدًا»:","options":["مفعول به منصوب (استثناء ناقص)","مستثنى منصوب وجوبًا","فاعل","بدل مرفوع"],"answer":0,"explanation":"الاستثناء ناقص (لا مستثنى منه) فيعرب بحسب موقعه: الأصل «ضربت زيدًا» - مفعول به منصوب."},{"question":"ما الفائدة البلاغية للبدل في «ما نجح إلا المجتهدُ»؟","options":["الحصر: النجاح خاص بالمجتهد","التشبيه","الاستعارة","التوكيد اللفظي"],"answer":0,"explanation":"أسلوب «ما... إلا» بمعنى الحصر: نفي الحكم عن الكل وإثباته للمستثنى وحده؛ يكثر في القرآن."},{"question":"ما السؤالان اللذان يحددان حكم المستثنى؟","options":["هل فيه مستثنى منه؟ وهل قبله نفي أو نهي أو استفهام؟","هل هو مفرد؟ وهل هو معرفة؟","هل قبله فعل؟ وهل هو نكرة؟","لا سؤالان"],"answer":0,"explanation":"سؤالان: التمام (فيه مستثنى منه؟) والإثبات (سبق بنفي أو نهي أو استفهام؟)؛ وعليهما تترتب الأحكام الثلاثة."}]}]},{"id":"wahi-sharh-033","title":"المنادى: التعريف وأدوات النداء","section":"شرح الكتاب: باب المنادى","order":33,"segments":[{"body":["خامس المنصوبات من المكملات: «المنادى». تعريفه: «اسم يقع بعد حرف نداء». النداء: أن تطلب من شخص أن يُقبل عليك: «يا محمدُ!» = أقبِل يا محمد.","حروف النداء كما في الكتاب: الهمزة (اَ)، ويا، وأي، وهيا، وأيّ... قال: «وحروف النداء: الهمزة ويا وأي وهيا»، نحو: اَ محمدُ، يا محمدُ، آي محمدُ، أيْ محمدُ، هيا محمدُ.","أكثرها استعمالًا «يا» وتسمى «أم الباب» لشهرتها. والهمزة للنداء القريب، ويا للقريب والبعيد، وأيّ وهيا للبعيد جدًا أو للترقيق. وأيْ مختصة بالندبة (نداء الحزن كأيْ شباهُ).","حروف النداء كلها مبنية: يا: حرف نداء مبني على السكون... بل على الفتح في الأكثر، لا محل له من الإعراب. والهمزة كذلك حرف نداء مبني على الفتح.","مثال معرب كامل: «يا محمدُ أقبِلْ»: يا: حرف نداء مبني لا محل له من الإعراب. محمدُ: منادى (سنفصّل إعرابه في الدرس التالي: مبني على الضم في محل نصب). أقبل: فعل أمر وفاعله مستتر «أنت».","النداء قد يكون للغائب في التشويق والتعجب: «يا ليلى!» وقد ينادى غير العاقل للحض أو التوجع: «يا قلبُ لا تحزنْ». وفي القرآن: «يا بنيَّ أقمِ الصلاةَ».","المنادى مكمل وليس ركنًا: الجملة تتم بدونه: «محمدٌ مقبلٌ» جملة كاملة؛ و«يا محمدُ أقبلْ» أضفنا النداء للطلب."],"examples":["يا محمدُ: يا حرف نداء ومحمد منادى","اَ محمدُ: الهمزة للنداء القريب","هيا محمدُ: هيا للبعيد أو الترقيق","يا بنيَّ أقم الصلاة: منادى مضاف لياء المتكلم","يا قلبُ لا تحزن: نداء غير العاقل","أيْ شباهُ: أي للندبة"],"questions":[{"question":"ما تعريف المنادى؟","options":["اسم يقع بعد حرف نداء","اسم يقع بعد حرف جر","اسم يقع بعد أداة استثناء","اسم مرفوع أول الجملة"],"answer":0,"explanation":"المنادى اسم يقع بعد حرف نداء: يا محمدُ؛ والنداء طلب إقبال المنادى."},{"question":"ما حروف النداء في الكتاب؟","options":["الهمزة ويا وأي وهيا (وأيّ)","إلا وغير وسوى","كان وصار وليس","الواو والفاء وثم"],"answer":0,"explanation":"حروف النداء: الهمزة للقريب، ويا أشهرها (أم الباب)، وأي وهيا للبعيد أو الترقيق، وأيْ للندبة."},{"question":"أي حرف نداء يسمى «أم الباب»؟","options":["يا","الهمزة","أيّ","هيا"],"answer":0,"explanation":"يا أكثر حروف النداء استعمالًا وتسمى أم الباب؛ تنادي القريب والبعيد."},{"question":"ما إعراب حروف النداء؟","options":["حروف مبنية لا محل لها من الإعراب","أسماء منصوبة","أفعال أمر","حروف جر"],"answer":0,"explanation":"حروف النداء كلها مبنية لا محل لها من الإعراب، توصف: حرف نداء."},{"question":"هل المنادى ركن من أركان الجملة؟","options":["لا؛ بل مكمل من المكملات المنصوبات","نعم ركن أساسي","نعم خبر المبتدأ","نعم فاعل"],"answer":0,"explanation":"المنادى من مكملات الجملتين المنصوبات: الجملة تتم بدونه، وهو يضيف طلب الإقبال."}]},{"body":["تدريب على إعراب جمل النداء كاملة: «يا معلمُ علّمنا»: يا حرف نداء مبني لا محل له، معلم منادى (سنفصّل حكمه: مبني على الضم في محل نصب)، علّم فعل أمر مبني، نا مفعول به في محل نصب، وفاعل الأمر مستتر «أنت».","«يا مسلمونَ اتحدوا»: مسلمون منادى مبني على الواو (لأنه جمع مذكر سالم) في محل نصب. نعم: المنادى حكمه الإجمالي النصب، لكن صورته تتغير كما سنرى.","نداء المعرفة بأل: الأصل ألا ينادى الاسم المعرف بأل إلا في التركيب الخاص «يا اللهُ» أو بأداة «أيها/أيتها»: «يا أيها المؤمنونَ»: أيها أداة نداء مبنية، والمؤمنون منادى مبني على الواو في محل نصب.","المنادى المضاف: «يا عبدَ اللهِ»: عبد منادى منصوب بالفتحة وهو مضاف، والله مضاف إليه مجرور. المضاف ينصب ولا يبنى - هذا التفصيل في الدرس التالي.","النداء في القرآن كثير: «يا أيها الناسُ اعبدوا ربكم»، «يا موسى أقبِلْ»، «يا يحيى خذِ الكتابَ». تأمل في كل مرة: حرف النداء ثم المنادى ثم جملة الطلب.","الخلاصة: المنادى اسم بعد حرف نداء (يا أشهرها)، من مكملات المنصوبات، وإعرابه التفصيلي بنوعيه في الدرس التالي."],"examples":["يا معلمُ علّمنا: نداء + أمر","يا مسلمونَ اتحدوا: منادى جمع مذكر","يا أيها المؤمنون: أيها أداة نداء","يا عبدَ الله: منادى مضاف منصوب","يا يحيى خذ الكتاب: نداء قرآني","يا ليلى: نداء تشويق للغائب"],"questions":[{"question":"أعرب «معلمُ» في «يا معلمُ علّمنا»:","options":["منادى مبني على الضم في محل نصب","مبتدأ مرفوع","فاعل مرفوع","منادى منصوب بالفتحة"],"answer":0,"explanation":"معلم اسم واحد معرفة (علم) فيبنى على الضم في محل نصب - تفصيل البناء والنصب في الدرس التالي."},{"question":"كيف ننادي الاسم المعرف بأل؟","options":["بأداة «أيها/أيتها»: يا أيها المؤمنون","نحذف أل دائمًا","بيا مباشرة","لا ينادى أبدًا"],"answer":0,"explanation":"المعرف بأل ينادى بأيها/أيتها: يا أيها الناس؛ واستثناء خاص: يا الله."},{"question":"أعرب «عبدَ» في «يا عبدَ اللهِ»:","options":["منادى منصوب بالفتحة وهو مضاف","منادى مبني على الضم","مضاف إليه مجرور","مبتدأ"],"answer":0,"explanation":"المنادى المضاف معرب منصوب بالفتحة: عبد منادى منصوب وهو مضاف، والله مضاف إليه مجرور."},{"question":"ما إعراب «نا» في «علّمنا»؟","options":["مفعول به في محل نصب","فاعل","منادى","مضاف إليه مجرور"],"answer":0,"explanation":"نا ضمير متصل مبني على السكون في محل نصب مفعول به، وفاعل الأمر مستتر تقديره أنت."},{"question":"ما موضع المنادى من أحكام الكلام؟","options":["من المكملات المنصوبات","من أركان الجملة الفعلية","من المجرورات","من المرفوعات"],"answer":0,"explanation":"المنادى خامس المنصوبات من مكملات الجملتين: المفاعيل، الحال، التمييز، المستثنى، المنادى."}]}]},{"id":"wahi-sharh-034","title":"نوعا المنادى: المبني والمعرب","section":"شرح الكتاب: باب المنادى - الأنواع","order":34,"segments":[{"body":["قسم الكتاب المنادى نوعين: النوع الأول: «ما كان اسمًا واحدًا ولا يلي منه... فهذا يُبنى على ما يُرفع به» (في محل نصب). أي المنادى الذي هو كلمة واحدة معيّنة (علم أو ما يقوم مقامه) نبنيه على علامة رفعه ونقدّر له محل النصب.","أمثلة الكتاب الثلاثة: «يا محمدانِ»: منادى مبني على الألف في محل نصب (مثنى: علامة رفعه الألف). «يا محمدونَ»: منادى مبني على الواو في محل نصب (جمع مذكر سالم: علامة رفعه الواو). «يا رجلٌ»: منادى مبني على الضم في محل نصب (هنا نكرة مقصودة: رجل بعينه تقصده).","فالقاعدة: المنادى المفرد العلم والنكرة المقصودة والمثنى وجمع المذكر السالم - إذا لم يضف - يبنى على ما يرفع به في محل نصب. لماذا «في محل نصب»؟ لأن أصل المنادى منصوب (المعنى: أدعو محمدًا = أدعو + مفعول به)، لكن العرب ثبّتوه على صورة الرفع تخفيفًا.","النوع الثاني: «وما سوى ذلك فهو معرب منصوب»، ويشمل صورتين: أ- ما كان أكثر من اسم: نحو «يا عبدَ العزيزِ» و«يا غفارَ الذنوبِ»: منادى منصوب وعلامة نصبه الفتحة. هنا المنادى مركب إضافي: عبد مضاف والعزيز مضاف إليه - فصار أكثر من اسم فنصب.","ب- وما كان غير معيّن (النكرة غير المقصودة): نحو «يا غافلًا اتقِ اللهَ» و«يا حاجًّا احفظ حجَّك»: منادى منصوب بالفتحة. غير المعين = لا تقصد شخصًا بعينه بل أي غافل وأي حاج.","جدول مبسط: منادى واحد معين (محمد، رجل بعينه، محمدان، محمدون) → مبني على الرفع في محل نصب. منادى أكثر من اسم أو مضاف (عبد الله) أو نكرة غير مقصودة (غافلًا) → معرب منصوب بالفتحة."],"examples":["يا محمدانِ: مبني على الألف في محل نصب","يا محمدونَ: مبني على الواو في محل نصب","يا رجلٌ: نكرة مقصودة مبني على الضم في محل نصب","يا عبدَ العزيزِ: مركب إضافي منصوب بالفتحة","يا غفارَ الذنوبِ: منصوب بالفتحة وهو مضاف","يا غافلًا اتق الله: نكرة غير مقصودة منصوبة"],"questions":[{"question":"ما حكم المنادى الذي هو اسم واحد معين؟","options":["يبنى على ما يرفع به في محل نصب","ينصب بالفتحة دائمًا","يجر بالكسرة","يبنى على السكون"],"answer":0,"explanation":"المنادى الواحد المعين (علم أو نكرة مقصودة أو مثنى أو جمع مذكر) يبنى على علامة رفعه في محل نصب: يا محمدُ."},{"question":"لماذا يقال للمنادى المبني «في محل نصب»؟","options":["لأن أصله منصوب (أدعو محمدًا) لكنه ثبت على صورة الرفع","لأنه مرفوع حقيقة","لأنه مجرور","لأنه فاعل"],"answer":0,"explanation":"أصل النداء: أدعو محمدًا - منصوب؛ لكن العرب بنت المنادى الواحد المعين على علامة الرفع وقدّرت له محل النصب."},{"question":"أعرب «محمدونَ» في «يا محمدونَ»:","options":["منادى مبني على الواو في محل نصب","منادى منصوب بالفتحة","فاعل مرفوع","مبتدأ مرفوع"],"answer":0,"explanation":"محمدون جمع مذكر سالم؛ المنادى منه يبنى على الواو (علامة رفعه) في محل نصب."},{"question":"متى يكون المنادى معربًا منصوبًا؟","options":["إذا كان أكثر من اسم (مضافًا) أو نكرة غير مقصودة","إذا كان علمًا مفردًا","إذا كان مثنى","إذا كان جمع مذكر"],"answer":0,"explanation":"المنادى المعرب المنصوب: ما سوى الواحد المعين: المضاف (يا عبد الله) والنكرة غير المقصودة (يا غافلًا)."},{"question":"ما الفرق بين النكرة المقصودة وغير المقصودة في النداء؟","options":["المقصودة تبنى على الضم (يا رجلٌ) وغير المقصودة تنصب (يا غافلًا)","كلتاهما مبنية","كلتاهما منصوبة","المقصودة تنصب"],"answer":0,"explanation":"النكرة المقصودة تقصد بها شخصًا بعينه فتبنى على الضم في محل نصب؛ وغير المقصودة تنادي أي أحد فتنصب بالفتحة."}]},{"body":["تدريبات متنوعة: «يا طالبَ العلمِ»: طالب منادى منصوب بالفتحة وهو مضاف (أكثر من اسم)، والعلم مضاف إليه مجرور.","«يا باحثُ»: باحث اسم واحد (وصف تقصد به شخصًا بعينه = نكرة مقصودة أو اسم جنس مقصود) → مبني على الضم في محل نصب.","«يا راكبًا أوقِفِ الدراجةَ»: راكبًا نكرة غير مقصودة (أي راكب) → منادى معرب منصوب بالفتحة.","«يا حسنُ»: علم مفرد → مبني على الضم في محل نصب. «يا حسنا»: خطأ؛ العلم المفرد لا ينصب في النداء.","«يا أبتا»: علم مفرد منقوص (منتهٍ بألف مقصورة أصلية) → يبنى على فتح مقدر في محل نصب. و«يا يحيى»: كذلك.","تنبيه: ياء المتكلم مع المنادى: «يا عبدي»: عبد منادى مبني على الضم المقدر في محل نصب (والياء مضاف إليه)... المضاف إلى ياء المتكلم يلحقه حكم خاص عند بعضهم: يجوز بناؤه ونصبه؛ والأشهر البناء على الضم المقدر.","الخلاصة: انظر إلى المنادى: واحد ومعين؟ ابنه على رفعه وقل: في محل نصب. غير ذلك (مضاف أو أكثر أو نكرة غير مقصودة)؟ انصبه بالفتحة. وبهذا أتممنا المنصوبات الخمسة من المكملات: المفاعيل والحال والتمييز والمستثنى والمنادى."],"examples":["يا طالبَ العلم: مضاف منصوب","يا باحثُ: واحد مقصود مبني على الضم","يا راكبًا أوقف الدراجة: نكرة غير مقصودة منصوبة","يا حسنُ: علم مفرد مبني","يا عبدي: مبني على الضم المقدر مع ياء المتكلم","يا أبتا: علم منقوص مبني على فتح مقدر"],"questions":[{"question":"أعرب «طالبَ» في «يا طالبَ العلمِ»:","options":["منادى منصوب بالفتحة وهو مضاف","منادى مبني على الضم","مضاف إليه","نعت"],"answer":0,"explanation":"طالب مضاف (أكثر من اسم) فينصب: منادى منصوب بالفتحة وهو مضاف، والعلم مضاف إليه مجرور."},{"question":"لماذا «يا حسنُ» مبني و«يا طالبَ العلمِ» منصوب؟","options":["حسن اسم واحد معين وطالب مضاف","حسن نكرة","طالب علم","لا فرق"],"answer":0,"explanation":"حسن علم مفرد (اسم واحد معين) فيبنى على الضم في محل نصب؛ وطالب العلم مركب إضافي فينصب بالفتحة."},{"question":"ما حكم المنادى المضاف إلى ياء المتكلم «يا عبدي»؟","options":["يبنى على ضم مقدر في محل نصب على الأشهر","ينصب وجوبًا","يجر وجوبًا","يبنى على الفتح"],"answer":0,"explanation":"المضاف إلى ياء المتكلم يبنى على ضم مقدر في محل نصب على الأشهر، ويجوز النصب عند بعضهم."},{"question":"«يا راكبًا» - لماذا نصبنا ولم نبنِ؟","options":["لأنها نكرة غير مقصودة (أي راكب)","لأنها علم","لأنها مثنى","لأنها جمع مذكر"],"answer":0,"explanation":"راكبًا هنا تنادي أي راكب لا شخصًا بعينه = نكرة غير مقصودة، فتعرب منصوبة بالفتحة."},{"question":"ما المنصوبات الخمسة من المكملات؟","options":["المفاعيل والحال والتمييز والمستثنى والمنادى","المبتدأ والخبر والفاعل ونائبه واسم كان","النعت والعطف والتوكيد والبدل والظرف","المضاف والمجرور والنعت والحال والبدل"],"answer":0,"explanation":"المكملات المنصوبات خمسة: المفاعيل الخمسة، الحال، التمييز، المستثنى، المنادى؛ وبعدها المجرورات والتوابع."}]}]},{"id":"wahi-sharh-035","title":"المكملات المجرورة: المجرور بحرف الجر","section":"شرح الكتاب: الشرب الثاني: المكملات المجرورات - باب المجرور بحرف الجر","order":35,"segments":[{"body":["أتممنا المنصوبات من المكملات، والآن «الشرب الثاني: المكملات المجرورات». وهي نوعان: ١- الاسم المجرور بحرف جر. ٢- الاسم المجرور بالإضافة. نبدأ بالأول.","تعريف المجرور بحرف الجر: «الاسم الواقع بعد حرف جر». وحروف الجر كما عدّها الكتاب: من، إلى، عن، على، في، اللام، الباء، الكاف، ربّ، واو (القسم)، مذ، منذ، حتى. وأحرف القسم وهي: الباء والواو والتاء. وأحرف الاستثناء (الجارة): خلا وعدا وحاشا.","حروف الجر كلها مبنية لا محل لها من الإعراب، وتجرّ الاسم بعدها: تدخل على الاسم فتغيّر آخره إلى حالة الجر (الكسرة أو ما ينوب عنها).","مثال الكتاب المعرب: «واللهِ إنَّ المؤمنينَ إلى الصلاةِ في الظلم... سكينةٌ للمؤمنين» (الأصل: واللهِ إنَّ المؤمنين لداعون إلى الصلاة في سكينة...). واللهِ: الواو حرف قسم وجر مبني على الفتح لا محل له من الإعراب. اسم الله: اسم مجرور بالواو وعلامة جره الكسرة. الصلاةِ: اسم مجرور بـ«إلى» وعلامة جره الكسرة. الظلم... (في): اسم مجرور بـ«في» وعلامة جره الكسرة.","تكملة أمثلة: «سكينةٍ»: اسم مجرور بالباء وعلامة جره الكسرة. «للمؤمنينَ»: اسم مجرور باللام وعلامة جره الياء (جمع مذكر سالم يجر بالياء).","علامات الجر: الكسرة للمفرد وجمع التكسير وجمع المؤنث السالم (المسلماتِ)، والياء للمثنى وجمع المذكر السالم (معلمَي الكتابِ، للمؤمنينَ)، والفتحة للممنوع من الصرف (مساجدَ)، وبالحروف: الياء للأسماء الخمسة (أبيكَ).","الجار والمجرور معًا يسميان «شبه جملة» ويتعلقان بفعل أو اسم قبلهما: «كتبتُ بالقلمِ»: بالقلم متعلق بكتبت. ولا يستقلان بمعنى تام وحدهما."],"examples":["من وإلى وعن وعلى وفي: أشهر حروف الجر","واللهِ: واو القسم + اسم مجرور بالكسرة","إلى الصلاةِ: مجرور بإلى بالكسرة","بسكينةٍ: مجرور بالباء بالكسرة","للمؤمنينَ: مجرور باللام بالياء (جمع مذكر)","مساجدَ: مجرور بالفتحة (ممنوع من الصرف)"],"questions":[{"question":"ما تعريف المجرور بحرف الجر؟","options":["الاسم الواقع بعد حرف جر","الاسم بعد المضاف","الاسم المرفوع","الاسم بعد حرف النسخ"],"answer":0,"explanation":"المجرور بحرف الجر: اسم يقع بعد حرف من حروف الجر فيجره: كتبت بالقلمِ."},{"question":"عدّ حروف الجر التي في الكتاب:","options":["من إلى عن على في اللام الباء الكاف رب واو مذ منذ حتى","إن أن لكن كأن لعل ليت","الواو الفاء ثم أو أم","إلا غير سوى"],"answer":0,"explanation":"حروف الجر: من، إلى، عن، على، في، اللام، الباء، الكاف، رب، واو، مذ، منذ، حتى؛ وأحرف القسم الباء والواو والتاء، وأحرف الاستثناء الجارة: خلا عدا حاشا."},{"question":"ما إعراب حروف الجر نفسها؟","options":["مبنية لا محل لها من الإعراب","منصوبة","مرفوعة","مجرورة"],"answer":0,"explanation":"حروف الجر كلها مبنية لا محل لها من الإعراب، توصف: حرف جر، وتعمل عملها في الاسم بعدها."},{"question":"ما علامة جر جمع المذكر السالم والمثنى؟","options":["الياء","الكسرة","الفتحة","الألف"],"answer":0,"explanation":"المثنى وجمع المذكر السالم يجران بالياء: للمؤمنينَ، بمعلمَي الكتابِ."},{"question":"متى يجر الاسم بالفتحة؟","options":["إذا كان ممنوعًا من الصرف","إذا كان مفردًا","إذا كان ضميرًا","إذا كان مثنى"],"answer":0,"explanation":"الممنوع من الصرف يجر بالفتحة نيابة عن الكسرة: مساجدَ، أحمدَ."}]},{"body":["تدريبات على الجر بالحرف: «ذهبتُ من البيتِ إلى المسجدِ»: من حرف جر مبني، البيتِ مجرور بالكسرة؛ إلى حرف جر، المسجدِ مجرور بالكسرة.","مع المثنى: «سلمتُ على المعلمينِ» - خطأ إن كانوا اثنين؛ الصواب للمثنى: «سلمتُ على المعلمَينِ»: المعلمين مجرور بعلى وعلامة جره الياء لأنه مثنى. وللجمع: «على المعلمينَ» بالياء أيضًا لأنه جمع مذكر سالم.","مع جمع المؤنث السالم: «قرأتُ في المجلاتِ»: المجلات مجرور بالكسرة (جمع المؤنث السالم يجر بالكسرة وينصب بها أيضًا).","مع الأسماء الخمسة: «سلمتُ على أخيكَ»: أخيك مجرور بعلى وعلامة جره الياء (الأسماء الخمسة تجر بالياء) والكاف مضاف إليه.","القسم: «تاللهِ لأجتهدنَّ»: التاء حرف قسم وجر مبني على الفتح، والله مجرور بها بالكسرة. أحرف القسم ثلاثة: الباء (بالله)، الواو (والله)، التاء (تالله).","متى يتصل الجار والمجرور بما قبله؟ دائمًا: إما بفعل (كتب بالقلم) أو باسم مشتق (الكتابةُ بالقلمِ) أو بخبر مبتدأ محذوف (القلمُ في المكتبِ: في المكتب خبر). فلا تجد جارًّا ومجرورًا سائبًا بلا متعلق.","الخلاصة: المجرور بحرف الجر: اسم بعد حرف جر، علامته الكسرة أو الياء أو الفتحة، والجار والمجرور شبه جملة متعلقة بما قبلها."],"examples":["ذهبتُ من البيتِ إلى المسجدِ: مجروران بالكسرة","سلمتُ على المعلمَينِ: مثنى مجرور بالياء","قرأتُ في المجلاتِ: جمع مؤنث مجرور بالكسرة","سلمتُ على أخيكَ: الأسماء الخمسة تجر بالياء","تاللهِ لأجتهدنَّ: تاء القسم","القلمُ في المكتبِ: الجار والمجرور خبر المبتدأ"],"questions":[{"question":"أعرب «البيتِ» في «ذهبتُ من البيتِ إلى المسجدِ»:","options":["اسم مجرور بمن وعلامة جره الكسرة","مفعول فيه","مضاف إليه","فاعل"],"answer":0,"explanation":"البيت اسم مجرور بحرف الجر «من» وعلامة جره الكسرة الظاهرة؛ والجار والمجرور متعلقان بذهبت."},{"question":"أعرب «أخيكَ» في «سلمتُ على أخيكَ»:","options":["اسم مجرور بعلى وعلامة جره الياء لأنه من الأسماء الخمسة","مفعول به منصوب بالألف","فاعل مرفوع بالواو","منادى"],"answer":0,"explanation":"أخو من الأسماء الخمسة: يرفع بالواو وينصب بالألف ويجر بالياء؛ هنا مجرور بعلى فجر بالياء والكاف مضاف إليه."},{"question":"ما أحرف القسم الثلاثة؟","options":["الباء والواو والتاء","من وعن وعلى","إن وأن ولا","لم ولن ولو"],"answer":0,"explanation":"أحرف القسم: الباء (بالله) والواو (والله) والتاء (تالله)؛ وهي حروف جر تجر المقسم به."},{"question":"بم يتعلق الجار والمجرور؟","options":["بفعل أو اسم قبلهما، ولا يستقلان وحدهما","لا يتعلقان بشيء","بما بعدهما فقط","بحرف النداء"],"answer":0,"explanation":"الجار والمجرور شبه جملة متعلقة بفعل (كتب بالقلم) أو خبر محذوف (القلم في المكتب)؛ لا معنى لها سائبة."},{"question":"ما علامة جر جمع المؤنث السالم؟","options":["الكسرة","الياء","الفتحة","الألف"],"answer":0,"explanation":"جمع المؤنث السالم يجر وينصب بالكسرة: قرأتُ في المجلاتِ - مجرور بالكسرة."}]}]},{"id":"wahi-sharh-036","title":"المجرور بالإضافة","section":"شرح الكتاب: باب المجرور بالإضافة","order":36,"segments":[{"body":["النوع الثاني من المجرورات: «المجرور بالإضافة». أولًا ما الإضافة؟ قال الكتاب: «الإضافة: اسمين يدلان على شيء واحد».","مثال الكتاب: «قلم» اسم يدل على آلة الكتابة، و«الأستاذ» اسم يدل على من يشرح ويعلّم - اسمان منفصلان يدلان على شيئين. فإذا قيل: «قلم الأستاذ» صار اسمين يدلان على شيء واحد (قلم معين مضاف لصاحبه). والذي جعل الاسمين يدلان على شيء واحد هو الإضافة.","الأول منهما يسمى «مضافًا» ويُعرب على حسب موقعه في الجملة (مرفوع أو منصوب أو مجرور)، والآخر يسمى «مضافًا إليه» وحكمه الجر دائمًا.","إعراب المضاف إليه: «فإن كان معربًا فهو مجرور»، نحو: «قلمُ ظافرَ»: ظافر مضاف إليه مجرور وعلامة جره الكسرة. «وإن كان مبنيًّا فهو في محل جر»، نحو: «قلمُكَ»: الكاف مضاف إليه في محل جر مبني على الفتح.","تذكير بما سبق في المعرفة: الإضافة تنكّر المضاف أو تخصّصه: «بابٌ» نكرة، «بابُ المسجدِ» صار معينًا بالإضافة. لذلك المضاف لا يقبل «أل» ولا تنوين.","الإضافة نوعان عند العلماء: لفظية (قلم الأستاذ: لفظان لشيء واحد) ومعنوية (تمليكية). والمهم لك الآن: مضاف + مضاف إليه مجرور.","أمثلة متنوعة: «بابُ المسجدِ» (باب مضاف مرفوع، المسجد مضاف إليه مجرور). «قرأتُ كتابَ الطالبِ» (كتاب مضاف منصوب، الطالب مضاف إليه مجرور). «سلمتُ على أستاذِ الرياضياتِ» (أستاذ مضاف مجرور بالحرف، الرياضيات مضاف إليه مجرور بالإضافة). لاحظ: قد يجتمع الجران في تركيب واحد."],"examples":["قلم + الأستاذ = قلم الأستاذ: اسمان يدلان على شيء واحد","قلمُ ظافرَ: مضاف إليه مجرور بالكسرة","قلمُكَ: الكاف مضاف إليه في محل جر","بابُ المسجدِ: مضاف مرفوع + مضاف إليه مجرور","قرأتُ كتابَ الطالبِ: مضاف منصوب + مضاف إليه مجرور","سلمتُ على أستاذِ الرياضياتِ: جران متتاليان"],"questions":[{"question":"ما تعريف الإضافة؟","options":["اسمين يدلان على شيء واحد","اسم واحد بمعنيين","فعل وفاعل","مبتدأ وخبر"],"answer":0,"explanation":"الإضافة اسمين يدلان على شيء واحد: قلم الأستاذ - القلم معين بإضافته للأستاذ."},{"question":"ما حكم المضاف؟","options":["يعرب على حسب موقعه في الجملة","مجرور دائمًا","مرفوع دائمًا","منصوب دائمًا"],"answer":0,"explanation":"المضاف يعرب بحسب موقعه: رفعًا (باب المسجدِ كبير) ونصبًا (قرأت كتاب الطالب) وجرًّا (سلمت على أستاذ الرياضيات)."},{"question":"ما حكم المضاف إليه؟","options":["الجر دائمًا","الرفع دائمًا","النصب دائمًا","حسب موقعه"],"answer":0,"explanation":"المضاف إليه مجرور دائمًا: معربًا فبالكسرة أو ما ينوب عنها (قلم ظافرَ)، مبنيًّا ففي محل جر (قلمُكَ)."},{"question":"أعرب «الكاف» في «قلمُكَ»:","options":["مضاف إليه في محل جر مبني على الفتح","مفعول به","فاعل","نعت"],"answer":0,"explanation":"الضمير المتصل مبني؛ وقوعه مضافًا إليه يجعله في محل جر: قلمك - الكاف في محل جر مضاف إليه."},{"question":"لماذا لا يقبل المضاف «أل» ولا تنوين؟","options":["لأن الإضافة عرّفته أو خصّصته فاستغنى عنهما","لأنه مجرور","لأنه مبني","لأنه ممنوع من الصرف"],"answer":0,"explanation":"المضاف صار معينًا بالإضافة؛ فلا يجمع بينها وبين أل والتنوين: لا نقول القلمُ الأستاذِ ولا قلمٌ الأستاذِ."}]},{"body":["معاني الإضافة الثلاثة كما في الكتاب: «الإضافة تكون على معنى ثلاثة أحرف جر»: ١- بمعنى «في» نحو: «صلاةُ الليلِ وصومُ النهارِ ونومُ الضحى»: صلاة في الليل، وصوم في النهار، ونوم في الضحى.","٢- بمعنى «من» نحو: «بابُ خشبٍ وثوبُ حريرٍ وخاتمُ فضةٍ»: باب من خشب، وثوب من حرير، وخاتم من فضة. هذه تسمى إضافة بيان الجنس: المضاف إليه يبيّن مادة الشيء.","٣- بمعنى اللام (الملك أو الاختصاص) نحو: «سيارةُ أحمدَ وكتابُ الطالبِ ومفتاحُ البابِ»: سيارة لأحمد، وكتاب للطالب، ومفتاح للباب.","اختبار سريع لمعنى الإضافة: جرّب الحروف الثلاثة: «في» و«من» و«اللام» - أيهما أصلح المعنى فهو معنى إضافتك: «غلطةُ الطفلِ» = غلطة من الطفل أو للطفل... حسب المقام. «ذنبُ الليلِ»؟ لا: صيام الليل = في الليل.","الإضافة قد تتسلسل: «بابُ بيتِ خالدٍ»: باب مضاف، بيت مضاف إليه مجرور وهو مضاف لخالد، خالد مضاف إليه مجرور. كل اسم يلي مضافًا يكون مضافًا إليه مجرورًا ولو كان نفسه مضافًا.","تنبيه مهم: المضاف إليه الوحيد الذي يتقدم على مضافه هو المضاف إلى ياء المتكلم في النداء المبني... هذا تفصيل لا يشغلك الآن. القاعدة الذهبية: مضاف إليه = مجرور أبدًا.","الخلاصة: الإضافة اسمان لشيء واحد: الأول مضاف يعرب بموقعه، الثاني مضاف إليه مجرور أبدًا، بمعنى في أو من أو اللام."],"examples":["صلاةُ الليل: بمعنى في","بابُ خشبٍ: بمعنى من (بيان الجنس)","سيارةُ أحمدَ: بمعنى اللام (الملك)","بابُ بيتِ خالدٍ: إضافتان متسلسلتان","مفتاحُ البابِ: بمعنى اللام","ثوبُ حريرٍ: بمعنى من"],"questions":[{"question":"على أي معاني تأتي الإضافة؟","options":["في ومن واللام","على وعن وإلى","الواو والفاء وثم","كان وإن وظن"],"answer":0,"explanation":"ثلاثة: صلاة الليل = في الليل؛ باب خشب = من خشب؛ سيارة أحمد = لأحمد."},{"question":"ما معنى إضافة «بابُ خشبٍ»؟","options":["بمعنى «من»: باب من خشب (بيان الجنس)","بمعنى في","بمعنى اللام","بمعنى على"],"answer":0,"explanation":"إضافة بيان الجنس: المضاف إليه يبين مادة المضاف: باب من خشب، خاتم من فضة."},{"question":"أعرب «بيتِ» في «بابُ بيتِ خالدٍ»:","options":["مضاف إليه مجرور وهو مضاف","مضاف مرفوع فقط","نعت","بدل"],"answer":0,"explanation":"بيت مضاف إليه مجرور بالكسرة وهو نفسه مضاف، وخالد مضاف إليه ثانٍ مجرور؛ الإضافة قد تتسلسل."},{"question":"أي تركيب إضافته بمعنى «في»؟","options":["صومُ النهارِ","خاتمُ فضةٍ","سيارةُ أحمدَ","مفتاحُ البابِ"],"answer":0,"explanation":"صوم النهار = صوم في النهار: المضاف إليه يبين الزمان؛ أما خاتم فضة فبمعنى من وسيارة أحمد بمعنى اللام."},{"question":"هل يكون المضاف إليه مرفوعًا في حالة ما؟","options":["لا؛ مجرور أبدًا","نعم إذا كان فاعلًا","نعم إذا تقدم","نعم في النداء فقط"],"answer":0,"explanation":"المضاف إليه مجرور أبدًا لا يتغير: معربًا فبالعلامة، مبنيًّا ففي محل جر؛ هذه القاعدة الذهبية."}]}]},{"id":"wahi-sharh-037","title":"أحكام المضاف: حذف التنوين والنون","section":"شرح الكتاب: باب المجرور بالإضافة - أحكام المضاف","order":37,"segments":[{"body":["للمضاف أحكام ثلاثة يجب ضبطها، وكلها تدور على الحذف. قال الكتاب: «ويحذف من المضاف ما فيه من تنوين».","الحكم الأول: حذف التنوين نحو: «معلمُ ظافرٍ وبابُ المسجدِ وأبوابُ المسجدِ وممراتُ المسجدِ». لا نقول «معلمٌ ظافرٌ» بالتنوين - التنوين يسقط من المضاف لأن الإضافة كفتنا تخصيصه. لاحظ الأمثلة: مفرد (معلمُ)، وجمع تكسير (أبوابُ)، وجمع مؤنث سالم (ممراتُ) - كلها بلا تنوين.","الحكم الثاني: حذف نون المثنى نحو: «معلما ظافرٍ وبابا المسجدِ». المثنى الأصل فيه: معلمانِ. فإذا أضفناه حذفنا النون: معلما. وكذلك في النصب والجر: رأيت معلمَي ظافرٍ، مررت بمعلمَي ظافرٍ - النون محذوفة في الأحوال الثلاث.","الحكم الثالث: حذف نون جمع المذكر السالم نحو: «معلمو ظافرٍ ومهندسو الشركةِ». الأصل: معلمونَ ومهندسونَ. بالإضافة: معلمو، مهندسو - النون تسقط.","لماذا تحذف النون تحديدًا؟ لأن نون المثنى وجمع المذكر السالم «عوض عن التنوين» فيهما؛ فكما حذفنا التنوين من المفرد حذفنا عوضه منهما. قاعدة شاملة: المضاف يتجرد من كل علامة تنوين أو ما ينوب عنه.","تنبيه إعرابي: نون المثنى وجمع المذكر تحذف إعرابًا لا لحنًا فقط: يجب كتابتها محذوفة ونطقها محذوفة: «معلمو الشركةِ» لا «معلمونَ الشركةِ» - والخطأ فيها من الأخطاء الشائعة جدًا في الكتابة.","جمع المؤنث السالم لا نون فيه أصلًا (مسلماتٌ) فيكفيه حذف التنوين: «معلماتُ المدرسةِ». وكذلك جمع التكسير: «أبوابُ المسجدِ»."],"examples":["معلمُ ظافرٍ: تنوين محذوف من المفرد","أبوابُ المسجدِ: جمع تكسير بلا تنوين","ممراتُ المسجدِ: جمع مؤنث بلا تنوين","معلما ظافرٍ: نون المثنى محذوفة","معلمو ظافرٍ: نون جمع المذكر محذوفة","مهندسو الشركةِ: نون محذوفة بالإضافة"],"questions":[{"question":"ماذا يحذف من المضاف؟","options":["التنوين ونون المثنى ونون جمع المذكر السالم","أل فقط","آخر حرف","الحركات"],"answer":0,"explanation":"يحذف من المضاف: التنوين (معلمُ ظافر)، ونون المثنى (معلما ظافر)، ونون جمع المذكر السالم (معلمو ظافر)."},{"question":"لماذا تحذف نون المثنى وجمع المذكر مع الإضافة؟","options":["لأنها عوض عن التنوين فيهما فتحذف كما يحذف","لأنها زائدة أصلًا","للتخفيف فقط بلا سبب","لأنها علامة جر"],"answer":0,"explanation":"نون المثنى وجمع المذكر عوض عن التنوين؛ فكما يسقط التنوين من المضاف تسقط النون عوضه: معلما، معلمو."},{"question":"أي صيغة صحيحة؟","options":["معلمو الشركةِ","معلمونَ الشركةِ","معلمٌ الشركةِ","المعلمو الشركة"],"answer":0,"explanation":"الصواب: معلمو الشركة - نون جمع المذكر تحذف بالإضافة، ولا تنوين ولا أل في المضاف."},{"question":"ماذا يكفي جمع المؤنث السالم المضاف؟","options":["حذف التنوين فقط لأنه لا نون فيه","حذف النون","حذف التاء","حذف أل"],"answer":0,"explanation":"جمع المؤنث السالم (مسلمات) لا نون فيه؛ فيكفي حذف التنوين: معلماتُ المدرسةِ."},{"question":"هل حذف النون من المضاف كتابة فقط؟","options":["لا؛ تحذف كتابة ونطقًا","نعم كتابة فقط","نطقًا فقط","تثبت في الوقف"],"answer":0,"explanation":"النون تحذف كتابة ونطقًا: معلمو الشركة؛ وإثباتها من أشهر الأخطاء في الكتابة العربية."}]},{"body":["تدريب عملي: أضف ثم اضبط: «الكتابان» + «الطالب» = كتابا الطالبِ (حذفنا النون والتنوين). إعرابه إن وقع فاعلًا: كتابا: فاعل مرفوع بالألف (مثنى مضاف، حذفت نونه)، والطالب مضاف إليه مجرور.","«المهندسون» + «الشركة» في موضع نصب: «كرّم المديرُ مهندسي الشركةِ»: مهندسي مفعول به منصوب بالياء (جمع مذكر مضاف محذوف النون)، والشركة مضاف إليه مجرور. لاحظ: حذف النون في الرفع والنصب والجر سواء.","«المعلمات» + «المدرسة»: «سلمتُ على معلماتِ المدرسةِ»: معلمات مجرور بالكسرة (جمع مؤنث مضاف محذوف التنوين)، والمدرسة مضاف إليه مجرور.","خطأ شائع آخر: الإضافة إلى المعرف بأل: «قلمُ الأستاذِ» صحيح - المضاف إليه يجوز فيه أل؛ الممنوع أل في المضاف نفسه: لا نقول «القلمُ الأستاذِ» بمعنى قلم الأستاذ المعين إلا بفصل... القاعدة: أل ممنوعة في المضاف، جائزة في المضاف إليه.","الإضافة غير الحقيقية (اللامية): نحو «حسنُ الخلقِ»: المضاف إليه هنا وصف للمضاف لا مالك له؛ وحكمها حكم الإضافة في الجر وحذف التنوين. «قليلُ الذنوبِ»، «كثيرُ الخيرِ» - كلها إضافات وصفية.","تدريب شامل: أعرب: «طلابُ العلمِ مجتهدونَ»: طلاب مبتدأ مرفوع بالضمة (جمع تكسير مضاف، محذوف التنوين)، العلم مضاف إليه مجرور، مجتهدون خبر مرفوع بالواو.","الخلاصة: المضاف يتجرد: لا تنوين، لا نون مثنى، لا نون جمع مذكر، لا أل. والمضاف إليه مجرور ثابت."],"examples":["كتابا الطالب: مثنى مضاف محذوف النون","كرّم المديرُ مهندسي الشركة: جمع مذكر منصوب بالياء محذوف النون","معلماتِ المدرسة: جمع مؤنث مضاف","حسنُ الخلق: إضافة وصفية","طلابُ العلمِ مجتهدون: مبتدأ مضاف","قلمُ الأستاذ: أل في المضاف إليه جائزة"],"questions":[{"question":"أعرب «كتابا» في «كتابا الطالبِ جديدانِ»:","options":["مبتدأ مرفوع بالألف مضاف محذوف النون","مبتدأ مرفوع بالضمة","مضاف إليه مجرور","نعت"],"answer":0,"explanation":"كتابا مثنى مرفوع بالألف (علامة رفع المثنى) وهو مضاف حذفت نونه للإضافة، والطالب مضاف إليه مجرور."},{"question":"هل تحذف نون المضاف في النصب والجر كما في الرفع؟","options":["نعم في الأحوال الثلاثة","في الرفع فقط","في النصب فقط","لا تحذف أصلًا"],"answer":0,"explanation":"نون المثنى وجمع المذكر تحذف رفعًا ونصبًا وجرًّا: معلمو الشركة، رأيت معلمي الشركة، مررت بمعلمي الشركة."},{"question":"أين تجوز «أل» في تركيب الإضافة؟","options":["في المضاف إليه ولا تجوز في المضاف","في المضاف فقط","فيهما معًا","لا تجوز أبدًا"],"answer":0,"explanation":"المضاف ممنوع من أل (لأن الإضافة خصصته) والمضاف إليه تجوز فيه: قلمُ الأستاذِ."},{"question":"ما الإضافة الوصفية (اللامية)؟","options":["أن يكون المضاف إليه وصفًا للمضاف كـ«حسنُ الخلقِ»","إضافة الملك فقط","إضافة الزمان","لا توجد"],"answer":0,"explanation":"الإضافة اللامية: المضاف إليه يصف المضاف لا يملكه: حسن الخلق، قليل الذنوب؛ وحكمها حكم الإضافة في الجر وحذف التنوين."},{"question":"أعرب «طلابُ» في «طلابُ العلمِ مجتهدونَ»:","options":["مبتدأ مرفوع بالضمة وهو مضاف","مضاف إليه","خبر مرفوع","فاعل"],"answer":0,"explanation":"طلاب جمع تكسير مبتدأ مرفوع بالضمة وهو مضاف (محذوف التنوين)، والعلم مضاف إليه مجرور، ومجتهدون خبر مرفوع بالواو."}]}]},{"id":"wahi-sharh-038","title":"التوابع: التعريف والنعت","section":"شرح الكتاب: الشرب الثالث: المكملات التوابع - باب النعت","order":38,"segments":[{"body":["«الشرب الثالث: المكملات التوابع». التوابع تعريفها: «ألفاظ تتبع ما قبلها في إعرابه: رفعًا ونصبًا وجرًّا وجزمًا». أي تأخذ حكم المتبوع بالضبط.","وهي أربعة كما في الكتاب: «النعت، والمعطوف، والتوكيد، والبدل». سبق أن أخذنا الحال وقلنا إنه يشبه النعت لكنه يلزم النصب؛ الآن نأخذ التوابع الحقيقية الأربعة.","لماذا سميت توابع؟ لأنها كالتابع في السير: حيث ذهب المتبوع ذهبت: مرفوعًا فمرفوعة، منصوبًا فمنصوبة، مجرورًا فمجرورة، مجزومًا (في الأفعال) فمجزومة.","الباب الأول: «النعت» - وقد سبق شرحه مع أحكام الكلام في باب الحال؛ نراجعه هنا: النعت «وصف يبين صفة من صفات صاحبه، ويوافقه في التعريف أو التنكير». ضابطه: أن تضع قبله «الموصوف بأنه».","النعت يتبع المنعوت في أربعة أشياء: ١- الإعراب (رفعًا ونصبًا وجرًّا). ٢- التعريف والتنكير. ٣- التذكير والتأنيث. ٤- العدد (إفراد وتثنية وجمع) في الغالب.","أمثلة التتبع: «جاء الطالبُ المجتهدُ» (مرفوع مرفوع). «رأيتُ الطالبَ المجتهدَ» (منصوب منصوب). «مررتُ بالطالبِ المجتهدِ» (مجرور مجرور). «جاءت الطالبةُ المجتهدةُ» (تأنيث يتبع تأنيثًا). «جاء الطلابُ المجتهدونَ» (جمع يتبع جمعًا).","فرق النعت عن الحال مرة أخرى باختصار: النعت موافق لموصوفه تعريفًا وتنكيرًا وإعرابًا (السيارة الجديدة)، والحال نكرة منصوبة مخالفة لصاحبها في التعريف (السيارة جديدةً)."],"examples":["جاء الطالبُ المجتهدُ: نعت مرفوع تابع","رأيتُ الطالبَ المجتهدَ: نعت منصوب تابع","مررتُ بالطالبِ المجتهدِ: نعت مجرور تابع","جاءت الطالبةُ المجتهدةُ: تأنيث تابع","جاء الطلابُ المجتهدونَ: جمع تابع","السيارةُ جديدةً: حال منصوب (للمقارنة)"],"questions":[{"question":"ما تعريف التوابع؟","options":["ألفاظ تتبع ما قبلها في إعرابه رفعًا ونصبًا وجرًّا وجزمًا","أسماء مرفوعة فقط","أفعال ماضية","حروف جر"],"answer":0,"explanation":"التوابع أربع: النعت والمعطوف والتوكيد والبدل؛ وتتبع متبوعها في الإعراب كله."},{"question":"كم عدد التوابع وما هي؟","options":["أربعة: النعت والمعطوف والتوكيد والبدل","ثلاثة: النعت والحال والبدل","خمسة","اثنان"],"answer":0,"explanation":"التوابع أربعة: النعت، والمعطوف (العطف)، والتوكيد، والبدل."},{"question":"في ماذا يتبع النعت منعوتَه؟","options":["الإعراب والتعريف والتنكير والتذكير والتأنيث والعدد","الإعراب فقط","التعريف فقط","لا يتبعه في شيء"],"answer":0,"explanation":"النعت يتبع منعوته في: الإعراب، والتعريف والتنكير، والتذكير والتأنيث، والعدد غالبًا."},{"question":"أعرب «المجتهدِ» في «مررتُ بالطالبِ المجتهدِ»:","options":["نعت مجرور وعلامة جره الكسرة","حال منصوب","مضاف إليه","بدل"],"answer":0,"explanation":"المجتهد نعت للطالب يتبعه في الجر: مجرور بالكسرة مثل متبوعه."},{"question":"ما الفرق بين النعت والحال؟","options":["النعت يوافق موصوفه تعريفًا وتنكيرًا وإعرابًا، والحال نكرة منصوبة مخالفة","كلاهما منصوب دائمًا","لا فرق","الحال معرفة"],"answer":0,"explanation":"النعت تابع موافق (السيارة الجديدةُ)؛ والحال نكرة منصوبة تبين هيئة مؤقتة (السيارة جديدةً)."}]},{"body":["النعت يأتي مفردًا كما سبق، ويأتي شبه جملة: «هذا كتابٌ غلافُه أحمرُ» - خطأ؛ شبه الجملة: «هذا كتابٌ في المكتبةِ»؟ لا - الصواب: «مررتُ برجلٍ في يدهِ عصًا»: في يده شبه جملة نعت لرجل في محل جر. وسبق في باب الحال: «جاء رجلٌ على قدميهِ» شبه الجملة نعت في محل رفع.","ويأتي النعت جملة: «اشتريتُ كتابًا يشرحُ النحوَ»: جملة يشرح فعلية نعت في محل نصب (فاعلها مستتر يعود على كتاب). و«هذا طالبٌ علمُه واسعٌ»: جملة اسمية نعت في محل جر.","النعت السبب: «جاءني رجلٌ كريمٌ أبوهُ»: كريم نعت لرجل بالمعنى: كريمٌ أبوه (أي صاحبه) - والأصل أن يعود الضمير على المنعوت.","تدريب متنوع: «قرأتُ القصصَ المفيدةَ الثلاثَ»: المفيدة نعت أول منصوب بالكسرة (جمع مؤنث)، والثلاث نعت ثانٍ منصوب (يتبع في الإعراب ولا يشترط التطابق في الجنس لاختلاف طبيعة العدد).","النعت قد يتعدد: «المؤمنُ الصادقُ المخلصُ محبوبٌ»: نعتان متتاليان كلاهما مرفوع تابع.","الخلاصة: النعت أول التوابع: يتبع متبوعه في الإعراب والتعريف والتنكير والجنس والعدد، ويأتي مفردًا وشبه جملة وجملة."],"examples":["مررتُ برجلٍ في يده عصًا: شبه جملة نعت في محل جر","اشتريتُ كتابًا يشرح النحو: جملة فعلية نعت","هذا طالبٌ علمُه واسعٌ: جملة اسمية نعت","جاءني رجلٌ كريمٌ أبوه: نعت سببي","قرأتُ القصصَ المفيدةَ الثلاثَ: نعتان","المؤمنُ الصادقُ المخلصُ محبوب: نعتان مرفوعان"],"questions":[{"question":"هل يأتي النعت جملة؟","options":["نعم: اشتريت كتابًا يشرح النحو","لا؛ مفرد فقط","لا؛ شبه جملة فقط","نعم لكن مرفوعًا دائمًا"],"answer":0,"explanation":"النعت يأتي مفردًا وشبه جملة وجملة: كتابًا يشرح النحو - الجملة الفعلية في محل نصب نعت."},{"question":"أعرب «في يده» في «مررتُ برجلٍ في يده عصًا»:","options":["شبه جملة نعت لرجل في محل جر","حال منصوب","خبر مبتدأ","مفعول فيه"],"answer":0,"explanation":"رجل نكرة و«في يده» شبه جملة توافقها في التنكير فهي نعت في محل جر؛ لو كانت بعد معرفة لكانت حالًا."},{"question":"ما النعت السببي؟","options":["نعت يتبع اسمًا قبل المنعوت المباشر: كريمٌ أبوه","نعت بلا ضمير","نعت مجرور فقط","نعت الأفعال"],"answer":0,"explanation":"النعت السببي ينعت اسمًا ويعود ضميره على المنعوت: جاءني رجل كريمٌ أبوه - أي كريمٌ صاحبُ هذا الرجل."},{"question":"هل يجوز تعدد النعوت لموصوف واحد؟","options":["نعم: المؤمن الصادق المخلص محبوب","لا؛ نعت واحد فقط","نعم لكن بالعطف حتمًا","لا يجوز إطلاقًا"],"answer":0,"explanation":"يجوز تعدد النعوت: المؤمن الصادق المخلص: كل نعت يتبع المنعوت في إعرابه."},{"question":"أعرب «الثلاثَ» في «قرأتُ القصصَ المفيدةَ الثلاثَ»:","options":["نعت ثانٍ منصوب","تمييز منصوب","مفعول به","بدل"],"answer":0,"explanation":"الثلاث نعت ثانٍ للقصص يتبعها في النصب؛ والعدد ينعت باعتبار لفظه وإن خالف التذكير والتأنيث."}]}]},{"id":"wahi-sharh-039","title":"العطف وحروفه التسعة","section":"شرح الكتاب: باب المعطوف","order":39,"segments":[{"body":["الباب الثاني من التوابع: «المعطوف» (العطف). العطف: إلحاق اسم باسم قبله بحرف عطف، فيتبعه في إعرابه.","حروف العطف تسعة كما عدّها الكتاب: ١- الواو: «جاء الولدُ وأبوهُ». ٢- الفاء: «جاء الولدُ فأبوهُ». ٣- ثم: «جاء الولدُ ثم أبوهُ». ٤- أو: «جاء الولدُ أو أبوهُ». ٥- أم: «أالولدُ جاء أم أبوهُ؟». ٦- حتى: «جاء الحجاجُ حتى المشاةَ». ٧- بل: «لا تكرم خالدًا بل فهدًا». ٨- لكنْ: «لا تكرم خالدًا لكنْ فهدًا». ٩- لا: «أكرم خالدًا لا فهدًا».","معاني الحروف: الواو: للجمع المطلق بلا ترتيب (معية). الفاء: للترتيب مع التعقيب (جاء الولد ثم أبوه فورًا). ثم: للترتيب مع التراخي (بعد مهلة). أو: للتخيير أو الإباحة. أم: للاستفهام المتصل (المنقطع). حتى: لانتهاء الغاية (وفيها خلاف: معطوفة أو حرف جر). بل ولا ولكن: للإضراب (العدول عن الحكم).","المعطوف يتبع المعطوف عليه في إعرابه تمامًا. أمثلة الكتاب المعربة: «قرأتُ في النحوِ والفقهِ»: الفقه معطوف على النحو، مجرور، وعلامة جره الكسرة. «ودرستُ النحوَ والفقهَ»: معطوف على النحو، منصوب، وعلامة نصبه الفتحة. «فسهل النحوُ والفقهُ»: معطوف على النحو، مرفوع، وعلامة رفعه الضمة.","إعراب حروف العطف: «والواو حرف عطف مبني على الفتح لا محل له من الإعراب». وكذلك جميع حروف العطف: مبنية لا محل لها من الإعراب، توصف: حرف عطف.","انتبه: الواو قد تكون للعطف (جاء زيد وعمرو) أو للمعية (سرت والقمرَ - درس سابق) أو للقسم (والله) أو للحال (جاء وهو يضحك). الفرق: العطف يتبع الإعراب، والمعية تنصب، والقسم يجر، والحال تدخل على جملة."],"examples":["جاء الولدُ وأبوه: الواو للجمع المطلق","جاء الولدُ فأبوه: الفاء للترتيب والتعقيب","جاء الولدُ ثم أبوه: ثم للترتيب والتراخي","قرأتُ في النحوِ والفقهِ: معطوف مجرور","درستُ النحوَ والفقهَ: معطوف منصوب","سهل النحوُ والفقهُ: معطوف مرفوع"],"questions":[{"question":"كم حروف العطف وعدّها:","options":["تسعة: الواو والفاء وثم وأو وأم وحتى وبل ولكن ولا","خمسة","ثلاثة","سبعة"],"answer":0,"explanation":"تسعة: الواو، الفاء، ثم، أو، أم، حتى، بل، لكن، لا؛ والمعطوف بعدها يتبع المعطوف عليه في الإعراب."},{"question":"ما الفرق بين الفاء وثم؟","options":["الفاء للترتيب مع التعقيب وثم للترتيب مع التراخي","لا فرق","الفاء للتخيير","ثم للتعقيب"],"answer":0,"explanation":"الفاء: ترتيب بلا مهلة (جاء الولد فأبوه فورًا)؛ ثم: ترتيب بعد مهلة."},{"question":"أعرب «الفقهِ» في «قرأتُ في النحوِ والفقهِ»:","options":["معطوف على النحو مجرور بالكسرة","مضاف إليه","مفعول به","نعت"],"answer":0,"explanation":"الفقه معطوف على النحو يتبعه في الجر بحرف «في»: مجرور بالكسرة، والواو حرف عطف مبني."},{"question":"أي حروف العطف للإضراب؟","options":["بل ولكن ولا","الواو والفاء","أو وأم","حتى"],"answer":0,"explanation":"بل ولكن ولا للإضراب: العدول عن الحكم: لا تكرم خالدًا بل فهدًا - أكرم فهدًا لا خالدًا."},{"question":"كيف تميز واو العطف من واو المعية؟","options":["المعطوف يتبع الإعراب والمفعول معه منصوب بمعنى مع","كلتاهما تنصب","كلتاهما عطف","واو المعية ترفع"],"answer":0,"explanation":"جاء زيد وعمرو: عمرو فاعل مثل زيد - عطف؛ سرت والقمر: القمر منصوب بمعنى مع - معية."}]},{"body":["تدريب إعرابي كامل: «سافر أحمدُ وخالدٌ إلى القاهرةِ أو الإسكندريةِ»: وخالد: الواو حرف عطف، خالد معطوف على أحمد مرفوع بالضمة. أو الإسكندرية: أو حرف عطف، الإسكندرية معطوف على القاهرة مجرور بالفتحة (ممنوع من الصرف).","«جاء الحجاجُ حتى المشاةَ»: حتى هنا عطفت المشاة على الحجاج فنصبته تبعًا... المشاة مفعول معه؟ لا: المعطوف على الفاعل يرفع: «حتى المشاةُ»؟ التركيب المشهور: «جاء الحجاج حتى المشاة» بمعنى جاءوا جميعًا حتى بلغ الأمر المشاة - والمشاة معطوف منصوب على محل... هذا من مواضع الخلاف؛ والأيسر لك: حتى بمعنى العطف يتبع ما بعدها ما قبلها.","العطف على الضمير المتصل: لا يعطف على الضمير المتصل إلا بضمير منفصل: «كرمتك وإيّاه» لا «كرمتك وهو». قاعدة: الضمير المتصل (كاف، هاء) لا يعطف عليه مباشرة.","العطف بلا: «أكرم خالدًا لا فهدًا»: لا هنا حرف عطف (زائدة للتأكيد كما قيل، أو عاطفة) وفهد معطوف منصوب. المعنى: أكرم خالدًا ولا تكرم فهدًا.","العطف على أكثر: «درستُ النحوَ والصرفَ والبلاغةَ»: عطف متسلسل، كل معطوف منصوب يتبع الأول. والعطف يتعدد بلا حدود.","الخلاصة: حروف العطف تسعة، المعطوف يتبع المعطوف عليه رفعًا ونصبًا وجرًّا، وحروف العطف مبنية لا محل لها من الإعراب."],"examples":["سافر أحمدُ وخالدٌ: معطوف مرفوع","إلى القاهرةِ أو الإسكندريةَ: معطوف مجرور بالفتحة (ممنوع)","كرمتك وإيّاه: عطف الضمير بضمير منفصل","أكرم خالدًا لا فهدًا: العطف بلا","درستُ النحوَ والصرفَ والبلاغةَ: عطف متسلسل","جاء الحجاجُ حتى المشاة: حتى العاطفة"],"questions":[{"question":"ما قاعدة العطف على الضمير المتصل؟","options":["لا يعطف عليه إلا بضمير منفصل: كرمتك وإيّاه","يعطف عليه مباشرة","لا يعطف عليه أبدًا","يعطف باسم ظاهر"],"answer":0,"explanation":"الضمير المتصل (تاء، كاف، هاء) لا يعطف عليه إلا بإعادته منفصلًا: كرمتك وإياك، لا كرمتك وأنت."},{"question":"أعرب «فهدًا» في «أكرم خالدًا لا فهدًا»:","options":["معطوف منصوب بالفتحة","مفعول به ثانٍ","بدل","مستثنى"],"answer":0,"explanation":"لا هنا عاطفة: فهد معطوف على خالد يتبعه في النصب؛ والمعنى إضراب: أكرم خالدًا ولا تكرم فهدًا."},{"question":"هل يتعدد العطف في جملة واحدة؟","options":["نعم بلا حد: درست النحو والصرف والبلاغة","لا؛ عطف واحد فقط","مرتان فقط","ثلاث مرات فقط"],"answer":0,"explanation":"العطف يتسلسل بلا حدود: درست النحوَ والصرفَ والبلاغةَ والأدبَ - كل معطوف يتبع الأول."},{"question":"أعرب «الإسكندريةَ» في «إلى القاهرةِ أو الإسكندريةَ»:","options":["معطوف مجرور بالفتحة لأنها ممنوع من الصرف","معطوف مجرور بالكسرة","مفعول به","تمييز"],"answer":0,"explanation":"الإسكندرية معطوف على القاهرة مجرور؛ ولأنها ممنوعة من الصرف (علم مؤنث مركب) جرت بالفتحة نيابة عن الكسرة."},{"question":"ما إعراب حروف العطف كلها؟","options":["مبنية لا محل لها من الإعراب","منصوبة","مجرورة","معربة حسب موقعها"],"answer":0,"explanation":"حروف العطف التسعة كلها مبنية لا محل لها من الإعراب، توصف: حرف عطف."}]}]},{"id":"wahi-sharh-040","title":"التوكيد: اللفظي والمعنوي","section":"شرح الكتاب: باب التوكيد","order":40,"segments":[{"body":["الباب الثالث من التوابع: «التوكيد». التوكيد: تقوية الكلام وإزالة الشك من ذهن السامع. وهو نوعان: لفظي ومعنوي.","النوع الأول: «التوكيد اللفظي: وهو يكون بتكرار لفظ الأول توكيدًا». أي تكرر الكلمة نفسها: نحو: «جاء السيلُ السيلُ»: الثانية توكيد لفظي مرفوع وعلامة رفعه الضمة. «وسلمتُ على الأميرِ الأميرِ»: توكيد لفظي مجرور بالكسرة. «وتخرّجتَ تخرّجتَ شاكرًا»... وقد يكون للفعل: «جاء جاء السيلُ»: توكيد لفظي للفعل السابق.","فاللفظي = كرر الكلمة كما هي: اسمًا أو فعلًا، ويعرب التوكيد إعراب المؤكَّد (الأول): مرفوعًا فمرفوع، مجرورًا فمجرور.","النوع الثاني: «التوكيد المعنوي: وهو يكون بستة ألفاظ وهي»: ١- «النفس والعين: ويكونان للمفرد والمثنى والجمع». ٢- «كلا وكلتا: ويؤكد بهما المثنى». ٣- «كل وجميع وأجمع: ويكون بها ما له أجزاء».","أمثلة الكتاب المعربة: «نجح معنٌ نفسُه»: توكيد معنوي مرفوع بالضمة. «وأكرمتُ معنًّا نفسَه»: توكيد معنوي منصوب بالفتحة. «وسلمتُ على معنٍّ نفسِه»: توكيد معنوي مجرور بالكسرة. «وأكرم الطالبَ نفسَه»: توكيد معنوي منصوب بالفتحة.","مع المثنى: «وأكرم الطالبينِ كلتَهما» (كلا/كلتا تكونان مضافتين): توكيد معنوي منصوب بالياء. مع الجمع: «وأكرم الطلابَ كلَّهم أجمعينَ»: كلهم توكيد معنوي منصوب بالفتحة، وأجمعين توكيد معنوي ثانٍ منصوب بالياء.","شرط التوكيد المعنوي: أن يضاف إلى ضمير يعود على المؤكد: نفسُه (الهاء تعود على معن)، كلَّهم (الهاء والميم تعود على الطلاب)، كلتَهما (الميم والألف تعود على الطالبين). بلا هذا الضمير لا يصح التوكيد."],"examples":["جاء السيلُ السيلُ: توكيد لفظي مرفوع","سلمتُ على الأميرِ الأميرِ: توكيد لفظي مجرور","جاء جاء السيل: توكيد لفظي للفعل","نجح معنٌ نفسُه: توكيد معنوي مرفوع","أكرمتُ معنًّا نفسَه: توكيد معنوي منصوب","أكرم الطلابَ كلَّهم أجمعين: توكيدان معنويان"],"questions":[{"question":"ما التوكيد اللفظي؟","options":["تكرار لفظ الأول نفسه توكيدًا","التوكيد بالنفس والعين","تكرار المعنى بلفظ آخر","العطف بالواو"],"answer":0,"explanation":"اللفظي: كرر الكلمة كما هي: جاء السيل السيل؛ ويعرب الثاني إعراب الأول."},{"question":"ما ألفاظ التوكيد المعنوي الستة؟","options":["النفس والعين وكلا وكلتا وكل وجميع وأجمع","الواو والفاء وثم","كان وإن وظن","من وإلى وعن"],"answer":0,"explanation":"ستة: النفس والعين (للمفرد والمثنى والجمع)، كلا وكلتا (للمثنى)، كل وجميع وأجمع (لذي الأجزاء)."},{"question":"بم تؤكد المثنى؟","options":["بكلا وكلتا","بالنفس فقط","بكل","بأجمع"],"answer":0,"explanation":"المثنى يؤكد بكلا وكلتا: أكرم الطالبين كلتهما؛ ويجوز بنفس وعين أيضًا."},{"question":"ما شرط التوكيد المعنوي؟","options":["إضافته إلى ضمير يعود على المؤكد","أن يكون مرفوعًا دائمًا","أن يكون نكرة","أن يسبق المؤكد"],"answer":0,"explanation":"لا بد من ضمير يعود على المؤكد: نفسُه، كلَّهم، كلتَهما؛ بلا عود الضمير لا يصح التوكيد."},{"question":"أعرب «كلَّهم» في «أكرم الطلابَ كلَّهم»:","options":["توكيد معنوي منصوب وعلامة نصبه الفتحة","مفعول به ثانٍ","نعت","بدل"],"answer":0,"explanation":"كلهم توكيد معنوي للطلاب منصوب بالفتحة وهو مضاف، والهاء والميم مضاف إليه يعودان على الطلاب."}]},{"body":["تدريبات: «حضر المديرُ بنفسِه»: بنفسه: الباء حرف جر، ونفس توكيد معنوي... الأدق: «حضر المديرُ نفسُه» - نفس توكيد معنوي مرفوع بالضمة. وإذا دخلت الباء فهي زائدة للتوكيد والجار والمجرور في محل رفع توكيد معنوي.","التوكيد في الأفعال: «افعلْ افعلْ» توكيد لفظي للفعل. وسبق: «وتخرجت تخرجت». التوكيد اللفظي يقع في الأسماء والأفعال جميعًا.","أجمع وأجمعون وأجمعين: تؤكد الجمع بعد «كل»: «حضر الطلابُ كلُّهم أجمعونَ»: أجمعون توكيد ثانٍ مرفوع بالواو. وتتصرف: أجمع، أجمعان، أجمعون، ميعون... المشهور: أجمع وأجمعون وأجمعين.","فائدة التوكيد: دفع توهم السامع: «جاء زيدٌ نفسُه» = ليس غلامه ولا رسوله. «رأيتُ الأميرَ عينَه» = رأيت شخصه لا صورته. التوكيد يجزم بالمعنى ويقطع الشك.","التوكيد في القرآن: «كلا سوف تعلمون ثم كلا سوف تعلمون» توكيد لفظي. و«لقد جاءكم رسول من أنفسكم»... وأمثلة التوكيد المعنوي: «حتى مطلع الفجر» لا - بل: «وكلوا واشربوا حتى يتبين لكم» - المهم: راقب التوكيد في تلاوتك وستجده كثيرًا.","الخلاصة: التوكيد لفظي (كرر اللفظ) أو معنوي (نفس، عين، كلا، كلتا، كل، جميع، أجمع - مع ضمير عائد)، ويتبع المؤكد في الإعراب."],"examples":["حضر المديرُ نفسُه: توكيد معنوي مرفوع","حضر المديرُ بنفسِه: باء زائدة وشبه الجملة في محل رفع توكيد","افعل افعل: توكيد لفظي للفعل","حضر الطلابُ كلهم أجمعون: أجمع توكيد ثانٍ مرفوع بالواو","رأيتُ الأميرَ عينَه: توكيد معنوي منصوب","كلا سوف تعلمون ثم كلا سوف تعلمون: توكيد لفظي قرآني"],"questions":[{"question":"أعرب «أجمعونَ» في «حضر الطلابُ كلُّهم أجمعونَ»:","options":["توكيد معنوي ثانٍ مرفوع وعلامة رفعه الواو","نعت مرفوع","حال منصوب","بدل"],"answer":0,"explanation":"أجمعون توكيد معنوي ثانٍ لكلهم مرفوع بالواو (جمع مذكر سالم)؛ ويجوز الجمع بين ألفاظ التوكيد المعنوي."},{"question":"هل يقع التوكيد اللفظي في الأفعال؟","options":["نعم: افعل افعل، جاء جاء السيل","لا؛ أسماء فقط","نعم لكن منصوبًا","لا يقع أبدًا"],"answer":0,"explanation":"التوكيد اللفظي يقع في الأسماء والأفعال جميعًا؛ أما المعنوي فأسماء فقط (سيأتي في الملحوظة)."},{"question":"ما فائدة التوكيد؟","options":["تقوية الكلام وإزالة الشك من ذهن السامع","زخرفة الكلام فقط","إطالة الجملة","العطف"],"answer":0,"explanation":"التوكيد يدفع توهم السامع: جاء زيد نفسه = لا رسوله؛ رأيت الأمير عينه = شخصه لا صورته."},{"question":"أي جملة فيها توكيد لفظي؟","options":["سلمتُ على الأميرِ الأميرِ","سلمتُ على الأميرِ نفسِه","سلمتُ على الأميرِ كلِّه","سلمتُ على الأميرِ وأخيه"],"answer":0,"explanation":"الأمير الثانية تكرار للفظ الأول = توكيد لفظي مجرور بالكسرة؛ نفسه وكله توكيد معنوي، وأخيه معطوف."},{"question":"أعرب «عينَه» في «رأيتُ الأميرَ عينَه»:","options":["توكيد معنوي منصوب بالفتحة","مفعول به ثانٍ","حال","تمييز"],"answer":0,"explanation":"عين توكيد معنوي يتبع المؤكد (الأمير) في النصب: منصوب بالفتحة، والهاء مضاف إليه يعود على الأمير."}]}]},{"id":"wahi-sharh-041","title":"البدل وأنواعه الأربعة","section":"شرح الكتاب: باب البدل","order":41,"segments":[{"body":["الباب الرابع والأخير من التوابع: «البدل». تعريفه في الكتاب: «الاسم المقصود بالحكم. وضابطه: صحة حذف المبدل منه». أي البدل هو الاسم الذي يقصد بالحكم حقيقة، ولو حذفتَ الأول بقي المعنى مستقيمًا.","أمثلة الضابط: «أكلتُ التفاحةَ نصفَها»: فالمقصود بالأكل النصف لا التفاحة كلها؛ فالنصف بدل. و«أعجبني الخطيبُ فصاحتُه»: المقصود بالإعجاب الفصاحة؛ فتكون بدلًا.","أنواع البدل أربعة: الأول: «بدل الكل من الكل»: الثاني عين الأول ونفسه. نحو: «جاء أخي وائلٌ»: بدل كل من (أخي) مرفوع وعلامة رفعه الضمة - وائل هو أخي عينه. «ورضي الله عن الصديقِ أبي بكرٍ»: بدل كل من (الصديق) مجرور وعلامة جره الياء.","الثاني: «بدل البعض من الكل»: الثاني بعض الأول وجزء منه. نحو: «أعجبني وائلٌ وجهُه»: بدل بعض من (وائل) مرفوع بالضمة - الوجه جزء من وائل. «ونظفتُ المسجدَ فناءَه»: بدل بعض من (المسجد) منصوب بالفتحة - الفناء جزء من المسجد.","الثالث: «بدل الاشتمال»: الثاني داخل في الأول بعلاقة غير الجزئية (صفة أو ملابسة). نحو: «أعجبني وائلٌ خلُقُه»: بدل اشتمال من (وائل) مرفوع بالضمة - الخلق ليس جزءًا ماديًّا لكنه من أوصافه. «وأكرمتُ المرأةَ حجابَها»: بدل اشتمال من (المرأة) منصوب بالفتحة.","الرابع: «بدل الغلط»: يذكر المتكلم كلمة ثم يصححها أو يتراجع: نحو: «قرأتُ القلمَ الكتابَ»: بدل غلط من (القلم) منصوب بالفتحة - قال القلم بالخطأ ثم صحح بالكتاب. «وأفضلُ الصحابةِ عمرُ أبو بكرٍ»: بدل غلط من (عمر) مرفوع بالواو - غلط ثم استدرك.","البدل كله تابع: يعرب إعراب المبدل منه رفعًا ونصبًا وجرًّا، كما رأيت في الأمثلة."],"examples":["جاء أخي وائلٌ: بدل كل من كل مرفوع","رضي الله عن الصديقِ أبي بكر: بدل كل مجرور بالياء","أعجبني وائلٌ وجهُه: بدل بعض من كل مرفوع","نظفتُ المسجدَ فناءَه: بدل بعض منصوب","أكرمتُ المرأةَ حجابَها: بدل اشتمال منصوب","قرأتُ القلمَ الكتابَ: بدل غلط منصوب"],"questions":[{"question":"ما تعريف البدل وضابطه؟","options":["الاسم المقصود بالحكم، وضابطه صحة حذف المبدل منه","الاسم المكرر لفظًا","الاسم بعد واو","الاسم المجرور"],"answer":0,"explanation":"البدل اسم يقصد بالحكم حقيقة: أكلت التفاحة نصفها - المقصود النصف؛ وضابطه أن يصح حذف الأول."},{"question":"ما أنواع البدل الأربعة؟","options":["بدل كل من كل، بدل بعض من كل، بدل اشتمال، بدل غلط","لفظي ومعنوي","مفرد وجمع","نكرة ومعرفة"],"answer":0,"explanation":"أربعة: بدل الكل من الكل (جاء أخي وائل)، بدل البعض من الكل (أعجبني وائل وجهه)، بدل الاشتمال (خلقه)، بدل الغلط (قرأت القلم الكتاب)."},{"question":"أعرب «وائلٌ» في «جاء أخي وائلٌ»:","options":["بدل كل من كل مرفوع وعلامة رفعه الضمة","نعت","عطف","توكيد"],"answer":0,"explanation":"وائل عين أخي نفسه؛ فهو بدل كل من كل يتبع المبدل منه في الرفع: مرفوع بالضمة."},{"question":"ما الفرق بين بدل البعض وبدل الاشتمال؟","options":["البعض جزء مادي من الكل، والاشتمال علاقة غير جزئية كالصفة","لا فرق","البعض للأفعال","الاشتمال للجمع"],"answer":0,"explanation":"بدل البعض: جزء حقيقي (وجهه، فناؤه)؛ بدل الاشتمال: داخل بالملابسة أو الوصف (خلقه، حجابها)."},{"question":"ما بدل الغلط؟","options":["كلمة يصحح بها المتكلم ما سبقها","التوكيد اللفظي","العطف بأو","الاستثناء"],"answer":0,"explanation":"بدل الغلط: قال القلم ثم صحح الكتاب: قرأت القلمَ الكتابَ - الكتاب بدل غلط منصوب تابع."}]},{"body":["تدريب التمييز بين الأنواع: «سافر صديقي أحمدُ»: أحمد عين صديقي = بدل كل من كل. «قرأتُ الكتابَ نصفَه»: النصف جزء = بدل بعض. «أعجبني البيتُ موقعُه»: الموقع ملابس لا جزء مادي... بل قد يعد جزءًا؛ الأوضح: «أعجبني الرجلُ خلقُه» = اشتمال. «زرتُ خالي عمي»: غلط وتصحيح.","علامة بدل الاشتمال والبعض: الضمير العائد على المبدل منه: «وجهُه» الهاء تعود على وائل؛ «خلقُه» كذلك. لا بد في بدل البعض والاشتمال من ضمير يربط البدل بالمبدل منه؛ أما بدل الكل فلا يحتاجه لأنه عينه.","البدل والنعت: «جاء أخي الكريمُ»: الكريم نعت (وصف)؛ «جاء أخي وائل»: وائل بدل (عين). النعت صفة والبدل عين أو جزء أو ملابس.","البدل والتوكيد المعنوي: «جاء أخي نفسُه»: نفس توكيد (لتأكيد الذات)؛ «جاء أخي وائل»: وائل بدل. التوكيد لفظ مخصوص (نفس، عين...) لا يفيد معنى جديدًا.","تدريب إعرابي مركب: «مررتُ بالرجلِ الصالحِ نفسِه أخيكَ»: الصالح نعت مجرور، نفس توكيد معنوي مجرور (وهو مضاف والهاء مضاف إليه)، أخيك بدل كل من كل مجرور بالكسرة (والكاف مضاف إليه). ثلاثة توابع في جملة واحدة!","الخلاصة: البدل رابع التوابع: كل من كل (عينه)، بعض من كل (جزؤه + ضمير)، اشتمال (ملابسه + ضمير)، غلط (تصحيح). وكلها تتبع المبدل منه في الإعراب."],"examples":["سافر صديقي أحمدُ: بدل كل من كل","قرأتُ الكتابَ نصفَه: بدل بعض من كل","أعجبني الرجلُ خلقُه: بدل اشتمال","زرتُ خالي عمي: بدل غلط","جاء أخي الكريمُ: نعت (للمقارنة)","مررتُ بالرجلِ الصالحِ نفسِه أخيكَ: نعت + توكيد + بدل"],"questions":[{"question":"ما علامة بدل البعض والاشتمال؟","options":["ضمير في البدل يعود على المبدل منه","التنوين","حرف الجر","أل"],"answer":0,"explanation":"لا بد في بدل البعض والاشتمال من ضمير عائد: وجهُه، خلقُه، حجابَها؛ أما بدل الكل فعين متبوعه فلا يحتاجه."},{"question":"ما الفرق بين البدل والنعت؟","options":["البدل عين المتبوع أو جزؤه أو ملابسه، والنعت صفة له","لا فرق","النعت منصوب دائمًا","البدل مرفوع دائمًا"],"answer":0,"explanation":"النعت وصف (أخي الكريم)؛ والبدل عين (أخي وائل) أو جزء (وجهه) أو ملابس (خلقه)؛ وكلاهما تابع."},{"question":"أعرب «أخيكَ» في «مررتُ بالرجلِ الصالحِ نفسِه أخيكَ»:","options":["بدل كل من كل مجرور بالكسرة","نعت مجرور","توكيد معنوي","مضاف إليه فقط"],"answer":0,"explanation":"أخيك بدل كل من كل من الرجل يتبعه في الجر: مجرور بالكسرة وهو مضاف، والكاف مضاف إليه."},{"question":"أي جملة فيها بدل اشتمال؟","options":["أكرمتُ المرأةَ حجابَها","جاء أخي وائل","قرأتُ الكتابَ نصفَه","زرتُ خالي عمي"],"answer":0,"explanation":"حجابها ملابس للمرأة لا جزء منها = بدل اشتمال منصوب؛ وائل بدل كل، نصفه بدل بعض، عمي بدل غلط."},{"question":"هل البدل تابع؟","options":["نعم يتبع المبدل منه رفعًا ونصبًا وجرًّا","لا؛ منصوب دائمًا","لا؛ مرفوع دائمًا","حسب نوعه"],"answer":0,"explanation":"البدل من التوابع الأربعة: يعرب إعراب المبدل منه: وائل مرفوع، أبا بكر مجرور بالياء، الكتابَ منصوب."}]}]},{"id":"wahi-sharh-042","title":"ملحوظة: التوابع في الفعل","section":"شرح الكتاب: ملحوظة التوابع في الفعل","order":42,"segments":[{"body":["قاعدة مهمة ختم بها الكتاب باب التوابع: «يقع العطف والتوكيد اللفظي والبدل في الفعل كما تقع في الاسم، أما النعت والتوكيد المعنوي فلا يقعان في الفعل».","لماذا؟ لأن النعت وصف للأسماء، والتوكيد المعنوي ألفاظه (نفس، عين، كل) توكد أعيانًا وذوات لا أحداثًا. أما العطف والتوكيد اللفظي والبدل فيصح فيها الحدث كما يصح الاسم.","أمثلة الكتاب على عطف الأفعال: «لا تُهمِلْ وتقصّرْ في دروسِكَ»: وتقصر: فعل مضارع معطوف على (تهمل)، مجزوم، وعلامة جزمه السكون. لاحظ: العطف على المجزوم يكون مجزومًا - تبعية كاملة.","«لن أُهملَ وأُفيدَ»... الأصل في الكتاب: «تَدْرُسُ... أُعَلِّمَ وأُفيدَ»: فعل مضارع معطوف على (أعلّم)، منصوب، وعلامة نصبه الفتحة (بعد لن). فالمعطوف على المنصوب منصوب.","مثال التوكيد اللفظي في الفعل: «وجاء جاء السيلُ»: جاء الثانية توكيد لفظي لـ(جاء) الأولى، لا محل له من الإعراب (لأن المؤكد فعل ماضٍ مبني).","مثال البدل في الفعل: «ومن يجتهدْ يذاكرْ دروسَه ينجحْ»: يذاكر فعل مضارع وهو بدل بعض من (يجتهد)، مجزوم، وعلامة جزمه السكون. المذاكرة نوع من الاجتهاد فهي بدل بعض من كل.","إذن التوابع في الأفعال تتبعها في الإعراب كما في الأسماء: المنصوب فمنصوب، والمجزوم فمجزوم، والمبني فلا محل له."],"examples":["لا تُهمِلْ وتقصّرْ: فعل معطوف مجزوم","لن أُهملَ وأُفيدَ: فعل معطوف منصوب","جاء جاء السيل: توكيد لفظي للفعل","من يجتهدْ يذاكرْ: بدل بعض في الفعل","ادرسِ النحوَ وحفِّظْه... افعلْ وافعلْ: عطف وتوكيد في الأفعال","النعت لا يقع في الفعل أبدًا"],"questions":[{"question":"أي التوابع يقع في الفعل؟","options":["العطف والتوكيد اللفظي والبدل","الأربعة كلها","النعت فقط","التوكيد المعنوي فقط"],"answer":0,"explanation":"يقع في الفعل: العطف والتوكيد اللفظي والبدل؛ ولا يقع فيه: النعت والتوكيد المعنوي."},{"question":"لماذا لا يقع النعت في الفعل؟","options":["لأن النعت وصف للأعيان والأسماء لا للأحداث","لأن الفعل مبني","لأن الفعل قصير","لأن النعت حرف"],"answer":0,"explanation":"النعت صفة تلازم ذات الموصوف؛ والفعل حدث متجدد لا يوصف بالنعت؛ وكذلك التوكيد المعنوي ألفاظه للذوات."},{"question":"أعرب «وتقصرْ» في «لا تُهمِلْ وتقصّرْ في دروسكَ»:","options":["فعل مضارع معطوف على تهمل مجزوم وعلامة جزمه السكون","فعل مضارع مرفوع","فعل ماضٍ","فعل أمر"],"answer":0,"explanation":"تقصر معطوف على تهمل المجزوم بلا الناهية؛ والتوابع تتبع متبوعها: مجزوم بالسكون."},{"question":"أعرب «جاء» الثانية في «جاء جاء السيل»:","options":["توكيد لفظي لا محل له من الإعراب","فاعل","مبتدأ","نعت"],"answer":0,"explanation":"الثانية تكرار للفعل الماضي = توكيد لفظي؛ والفعل الماضي مبني لا محل له من الإعراب."},{"question":"أعرب «يذاكرْ» في «من يجتهدْ يذاكرْ دروسَه ينجحْ»:","options":["فعل مضارع بدل بعض من يجتهد مجزوم بالسكون","معطوف","توكيد لفظي","جواب الشرط"],"answer":0,"explanation":"يذاكر بدل بعض من كل من يجتهد (المذاكرة جزء الاجتهاد)؛ والأفعال الواقعة جواب شرط مجزومة فيتبعها: مجزوم بالسكون."}]},{"body":["تدريب شامل على تبعية الأفعال: الفعل المعطوف يأخذ حكم ما قبله حرفيًّا: «إن تدرسْ وتجتهدْ تنجحْ»: تجتهد معطوف على تدرس مجزوم بالسكون (جواب الشرط: تنجح مجزوم أيضًا).","«هو يقرأُ ويكتبُ»: ويكتب معطوف على يقرأ مرفوع بالضمة (الفعل المضارع المرفوع). لا ننسى: العطف في المرفوع على المرفوع.","«لم يهملْ ويقصّرْ»: معطوف على المجزوم بلم: مجزوم بالسكون. كل أدوات الجزم والنصب تسري على المعطوف.","التوكيد اللفظي في المضارع: «يكتبُ يكتبُ الولدُ»: الثانية توكيد. وفي الأمر: «اكتبِ اكتبِ الدرسَ». وفي الماضي: «كتب كتب». كله جائز.","البدل في الفعل تدريب: «أُحبُّ القراءةَ أقرأُ فيها» - الأوضح من الكتاب: يجتهد يذاكر: الثاني يبين بعض الأول. البدل في الأفعال يوضح الحدث بحدث أخص منه.","الخلاصة: قاعدة التوابع عامة في الاسم والفعل، لكن: النعت والتوكيد المعنوي خاصان بالأسماء. احفظ: ثلاثة تعم (عطف، توكيد لفظي، بدل)، واثنان يخصان الاسم (نعت، توكيد معنوي)."],"examples":["إن تدرسْ وتجتهدْ تنجحْ: معطوف مجزوم","هو يقرأ ويكتب: معطوف مرفوع","لم يهمل ويقصر: معطوف مجزوم بلم","يكتب يكتب الولد: توكيد لفظي للمضارع","اكتب اكتب الدرس: توكيد لفظي للأمر","يجتهد يذاكر: بدل بعض يخصص الحدث"],"questions":[{"question":"أعرب «ويكتبُ» في «هو يقرأُ ويكتبُ»:","options":["فعل مضارع معطوف على يقرأ مرفوع بالضمة","منصوب بالفتحة","مجزوم بالسكون","مبني"],"answer":0,"explanation":"يكتب معطوف على يقرأ المرفوع؛ والتوابع تتبع متبوعها: مرفوع بالضمة."},{"question":"ماذا يسري من أدوات النصب والجزم على المعطوف من الأفعال؟","options":["يسري عليه حكم الأداة كمتبوعه","لا يسري","يسري على الأول فقط","يسري على الأمر فقط"],"answer":0,"explanation":"العطف تبعية كاملة: لم يهمل ويقصر - لم تجزم الاثنين؛ لن أهمل وأفيد - لن تنصب الاثنين."},{"question":"أي الجمل فيها توكيد لفظي لفعل مضارع؟","options":["يكتب يكتب الولد","يكتب الولد نفسه","يكتب الولد ويقرأ","يكتب الولد الكتاب"],"answer":0,"explanation":"يكتب الثانية تكرار = توكيد لفظي؛ نفسه توكيد معنوي للاسم، ويقرأ عطف، الكتاب مفعول به."},{"question":"ما الاثنان اللذان يختصان بالأسماء؟","options":["النعت والتوكيد المعنوي","العطف والبدل","التوكيد اللفظي والعطف","البدل والعطف"],"answer":0,"explanation":"النعت والتوكيد المعنوي للأسماء فقط؛ والعطف والتوكيد اللفظي والبدل في الاسم والفعل."},{"question":"«من يجتهدْ يذاكرْ» - لماذا يذاكر بدل بعض؟","options":["لأن المذاكرة نوع وجزء من الاجتهاد","لأنه معطوف","لأنه توكيد","لأنه جواب شرط"],"answer":0,"explanation":"المذاكرة بعض الاجتهاد؛ فالثاني بدل بعض من كل من الأول، مجزوم تبعًا له بالسكون."}]}]},{"id":"wahi-sharh-043","title":"خلاصة المرفوعات: المواضع السبعة","section":"شرح الكتاب: خلاصة أحكام الإعراب - المرفوعات","order":43,"segments":[{"body":["وصلنا إلى «الخلاصة» - الدرس الذي يجمع كل ما تعلمناه في أحكام الكلام في ثلاث لوحات: المرفوعات، والمجرورات، والمنصوبات. لو حفظتها امتلكت خريطة الإعراب كاملة.","قال الكتاب: «الاسم يُرفع في سبعة مواضع، وهي: ١- الفاعل. ٢- ونائبه. ٣- والمبتدأ. ٤- وخبره. ٥- واسم كان وأخواتها. ٦- وخبر إن وأخواتها. ٧- والتابع للمرفوع».","لنسترجع كل موضع: الفاعل: من قام بالفعل (كتب زيدٌ). نائب الفاعل: المفعول بعد حذف الفاعل (كُتب الدرسُ). المبتدأ: الاسم العاري من العوامل (العلمُ نافع). الخبر: المخبر به عن المبتدأ (العلم نافعٌ).","اسم كان وأخواتها: المبتدأ بعد دخول الناسخ الناقص (كان العلمُ نافعًا). خبر إن وأخواتها: الخبر بعد دخول إن (إن العلمَ نافعٌ). التابع للمرفوع: النعت والمعطوف والتوكيد والبدل الواقعة على اسم مرفوع (جاء زيدٌ الكريمُ وأخوهُ).","لاحظ الذكاء في الترتيب: المواضع الستة الأولى «متبوعات» أصلية، والسابع «تابع» يتبع أيًّا منها. فكل اسم مرفوع لا بد أن يندرج تحت واحد من السبعة.","تدريب: صنف المرفوعات: «كان المعلمُ مخلصًا وكرّم تلاميذَه»: المعلم: اسم كان مرفوع. «إن المعلمَ مخلصٌ»: مخلص: خبر إن مرفوع. «قُرئ الدرسُ الجديدُ»: الدرس: نائب فاعل مرفوع، الجديد: نعت مرفوع (تابع للمرفوع).","قاعدة عملية: إذا وجدت اسمًا مرفوعًا فاسأل: أسبقه فعل؟ فهو فاعل (أو نائبه إن كان الفعل للمجهول). أهو أول الجملة؟ فمبتدأ. أبعد مبتدأ؟ فخبر. أبعد كان؟ فاسمها. أبعد إن؟ فخبرها. أتابع لواحد منها؟ فتابع."],"examples":["كتب زيدٌ: فاعل","كُتب الدرسُ: نائب فاعل","العلمُ نافعٌ: مبتدأ وخبر","كان العلمُ نافعًا: اسم كان","إن العلمَ نافعٌ: خبر إن","جاء زيدٌ الكريمُ وأخوه: تابعان للمرفوع"],"questions":[{"question":"كم موضعًا يرفع فيه الاسم؟","options":["سبعة مواضع","خمسة","ثلاثة","عشرة"],"answer":0,"explanation":"سبعة: الفاعل، ونائبه، والمبتدأ، وخبره، واسم كان وأخواتها، وخبر إن وأخواتها، والتابع للمرفوع."},{"question":"عدّ المرفوعات السبعة:","options":["الفاعل ونائبه والمبتدأ وخبره واسم كان وخبر إن والتابع للمرفوع","المفاعيل الخمسة والحال والتمييز","المجرور بالحرف والمضاف إليه والنعت","النواسخ الثلاثة والتوابع"],"answer":0,"explanation":"السبعة: فاعل، نائب فاعل، مبتدأ، خبر، اسم كان وأخواتها، خبر إن وأخواتها، والتابع لأي مرفوع."},{"question":"«قُرئ الدرسُ الجديدُ» - صنّف المرفوعين:","options":["الدرس نائب فاعل والجديد تابع للمرفوع","الدرس فاعل والجديد خبر","الدرس مبتدأ والجديد خبر","كلاهما توابع"],"answer":0,"explanation":"الدرس نائب فاعل مرفوع (الفعل مبني للمجهول)، والجديد نعت مرفوع = تابع للمرفوع."},{"question":"ما الذي يجمع المواضع الستة الأولى من المرفوعات؟","options":["أنها متبوعات أصلية والسابع تابع لها","أنها منصوبة","أنها أفعال","أنها نواسخ"],"answer":0,"explanation":"الستة الأولى مواضع أصلية (متبوعات)، والسابع هو التابع الذي يلحق بأي مرفوع منها."},{"question":"«كان المعلمُ مخلصًا» - أين الموضع المرفوع؟","options":["المعلم: اسم كان مرفوع","مخلصًا مرفوع","كان مرفوعة","لا مرفوع"],"answer":0,"explanation":"المعلم اسم كان مرفوع بالضمة؛ ومخلصًا خبر كان منصوب - من المنصوبات لا المرفوعات."}]},{"body":["تدريب شامل على تصنيف المرفوعات في جمل مركبة: «إنَّ الطالبَ المجتهدَ ناجحٌ»: الطالب: اسم إن منصوب (ليس من المرفوعات!)، المجتهد: نعت منصوب (تابع للمنصوب)، ناجح: خبر إن مرفوع. انتبه: اسم إن منصوب وخبرها مرفوع - لا تخلط.","«كان الجوُّ صحوًا والسماءُ صافيةٌ»: الجو: اسم كان مرفوع. السماء: معطوف على الجو = تابع للمرفوع مرفوع. صافية: خبر ثانٍ؟ لا: المعطوف على اسم كان يأخذ حكمه، وصافية خبر له - خبر معطوف منصوب.","«كتب المعلمُ الدرسَ وكُتب التمرينُ»: المعلم: فاعل مرفوع. التمرين: نائب فاعل مرفوع. جملتان تجمعان الموضعين الأولين.","«العلمُ نورٌ والجهلُ ظلامٌ»: العلم مبتدأ، نور خبر، الجهل معطوف (تابع للمرفوع)، ظلام خبر للمعطوف.","«ظننتُ الحقَّ غالبًا»: الحق مفعول أول منصوب - ليس مرفوعًا! ظن وأخواتها تنصب الاثنين، فلا مرفوع فيها إلا فاعلها المستتر أو الظاهر: ظننتُ: التاء فاعل مرفوع... في محل رفع.","الخلاصة: احفظ السبعة كقائمة مراجعة: فاعل، نائب فاعل، مبتدأ، خبر، اسم كان، خبر إن، تابع. وكل اسم مرفوع تراه فهو واحد منها لا ثامن له."],"examples":["إن الطالبَ المجتهدَ ناجحٌ: خبر إن مرفوع","كان الجوُّ صحوًا والسماءُ صافية: معطوف على اسم كان","كتب المعلمُ وكُتب التمرينُ: فاعل ونائب فاعل","العلمُ نورٌ والجهلُ ظلام: معطوف وخبره","ظننتُ الحقَّ غالبًا: التاء فاعل والمنصوبان مفعولان","الطالبُ المجتهدُ ناجحٌ: مبتدأ ونعت وخبر - ثلاثة مرفوعات"],"questions":[{"question":"«إنَّ الطالبَ المجتهدَ ناجحٌ» - ما المرفوع فيها؟","options":["ناجح فقط: خبر إن مرفوع","الطالب","المجتهد","الكل مرفوع"],"answer":0,"explanation":"اسم إن منصوب ونعته منصوب تبعًا؛ والمرفوع الوحيد: ناجح خبر إن مرفوع بالضمة."},{"question":"أعرب «والسماءُ» في «كان الجوُّ صحوًا والسماءُ صافيةٌ»:","options":["معطوف على اسم كان مرفوع (تابع للمرفوع)","مبتدأ","خبر إن","فاعل"],"answer":0,"explanation":"السماء معطوف على الجو (اسم كان المرفوع) فهي تابع للمرفوع مرفوعة بالضمة، وصافية خبرها منصوب."},{"question":"كم مرفوعًا في «الطالبُ المجتهدُ ناجحٌ»؟","options":["ثلاثة: مبتدأ ونعت وخبر","واحد","اثنان","لا مرفوع"],"answer":0,"explanation":"الطالب مبتدأ مرفوع، المجتهد نعت مرفوع (تابع)، ناجح خبر مرفوع: ثلاثة مواضع من السبعة في جملة واحدة."},{"question":"هل «المفعول به الأول» في ظن من المرفوعات؟","options":["لا؛ منصوب","نعم","حسب الجملة","نعم إذا تقدم"],"answer":0,"explanation":"ظن وأخواتها تنصب المبتدأ والخبر مفعولين؛ فالمنصوبان من المنصوبات، والمرفوع فيها فاعلها فقط."},{"question":"ما القائمة الذهبية لمراجعة أي اسم مرفوع؟","options":["فاعل، نائب فاعل، مبتدأ، خبر، اسم كان، خبر إن، تابع","به، فيه، له، معه، مطلق","نعت، عطف، توكيد، بدل","من، إلى، عن، على"],"answer":0,"explanation":"كل اسم مرفوع يندرج تحت واحد من السبعة: فاعل، نائبه، مبتدأ، خبره، اسم كان وأخواتها، خبر إن وأخواتها، تابع للمرفوع."}]}]},{"id":"wahi-sharh-044","title":"خلاصة المجرورات والمنصوبات","section":"شرح الكتاب: خلاصة أحكام الإعراب - المجرورات والمنصوبات","order":44,"segments":[{"body":["اللوحة الثانية: المجرورات. قال الكتاب: «ويُجر في ثلاثة مواضع وهي: ١- الاسم المسبوق بحرف جر. ٢- والاسم إذا كان مضافًا إليه. ٣- والتابع للمجرور».","استرجاع: المجرور بحرف الجر: كتبتُ بالقلمِ. المضاف إليه: قلمُ الأستاذِ. التابع للمجرور: مررتُ بالطالبِ المجتهدِ (نعت)، سلمتُ على زيدٍ وعمروٍ (معطوف)، مررت بالرجلِ نفسِه (توكيد)، مررت بأخيك وائلٍ (بدل).","ثلاثة مواضع فقط للجر - أبسط اللوحات الثلاث: حرف جر قبله، أو مضاف قبله، أو تابع لواحد منهما. كل اسم مجرور تراه فهو واحد من الثلاثة.","اللوحة الثالثة: المنصوبات - وهي الأكثر: ١- المفاعيل الخمسة: به وفيه وله ومعه والمطلق. ٢- وخبر كان وأخواتها. ٣- واسم إن وأخواتها. ٤- والحال. ٥- والتمييز. ٦- والمستثنى في أكثر أحواله. ٧- والمنادى. ٨- والتابع للمنصوب.","استرجاع المنصوبات: به (قرأت الكتابَ)، فيه (صمت يومًا)، له (جاء طلبًا)، معه (سرت والقمرَ)، مطلق (دعوت دعاءً). خبر كان (كان العلم نافعًا). اسم إن (إن العلمَ نافع). الحال (جاء ضاحكًا). التمييز (عشرون رجلًا). المستثنى (جاء القوم إلا زيدًا - في التام المثبت وأحد وجهي المنفي). المنادى (يا غافلًا، والمبني في محل نصب). التابع للمنصوب (رأيت زيدًا الكريمَ).","عدّها: خمسة + سبعة = اثنا عشر موضعًا للنصب (المفاعيل تعد خمسة مواضع). لهذا قيل: النصب أكثر أحوال الاسم تفرعًا.","ملاحظة دقيقة في كلام الكتاب: «المستثنى في أكثر أحواله» - لأن المستثنى ينصب في التام المثبت وأحد وجهي المنفي، لكنه يرفع بدلًا أو بحسب الموقع في أحوال أخر؛ فلم يقل: المستثنى مطلقًا."],"examples":["كتبتُ بالقلمِ: مجرور بحرف الجر","قلمُ الأستاذِ: مضاف إليه","مررتُ بالطالبِ المجتهدِ: تابع للمجرور","قرأتُ الكتابَ + صمتُ يومًا + جاء طلبًا: ثلاثة مفاعيل","كان العلمُ نافعًا + إن العلمَ نافعٌ: خبر كان واسم إن","جاء ضاحكًا + عشرون رجلًا + جاء القوم إلا زيدًا + يا غافلًا: حال وتمييز ومستثنى ومنادى"],"questions":[{"question":"كم موضعًا يجر فيه الاسم؟","options":["ثلاثة: بحرف جر، وبالإضافة، والتابع للمجرور","سبعة","خمسة","اثنا عشر"],"answer":0,"explanation":"ثلاثة فقط: الاسم المسبوق بحرف جر، والمضاف إليه، والتابع للمجرور."},{"question":"عدّ المنصوبات كما في الخلاصة:","options":["المفاعيل الخمسة وخبر كان واسم إن والحال والتمييز والمستثنى في أكثر أحواله والمنادى والتابع للمنصوب","الفاعل والمبتدأ والخبر","المجرور بالحرف والمضاف","النواسخ الثلاثة"],"answer":0,"explanation":"المنصوبات: المفاعيل الخمسة، خبر كان وأخواتها، اسم إن وأخواتها، الحال، التمييز، المستثنى في أكثر أحواله، المنادى، التابع للمنصوب."},{"question":"لماذا قال الكتاب «المستثنى في أكثر أحواله»؟","options":["لأنه ينصب غالبًا لكنه يرفع بدلًا أو بحسب الموقع أحيانًا","لأنه مرفوع دائمًا","لأنه مجرور","عبث بلا معنى"],"answer":0,"explanation":"المستثنى ينصب في التام المثبت وأحد وجهي المنفي، ويرفع في الوجه الآخر وفي الناقص؛ فقيده بأكثر أحواله."},{"question":"أي لوحات الإعراب أكثر مواضع؟","options":["المنصوبات (اثنا عشر موضعًا)","المرفوعات","المجرورات","متساوية"],"answer":0,"explanation":"المنصوبات اثنا عشر موضعًا (المفاعيل الخمسة + سبعة)، والمرفوعات سبعة، والمجرورات ثلاثة."},{"question":"«رأيتُ زيدًا الكريمَ» - ما موضع «الكريمَ»؟","options":["تابع للمنصوب (نعت منصوب)","تابع للمرفوع","حال","تمييز"],"answer":0,"explanation":"الكريم نعت لزيد المنصوب = تابع للمنصوب منصوب بالفتحة؛ التابع يتبع متبوعه أيًّا كان إعرابه."}]},{"body":["الآن نجمع اللوحات الثلاث في تدريب عملي كبير. خذ الجملة وصنف كل اسم: «إنَّ المؤمنينَ صادقونَ وينصرونَ إخوانَهم في الشدةِ إخلاصًا للهِ».","المؤمنين: اسم إن منصوب (منصوبات). صادقون: خبر إن مرفوع (مرفوعات - خبر إن). ينصرون: الواو فاعل مرفوع (مرفوعات - فاعل... في محل رفع). إخوانهم: مفعول به منصوب (منصوبات - به).","في الشدة: الشدة مجرور بحرف الجر (مجرورات). إخلاصًا: مفعول له منصوب (منصوبات - له). لله: الله مجرور بحرف الجر (مجرورات) وهو مضاف إليه أيضًا لإخلاص - اسم واحد قد يجمع سببين للجر!","قاعدة مهمة: الاسم الواحد قد يجتمع فيه سببان من أسباب الإعراب: «لله» مجرور بحرف الجر ومضاف إليه معًا - إعرابه واحد لكن سياقه يحمل الوصفين.","تدريب آخر: «يا طالبَ العلمِ اجتهدْ وذاكرْ دروسَك ليلًا ناشئًا»: طالب: منادى منصوب مضاف. العلم: مضاف إليه مجرور. وذاكر: معطوف مجزوم. دروسك: مفعول به منصوب. ليلًا: ظرف زمان (فيه) منصوب. ناشئًا: حال منصوب.","الخلاصة الكبرى: الاسم في العربية له ثلاث حالات: رفع (سبعة مواضع)، ونصب (اثنا عشر)، وجر (ثلاثة). احفظ اللوحات الثلاث ورددها حتى تصير غريزة؛ فهي مفتاح إعراب أي جملة تقرؤها في القرآن والحديث والأدب."],"examples":["إنَّ المؤمنينَ صادقون: اسم إن منصوب وخبرها مرفوع","وينصرونَ إخوانَهم: فاعل ومفعول به","في الشدةِ: مجرور بحرف الجر","إخلاصًا لله: مفعول له + مجرور يجمع سببين","يا طالبَ العلمِ: منادى منصوب ومضاف إليه","ليلًا ناشئًا: ظرف وحال - منصوبان"],"questions":[{"question":"أعرب «صادقونَ» في «إنَّ المؤمنينَ صادقونَ»:","options":["خبر إن مرفوع بالواو","اسم إن منصوب","مفعول به","حال"],"answer":0,"explanation":"صادقون خبر إن مرفوع وعلامة رفعه الواو (جمع مذكر سالم) - من مواضع المرفوعات السبعة."},{"question":"هل يجتمع في الاسم الواحد سببان للجر؟","options":["نعم: للهِ مجرور بالحرف ومضاف إليه معًا","لا أبدًا","نعم للرفع فقط","نعم للنصب فقط"],"answer":0,"explanation":"نعم: «إخلاصًا لله» - لفظ الجلالة مجرور باللام ومضاف إليه لإخلاص معًا؛ الإعراب واحد والأسباب اثنان."},{"question":"أعرب «ناشئًا» في «يا طالبَ العلمِ اجتهدْ وذاكرْ دروسَك ليلًا ناشئًا»:","options":["حال منصوب بالفتحة","مفعول به","ظرف","تمييز"],"answer":0,"explanation":"ناشئًا وصف نكرة يبين هيئة المخاطب وقت المذاكرة: حال منصوب بالفتحة - من المنصوبات."},{"question":"ما اللوحات الثلاث للإعراب؟","options":["مرفوعات سبعة، منصوبات اثنا عشر، مجرورات ثلاثة","مرفوعات ثلاثة ومنصوبات سبعة","كلها سبعة","أربع لوحات"],"answer":0,"explanation":"الرفع: سبعة مواضع؛ النصب: اثنا عشر؛ الجر: ثلاثة؛ مجموعها اثنان وعشرون موضعًا تغطي كل إعراب الاسم."},{"question":"أعرب «دروسَك» في التدريب السابق:","options":["مفعول به منصوب بالفتحة","مفعول فيه","مفعول له","حال"],"answer":0,"explanation":"دروس مفعول به منصوب بالفتحة (وقعت عليه المذاكرة) والكاف مضاف إليه؛ من مواضع النصب: به."}]}]},{"id":"wahi-sharh-045","title":"تطبيقات إعرابية شاملة على أحكام الكلام","section":"شرح الكتاب: مراجعة الجزء الثاني","order":45,"segments":[{"body":["درس مراجعة وتطبيق: نأخذ جملًا متنوعة ونعربها إعرابًا كاملًا بما تعلمناه في الجزء الثاني كله: الجملتان، النواسخ، المفاعيل، المنصوبات، المجرورات، التوابع.","التطبيق الأول: «كان المسلمونَ الأوائلُ يضحّونَ بأموالِهم طلبًا لمرضاةِ اللهِ»: كان: فعل ماضٍ ناسخ مبني على الفتح. المسلمون: اسم كان مرفوع بالواو. الأوائل: نعت مرفوع (تابع). يضحون: جملة فعلية في محل نصب خبر كان (الواو فاعل). بأموالهم: مجرور بحرف الجر. طلبًا: مفعول له منصوب. لمرضاة: مجرور باللام. الله: مضاف إليه مجرور.","التطبيق الثاني: «إنَّ الذي يقرأُ القرآنَ غافلًا كمن لم يقرأْ»: إن: حرف توكيد. الذي: اسم موصول مبني في محل نصب اسم إن. يقرأ: جملة صلة. القرآن: مفعول به. غافلًا: حال منصوب. كمن: الكاف حرف جر ومن مجرور - شبه الجملة في محل رفع خبر إن.","التطبيق الثالث: «سافر التجارُ والعلماءُ طلبًا للرزقِ والعلمِ إلا القاعدينَ»: التجار: فاعل مرفوع بالضمة (جمع تكسير). العلماء: معطوف مرفوع (تابع). طلبًا: مفعول له. للرزق: مجرور باللام وهو مضاف إليه. والعلم: معطوف مجرور (تابع للمجرور). إلا: أداة استثناء. القاعدين: مستثنى منصوب بالياء (تام مثبت - وجوب النصب).","التطبيق الرابع: «يا أبا الحسنِ أكرمْ ضيفَك إجلالًا وتوقيرًا»: أبا: منادى منصوب بالألف (الأسماء الخمسة) وهو مضاف. الحسن: مضاف إليه مجرور. أكرم: فعل أمر والفاعل مستتر أنت. ضيفك: مفعول به. إجلالًا: مفعول له. وتوقيرًا: معطوف منصوب (تابع للمنصوب).","كيف تتدرّب وحدك؟ خذ آية قصيرة أو حديثًا، وطبق اللوحات الثلاث: ابدأ بالفعل: ماذا يرفع؟ فاعله. ماذا ينصب؟ مفعولاته. ثم الجملة الاسمية: مبتدأ وخبر ونواسخهما. ثم التوابع: تابع لأي متبوع؟","هذه المراجعة تختم دروس «أحكام الكلام» الأولى؛ والدروس القادمة تتعمق في أبواب فتحية أخرى من الكتاب: تفاصيل أحكام المبتدأ والخبر والمفاعيل وأخوات كان وإعراب الفعل المضارع، بإذن الله."],"examples":["كان المسلمون الأوائل يضحون: اسم كان ونعت وخبر جملة","إن الذي يقرأ القرآن غافلًا: اسم موصول اسم إن + حال","سافر التجار والعلماء طلبًا: فاعل ومعطوف ومفعول له","إلا القاعدين: مستثنى تام مثبت منصوب وجوبًا","يا أبا الحسن: منادى من الأسماء الخمسة منصوب بالألف","إجلالًا وتوقيرًا: مفعول له ومعطوف منصوب"],"questions":[{"question":"أعرب «الأوائلُ» في «كان المسلمونَ الأوائلُ يضحون»:","options":["نعت مرفوع (تابع للمرفوع)","خبر كان منصوب","مبتدأ","حال"],"answer":0,"explanation":"الأوائل نعت للمسلمين (اسم كان المرفوع) فهو تابع للمرفوع مرفوع بالضمة؛ وخبر كان الجملة الفعلية بعده."},{"question":"أعرب «غافلًا» في «إنَّ الذي يقرأ القرآن غافلًا»:","options":["حال منصوب بالفتحة","نعت منصوب","مفعول به","خبر إن"],"answer":0,"explanation":"غافلًا وصف نكرة يبين هيئة القارئ وقت القراءة: حال منصوب بالفتحة، صاحبها الموصول."},{"question":"أعرب «القاعدينَ» في «سافر التجارُ إلا القاعدينَ»:","options":["مستثنى منصوب بالياء وجوبًا (تام مثبت)","بدل مرفوع","معطوف","فاعل"],"answer":0,"explanation":"الاستثناء تام (التجار مستثنى منه) مثبت (لا نفي) فيجب النصب: القاعدين مستثنى منصوب بالياء."},{"question":"أعرب «أبا» في «يا أبا الحسنِ»:","options":["منادى منصوب بالألف لأنه من الأسماء الخمسة وهو مضاف","منادى مبني على الضم","مبتدأ","فاعل"],"answer":0,"explanation":"أبو من الأسماء الخمسة ينصب بالألف؛ وكونه مضافًا جعل المنادى معربًا منصوبًا: أبا منادى منصوب بالألف وهو مضاف."},{"question":"ما خطوات إعراب أي جملة جديدة؟","options":["ابدأ بالفعل وأركانه، ثم الجملة الاسمية ونواسخها، ثم التوابع بلوحات الإعراب الثلاث","ابدأ بآخر الجملة","ابدأ بالتوابع","ابدأ بالحروف"],"answer":0,"explanation":"خطة الإعراب: الفعل فما يرفعه وما ينصبه، ثم المبتدأ والخبر والنواسخ، ثم التوابع؛ واللوحات الثلاث (7 مرفوعات، 12 منصوبات، 3 مجرورات) قائمة المراجعة."}]},{"body":["تطبيق خامس متقدم: «وما زال العلمُ يرفعُ أهلَه درجاتٍ حتى يبلغوا أعاليَ الأمورِ»: ما: نافية. زال: فعل ماضٍ ناسخ. العلم: اسم زال مرفوع. يرفع: جملة فعلية في محل نصب خبر زال. أهل: مفعول به. درجات: مفعول به ثانٍ منصوب بالكسرة (جمع مؤنث) أو حال... الأرجح: مفعول ثانٍ. حتى: حرف غاية وجر أو عطف. يبلغوا: مضارع منصوب بأن مضمرة بعد حتى. أعالي: مفعول به مضاف. الأمور: مضاف إليه.","تطبيق سادس: «ليتَ الشبابَ يعودُ يومًا فأخبرَه بما فعلَ المشيبُ»: ليت: حرف تمنٍّ مبني. الشباب: اسم ليت منصوب. يعود: جملة فعلية في محل رفع خبر ليت. يومًا: ظرف زمان (مفعول فيه) منصوب. فأخبره: الفاء عاطفة وأخبر معطوف مرفوع والهاء مفعول به. بما: الباء جارة وما مجرورة. فعل: فعل ماضٍ. المشيب: فاعل مرفوع.","تطبيق سابع: «ظنَّ الجاهلُ الجهلَ نورًا والعلمَ ظلامًا»: ظن: فعل ماضٍ. الجاهل: فاعل. الجهل: مفعول أول منصوب. نورًا: مفعول ثانٍ منصوب. والعلم: معطوف على الجهل منصوب (تابع للمنصوب). ظلامًا: معطوف على نورًا منصوب.","تطبيق ثامن: «لا بأسَ عليكَ إن اجتهدتَ ولا غنى لمن كسلَ»: لا بأس: لا النافية للجنس وبأس اسمها منصوب بلا تنوين. عليك: شبه جملة خبرها في محل رفع. إن: شرطية. اجتهدت: فعل وفاعل. ولا غنى: لا الثانية نافية للجنس أيضًا (لم تتصل... تكررت فقيل: بطل عملها - والأرجح هنا أنها في جملة مستقلة فتعمل). لمن: شبه جملة خبرها.","بهذه التطبيقات الثمانية ترى أن الإعراب ليس حفظًا جافًّا بل خريطة تسير عليها عينك في كل نص. كلما أعربت أكثر رسخت القواعد.","الخلاصة النهائية: تعلمنا في هذا الجزء: الجملة الاسمية والفعلية، النواسخ الثلاثة ولا النافية للجنس، المفاعيل الخمسة، الحال والتمييز والمستثنى والمنادى، المجرورات بنوعيها، التوابع الأربعة، ولوحات الإعراب الثلاث. والقادم: تعمق أكثر في هذه الأبواب وأبواب إعراب الفعل المضارع، فواصل المسير!"],"examples":["وما زال العلمُ يرفع أهله درجات: اسم زال وخبرها ومفعولان","ليت الشبابَ يعود يومًا: اسم ليت وخبرها وظرف","ظن الجاهلُ الجهلَ نورًا: مفعولان لظن","والعلمَ ظلامًا: معطوفان منصوبان","لا بأسَ عليك: لا نافية للجنس واسمها منصوب بلا تنوين","فأخبره بما فعل المشيب: معطوف وفاعل مرفوع"],"questions":[{"question":"أعرب «العلمُ» في «وما زال العلمُ يرفع أهلَه»:","options":["اسم زال مرفوع بالضمة","فاعل يرفع","مبتدأ","خبر زال"],"answer":0,"explanation":"العلم اسم زال مرفوع بالضمة؛ والجملة الفعلية «يرفع أهله» في محل نصب خبرها."},{"question":"أعرب «يومًا» في «ليت الشباب يعود يومًا»:","options":["مفعول فيه (ظرف زمان) منصوب بالفتحة","مفعول به","حال","تمييز"],"answer":0,"explanation":"يومًا ظرف زمان منصوب بالفتحة يبين زمن العود: متى يعود؟ يومًا - من مواضع النصب: فيه."},{"question":"أعرب «نورًا» في «ظنَّ الجاهلُ الجهلَ نورًا»:","options":["مفعول به ثانٍ منصوب بالفتحة","خبر كان","حال","تمييز"],"answer":0,"explanation":"ظن وأخواتها تنصب مفعولين أصلهما المبتدأ والخبر: الجهل مفعول أول، نورًا مفعول ثانٍ."},{"question":"أعرب «بأسَ» في «لا بأسَ عليكَ»:","options":["اسم لا النافية للجنس منصوب بالفتحة بلا تنوين","مبتدأ مرفوع","خبر مرفوع","مفعول به"],"answer":0,"explanation":"بأس اسم لا النافية للجنس منصوب بالفتحة ولا يُنوَّن؛ وعليك شبه الجملة خبرها في محل رفع."},{"question":"ماذا تعلمنا في الجزء الثاني كله؟","options":["الجملتان والنواسخ والمفاعيل والمنصوبات والمجرورات والتوابع ولوحات الإعراب","أحكام الكلمة فقط","المبني والمعرب فقط","الحروف فقط"],"answer":0,"explanation":"الجزء الثاني (أحكام الكلام): الجملتان وأركانهما، النواسخ الثلاثة ولا، المفاعيل الخمسة، الحال والتمييز والمستثنى والمنادى، المجرورات، التوابع الأربعة، ولوحات الإعراب الثلاث."}]}]},{"id":"wahi-sharh-046","title":"إعراب الفعل المضارع: النصب ونواصبه","section":"شرح الكتاب: القسم الرابع: إعراب الفعل المضارع - باب نصب الفعل المضارع","order":46,"segments":[{"body":["ختمنا أحكام الكلام بـ«القسم الرابع: إعراب الفعل المضارع». تعلمنا سابقًا أن المضارع معرب (يتغير آخره)، والآن نعرف أحواله الثلاث: «يُنصب إذا سبق بناصب، ويُجزم إذا سبق بجازم، ويُرفع إذا لم يسبق بناصب ولا جازم».","فلا بد من معرفة نواصبه وجوازمه. باب النصب: «يُنصب المضارع بعد عشرة أحرف»:","١- «أنْ»: نحو: يجب أن تجتهدَ، أحب أن تسافروا. ٢- «ولن»: نحو: لن أُهملَ، لن تسافروا. ٣- «وكي»: نحو: جئتُ كي أتعلمَ، سافروا كي تستفيدوا. ٤- «وإذن» وهي حرف جواب: نحو: إذن تنجحُ... إذن تنجحَ (لمن قال: سأجتهد).","٥- «ولام التعليل»: نحو: جئتُ لأتعلمَ، سافروا لتستفيدوا. ٦- «ولام الجحود»: وهي لام تقع بعد «ما كان» و«لم يكن»، نحو: ما كان قيسٌ ليسافرَ، لم يكن قيس ليسافرَ.","٧- «وحتى»: نحو: جئتُ حتى أستفيدَ، وسأنتظرك حتى تغيبَ الشمسُ. ٨- «والواو التي بمعنى (إلى أن) أو بمعنى (إلا أن)»: نحو: سأجتهدُ أو أنجحَ (أي: إلى أن أنجح)، وسأفصلك من العمل أو تعتذرَ (أي: إلا أن تعتذر).","٩- «وفاء السببية»: إذا وقعت بعد نفي أو طلب، نحو: اجتهدْ فتنجحَ. ١٠- «وواو المعية»: إذا وقعت بعد نفي أو طلب، نحو: اجتهدْ وتنجحَ.","إعراب المضارع المنصوب: «فعل مضارع منصوب وعلامة نصبه الفتحة». والمثال الجامع في الكتاب: «يجب أن تُعيدَ وأن تُصلِّيَ كي تنجوَ إذن تنجحَ» - جمع أربعة نواصب في جملة واحدة."],"examples":["يجب أن تجتهد: أن ناصبة","لن أهمل: لن ناصبة","جئت كي أتعلم: كي ناصبة","إذن تنجح (لمن قال سأجتهد): إذن ناصبة","جئت لأتعلم: لام التعليل ناصبة","اجتهد فتنجح: فاء السببية بعد طلب"],"questions":[{"question":"متى يُنصب الفعل المضارع؟","options":["إذا سبق بناصب","إذا سبق بجازم","إذا لم يسبقه شيء","دائمًا"],"answer":0,"explanation":"المضارع ينصب إذا سبق بناصب، ويجزم إذا سبق بجازم، ويرفع إذا لم يسبق بناصب ولا جازم."},{"question":"كم عدد نواصب المضارع؟","options":["عشرة أحرف","خمسة","أربعة","ثلاثة"],"answer":0,"explanation":"عشرة: أن، لن، كي، إذن، لام التعليل، لام الجحود، حتى، الواو بمعنى إلى أن/إلا أن، فاء السببية، واو المعية."},{"question":"ما لام الجحود؟","options":["لام تقع بعد ما كان ولم يكن تنصب المضارع","لام التعليل","لام الأمر","لام الابتداء"],"answer":0,"explanation":"لام الجحود تقع بعد «ما كان» و«لم يكن»: ما كان قيس ليسافرَ - تنصب المضارع وتجحد وقوعه."},{"question":"متى تنصب فاء السببية وواو المعية المضارع؟","options":["إذا وقعتا بعد نفي أو طلب","في كل موضع","بعد النفي فقط","بعد الطلب فقط"],"answer":0,"explanation":"فاء السببية وواو المعية تنصبان المضارع بشرط أن تقعا بعد نفي أو طلب (أمر أو نهي أو دعاء): اجتهد فتنجح."},{"question":"أعرب «تستفيدوا» في «سافروا كي تستفيدوا»:","options":["فعل مضارع منصوب وعلامة نصبه الفتحة","فعل مضارع مرفوع","فعل مضارع مجزوم","فعل أمر"],"answer":0,"explanation":"كي من نواصب المضارع: تستفيدوا فعل مضارع منصوب بالفتحة (والواو فاعل)."}]},{"body":["تدريب على التمييز بين النواصب: أن: للمصدر المؤول (يجب أن تجتهد = يجب اجتهادُك). لن: للنفي المؤبد (لن أهمل = لا أهمل أبدًا). كي ولام التعليل: للتعليل (كي أتعلم = لأتعلم = من أجل التعلم).","إذن: حرف جواب وجزاء، تجيب به من وعد أو طلب: قال: سأجتهد. قلت: إذن تنجحَ. حتى: للغاية: سأنتظرك حتى تغيب الشمس = إلى غاية غيابها.","الواو بمعنى (إلى أن): سأجتهد أو أنجح = سأجتهد إلى أن أنجح - تعطي معنى الاستمرار حتى الغاية. وبمعنى (إلا أن): سأفصلك أو تعتذر = إلا أن تعتذر.","النفي والطلب قبل فاء السببية: النفي: «لا تهملْ فتندمَ». الطلب بأنواعه: أمر: «ادرسْ تفُزْ». نهي: «لا تكسلْ تنجحْ». دعاء: «اللهم وفقني فأشكرَ». استفهام: «أتدرس فتفهمَ؟». عرض وتمنٍّ... كلها طلب.","ملاحظة إعرابية: أن وكي ولن وإذن وحتى كلها أحرف مبنية لا محل لها من الإعراب، توصف: حرف نصب. وأن المصدرية تؤول مع ما بعدها بمصدر في محل رفع أو نصب: يجب أن تجتهد = يجب الاجتهاد (فاعل).","الخلاصة: عشرة أحرف تنصب المضارع: أن ولن وكي وإذن ولام التعليل ولام الجحود وحتى والواو الغائية وفاء السببية وواو المعية بعد نفي أو طلب. وعلامة النصب الفتحة (أو حذف النون في الأفعال الخمسة)."],"examples":["لا تهمل فتندم: فاء السببية بعد نهي","سأجتهد أو أنجح: الواو بمعنى إلى أن","سأفصلك أو تعتذر: الواو بمعنى إلا أن","سأنتظرك حتى تغيب الشمس: حتى الغائية","ما كان قيس ليسافر: لام الجحود","يجب أن تجتهد: أن المصدرية"],"questions":[{"question":"ما معنى «لن»؟","options":["نفي مؤبد مع نصب المضارع","تعليل","جواب","غاية"],"answer":0,"explanation":"لن حرف نفي يفيد التأبيد وينصب المضارع: لن أهمل = لا أهمل أبدًا."},{"question":"ما معنى «كي» و«لام التعليل»؟","options":["التعليل: من أجل","النفي","الغاية الزمنية","الجواب"],"answer":0,"explanation":"كي ولام التعليل للتعليل: جئت كي أتعلم = جئت لأتعلم = من أجل التعلم؛ وتنصبان المضارع."},{"question":"أي الأنواع يعد من الطلب الذي تنصب بعده فاء السببية؟","options":["الأمر والنهي والدعاء والاستفهام","الخبر فقط","النفي فقط","لا شيء"],"answer":0,"explanation":"الطلب أنواع: أمر (ادرس تفز)، نهي (لا تكسل تنجح)، دعاء، استفهام، تمنٍّ، عرض؛ وبعدها وبعد النفي تنصب فاء السببية."},{"question":"ما إعراب «كي»؟","options":["حرف نصب مبني لا محل له من الإعراب","فعل","اسم","حرف جر"],"answer":0,"explanation":"كي حرف نصب مبني لا محل له من الإعراب؛ وكذلك كل نواصب المضارع أحرف مبنية."},{"question":"في «يجب أن تجتهد» ما محل «أن تجتهد»؟","options":["المصدر المؤول في محل رفع فاعل","مفعول به","حال","خبر"],"answer":0,"explanation":"أن المصدرية والمضارع بعدها يؤولان بمصدر: يجب أن تجتهد = يجب الاجتهاد - في محل رفع فاعل يجب."}]}]},{"id":"wahi-sharh-047","title":"جزم الفعل المضارع: الجوازم الأربعة","section":"شرح الكتاب: باب جزم الفعل المضارع","order":47,"segments":[{"body":["باب الجزم: «يُجزم المضارع بعد خمسة أشياء صارت نوعين». النوع الأول: «ما يجزم فعلًا واحدًا، وهي أربعة أحرف: لم، ولما، ولا الناهية، ولام الأمر».","«لم»: حرف نفي يجزم المضارع ويقلب زمنه إلى الماضي: «لم يذهبْ» = لم يحدث الذهاب في الماضي. إعراب المضارع بعدها: «فعل مضارع مجزوم وعلامة جزمه السكون».","مع الأفعال الخمسة: «لم يذهبوا»: فعل مضارع مجزوم وعلامة جزمه حذف النون. الأفعال الخمسة (كل مضارع اتصلت به واو جماعة أو ألف اثنين أو ياء مخاطبة) تحذف نونها عند الجزم.","«لما»: حرف نفي يجزم أيضًا، بمعنى التوقع: «لما يذهبْ» = لم يذهب بعدُ ويُتوقع ذهابه. الفرق بين لم ولما: لم للنفي المطلق، ولما لنفي ما يُتوقع وقوعه.","«لا الناهية»: حرف نهي يجزم: «لا تذهبْ» = أطلب منك الكف عن الذهاب. وتسمى «لا الناهية» تمييزًا لها من لا النافية التي لا تجزم: «لا يذهبُ» مرفوع.","«لام الأمر»: لام تدخل على المضارع فتفيد الأمر أو الدعاء وتجزم: «ولتذهبْ» = اذهب. وتسبقها الفاء أو الواو غالبًا: «فلتكتبْ»، «وليقمْ». أمثلة الكتاب: لم يذهبْ (سكون)، لم يذهبوا (حذف النون)، لما يصلوا، لا تذهبْ، لا تدعوا، ولتذهبْ، وليقُمْ... (وليلقَ - حذف النون مع الواو).","إعراب هذه الأحرف الأربعة: حروف جزم مبنية لا محل لها من الإعراب: لم مبنية على السكون، ولا مبنية على السكون، واللام مبنية على الكسر... والمبني لا إعراب له."],"examples":["لم يذهبْ: مجزوم بالسكون بلم","لم يذهبوا: مجزوم بحذف النون","لما يصلوا: لما الجازمة","لا تذهبْ: لا الناهية تجزم","ولتذهبْ: لام الأمر تجزم","لا يذهبُ (نافية): مرفوع - للمقارنة"],"questions":[{"question":"ما الجوازم التي تجزم فعلًا واحدًا؟","options":["أربعة: لم ولما ولا الناهية ولام الأمر","خمسة","عشرة","ثلاثة"],"answer":0,"explanation":"أربعة أحرف تجزم فعلًا واحدًا: لم، ولما، ولا الناهية، ولام الأمر."},{"question":"ما معنى «لم» وعملها؟","options":["حرف نفي يجزم المضارع ويقلبه إلى الزمن الماضي","حرف نهي","حرف أمر","حرف شرط"],"answer":0,"explanation":"لم: نفي + جزم + قلب الزمن: لم يذهب = لم يحدث الذهاب في الماضي؛ المضارع بعدها مجزوم بالسكون."},{"question":"ما الفرق بين «لم» و«لما»؟","options":["لم للنفي المطلق ولما لنفي ما يتوقع وقوعه","لا فرق","لما لا تجزم","لم للأمر"],"answer":0,"explanation":"لم يذهب: نفي مطلق؛ لما يذهب: لم يذهب بعد ويُتوقع ذهابه؛ وكلتاهما تجزم."},{"question":"كيف تميز لا الناهية من لا النافية؟","options":["الناهية تجزم المضارع والنافية لا تعمل","النافية تجزم","كلتاهما تجزم","لا فرق"],"answer":0,"explanation":"لا تذهبْ: ناهية جازمة (طلب الكف)؛ لا يذهبُ: نافية فقط والمضارع مرفوع."},{"question":"ما علامة جزم الأفعال الخمسة؟","options":["حذف النون","السكون","الفتحة","حذف حرف العلة"],"answer":0,"explanation":"الأفعال الخمسة تجزم وترفع بحذف النون وثبوتها: لم يذهبوا - مجزوم بحذف النون."}]},{"body":["تدريب إعرابي: «لم يكتبِ التلميذُ الدرسَ»: لم: حرف نفي وجزم مبني على السكون لا محل له. يكتب: فعل مضارع مجزوم بلم وعلامة جزمه السكون. التلميذ: فاعل مرفوع بالضمة. الدرس: مفعول به منصوب بالفتحة.","«لا تؤجّلْ عملَ اليومِ»: لا: حرف نهي جازم مبني على السكون. تؤجل: فعل مضارع مجزوم بلا الناهية بالسكون، والفاعل مستتر «أنت». عمل: مفعول به مضاف. اليوم: مضاف إليه.","«ولتصبرْ على الطاعةِ»: اللام: لام الأمر مبنية على الكسر... (لام الأمر تكون مكسورة وتدخلها الفاء أو الواو: فلتصبر، ولتصبر). تصبر: مضارع مجزوم بالسكون. على الطاعة: جار ومجرور متعلق بتصبر.","لام الأمر تسمى أيضًا «لام الاقتراح» وتفيد الطلب: للغائب: «ليأتِ زيدٌ». وللمخاطب مع الواو: «فلتقُمْ». ومع الكسر قبلها للمتكلم: «لأُنصفَنَّ المظلومَ»... المهم: تجزم المضارع.","تنبيه: لام الأمر تختلف عن لام التعليل: التعليل تنصب (جئت لأتعلمَ) والأمر تجزم (لتتعلمْ). الفرق في المعنى: التعليل سبب لفعل سابق، والأمر طلب مستقل.","الخلاصة: أربعة أحرف تجزم فعلًا واحدًا: لم (نفي ماضٍ)، لما (نفي متوقع)، لا الناهية (طلب الكف)، لام الأمر (طلب الفعل). وعلامات الجزم: السكون، وحذف النون، وحذف حرف العلة."],"examples":["لم يكتب التلميذ الدرس: مجزوم بالسكون","لا تؤجل عمل اليوم: مجزوم بلا الناهية","ولتصبر على الطاعة: لام الأمر جازمة","ليأتِ زيد: لام الأمر للغائب","جئت لأتعلم: لام تعليل ناصبة (للمقارنة)","لم يذهبوا ولم يصلوا: حذف النون"],"questions":[{"question":"أعرب «تؤجل» في «لا تؤجلْ عمل اليوم»:","options":["فعل مضارع مجزوم بلا الناهية وعلامة جزمه السكون","منصوب بالفتحة","مرفوع بالضمة","مبني"],"answer":0,"explanation":"تؤجل مضارع مجزوم بلا الناهية بالسكون، والفاعل ضمير مستتر تقديره أنت."},{"question":"كيف تفرق بين لام التعليل ولام الأمر؟","options":["التعليل تنصب المضارع والأمر تجزمه","كلتاهما تنصب","كلتاهما تجزم","لا فرق"],"answer":0,"explanation":"لام التعليل: جئت لأتعلمَ (نصب، وسبب لفعل سابق)؛ لام الأمر: لتتعلمْ (جزم، وطلب مستقل)."},{"question":"أي الجمل فيها لام أمر؟","options":["ولتصبرْ على الطاعة","جئت لأتعلم","لم يصبرْ","لن يصبرَ"],"answer":0,"explanation":"ولتصبر: اللام لام أمر جازمة؛ لأتعلم لام تعليل ناصبة، لم جازمة نافية، لن ناصبة نافية."},{"question":"ما علامات جزم المضارع الثلاث؟","options":["السكون وحذف النون وحذف حرف العلة","الفتحة فقط","الضمة والسكون","الكسرة"],"answer":0,"explanation":"الجزم علاماته: السكون (لم يذهب)، حذف النون (لم يذهبوا)، حذف حرف العلة (لم يدعُ، لم يخشَ)."},{"question":"أعرب «يذهبوا» في «لم يذهبوا»:","options":["فعل مضارع مجزوم بلم وعلامة جزمه حذف النون","مرفوع بثبوت النون","منصوب بالفتحة","فعل أمر"],"answer":0,"explanation":"يذهبوا من الأفعال الخمسة (اتصلت به واو الجماعة)؛ جزمته لم فحذفت نونه: مجزوم بحذف النون."}]}]},{"id":"wahi-sharh-048","title":"أدوات الشرط الجازمة","section":"شرح الكتاب: باب جزم الفعل المضارع - أدوات الشرط","order":48,"segments":[{"body":["النوع الثاني من الجوازم: «ما يجزم فعلين: الأول يُسمى فعل الشرط، والآخر يُسمى جواب الشرط. وهي أدوات الشرط الجازمة: إن، إذما، من، ما، مهما، متى، أيان، أين، أنّى، حيثما، كيفما، وأيّ».","الشرط: تعليق أمر على أمر: «إن تأتِ أُكرمْكَ»: إكرامك معلق على إتيانك. الأول فعل الشرط والثاني جواب الشرط، وكلاهما مجزوم.","أمثلة الكتاب المعربة: «إن تأتِ أُكرمْكَ»: تأتِ: فعل الشرط، وهو فعل مضارع مجزوم وعلامة جزمه حذف حرف العلة (أصلها تأتي بحذفت الياء). أكرمك: جواب الشرط، وهو فعل مضارع مجزوم وعلامة جزمه السكون.","«من يدعُ يُسمعْه اللهُ» (من يدعُ اللهَ يستجب له): يدع: فعل الشرط مجزوم وعلامة جزمه حذف حرف العلة. يسمعه: جواب الشرط مجزوم بالسكون.","«أين تجلسْ تستفدْ»: تجلس: فعل الشرط مجزوم بالسكون. تستفد: جواب الشرط مجزوم بالسكون.","أمثلة قرآنية من الكتاب: «وما تتقوا الله يجعلْ لكم فرقانًا» (الأنفال): تتقوا: فعل الشرط مجزوم بحذف النون (الواو فاعل). يجعل: جواب الشرط مجزوم بالسكون. و«وما تفعلوا من خيرٍ يعلمْه اللهُ» (البقرة): تفعلوا: فعل الشرط مجزوم بحذف النون. يعلمه: جواب الشرط مجزوم بالسكون.","معاني الأدوات: إن: للأمر المظنون المستقبل. من: للعاقل. ما ومهما: لغير العاقل. متى وأيان: للزمان. أين وأنى وحيثما: للمكان. كيفما: للحال. أيّ: لما تضيفه إليه. إذما: للتعليل والجزاء (غالبة مع الماضي غالبًا... ولكنها تجزم المضارع أيضًا)."],"examples":["إن تأتِ أكرمك: فعل شرط مجزوم بحذف حرف العلة","من يدعُ يسمعه الله: جواب شرط مجزوم بالسكون","أين تجلس تستفد: أين للمكان","وما تتقوا الله يجعل لكم فرقانا: حذف النون في فعل الشرط","وما تفعلوا من خير يعلمه الله: شرط قرآني","مهما تدرس تفد: مهما لغير العاقل"],"questions":[{"question":"ما الذي تجزمه أدوات الشرط؟","options":["فعلين: فعل الشرط وجواب الشرط","فعلًا واحدًا","ثلاثة أفعال","اسمين"],"answer":0,"explanation":"أدوات الشرط الجازمة تجزم فعلين: فعل الشرط وجواب الشرط: إن تأتِ أكرمك."},{"question":"عدّ أدوات الشرط الجازمة:","options":["إن وإذما ومن وما ومهما ومتى وأيان وأين وأنى وحيثما وكيفما وأي","لم ولما ولا ولام الأمر","أن ولن وكي","الواو والفاء وثم"],"answer":0,"explanation":"إثنتا عشرة أداة: إن، إذما، من، ما، مهما، متى، أيان، أين، أنى، حيثما، كيفما، أي."},{"question":"أعرب «تأتِ» في «إن تأتِ أكرمك»:","options":["فعل الشرط مجزوم وعلامة جزمه حذف حرف العلة","مرفوع بالضمة","منصوب بالفتحة","مجزوم بالسكون"],"answer":0,"explanation":"تأتِ أصله يأتي معتل الآخر بالياء؛ جزم فحذف حرف العلة: فعل الشرط مجزوم بحذف حرف العلة."},{"question":"ما معنى أداة الشرط «من»؟","options":["للعاقل","لغير العاقل","للزمان","للمكان"],"answer":0,"explanation":"من للعاقل (من يجتهد ينجح)، وما ومهما لغير العاقل، ومتى وأيان للزمان، وأين وأنى وحيثما للمكان، وكيفما للحال، وأي لما تضاف إليه."},{"question":"أعرب «تتقوا» في «وما تتقوا الله يجعل لكم فرقانا»:","options":["فعل الشرط مجزوم وعلامة جزمه حذف النون","مرفوع بثبوت النون","منصوب بالفتحة","فعل أمر"],"answer":0,"explanation":"تتقوا من الأفعال الخمسة (واو الجماعة فاعل)؛ جزمته ما الشرطية فحذفت نونه: مجزوم بحذف النون."}]},{"body":["أركان الجملة الشرطية ثلاثة: ١- أداة الشرط (إن). ٢- فعل الشرط (تأتِ). ٣- جواب الشرط (أكرمك). والأداة أسماء وحروف: «إن» حرف باتفاق، و«إذما» حرف على الراجح، والباقي أسماء مبنية (من، ما، متى، أين...) إلا «أيّ» فمعربة.","جواب الشرط يجزم إذا كان مضارعًا ولم تكن الجملة طلبية... التفصيل: إن اقترن الجواب بالفاء أو إذا الفجائية لم يجزم: «إن تدرسْ فسوف تنجحُ» - تنجح مرفوع لاقترانه بالفاء. هذا باب طويل؛ المهم الآن: الأصل جزم الفعلين.","تدريب: «مهما تبذلْ من جهدٍ تجدْ ثمرتَه»: مهما: أداة شرط جازمة مبنية. تبذل: فعل الشرط مجزوم بالسكون. من جهد: جار ومجرور. تجد: جواب الشرط مجزوم بالسكون. ثمرته: مفعول به.","«متى تزرْنا نُكرمْكَ»: متى أداة شرط للزمان. تزر: فعل الشرط مجزوم (حذفت نونه... لا: تزر بالنون لتصال نا الدالة على الفاعلين - نكرمك: جواب مجزوم بالسكون).","«كيفما تجلسْ يكنْ حالُك»: كيفما للحال، تجلس فعل الشرط، يكن جواب الشرط مجزوم.","الخلاصة: أدوات الشرط اثنتا عشرة تجزم فعلين: فعل الشرط وجوابه، وعلامات الجزم الثلاث تعمل فيهما: السكون وحذف النون وحذف حرف العلة."],"examples":["مهما تبذل من جهد تجد ثمرته: شرط كامل","متى تزرنا نكرمك: متى للزمان","كيفما تجلس يكن حالك: كيفما للحال","إن تدرس فسوف تنجح: الجواب مقترن بالفاء فلم يجزم","من يزرع يحصد: شرط حكمة","أي كتاب تقرأ تستفد: أي لما تضاف إليه"],"questions":[{"question":"ما أركان الجملة الشرطية؟","options":["أداة الشرط وفعل الشرط وجواب الشرط","فعلان فقط","مبتدأ وخبر","فاعل ومفعول"],"answer":0,"explanation":"ثلاثة: أداة الشرط (إن)، وفعل الشرط (تأت)، وجواب الشرط (أكرمك)؛ والفعلان مجزومان."},{"question":"متى لا يجزم جواب الشرط؟","options":["إذا اقترن بالفاء أو إذا الفجائية","إذا كان مضارعًا","إذا كان ماضيًا","دائمًا يجزم"],"answer":0,"explanation":"إن اقترن الجواب بالفاء أو إذا الفجائية لم يجزم: إن تدرس فسوف تنجحُ - مرفوع."},{"question":"ما إعراب «إن» الشرطية؟","options":["حرف شرط جازم مبني على السكون لا محل له من الإعراب","اسم شرط","فعل شرط","حرف نصب"],"answer":0,"explanation":"إن حرف باتفاق مبني على السكون لا محل له من الإعراب؛ وإذما حرف على الراجح؛ والباقي أسماء مبنية إلا أيّ."},{"question":"أعرب «تجدْ» في «مهما تبذل من جهد تجد ثمرته»:","options":["جواب الشرط مجزوم بالسكون","فعل الشرط","مرفوع","منصوب"],"answer":0,"explanation":"تجد جواب الشرط فعل مضارع مجزوم وعلامة جزمه السكون؛ وثمرته مفعول به منصوب."},{"question":"أي أدوات الشرط للمكان؟","options":["أين وأنى وحيثما","متى وأيان","من وما","كيفما"],"answer":0,"explanation":"أين وأنى وحيثما للمكان: أين تجلس تستفد؛ ومتى وأيان للزمان، ومن للعاقل، وما ومهما لغير العاقل."}]}]},{"id":"wahi-sharh-049","title":"رفع الفعل المضارع وخاتمة المختصر","section":"شرح الكتاب: باب رفع الفعل المضارع","order":49,"segments":[{"body":["الباب الأخير من إعراب المضارع: «باب رفع الفعل المضارع». القاعدة الجامعة: «الفعل المضارع ينصب في عشرة مواضع، ويُجزم في خمسة مواضع، ويرفع فيما سوى ذلك».","أي أن الرفع هو الأصل: كل مضارع لم تتقدمه ناصبة ولا جازمة فهو مرفوع. إعرابه: «فعل مضارع مرفوع وعلامة رفعه الضمة» (أو ثبوت النون في الأفعال الخمسة).","أمثلة الكتاب على المضارع المرفوع: «يسأل الله في عافيتا» أي: أسأل الله في عافيتي. «والله يرزقنا الإخلاصَ والتوفيقَ». «وأحمدُ الله على فضله». كلها مضارعات مرفوعة لأنه لم يسبقها ناصب ولا جازم.","أمثلة قرآنية ذكرها الكتاب وفيها أفعال مضارعة مرفوعة: «والله يعلم ما تسرون وما تعلنون» (النحل): يعلم ويسرون ويعلنون ويحب - أربعة أفعال مضارعة مرفوعة. «الذين يؤمنون بالغيب ويقيمون الصلاة ومما رزقناهم ينفقون» (البقرة): يؤمنون ويقيمون وينفقون - ثلاثة أفعال مرفوعة بثبوت النون (أفعال خمسة).","«وما يتم الكتابُ إلا بتوفيق الله»: يتم مضارع مرفوع (ما قبله نافية لا ناهية). «إذا ألقى الله البركة في الكتاب ينفع الناس»: إذا ظرفية غير جازمة فالمضارع بعدها مرفوع: ينفع مرفوع.","ملاحظة الفرق: «إذا» الظرفية لا تجزم (إذا جاء زيد أكرمته)؛ أما «إن» الشرطية فتجزم. و«ما» النافية لا تعمل، و«ما» الشرطية تجزم. السياق يحدد.","ثم خاتمة المختصر: «الحمد لله الذي بنعمته تتم الصالحات، والصلاة والسلام على نبينا محمد وعلى آله وأصحابه أجمعين» - وانتهى «فتح النحو الصغير» بحمد الله وتوفيقه. وبعده يبدأ الشارح قسمًا أوسع: شرح النحو الصغير المفصل، وهو ما ندخل فيه من الدرس القادم."],"examples":["يسأل الله في عافيتي: مضارع مرفوع","والله يرزقنا الإخلاص: مرفوع","الذين يؤمنون ويقيمون وينفقون: مرفوعة بثبوت النون","والله يعلم ما تسرون: يعلم مرفوع","وما يتم الكتاب إلا بتوفيق الله: يتم مرفوع بعد نافية","إذا ألقى الله البركة ينفع الناس: ينفع مرفوع"],"questions":[{"question":"متى يرفع الفعل المضارع؟","options":["إذا لم يسبق بناصب ولا جازم","إذا سبق بأن","إذا سبق بلم","إذا سبق بإن الشرطية"],"answer":0,"explanation":"الرفع أصل المضارع: ينصب في عشرة مواضع ويجزم في خمسة، ويرفع فيما سوى ذلك."},{"question":"كم موضعًا ينصب فيه المضارع وكم يجزم؟","options":["ينصب في عشرة ويجزم في خمسة","ينصب في خمسة ويجزم في عشرة","متساويان","ثلاثة وثلاثة"],"answer":0,"explanation":"ينصب بعد عشرة أحرف، ويجزم بعد خمسة أشياء (أربعة أحرف + أدوات الشرط)، ويرفع في الباقي."},{"question":"ما علامة رفع الأفعال الخمسة؟","options":["ثبوت النون","الضمة","الفتحة","السكون"],"answer":0,"explanation":"الأفعال الخمسة ترفع بثبوت النون: يؤمنون ويقيمون وينفقون - مضارعات مرفوعة بثبوت النون."},{"question":"هل تجزم «إذا» الظرفية المضارع؟","options":["لا؛ إن الشرطية هي الجازمة","نعم","أحيانًا تجزم","تجزم بشرط"],"answer":0,"explanation":"إذا الظرفية غير جازمة: إذا ألقى الله البركة ينفع الناس - ينفع مرفوع؛ أما إن الشرطية فتجزم."},{"question":"أعرب «ينفقون» في «ومما رزقناهم ينفقون»:","options":["فعل مضارع مرفوع وعلامة رفعه ثبوت النون","منصوب بحذف النون","مجزوم بحذف النون","مبني"],"answer":0,"explanation":"لم يسبقه ناصب ولا جازم فهو مرفوع؛ وهو من الأفعال الخمسة فعلامة رفعه ثبوت النون، والواو فاعل."}]},{"body":["تدريب التمييز بين الأحوال الثلاث: «لا تغفلْ عن ذكر الله لتحيا قلبُك»... الأصح: «اذكرِ اللهَ يحيَ قلبُك»... لنأخذ: «لن أنسى فضلَك» (نصب بلن)، «لم أنسَ فضلَك» (جزم بلم)، «لا أنسى فضلَك» (رفع مع لا النافية). ثلاث صيغ متشابهة بثلاثة أحوال!","تدريب مع حرف واحد بمعنيين: «لا تكسلْ» (لا ناهية جازمة) مقابل «لا تكسلُ في العبادة» (لا نافية والمضارع مرفوع). العين تلتقط الفرق بالسياق: نهي وطلب أم خبر ونفي.","تدريب شامل: «إن تحفظِ القرآنَ تسعدْ في الدنيا والآخرة»: إن أداة شرط. تحفظ: فعل الشرط مجزوم بالسكون. القرآن: مفعول به. تسعد: جواب الشرط مجزوم بالسكون. في الدنيا والآخرة: جار ومجرور ومعطوف.","«الطالبُ يذاكرُ دروسَه ليتفوقَ ويُسعدَ والديهِ»: يذاكر: مرفوع (لا ناصب ولا جازم). ليتفوق: منصوب بلام التعليل. ويسعد: معطوف على ليتفوق منصوب بالفتحة (العطف على المنصوب منصوب).","ملخص أدوات الإعراب في المضارع: نواصب عشرة (أن لن كي إذن لام التعليل لام الجحود حتى الواو الغائية فاء السببية وواو المعية)، جوازم: أربعة أحرف (لم لما لا الناهية لام الأمر) وأدوات شرط اثنتا عشرة، والباقي رفع.","وبهذا أتممنا «فتح النحو الصغير» - الشرح المختصر - بجميع أقسامه الأربعة: أحكام الكلمة، أركان الجملتين، مكملات الجملتين، وإعراب الفعل المضارع. والحمد لله الذي بنعمته تتم الصالحات. ومن الدرس القادم نبدأ القسم الموسع من الكتاب: «شرح النحو الصغير» المفصل، الذي يعيد البناء من الأساس ببيان أعمق وتفصيل أوسع."],"examples":["لن أنسى فضلَك: نصب بلن","لم أنسَ فضلَك: جزم بلم","لا أنسى فضلَك: رفع مع النافية","لا تكسلْ (ناهية) مقابل لا تكسلُ (نافية)","إن تحفظ القرآن تسعد: شرط كامل","يذاكر ليتفوق ويسعد: رفع ونصب وعطف"],"questions":[{"question":"أعرب «أنسى» في «لن أنسى فضلَك»:","options":["فعل مضارع منصوب بلن وعلامة نصبه الفتحة","مجزوم بالسكون","مرفوع بالضمة","فعل أمر"],"answer":0,"explanation":"لن من نواصب المضارع: أنسى فعل مضارع منصوب بلن وعلامة نصبه الفتحة."},{"question":"أعرب «تكسل» في «لا تكسلُ في العبادة»:","options":["فعل مضارع مرفوع بالضمة (لا نافية)","مجزوم بالسكون","منصوب","فعل أمر"],"answer":0,"explanation":"لا هنا نافية لا ناهية: تكسل مضارع مرفوع بالضمة؛ لو كانت ناهية لجزمت: لا تكسلْ."},{"question":"أعرب «ويسعدَ» في «يذاكر ليتفوق ويسعد والديه»:","options":["فعل مضارع معطوف على ليتفوق منصوب بالفتحة","مرفوع","مجزوم","فعل أمر"],"answer":0,"explanation":"يسعد معطوف على ليتفوق المنصوب بلام التعليل؛ والتوابع تتبع متبوعها: منصوب بالفتحة."},{"question":"ما أحوال الفعل المضارع الثلاثة وضابطها؟","options":["نصب بناصب، وجزم بجازم، ورفع فيما سوى ذلك","نصب دائمًا","رفع دائمًا","جزم دائمًا"],"answer":0,"explanation":"الضابط الجامع: ينصب إذا سبق بناصب، ويجزم إذا سبق بجازم، ويرفع إذا لم يسبق بناصب ولا جازم."},{"question":"ماذا أتممنا بختم القسم الرابع؟","options":["فتح النحو الصغير المختصر بأقسامه الأربعة","الكتاب كله","الجزء الأول فقط","الملاحق"],"answer":0,"explanation":"اكتمل الشرح المختصر بأقسامه الأربعة: أحكام الكلمة، أركان الجملتين، المكملات، إعراب المضارع؛ والقادم الشرح الموسع."}]}]},{"id":"wahi-sharh-050","title":"مدخل الشرح الموسع وخريطة علم النحو","section":"شرح الكتاب: شرح النحو الصغير المفصل - المقدمة وموضوع العلم","order":50,"segments":[{"body":["انتهينا من الشرح المختصر، ونفتح الآن «شرح النحو الصغير» الموسع. يبدأ المؤلف بمقدمة ثانية يحمد الله فيها ويثني عليه، ويبين أن هذا الشرح جاء «متوسطًا حفيظًا رصينًا»: أوسع من المختصر وأوجز من المطولات، جمع فيه الفوائد وقرّبها لكل طالب.","نصائح المؤلف للطالب: أن يخلص النية لله، وأن يحفظ النظم أولًا (فهو المتن)، ثم يقرأ الشرح عليه، وأن يكثر من التطبيق والإعراب؛ فالنحو لا يثبت بالقراءة وحدها بل بالتدريب.","موضوع علم النحو: هو علم تُعرف به أحوال أواخر الكلم: إعرابًا وبناءً. الغاية منه: صيانة اللسان عن الخطأ في كتاب الله وسنة رسوله، وفهم كلام العرب على وجهه.","خريطة النحو عند المؤلف: الكلام العربي كله يتركب من كلمات، والكلمة ثلاثة أقسام: اسم وفعل وحرف. ثم تنقسم أبواب العلم قسمين كبيرين: «أحكام الكلمة» (ما يخص الكلمة الواحدة: نوعها، نكرتها ومعرفتها، إعرابها وبناؤها) و«أحكام الكلام» (ما يخص تركيب الكلمات في الجملة: المبتدأ والخبر، الفعل والفاعل، والمفاعيل...).","أحكام الكلمة ثلاثة أبواب: الأول: أنواع الكلمة الثلاثة (اسم وفعل وحرف وضوابطها). الثاني: النكرة والمعرفة وأقسام المعارف الستة. الثالث: المعرب والمبني (أي الكلمات يتغير آخرها وأيها يلزم حالة واحدة).","ثم أحكام الكلام: الجملة الاسمية وأركانها (المبتدأ والخبر)، والجملة الفعلية وأركانها (الفعل والفاعل أو نائبه)، ثم المكملات: كان وأخواتها وإن وأخواتها والمفاعيل والحال والتمييز والاستثناء والنداء والمجرورات والتوابع، ثم إعراب المضارع.","سنمر الآن على هذه الأبواب مرة أخرى لكن بتفصيل أعمق: ضوابط دقيقة، وحصر للأنواع، وأمثلة قرآنية وشعرية. لا تستغرب التكرار: فهذا أسلوب أهل العلم: متن مختصر يُحفظ، ثم شرح يوسّعه ويثبّته."],"examples":["خريطة النحو: كلمة ← كلام","أحكام الكلمة: ثلاثة أبواب","أحكام الكلام: جملتان ومكملات","موضوع النحو: أحوال أواخر الكلم","الغاية: صيانة اللسان عن اللحن","أسلوب أهل العلم: متن ثم شرح"],"questions":[{"question":"بمَ بدأ المؤلف القسم الموسع؟","options":["بمقدمة ثانية يحمد الله ويبين منهج الشرح","بأحكام الكلام مباشرة","بالمفاعيل","بالفهارس"],"answer":0,"explanation":"بدأ بمقدمة ثانية ونصائح للطالب: الإخلاص، حفظ النظم أولًا، ثم القراءة مع كثرة التطبيق."},{"question":"ما موضوع علم النحو؟","options":["علم تُعرف به أحوال أواخر الكلم إعرابًا وبناءً","علم البلاغة","علم الأصوات","علم المعاني"],"answer":0,"explanation":"النحو يبحث في أواخر الكلمات: متى تكون مرفوعة أو منصوبة أو مجرورة أو مجزومة أو مبنية."},{"question":"ما غاية تعلم النحو؟","options":["صيانة اللسان عن الخطأ وفهم الكتاب والسنة","التفاخر بالعلم","حفظ الألفاظ فقط","كتابة الشعر"],"answer":0,"explanation":"الغاية صيانة اللسان عن اللحن في كتاب الله وسنة رسوله وفهم كلام العرب على وجهه."},{"question":"إلامَ تنقسم أبواب النحو الكبرى؟","options":["أحكام الكلمة وأحكام الكلام","نصب ورفع فقط","أسماء فقط","أفعال فقط"],"answer":0,"explanation":"قسمان: أحكام الكلمة (نوعها ومعرفتها وإعرابها وبناؤها) وأحكام الكلام (الجمل وأركانها ومكملاتها)."},{"question":"كم بابًا في أحكام الكلمة؟","options":["ثلاثة: أنواع الكلمة، النكرة والمعرفة، المعرب والمبني","خمسة","عشرة","باب واحد"],"answer":0,"explanation":"ثلاثة أبواب: أنواع الكلمة الثلاثة، ثم النكرة والمعرفة، ثم المعرب والمبني؛ وسيأتي كل باب مفصلًا."}]},{"body":["لماذا التكرار بين المختصر والموسع؟ لأن العلم يثبت بالتدرج: تحفظ القاعدة وجملة عنها أولًا، ثم تعود إليها فتعرف وجوهها وشواذها وأمثلتها. كالبناء: أساس ثم جدران ثم سقف.","في هذا القسم الموسع ستجد: ضوابط عملية تميز بها الاسم من الفعل من الحرف بعلامات ملموسة (التنوين، أل، النداء، حرف الجر للاسم؛ تاء التأنيث الساكنة للماضي، لم للمضارع، ياء المخاطبة للأمر).","وستجد حصرًا دقيقًا: المعارف ستة محصورة، والضمائر معدودة، وأسماء الإشارة محصورة، والموصولات محصورة، والأسماء المبنية عشرة أنواع. الحصر يعني: لا سابع لها؛ فما وجدتَه خارجها فهو نكرة أو معرب.","وستجد أمثلة من القرآن والشعر وكلام العرب، لتربط القاعدة بنص حقيقي. اجعل لكل باب أمثلة تحفظها: فالمثال المحفوظ يستدعي القاعدة عند الحاجة.","منهجك معنا في الدروس القادمة: كل باب درس أو درسان: نشرح القاعدة بالألفاظ السهلة أولًا، نفكك الكلمات لفظًا لفظًا، ثم الأمثلة، ثم أسئلة تثبيت. لا تنتقل قبل أن تتقن ما قبله؛ فالأبواب متراكمة: من لم يعرف الاسم لن يعرف النكرة، ومن لم يعرف المعرب لن يعرب جملة.","تذكير بالرموز الإعرابية الأربعة التي ستلازمنا: الرفع (للأعلى: مبتدأ، خبر، فاعل...)، والنصب (للأدنى: مفاعيل وما شابهها)، والجر (للمتوسطة الأدنى)، والجزم (خاص بالمضارع). هذه هي المفاتيح الأربعة التي عليها يدور العلم كله.","هيّا نبدأ بأول أبواب أحكام الكلمة مفصلًا: أنواع الكلمة وضوابطها."],"examples":["التدرج: قاعدة محفوظة ثم توسعة","ضوابط ملموسة: التنوين وأل للاسم","حصر دقيق: المعارف ستة لا سابع","أمثلة قرآنية تربط القاعدة بالنص","الأبواب متراكمة: لا تتجاوز قبل الإتقان","المفاتيح الأربعة: رفع ونصب وجر وجزم"],"questions":[{"question":"لماذا يعيد المؤلف الأبواب بتفصيل بعد المختصر؟","options":["ليثبت العلم بالتدرج ويبين وجوهه وأمثلته","لأنه نسي","ليطيل الكتاب","لا سبب"],"answer":0,"explanation":"أسلوب أهل العلم: متن يحفظ ثم شرح يوسع؛ كالبناء: أساس ثم جدران ثم سقف."},{"question":"ما الضوابط الملموسة للاسم التي ستأتي؟","options":["التنوين وأل والنداء وحرف الجر","لم وسوف","تاء التأنيث","ياء المخاطبة"],"answer":0,"explanation":"الاسم يعرف بالتنوين ودخول أل والنداء وحرف الجر؛ وتاء التأنيث للماضي ولم للمضارع وياء المخاطبة للأمر."},{"question":"ما فائدة حصر الأنواع (كالمعارف الستة)؟","options":["ما خرج عنها عرفنا حكمه بيقين","لا فائدة","للحفظ فقط","زيادة علمية فقط"],"answer":0,"explanation":"الحصر يعني لا سابع لها: فكل اسم ليس من الستة فهو نكرة؛ وهذا ييسر الحكم العملي."},{"question":"ما منهج الدروس القادمة لكل باب؟","options":["شرح مبسط ثم تفكيك الألفاظ ثم أمثلة ثم أسئلة","أسئلة فقط","حفظ بلا فهم","أمثلة بلا قاعدة"],"answer":0,"explanation":"قاعدة بألفاظ سهلة، ثم تفكيك لفظًا لفظًا، ثم أمثلة، ثم تثبيت بالأسئلة؛ مع عدم تجاوز باب قبل إتقانه."},{"question":"ما المفاتيح الأربعة التي يدور عليها الإعراب؟","options":["الرفع والنصب والجر والجزم","الفتح فقط","الضم فقط","الكسر فقط"],"answer":0,"explanation":"أربعة: رفع (للأعلى كالفاعل والمبتدأ)، نصب (للأدنى كالمفاعيل)، جر (للمتوسطة الأدنى)، جزم (خاص بالمضارع)."}]}]},{"id":"wahi-sharh-051","title":"ضابط الاسم وأنواعه","section":"شرح الكتاب: أحكام الكلمة - باب أنواع الكلمة مفصلًا: الاسم","order":51,"segments":[{"body":["باب أنواع الكلمة مفصلًا. الكلمة اسم أو فعل أو حرف. كيف تعرف الاسم؟ ضابط الاسم: «ما دل على معنى في نفسه غير مقترن بزمن». أي: تفهمه وحده بلا حاجة إلى زمن: «محمد»، «شجرة»، «علم».","لكن هذا الضابط المعنوي صعب على المبتدئ؛ فجاءت العلامات اللفظية العملية، وهي أربع: «يقبل التنوين، والنداء، وحرف الجر، و(أل)».","التنوين: نون ساكنة زائدة تلحق آخر الاسم تلفظًا لا كتابة: رجلٌ، كتابٍ، مؤمنٌ. لا يقبله الفعل ولا الحرف: لا تقول «ذهبٌ».","النداء: أن ينادى بيا وأمثالها: يا محمدُ، يا رجلُ. لا ينادى الفعل: لا تقول «يا اذهبْ» بمعنى الاسم.","حرف الجر: يدخل عليه: مررتُ بمحمدٍ، في البيتِ، إلى المسجدِ. لا يدخل حرف الجر على فعل.","أل: التعريف: الرجلُ، الكتابُ. لا تدخل على فعل: لا تقول «الذهبَ» بمعنى أل التعريفية.","جمع المؤلف هذه الضوابط في بيت ضابط: «وكلُّ ما دخل التنوينُ عليه # ويُنادى ويُجرُّ و(أل) تَليهِ - فهو اسمٌ...». فإن قبل الاسم واحدة من هذه الأربع فهو اسم قطعًا.","أنواع الاسم: اسم جنس (رجل، شجرة)، واسم علم (محمد، القاهرة)، واسم فاعل واسم مفعول (كاتب، مكتوب)، وصيغ مبالغة (غفار)، وأسماء مصادر... وسيأتي تفصيل النكرة والمعرفة في الباب القادم."],"examples":["ضابط الاسم: معنى في نفسه بلا زمن","علامة ١: التنوين (رجلٌ)","علامة ٢: النداء (يا محمد)","علامة ٣: حرف الجر (مررت بمحمد)","علامة ٤: أل (الكتاب)","الفعل لا يقبل شيئًا منها"],"questions":[{"question":"ما ضابط الاسم المعنوي؟","options":["ما دل على معنى في نفسه غير مقترن بزمن","ما دل على حدث بزمن","ما لا معنى له","ما اقترن بزمن"],"answer":0,"explanation":"الاسم يدل على معنى مفهوم وحده غير مقترن بزمن: محمد وشجرة وعلم؛ بخلاف الفعل المقترن بزمن."},{"question":"ما العلامات اللفظية الأربع للاسم؟","options":["التنوين والنداء وحرف الجر وأل","لم وسوف وقد","تاء التأنيث ونون النسوة","الفتح والضم"],"answer":0,"explanation":"أربع علامات عملية: يقبل التنوين (رجلٌ)، والنداء (يا رجل)، وحرف الجر (مررت برجل)، وأل (الرجل)."},{"question":"لماذا نحتاج علامات لفظية مع وجود الضابط المعنوي؟","options":["لأن الضابط المعنوي صعب على المبتدئ والعلامات أوضح","للزينة","لا حاجة","للتطويل"],"answer":0,"explanation":"الضابط المعنوي يحتاج ذوقًا؛ فالعلامات اللفظية تضبط الاسم ضبطًا عمليًا سريعًا يصلح للمبتدئ."},{"question":"هل يقبل الفعل التنوين أو أل؟","options":["لا؛ وذلك علامة أنه ليس اسمًا","نعم دائمًا","أحيانًا","يقبل أل فقط"],"answer":0,"explanation":"الفعل لا يقبل التنوين ولا النداء ولا حرف الجر ولا أل؛ فما لم يقبلها ودل على حدث بزمن فهو فعل."},{"question":"«مررت بعالمٍ»: ما دليل أن «عالم» اسم؟","options":["قبل حرف الجر والتنوين معًا","لأنه في أول الجملة","لأنه فعل","لا دليل"],"answer":0,"explanation":"دخل عليه حرف الجر (ب) والتنوين (عالمٌ)؛ وكل ما دخله التنوين ويُجر فهو اسم."}]},{"body":["تدريب عملي: مر الكلمات التالية على العلامات الأربع: «مدرسة»: تقبل أل (المدرسة) والتنوين (مدرسةٌ) → اسم. «يكتب»: لا تقبل أل ولا تنوين → ليست اسمًا (فعل مضارع). «من»: لا تقبل شيئًا → حرف. «علمٌ»: قبل التنوين → اسم.","تنبيه: التنوين لا يقبله كل اسم: أسماء الإشارة (هذا) والضمائر (أنا) والموصولات (الذي) لا تُنوَّن لأنها مبنية؛ لكنها معروفة أنها أسماء بضوابط أخرى (تدخل في المعرفة وتدل على معنى في نفسها).","تنبيه ثانٍ: بعض الأسماء ممنوعة من الصرف فلا تُنوَّن وهي معربة: مساجدُ (بالفتحة بدل التنوين)، وأحمدُ. فالمانع هنا صرفي لا نحوي.","الفرق بين اسم الجنس واسم العلم: الجنس يقع على كل فرد من نوعه: «رجل» كل رجل، «شجرة» كل شجرة. والعلم مختص بمسماه: «محمد» شخص بعينه، «القاهرة» بلدة بعينها. وسنفصله في باب النكرة والمعرفة.","اسم الفاعل واسم المفعول: مشتقان من الفعل: كتب → كاتب (فاعل) / مكتوب (مفعول). ويقبلان علامات الاسم كلها: الكاتبُ، المكتوبُ. فهما اسمان وإن اشبههما الفعل في المادة.","الخلاصة: الاسم ما دل على معنى في نفسه بلا زمن، وعلاماته الأربع: التنوين والنداء وحرف الجر وأل؛ ومنها يقطع المبتدئ بأن الكلمة اسم."],"examples":["مدرسة: تقبل أل والتنوين = اسم","يكتب: لا تقبل = فعل مضارع","من: لا تقبل شيئًا = حرف","هذا: اسم وإن لم يتنوّن (مبني)","مساجد: ممنوع من الصرف","كاتب ومكتوب: اسمان مشتقان"],"questions":[{"question":"«المدرسة» قبلت أل؛ فما حكمها؟","options":["اسم","فعل","حرف","لا يعرف"],"answer":0,"explanation":"من علامات الاسم قبول أل؛ فالمدرسة اسم لقبولها أل والتنوين."},{"question":"لماذا لا يتنون «هذا» مع أنه اسم؟","options":["لأنه مبني والمبني لا يتغير آخره","لأنه فعل","لأنه حرف","خطأ لغوي"],"answer":0,"explanation":"أسماء الإشارة مبنية فلا تُنوَّن؛ وكونها أسماء يعرف بضوابط أخرى كدلالتها على معنى في نفسها وكونها من المعارف."},{"question":"ما حكم «مساجدُ» مع أنها لا تقبل التنوين؟","options":["اسم معرب ممنوع من الصرف","فعل","حرف","مبني"],"answer":0,"explanation":"مساجد اسم معرب ممنوع من الصرف؛ يجر بالفتحة نيابة عن الكسرة؛ والمنع صرفي لا نحوي."},{"question":"ما الفرق بين «رجل» و«محمد»؟","options":["رجل اسم جنس يقع على كل فرد ومحمد اسم علم مختص بمسماه","لا فرق","كلاهما علم","كلاهما جنس"],"answer":0,"explanation":"الجنس عام على النوع: كل رجل؛ والعلم خاص بمسماه: شخص بعينه؛ وستفصل في باب النكرة والمعرفة."},{"question":"«كاتب» و«مكتوب» ما هما؟","options":["اسمان مشتقان: اسم فاعل واسم مفعول","فعلان","حرفان","أدوات شرط"],"answer":0,"explanation":"اشتقا من كتب: كاتب (من قام بالفعل) ومكتوب (من وقع عليه الفعل)؛ ويقبلان علامات الاسم: الكاتب، المكتوب."}]}]},{"id":"wahi-sharh-052","title":"ضوابط الأفعال الثلاثة: الماضي والمضارع والأمر","section":"شرح الكتاب: باب أنواع الكلمة مفصلًا: الفعل","order":52,"segments":[{"body":["ضابط الفعل العام: «ما دل على حدث مقترن بزمن». حدث: فعل أو وقوع (ذهب، جلس، علم). زمن: ماضٍ أو حاضر أو مستقبل. والأفعال ثلاثة أقسام: ماضٍ، ومضارع، وأمر.","الفعل الماضي: «ما دل على حدث في زمن ماضٍ» أي قبل زمن التكلم: ذهبَ، كتبَ، علمَ. ضابطه العملي: «يقبل تاء التأنيث الساكنة»: ذهبتْ، كتبتْ، علمتْ. فكل كلمة دخلت عليها تاء التأنيث الساكنة فهي فعل ماضٍ.","تاء التأنيث الساكنة: تاء ساكنة تلحق آخر الماضي للدلالة على أن الفاعل مؤنث: قامتْ فاطمةُ. لا تلحق اسمًا ولا حرفًا: لا تقول «رجلتْ».","الفعل المضارع: «ما دل على حدث في زمن حاضر أو مستقبل»: يذهبُ (الآن)، سيذهبُ (بعدًا). ضابطه العملي: «يقبل لم»: لم يذهبْ، ويقبل حروف «أنيت»: أوله أحد: ألف (أكتب) أو نون (نكتب) أو ياء (يكتب) أو تاء (تكتب).","فإن قبلت الكلمة «لم» فهي مضارع قطعًا: لم يكتبْ، لم تكتبْ، لم نكتبْ، لم أكتبْ. وسوف و السين أيضًا علامتان للمستقبل لكن لا تجزمان: سوف يكتبُ، سيكتبُ.","فعل الأمر: «ما دل على طلب الحدث بالأمر»: اكتبْ، اذهبْ، اجلسْ. ضابطه العملي: «يقبل ياء المخاطبة مع الدلالة على الطلب»: اكتبي (لمخاطبة مؤنثة بطلب).","فإن قيل: اكتبي وتدل على طلب → فعل أمر. وإن قيل: تكتبي بغير طلب فتاء مضارع. الدلالة على الطلب هي الفيصل.","جمع المؤلف الضوابط: الماضي يقبل تاء التأنيث الساكنة، والمضارع يقبل لم، والأمر يقبل ياء المخاطبة مع الدلالة على الطلب. بهذه الثلاثة تميز الأفعال كلها."],"examples":["ضابط الفعل: حدث مقترن بزمن","الماضي: يقبل تاء التأنيث (ذهبتْ)","المضارع: يقبل لم (لم يذهب)","حروف أنيت: أ ن ي ت","الأمر: يقبل ياء المخاطبة مع الطلب (اكتبي)","سوف والسين: علامتا مستقبل"],"questions":[{"question":"ما ضابط الفعل العام؟","options":["ما دل على حدث مقترن بزمن","ما دل على معنى بلا زمن","ما لا معنى له","ما قبل التنوين"],"answer":0,"explanation":"الفعل يدل على حدث (وقوع) مقترن بزمن: ماضٍ أو حاضر أو مستقبل؛ بخلاف الاسم."},{"question":"ما ضابط الفعل الماضي العملي؟","options":["يقبل تاء التأنيث الساكنة","يقبل لم","يقبل التنوين","يقبل أل"],"answer":0,"explanation":"الماضي يقبل تاء التأنيث الساكنة: ذهبتْ وكتبتْ؛ فما دخلت عليه فهو فعل ماضٍ."},{"question":"ما ضابط المضارع العملي؟","options":["يقبل لم وحروف أنيت","يقبل التنوين","يقبل تاء التأنيث","يقبل النداء"],"answer":0,"explanation":"المضارع يقبل لم: لم يكتب؛ ويبدأ بأحد حروف أنيت: أكتب، نكتب، يكتب، تكتب."},{"question":"ما ضابط فعل الأمر العملي؟","options":["يقبل ياء المخاطبة مع الدلالة على الطلب","يقبل لم","يقبل أل","يقبل تاء التأنيث"],"answer":0,"explanation":"الأمر يقبل ياء المخاطبة مع معنى الطلب: اكتبي (اطلبي الكتابة)؛ فإن لم يكن طلب فهو مضارع."},{"question":"كيف تميز «تكتبين» مضارعة من «اكتبي» أمرًا؟","options":["بالدلالة على الطلب في الأمر","لا فرق","بالتنوين","بالسياق الزمني الماضي"],"answer":0,"explanation":"الأمر طلب: اكتبي (أطلب منك)؛ والمضارع خبر عن حاضر أو مستقبل: تكتبين الآن؛ الدلالة على الطلب هي الفيصل."}]},{"body":["تدريب عملي بالضوابط الثلاثة: «علّمتْ»: قبلت تاء التأنيث الساكنة → ماضٍ. «يعلّم»: قبل لم (لم يعلّم) ويبدأ بالياء من أنيت → مضارع. «علّمْ»: قبل ياء المخاطبة مع الطلب (علّمي) → أمر. كلمة واحدة بصيغها الثلاث!","«فهم»: فهمَ (تقبل تاء التأنيث: فهمتْ) → ماضٍ. يفهم (لم يفهمْ) → مضارع. افهمْ (افهمي) → أمر.","تنبيه: ليس كل ما بدأ بالياء مضارعًا: «ياسر» اسم علم، «يوم» اسم جنس. الضابط الأقوى: قبول لم. وكذلك ليس كل ما انتهى بتاء ماضيًا: «بنت» اسم. فالتاء في «فهمتْ» ساكنة زائدة للتأنيث، وفي «بنت» أصلية.","الأمر من المجرد الثلاثي يبدأ بهمزة وصل: اكتبْ، اجلسْ، افهمْ. ومن الرباعي وما فوقه: علّمْ، أكرمْ، استغفرْ. وهمزة الوصل تنطق عند الابتداء وتسقط وصلًا.","أمثلة من القرآن: «قالتْ» ماضٍ قبل تاء التأنيث. «يعلمون» مضارع يقبل لم. «قُلْ» و«اعبدوا» و«اصبروا» أوامر تقبل ياء المخاطبة مع الطلب: قولي، اعبدي، اصبري.","الخلاصة: ثلاثة ضوابط عملية للأفعال الثلاثة: الماضي + تاء التأنيث الساكنة، المضارع + لم، الأمر + ياء المخاطبة مع الطلب. طبقها على أي كلمة تعرف نوعها فورًا."],"examples":["علّمتْ / يعلّم / علّمْ: صيغة واحدة بأزمنة ثلاثة","فهمَ / يفهم / افهمْ","ياسر ويوم: اسمان لا مضارعان","بنت: اسم والتاء أصلية","قالت: ماض قرآني","قل واعبدوا واصبروا: أوامر قرآنية"],"questions":[{"question":"«علّمتْ» ما نوعها ولماذا؟","options":["فعل ماضٍ لقبولها تاء التأنيث الساكنة","مضارع","أمر","اسم"],"answer":0,"explanation":"قبلت تاء التأنيث الساكنة (علّمتْ) فهي فعل ماضٍ؛ ضابط الماضي العملي."},{"question":"«يعلّم» ما نوعها؟","options":["فعل مضارع لقبولها لم","ماض","أمر","اسم"],"answer":0,"explanation":"تقبل لم: لم يعلّمْ؛ وتبدأ بالياء من حروف أنيت؛ فهي فعل مضارع."},{"question":"لماذا «ياسر» ليست مضارعًا رغم البدء بالياء؟","options":["لأنها لا تقبل لم فهي اسم علم","لأنها أمر","لا سبب","لأنها مبنية"],"answer":0,"explanation":"الضابط الأقوى قبول لم؛ ياسر لا تقول فيها «لم ياسرْ»؛ فهي اسم علم والياء أصلية."},{"question":"لماذا «بنت» ليست فعلًا ماضيًا؟","options":["لأن التاء فيها أصلية لا زائدة للتأنيث","لأنها تقبل لم","لا سبب","لأنها جمع"],"answer":0,"explanation":"تاء التأنيث الساكنة زائدة تلحق الماضي (فهمتْ)؛ وتاء «بنت» أصلية من بنية الكلمة فهي اسم."},{"question":"«استغفروا» في القرآن ما نوعها؟","options":["فعل أمر لقبولها ياء المخاطبة مع الطلب","ماض","مضارع","اسم"],"answer":0,"explanation":"استغفروا أمر من الاستغفار يقبل ياء المخاطبة مع الطلب: استغفري؛ فهو فعل أمر."}]}]},{"id":"wahi-sharh-053","title":"ضابط الحرف وأنواع الحروف","section":"شرح الكتاب: باب أنواع الكلمة مفصلًا: الحرف","order":53,"segments":[{"body":["ضابط الحرف: «ما دل على معنى في غيره غير مقترن بزمن». أي: لا يُفهم وحده: «من»، «في»، «على»، «هل» - لا معنى لها إلا مع ما بعدها: من البيت، في المسجد.","الضابط العملي الأسهل: «ما لا يقبل شيئًا من علامات الاسم ولا علامات الفعل»: لا يقبل التنوين (لا «منٌّ») ولا أل ولا النداء ولا حرف الجر، ولا يقبل تاء التأنيث ولا لم ولا ياء المخاطبة. فما رفض العلامات كلها فهو حرف.","بيت الحريري الجامع الذي أورده المؤلف في تبويب الحروف يقسمها أقسامًا كثيرة، وأهمها عندنا الآن: حروف الجر، وحروف النصب، وحروف الجزم، وحروف العطف، وحروف الاستفهام، وحروف النفي...","حروف الجر التي تقدمت: من، إلى، عن، على، في، الباء، الكاف، اللام، والتاء للقسم، ورب، ومذ ومنذ، وخلا وعدا وحاشا. تدخل على الاسم فتجره: مررتُ بزيدٍ.","حروف النصب (نواصب المضارع): أن، لن، كي، إذن، لام التعليل، لام الجحود، حتى... تقدمت في باب إعراب المضارع.","حروف الجزم: لم، لما، لا الناهية، لام الأمر. وحروف العطف: الواو والفاء وثم وأو وبل ولا ولكن. وحروف الاستفهام: همزة الاستفهام وهل. وحروف النفي: لا ولم ولما ولن وما.","وهناك حروف مصدرية: أن وما ولو... وحروف زائدة: ما ولا الزائدتان (ما جاءني زيد، لا تسأل عما...). وحروف التنبيه: ألا وها وأما. وكلها مبنية لا إعراب لها.","الخلاصة: الحرف ما دل على معنى في غيره، ولا يقبل علامة من علامات الاسم ولا الفعل، وهو مبني كله، وأقسامه كثيرة بحسب عمله: جر ونصب وجزم وعطف واستفهام ونفي وغيرها."],"examples":["ضابط الحرف: معنى في غيره","الضابط العملي: رفض كل العلامات","حروف الجر: من إلى عن على في...","حروف العطف: الواو والفاء وثم وأو","حروف الاستفهام: الهمزة وهل","حروف التنبيه: ألا وها وأما"],"questions":[{"question":"ما ضابط الحرف المعنوي؟","options":["ما دل على معنى في غيره غير مقترن بزمن","ما دل على معنى في نفسه","ما دل على حدث بزمن","ما قبل التنوين"],"answer":0,"explanation":"الحرف لا يفهم وحده: من وفي وعلى لا معنى لها إلا مع ما بعدها؛ فهي تدل على معنى في غيرها."},{"question":"ما الضابط العملي للحرف؟","options":["ما لا يقبل شيئًا من علامات الاسم ولا الفعل","ما يقبل لم","ما يقبل أل","ما يقبل التنوين"],"answer":0,"explanation":"الحرف يرفض العلامات كلها: لا تنوين ولا أل ولا نداء ولا جر ولا تاء تأنيث ولا لم؛ فما رفضها فهو حرف."},{"question":"أعط ثلاثة أمثلة لحروف الجر:","options":["من وإلى وعلى","أن ولن وكي","لم ولما ولا","الواو والفاء وثم"],"answer":0,"explanation":"حروف الجر: من وإلى وعن وعلى وفي والباء والكاف واللام...؛ وأن ولن وكي نواصب؛ ولم ولما جوازم."},{"question":"ما أمثلة حروف العطف؟","options":["الواو والفاء وثم وأو وبل ولا ولكن","من وعن وفي","هل وهمزة","لم ولن"],"answer":0,"explanation":"حروف العطف: الواو والفاء وثم وأو وبل ولا ولكن؛ تعطف الاسم على الاسم والفعل على الفعل."},{"question":"ما إعراب الحروف كلها؟","options":["مبنية لا محل لها من الإعراب","معربة","مرفوعة","منصوبة"],"answer":0,"explanation":"الحروف كلها مبنية: لا محل لها من الإعراب؛ توصف بعملها: حرف جر مبني، حرف نصب مبني..."}]},{"body":["تدريب التمييز الثلاثي: «على»: لا تقبل تنوينًا ولا لم → حرف جر. «علمٌ»: قبل التنوين → اسم. «علّمَ»: قبل تاء التأنيث → فعل ماضٍ. ثلاث كلمات من مادة واحدة (ع ل م) بثلاثة أنواع!","«في»: حرف جر. «فيلٌ»: اسم (قبل التنوين). «فازَ»: فعل. «فاء العطف»: حرف. نفس الأصوات تقريبًا وأنواع مختلفة: العلامات تحسم.","«هل» حرف استفهام: هل ذهبتَ؟ لا تقبل شيئًا. «همزة الاستفهام»: أذهبتَ؟ والفرق بينهما مذكور في الكتب المطولة؛ المهم: كلتاهما حرفان للاستفهام.","«ما» عسيرة: قد تكون نافية (ما جاء زيد)، أو شرطية جازمة (ما تدرس تفهم)، أو موصولة اسمية (أكرمتُ ما أحببت)، أو مصدرية (أعجبني ما صنعت). السياق يعين؛ وسيأتي لكل نوع بابه. لكن أصلها في كل ذلك: حرف... إلا الموصولة فاسم.","حروف زائدة: تزاد في الكلام للتوكيد: «ما جاءني من أحدٍ» ما زائدة، و«لا تسألْ عمّا...». والزائدة لا عمل لها: ما بعدها على إعرابه الأصلي.","الخلاصة العملية: ميّز الكلمة بترتيب: جرّب علامات الاسم الأربع؛ فإن رفضتها جرّب ضوابط الأفعال الثلاثة؛ فإن رفضتها فهي حرف. ومع الأيام تصير هذه المحاكمة عادة سريعة في لسانك."],"examples":["على / علمٌ / علّمَ: مادة واحدة ثلاثة أنواع","في حرف وفيلٌ اسم","هل وأ: حرفا استفهام","ما: نافية أو شرطية أو موصولة أو مصدرية","ما جاءني من أحد: ما زائدة","الترتيب: اسم؟ فعل؟ فحرف"],"questions":[{"question":"كيف تميز بين «على» و«علمٌ» و«علّمَ»؟","options":["بالعلامات: الأولى حرف والثانية اسم والثالثة فعل","كلها أسماء","كلها حروف","لا يمكن التمييز"],"answer":0,"explanation":"على رفضت العلامات فحرف جر؛ علم قبلت التنوين فاسم؛ علّم قبلت تاء التأنيث فماضٍ."},{"question":"«ما» في «ما تدرس تفهم» ما هي؟","options":["ما شرطية جازمة","ما نافية","ما زائدة","ما مصدرية"],"answer":0,"explanation":"تجزم فعلين (تدرس وتفهم) فهي شرطية؛ وما جاء زيد نافية؛ والسياق يعين على نوعها."},{"question":"ما حكم الحروف الزائدة؟","options":["لا عمل لها وما بعدها على إعرابه الأصلي","تجر دائمًا","تنصب دائمًا","تجزم دائمًا"],"answer":0,"explanation":"الزائدة للتوكيد لا تعمل: «ما جاءني من أحد» - «من» باقية جارة وما زائدة."},{"question":"ما الترتيب العملي لتمييز نوع الكلمة؟","options":["علامات الاسم ثم ضوابط الفعل فإن رفضتها فحرف","الحرف أولًا","الفعل أولًا","عشوائي"],"answer":0,"explanation":"جرّب علامات الاسم الأربع، فإن رفضتها جرّب ضوابط الأفعال الثلاثة، فإن رفضتها فهي حرف."},{"question":"«ألا» و«ها» و«أما» ما هي؟","options":["حروف تنبيه مبنية","أسماء إشارة","أفعال أمر","أدوات شرط"],"answer":0,"explanation":"حروف تنبيه تفتح بها الكلام لتنبيه السامع: ألا إن نصر الله قريب؛ وهي حروف مبنية."}]}]},{"id":"wahi-sharh-054","title":"النكرة والمعرفة وحصر المعارف الستة","section":"شرح الكتاب: أحكام الكلمة - باب المعرفة والنكرة مفصلًا","order":54,"segments":[{"body":["باب المعرفة والنكرة مفصلًا. الضابط الجامع: «النكرة ما قبل (أن) والمعرفة ما لم يقبلها».","جرب: «أن يكون رجلٌ كريمًا» - قبلت «رجل» أن فهي نكرة. ولا يصح: «أن يكون محمدٌ» بمعنى علمية محمد - فمحمد معرفة.","النكرة: اسم يدل على معنى غير معين: «رجل» أي رجل، «كتاب» أي كتاب. والمعرفة: اسم يدل على معين: «محمد» هذا الشخص، «الكتاب» هذا الكتاب المعهود.","حصر المعارف: ستة أنواع لا سابع لها، جمعها المؤلف في بيت: «وبثلها: آدمُ ورندٌ وهذا # والذي والقاهرةُ وذو الفتى». فككناه في المختصر، ونعيده هنا بحصر أدق:","١- الضمير (رموزه في البيت «آدم»): كل اسم يدل على متكلم أو مخاطب أو غائب: أنا، أنت، هو... ٢- العلم («رند»): كل اسم اختص بمسماه: محمد، القاهرة.","٣- اسم الإشارة («هذا»): ما أشير به إلى معين: هذا، هذه، هؤلاء... ٤- الاسم الموصول («الذي»): الذي، التي، الذين... ٥- المعرف بأل («القاهرة»... بل الرمز هنا لأل التي في مثل الرجل): كل اسم دخلته أل التعريفية. ٦- المضاف إلى معرفة («ذو الفتى»): كل اسم أضيف إلى معرفة: قلم محمد، كتابي.","كل اسم في العربية معرفة فهو من هذه الستة قطعًا؛ فإن لم تجده فيها فهو نكرة. هذا الحصر يجعل الحكم سريعًا: «كتابٌ» ليس ضميرًا ولا علمًا ولا إشارة ولا موصولًا ولا ذا أل ولا مضافًا → نكرة.","وسندرس كل نوع من الستة في درس: الضمائر درسان، والعلم درس، والإشارة والموصول وأل والمضاف درس."],"examples":["الضابط: النكرة تقبل أن","رجل نكرة ومحمد معرفة","بيت الحصر: آدم ورند وهذا والذي والقاهرة وذو الفتى","المعارف ستة لا سابع","كتابٌ: خارج الستة فنكرة","كل معرفة من الستة قطعًا"],"questions":[{"question":"ما ضابط النكرة العملي؟","options":["تقبل أن","تقبل أل","لا تقبل شيئًا","تقبل لم"],"answer":0,"explanation":"النكرة تقبل أن: أن يكون رجل كريمًا؛ والمعرفة لا تقبلها."},{"question":"كم عدد المعارف المحصورة؟","options":["ستة لا سابع لها","خمسة","عشرة","أربعة"],"answer":0,"explanation":"ستة: الضمير، العلم، اسم الإشارة، الاسم الموصول، المعرف بأل، المضاف إلى معرفة."},{"question":"ما رمز العلم في بيت الحصر؟","options":["رند","آدم","هذا","الذي"],"answer":0,"explanation":"آدم رمز الضمير، ورند رمز العلم، وهذا رمز الإشارة، والذي رمز الموصول، وأل في مثل القاهرة... والقاهرة للمعرف بأل، وذو الفتى للمضاف إلى معرفة."},{"question":"«قلم محمد» أي نوع من المعارف؟","options":["مضاف إلى معرفة","علم","معرف بأل","ضمير"],"answer":0,"explanation":"قلم نكرة أصلًا لكنه أضيف إلى محمد العلم المعرفة فصار معرفة بالإضافة: ذو الفتى في البيت رمزه."},{"question":"«كتابٌ» لماذا نكرة؟","options":["لأنه خارج المعارف الستة ويقبل أن","لأنه مبني","لأنه فعل","لأنه معرف بأل"],"answer":0,"explanation":"ليس ضميرًا ولا علمًا ولا إشارة ولا موصولًا ولا ذا أل ولا مضافًا إلى معرفة، ويقبل أن: فهو نكرة."}]},{"body":["تدريب سريع على الحصر: «هو»: ضمير → معرفة. «مصر»: علم → معرفة. «تلك»: إشارة → معرفة. «الذين»: موصول → معرفة. «البيتُ»: معرف بأل → معرفة. «مفتاحُ السيارةِ»: مضاف إلى معرفة → معرفة. «مفتاحٌ»: خارج الستة → نكرة.","تنبيه مهم: الإضافة إلى نكرة لا تعرف: «مفتاحُ سيارةٍ» نكرة؛ فالضابط: المضاف إلى «معرفة» فقط. مفتاح السيارة (معرفة) مقابل مفتاح سيارة (نكرة: أي مفتاح لأي سيارة).","تنبيه: أل في العلم كـ«الله» و«الرحمن» زائدة ملاصقة ليست من باب التعريف، لكن العلم معرفة بنفسه. وأل الجنسية في «الإنسان» (الجنس كله) تعريف أيضًا. فالمعرفة بأل نوعان: عهدية (الكتاب الذي ذكرناه) وجنسية (الإنسان كله).","النكرة نوعان في الاستعمال: مقصودة: «رأيت رجلًا» (رجل معين عندي) وغير مقصودة: «أحتاج كتابًا» (أي كتاب). وكلاهما نكرة إعرابًا وحكمًا.","لماذا هذا الحصر مهم؟ لأن كثيرًا من الأبواب تبنى عليه: خبر المبتدأ يشترط فيه أن لا يطابقه في التعريف (لا تقول: محمدٌ محمدٌ)، والنعت يتبع منعوته نكرة ومعرفة، ونداء المعرفة له أحكام...","الخلاصة: احفظ الستة حفظًا: ضمير، علم، إشارة، موصول، معرف بأل، مضاف إلى معرفة. وما عداها نكرة. ثم اقرن كل نوع بمثال واحد محفوظ: هو / محمد / هذا / الذي / الرجل / قلم محمد."],"examples":["هو ومصر وتلك والذين والبيت ومفتاح السيارة: معارف","مفتاحٌ ومفتاح سيارةٍ: نكرتان","الإضافة إلى نكرة لا تعرف","الله والرحمن: أل زائدة والعلم معرفة بنفسه","الإنسان: أل جنسية","احفظ مثالًا لكل نوع"],"questions":[{"question":"«مفتاح سيارةٍ» ما حكمه؟","options":["نكرة لأنه مضاف إلى نكرة","معرفة","علم","مبني"],"answer":0,"explanation":"الإضافة إلى نكرة لا تعرف: مفتاح سيارة أي مفتاح لأي سيارة؛ بخلاف مفتاح السيارة المعينة."},{"question":"«الله» و«الرحمن» ما حكم أل فيهما؟","options":["أل زائدة ملاصقة والعلم معرفة بنفسه","أل تعريفية","أل استغراقية","ليسا اسمين"],"answer":0,"explanation":"أل في أعلام مثل الله والرحمن زائدة لا تفيد التعريف بالعهد؛ والعلم معرفة بذاته."},{"question":"ما نوعا أل التعريفية؟","options":["عهدية وجنسية","زائدة فقط","للأسماء فقط","للأفعال"],"answer":0,"explanation":"عهدية: الكتاب المعهود بيننا؛ وجنسية: الإنسان بمعنى الجنس كله."},{"question":"لماذا يهم حصر المعارف في الأبواب القادمة؟","options":["لأن أحكام الخبر والنعت والنداء تبنى على التعريف والتنكير","لا أهمية","للحفظ فقط","للبيان فقط"],"answer":0,"explanation":"النعت يتبع منعوته تعريفًا وتنكيرًا، وخبر المبتدأ له شروط في التعريف؛ فالضبط هنا أساس لاحق."},{"question":"أي الأسماء التالية نكرة؟","options":["مدينةٌ","القاهرة","هذه","اللائي"],"answer":0,"explanation":"مدينة خارج الستة فنكرة؛ والقاهرة علم، وهذه إشارة، واللائي موصول - كلها معارف."}]}]},{"id":"wahi-sharh-055","title":"الضمائر المنفصلة: ضمائر الرفع والنصب","section":"شرح الكتاب: باب المعرفة والنكرة - الضمائر مفصلًا","order":55,"segments":[{"body":["الضمير: «كل اسم يدل على متكلم أو مخاطب أو غائب». سمي ضميرًا لأنه يُضمر (يخفى) في النفس فيغني عن ذكر الاسم الظاهر: بدل «محمد ذهب» تقول «هو ذهب».","الضمائر ضربان: منفصلة ومتصلة. المنفصلة: تقوم بنفسها كلمة مستقلة. والمتصلة: تلحق آخر الكلمة جزءًا منها. والمنفصلة نوعان: للرفع وللنصب.","الضمائر المنفصلة للرفع - ثلاثة أصول وفروعها: «أنا» للمتكلم مفردًا أو مع غيره، و«أنتَ» للمخاطب، و«هو» للغائب.","فروعها للمثنى والجمع والتأنيث: من «أنا»: «نحن» للمتكلمين. من «أنتَ»: «أنتِ» للمخاطبة، «أنتما» للمثنى (مذكرًا ومؤنثًا)، «أنتم» للجمع المذكر، «أنتنَّ» للجمع المؤنث. من «هو»: «هي» للغائبة، «هما» للمثنى، «هم» للجمع المذكر، «هنَّ» للجمع المؤنث.","إعرابها: تكون مبتدأ (هو قائمٌ) أو خبرًا (القائم هو) أو فاعلًا مستترًا... والمنفصل للرفع يستعمل حيث يحتاج الرفع مع التأكيد أو الفصل: «أنا الغنيُّ» لا يصح فيها التاء المتصلة.","الضمائر المنفصلة للنصب - ثلاثة أصول وفروعها: «إيايَ» للمتكلم، و«إياكَ» للمخاطب، و«إياهُ» للغائب. وفروعها: إيانا، إياكِ، إياكما، إياكم، إياكنَّ، إياها، إياهما، إياهم، إياهنَّ.","تستعمل منفصلة النصب مفعولًا به عند التقديم أو الحصر أو التوكيد: «إياكَ نعبدُ وإياكَ نستعينُ» (الفاتحة): قُدمت إياك على نعبد للحصر: لا نعبد سواك. ولو تأخرت لاتصلت: نعبدُك.","كلها معرفة ومبنية: لا يتغير آخرها بتغير موقعها: هو قائم، رأيت هو؟ لا: رأيتُه (متصل) أو رأيت إياهُ (منفصل ثابت البناء)."],"examples":["الضمير: اسم يدل على متكلم أو مخاطب أو غائب","منفصلة للرفع: أنا وأنت وهو وفروعها","نحن وأنتما وأنتم وأنتن وهي وهما وهم وهن","منفصلة للنصب: إياي وإياك وإياه","إياك نعبد: تقديم للحصر","كلها مبنية معرفة"],"questions":[{"question":"ما تعريف الضمير؟","options":["كل اسم يدل على متكلم أو مخاطب أو غائب","كل اسم مجرور","كل فعل ماض","كل حرف جر"],"answer":0,"explanation":"الضمير اسم معرفة يدل على معين بغير تسمية ظاهرة: أنا (متكلم) وأنت (مخاطب) وهو (غائب)."},{"question":"ما أصول الضمائر المنفصلة للرفع؟","options":["أنا وأنت وهو","إياي وإياك وإياه","تاء وواو وألف","هاء وياء وكاف"],"answer":0,"explanation":"ثلاثة أصول: أنا للمتكلم، وأنت للمخاطب، وهو للغائب؛ ومنها الفروع للتثنية والجمع والتأنيث."},{"question":"عدّ فروع «أنتَ»:","options":["أنتِ وأنتما وأنتم وأنتن","هما وهم وهن","إياك وإياكم","نحن وأنا"],"answer":0,"explanation":"أنتِ للمخاطبة، أنتما للمثنى، أنتم لجمع المذكر، أنتن لجمع المؤنث؛ وكلها منفصلة للرفع."},{"question":"ما أصول الضمائر المنفصلة للنصب؟","options":["إياي وإياك وإياه","أنا وأنت وهو","نا وكاف وهاء","تاء الفاعل"],"answer":0,"explanation":"إياي للمتكلم، إياك للمخاطب، إياه للغائب؛ وفروعها إيانا وإياكم وإياهم... تنصب مفعولًا به."},{"question":"لماذا قُدمت «إياك» في «إياك نعبد وإياك نستعين»؟","options":["للحصر: لا نعبد إلا الله","للزينة","خطأ","للسجع"],"answer":0,"explanation":"تقديم المفعول المنفصل على الفعل يفيد الحصر: العبادة والاستعانة مختصتان بالله وحده."}]},{"body":["تدريب إعرابي: «أنا طالبٌ»: أنا: ضمير منفصل مبني في محل رفع مبتدأ. طالب: خبر مرفوع بالضمة. «أنتم مجتهدون»: أنتم مبتدأ، مجتهدون خبر مرفوع بالواو (جمع مذكر سالم).","«إياكم نسألُ العونَ»: إياكم: ضمير منفصل مبني في محل نصب مفعول به مقدم. نسأل: فعل مضارع مرفوع والفاعل مستتر نحن. العون: مفعول به ثانٍ... بل العون مفعول به وإياكم متعلق بالسؤال... الأبسط: إياكم مفعول به مقدم للحصر.","متى يجب الانفصال؟ عند تقديم المفعول (إياك نعبد)، وعند العطف على الضمير (أكرمتك وإياه)، وعند التوكيد (رأيتك إياك)، وعند القصر (إياهم أقصد).","التأنيث في الضمائر: «هي» للغائبة، «أنتِ» للمخاطبة. والمثنى: «أنتما» و«هما» للمذكر والمؤنث على السواء (أنتما رجلان أو امرأتان). والجمع المؤنث: «أنتنَّ» و«هنَّ» ونونهما مفتوحة.","ملاحظة بنائية: هذه الضمائر مبنية على حركات مختلفة: «أنا» مبنية على السكون (الفتح على الألف محالة)، «أنتَ» مبنية على الفتح، «هو» مبنية على الضم (على الواو)، «إياك» على الفتح... والمبني لا يوصف بالرفع والنصب إلا بمحل: «في محل رفع».","الخلاصة: منفصلة الرفع: أنا وأنت وهو وفروعها التسعة... وتفيد الرفع مع الابتداء أو التوكيد. ومنفصلة النصب: إياي وإياك وإياه وفروعها، وتستعمل للحصر والتوكيد والعطف. وكلها مبنية معرفة."],"examples":["أنا طالب: مبتدأ وخبر","أنتم مجتهدون: خبر جمع مذكر سالم","إياكم نسأل: مفعول مقدم","أكرمتك وإياه: عطف يوجب الانفصال","أنتما وهما: للمذكر والمؤنث","أنتن وهن: نون مفتوحة"],"questions":[{"question":"أعرب «أنا» في «أنا طالب»:","options":["ضمير منفصل مبني في محل رفع مبتدأ","فاعل","مفعول به","حرف"],"answer":0,"explanation":"أنا ضمير منفصل مبني على السكون في محل رفع مبتدأ؛ وطالب خبر مرفوع بالضمة."},{"question":"متى يجب استعمال الضمير المنفصل للنصب؟","options":["عند التقديم للحصر أو العطف أو التوكيد","في كل موضع","مع الفاعل","مع المبتدأ"],"answer":0,"explanation":"يُفصل عند تقديم المفعول (إياك نعبد)، والعطف على متصل (أكرمتك وإياه)، والتوكيد (رأيتك إياك)."},{"question":"«أنتما» لمن تستعمل؟","options":["للمثنى مذكرًا كان أو مؤنثًا","للمذكر فقط","للمؤنث فقط","للجمع"],"answer":0,"explanation":"أنتما للمثنى مطلقًا: تقول للرجلين والمرأتين: أنتما؛ وكذلك هما للغائبين والغائبتين."},{"question":"لماذا يقال «مبني في محل رفع» ولا يقال «مرفوع» للضمير؟","options":["لأن المبني لا تتغير صورته فالإعراب محلي لا لفظي","لأنه فعل","لأنه حرف","لا سبب"],"answer":0,"explanation":"الضمير آخره ثابت لا يتغير بالموقع؛ فالرفع فيه معنوي محلي: مبني في محل رفع."},{"question":"«أنتنَّ» نونها:","options":["مفتوحة","ساكنة","محذوفة","مكسورة"],"answer":0,"explanation":"نون أنتن وهن مفتوحة: أنتنَّ وهنَّ؛ بخلاف نون النسوة الساكنة في الأفعال: كتبنَ."}]}]},{"id":"wahi-sharh-056","title":"الضمائر المتصلة: «تواني» و«هيك» و«نا»","section":"شرح الكتاب: الضمائر المتصلة مفصلًا","order":56,"segments":[{"body":["الضمائر المتصلة تسعة، مجموعة في كلمتين سهلتين: خمسة للرفع مجموعة في «تَوَانِي»: تاء الفاعل، واو الجماعة، ألف الاثنين، نون النسوة، ياء المخاطبة.","تاء الفاعل: تاء متحركة تدل على فاعل مفرد متكلم أو مخاطب: كتبتُ (أنا)، كتبتَ (أنت)، كتبتِ (أنتِ). إياك أن تخلطها بتاء التأنيث الساكنة (كتبتْ فاطمة) فتلك للدلالة على تأنيث الفاعل الظاهر لا ضمير.","واو الجماعة: واو تدل على فاعلين فأكثر ذكورًا: كتبوا، يكتبون. وألف الاثنين: تدل على فاعلين اثنين: كتبا، يكتبان. ونون النسوة: تدل على فاعلات: كتبْنَ، يكتبْنَ. وياء المخاطبة: تدل على فاعلة مخاطبة في المضارع: تكتبينَ، وفي الأمر: اكتبي.","أربعة للنصب والجر مجموعة في «هَيْكَ» - هيك: هاء الغائب، ياء المتكلم، كاف المخاطب (بالإضافة إلى نا المتكلمين التي للأحوال الثلاثة).","هاء الغائب: كتبتُه (نصبًا)، مررتُ به (جرًا)؛ وفروعه هما وهم وهن: رأيتهم، سلمت عليهن. ياء المتكلم: كتابي (جر بالإضافة)، أكرمني (نصبًا). كاف المخاطب: كتابك (جر)، أكرمك (نصب)؛ وفروعها كما وكم وكن.","نا المتكلمين: للرفع والنصب والجر معًا: كتبنا (رفعًا: فاعل)، أكرمنا (نصبًا: مفعول)، كتابنا (جرًا: مضاف إليه). واحدة بثلاثة أحوال!","كل المتصلة مبنية: تلحق الأفعال والأسماء والحروف: فعلًا (كتبنا)، اسمًا (كتابنا)، حرفًا (لنا، عنها). ولا تنفصل أبدًا؛ فإن احتجت الفصل استعملت المنفصلة: إياك."],"examples":["تواني: خمسة للرفع","تاء الفاعل: كتبتُ كتبتَ كتبتِ","واو الجماعة وألف الاثنين ونون النسوة وياء المخاطبة","هيك: هاء وياء وكاف للنصب والجر","نا للأحوال الثلاثة: كتبنا أكرمنا كتابنا","متصلة لا تنفصل أبدًا"],"questions":[{"question":"كم عدد الضمائر المتصلة وكيف جمعت؟","options":["تسعة: خمسة للرفع في «تواني» وأربعة للنصب والجر في «هيك» مع نا","خمسة فقط","ثلاثة","عشرون"],"answer":0,"explanation":"تسعة: تواني (تاء، واو، ألف، نون، ياء) للرفع، وهيك (هاء، ياء، كاف) للنصب والجر، ونا للثلاثة."},{"question":"ما الفرق بين تاء الفاعل وتاء التأنيث الساكنة؟","options":["تاء الفاعل متحركة ضمير وتاء التأنيث ساكنة علامة تأنيث الفاعل الظاهر","لا فرق","الأولى للمؤنث","الثانية ضمير"],"answer":0,"explanation":"كتبتُ: التاء المتحركة ضمير فاعل (أنا)؛ كتبتْ فاطمة: التاء الساكنة علامة أن الفاعل مؤنث ظاهر، وليست ضميرًا."},{"question":"«يكتبْنَ» ما نونها؟","options":["نون النسوة ضمير رفع للفاعلات","نون التوكيد","نون الرفع","تنوين"],"answer":0,"explanation":"نون النسوة الساكنة ضمير متصل في محل رفع فاعل يدل على جماعة الإناث: يكتبنَ وكتبنَ."},{"question":"«نا» لأي الأحوال تستعمل؟","options":["للرفع والنصب والجر معًا","للرفع فقط","للجر فقط","للنصب فقط"],"answer":0,"explanation":"نا للأحوال الثلاثة: فاعل (كتبنا)، مفعول (أكرمنا)، مضاف إليه (كتابنا)؛ إعرابها بحسب موقعها."},{"question":"«كتابي» ما إعراب الياء؟","options":["ضمير متصل مبني في محل جر مضاف إليه","فاعل","حرف جر","تنوين"],"answer":0,"explanation":"ياء المتكلم من «هيك» للنصب والجر؛ هنا متصلة باسم فهي في محل جر بالإضافة: كتابي = كتاب + ياء."}]},{"body":["تدريب إعرابي شامل: «أكرمتُهم وسلّمتُ عليهم»: أكرمت: فعل ماض، التاء ضمير متصل في محل رفع فاعل. هم: ضمير متصل (هاء الغائب للجمع) في محل نصب مفعول به. عليهم: على حرف جر، هم مضاف إليه في محل جر.","«كتابُكَ جديدٌ»: كتاب: مبتدأ مرفوع بالضمة. كاف المخاطب: ضمير متصل مبني في محل جر مضاف إليه. جديد: خبر مرفوع.","«يدرسنَ الدرسَ»: يدرسن: فعل مضارع مرفوع، ونون النسوة ضمير متصل في محل رفع فاعل. الدرس: مفعول به منصوب. لاحظ: الفعل المضارع مع نون النسوة مبني على السكون (يدرسنَ) كما سيأتي في باب البناء.","«اذهبوا إلى المسجدِ»: اذهبوا: فعل أمر مبني على حذف النون، وواو الجماعة ضمير متصل في محل رفع فاعل. إلى: حرف جر. المسجد: مجرور بأل.","متى تحذف نون الأفعال الخمسة ومتى تثبت؟ تثبت في الرفع (يكتبون) وتحذف في النصب والجزم (لن يكتبوا، لم يكتبوا). والنون هنا ليست من تواني؛ بل علامة إعراب؛ الواو هي الضمير.","الخلاصة: احفظ تواني للرفع (تاء، واو، ألف، نون نسوة، ياء مخاطبة) وهيك للنصب والجر (هاء، ياء متكلم، كاف مخاطب) ونا للثلاثة. وميّز علامات الإعراب من الضمائر: الواو ضمير والنون علامة في يكتبون."],"examples":["أكرمتُهم: تاء رفعًا وهم نصبًا","عليهم: جار ومجرور بضمير","كتابك جديد: كاف مضاف إليه","يدرسنَ الدرس: نون النسوة فاعل","اذهبوا: واو الجماعة فاعل","يكتبون: الواو ضمير والنون علامة"],"questions":[{"question":"أعرب التاء في «أكرمتُهم»:","options":["ضمير متصل مبني في محل رفع فاعل","تاء تأنيث ساكنة","مفعول به","حرف"],"answer":0,"explanation":"التاء المتحركة تاء الفاعل: ضمير متصل للمتكلم مبني في محل رفع فاعل."},{"question":"أعرب «هم» في «سلمت عليهم»:","options":["ضمير متصل مبني في محل جر مضاف إليه","فاعل","مبتدأ","حرف جر"],"answer":0,"explanation":"هم من هاء الغائب وفروعها؛ جاءت بعد حرف الجر على: مبنية في محل جر مضاف إليه... بل اسم مجرور بعلى."},{"question":"في «يكتبون» ما الضمير وما العلامة؟","options":["الواو ضمير فاعل والنون علامة رفع","النون ضمير والواو علامة","كلتاهما ضمير","كلتاهما علامة"],"answer":0,"explanation":"واو الجماعة من تواني ضمير فاعل؛ والنون علامة رفع الأفعال الخمسة تثبت في الرفع وتحذف في النصب والجزم."},{"question":"أعرب نون «يدرسنَ»:","options":["ضمير متصل في محل رفع فاعل (نون النسوة)","علامة رفع","نون توكيد","حرف"],"answer":0,"explanation":"نون النسوة من تواني: ضمير للفاعلات في محل رفع فاعل؛ والفعل معها مبني على السكون."},{"question":"أعرب كاف «كتابُكَ»:","options":["ضمير متصل مبني في محل جر مضاف إليه","فاعل","مفعول به","خبر"],"answer":0,"explanation":"كاف المخاطب من هيك متصلة باسم: كتاب مبتدأ مرفوع والكاف مضاف إليه في محل جر، وجديد خبر."}]}]},{"id":"wahi-sharh-057","title":"العلم: تعريفه وأمثلته وأنواعه الثلاثة","section":"شرح الكتاب: باب المعرفة والنكرة - العلم مفصلًا","order":57,"segments":[{"body":["العلم: «كل اسم اختص بمسماه». أي: وضع ليدل على معين بعينه لا يشاركه فيه غيره بالحقيقة: محمد هذا الشخص، مكة هذه البلدة.","أمثلة العلم التي أحصاها المؤلف: أسماء الله تعالى: الله، الرحمن، العليم... وأسماء الملائكة: جبريل، ميكائيل... وأسماء الناس: محمد، فاطمة... وأسماء البلدان: مكة، المدينة، القاهرة، دمشق... وأسماء الكواكب: الزهرة، المشتري... وأسماء الشهور والأيام: رمضان، شعبان، الجمعة، السبت...","العلم معرفة بنفسه وإن لم تدخله أل؛ وأل التي في بعضه زائدة: «الله» ألها زائدة ملاصقة لا تعريفية؛ و«الرحمن» كذلك.","أنواع العلم ثلاثة: ١- الاسم العلم: ما سمي به من يوم وضع: محمد، خديجة. ٢- اللقب العلم: ما لُقب به بعد كمال صفة فيه: الصديق (لأبي بكر لشدة تصديقه)، الفاروق (لعمر لفرقانه بين الحق والباطل)، ذو النورين (لعثمان).","٣- الكنية العلم: ما صدر بأب أو أم: أبو بكر، أبو حفص (عمر)، أم كلثوم. والكنية تكون بغير الأب أيضًا: أبو الطيب للمتنبي... وقد تكون الكنية على الابن: أبو محمد لمن له ابن اسمُه محمد، وقد تكون لقبًا بلا ولد: أبو بكر لا ولد له اسمُه بكر.","الفرق بين اللقب والكنية: اللقب وصف غالِب (الصديق)، والكنية مصدرة بأب أو أم (أبو بكر). وكلاهما علم إذا اشتهرا واختصا بالمسمى.","حكم العلم: معرفة مبني؟ لا: العلم معرب غالبًا (محمدُ محمدٍ محمدٍ بحسب موقعه) إلا ما كان منه معجبًا أو مركبًا تركيب مزجي كحضرموت وبعلبك فممنوع من الصرف... وسيأتي الممنوع في بابه."],"examples":["العلم: اسم اختص بمسماه","أسماء الله والملائكة والناس","البلدان والكواكب والشهور والأيام","أنواعه: اسم ولقب وكنية","الصديق والفاروق: لقبان","أبو بكر وأم كلثوم: كنيتان"],"questions":[{"question":"ما تعريف العلم؟","options":["كل اسم اختص بمسماه","كل اسم يقبل أن","كل ما قبل التنوين","كل فعل"],"answer":0,"explanation":"العلم وضع لمعين بعينه: محمد لذلك الشخص، مكة لتلك البلدة؛ لا يقع على غيره بالحقيقة."},{"question":"عدّ من أمثلة الأعلام:","options":["أسماء الله والملائكة والناس والبلدان والكواكب والشهور والأيام","الضمائر فقط","الحروف","الأفعال"],"answer":0,"explanation":"أحصى المؤلف: أسماء الله (الرحمن)، الملائكة (جبريل)، الناس (محمد)، البلدان (مكة)، الكواكب (الزهرة)، الشهور والأيام (رمضان والجمعة)."},{"question":"ما أنواع العلم الثلاثة؟","options":["الاسم العلم واللقب العلم والكنية العلم","مذكر ومؤنث","مفرد وجمع","نكرة ومعرفة"],"answer":0,"explanation":"اسم علم (محمد)، ولقب علم (الصديق)، وكنية علم (أبو بكر)؛ كلها معارف تختص بمسمياتها."},{"question":"ما الفرق بين اللقب والكنية؟","options":["اللقب وصف غالب والكنية مصدرة بأب أو أم","لا فرق","اللقب للنساء","الكنية وصف"],"answer":0,"explanation":"الصديق لقب لشدة التصديق؛ وأبو بكر كنية مصدرة بأب وإن لم يكن له ولد اسمُه بكر."},{"question":"ما حكم أل في «الله» و«الرحمن»؟","options":["زائدة ملاصقة لا تعريفية والعلم معرفة بنفسه","عهدية","جنسية","ليست أل"],"answer":0,"explanation":"أل في أعلام كالله والرحمن زائدة؛ والعلم معرفة بذاته لا يحتاج أل للتعريف."}]},{"body":["تدريب: «مكةُ المكرمةُ بلدةٌ عظيمةٌ»: مكة: مبتدأ علم مرفوع بالضمة. المكرمة: نعت مرفوع. بلدة: خبر مرفوع. عظيمة: نعت للخبر. مكة علم معرفة بنفسه رغم عدم دخول أل عليه.","«الصديقُ أولُ الخلفاءِ»: الصديق مبتدأ لقب علم؛ أول خبر مضاف؛ الخلفاء مضاف إليه. اللقب هنا اشتهر حتى صار كالاسم الأصلي.","«قرأتُ ديوانَ أبي الطيبِ»: أبو الطيب كنية المتنبي، وهي علم لشهرتها به؛ وتركيبها إضافي (أبو + الطيب) فيجر الثاني ويبنى الأول... التركيب الإضافي يعرب كإضافة عادية.","تمييز العلم من اسم الجنس: «رجل» جنس يقع على كل رجل؛ «زيد» علم يختص بواحد. وقد ينتقل الاسم من جنس إلى علم بالتسمية: سميتَ ابنك «نجاحًا» فصار علمًا.","من فوائد باب العلم: معرفة الممنوع من الصرف: العلم الأعجمي (إبراهيم، يوسف) والمؤنث بالتاء المربوطة أو الألف المقصورة (فاطمة، زينبَ؟ زينب بلا تاء... بل فاطمة ومريم) والمركب المزجي (بعلبك) يمنع من الصرف: يجر بالفتحة. وسيأتي مفصلًا.","الخلاصة: العلم اسم مختص بمسماه، معرفة بذاته، أمثلته أسماء الله والملائكة والناس والبلدان والكواكب والشهور والأيام، وأنواعه: اسم ولقب وكنية، وكثير منه معرب وبعضه ممنوع من الصرف."],"examples":["مكة المكرمة بلدة عظيمة: علم مبتدأ","الصديق أول الخلفاء: لقب","ديوان أبي الطيب: كنية المتنبي","زيد علم ورجل جنس","إبراهيم وبعلبك: ممنوعان من الصرف","فاطمة: ممنوع للتأنيث"],"questions":[{"question":"أعرب «مكة» في «مكة المكرمة بلدة عظيمة»:","options":["مبتدأ مرفوع بالضمة وهو علم","خبر","نعت","مفعول به"],"answer":0,"explanation":"مكة مبتدأ مرفوع بالضمة، علم معرفة بذاته؛ المكرمة نعت، بلدة خبر، عظيمة نعت الخبر."},{"question":"«أبو الطيب» في «ديوان أبي الطيب»:","options":["كنية علم مجرورة بالإضافة","لقب","نكرة","ضمير"],"answer":0,"explanation":"كنية المتنبي مصدرة بأب؛ تركيبها إضافي: أبو مضاف مجرور بالكسرة... والطيب مضاف إليه."},{"question":"متى ينتقل اسم الجنس إلى علم؟","options":["إذا سُمي به معين","لا ينتقل","بالتنوين","بأل"],"answer":0,"explanation":"من سمى ابنه «نجاحًا» صار نجاح علمًا لذلك الشخص بعد أن كان جنسًا؛ التسمية تنقله."},{"question":"أي الأعلام التالية ممنوع من الصرف؟","options":["إبراهيم وبعلبك وفاطمة","محمد","زيد","مكة"],"answer":0,"explanation":"إبراهيم علم أعجمي، وبعلبك مركب مزجي، وفاطمة مؤنث بالتاء؛ كلها ممنوعة من الصرف تجر بالفتحة."},{"question":"«ذو النورين» أي نوع من الأعلام؟","options":["لقب علم لعثمان رضي الله عنه","كنية","اسم علم أولي","نكرة"],"answer":0,"explanation":"ذو النورين لقب عثمان لتزوجه ابنتي النبي ﷺ؛ واللقب العلم ما غلب على المسمى من وصف."}]}]},{"id":"wahi-sharh-058","title":"أسماء الإشارة والأسماء الموصولة والمعرف بأل والمضاف إلى معرفة","section":"شرح الكتاب: باب المعرفة والنكرة - بقية المعارف مفصلًا","order":58,"segments":[{"body":["المعرفة الثالثة: اسم الإشارة، وهي محصورة: «هذا» للمفرد المذكر القريب، «هذه» للمفردة المؤنثة، «هذان» للمثنى المذكر، «هاتان» للمثنى المؤنث، «هؤلاء» للجمع مطلقًا، و«هنا» و«ثَمَّ» للمكان.","وللبعيد تزاد أل والكاف أو تطول الألف: «ذلك» للمفرد البعيد، «تلك»، «أولئك» للجمع. و«ذاك» ولغات. كلها معرفة؛ وأكثرها مبني إلا المثنى (هذان وهاتان) فمعرب بالألف والياء.","المعرفة الرابعة: الاسم الموصول، وهي محصورة: «الذي» للمفرد المذكر، «التي» للمفردة المؤنثة، «اللذان» للمثنى المذكر، «اللتان» للمثنى المؤنث، «الذين» للجمع المذكر، «اللائي» و«اللاتي» و«اللواتي» للجمع المؤنث. ويلحق بها «من» للعاقل و«ما» لغيره و«أيّ». وسميت موصولة لأنها لا تتم إلا بجملة بعدها تسمى صلة الموصول: «الذي نجحَ مجتهدٌ».","المعرفة الخامسة: المعرف بأل: كل اسم دخلته أل التعريفية: الرجل، الشجرة. فائدة: «إذا حذفت أل عاد الاسم إلى التنكير»: الرجل → رجل (نكرة). بخلاف أل الزائدة في الأعلام: الله، الرحمن - لا يصح حذفها.","فائدة من الكتاب: «المدينة» اسم جنس (أي مدينة معرفة بأل) وقد تصير علمًا لطيبة الطيبة؛ فالسياق يحدد: سكنتُ المدينةَ (إن عنيت مدينة رسول الله ﷺ فعلم).","المعرفة السادسة: المضاف إلى معرفة: كل اسم أضيف إلى معرفة صار معرفة: «قلمي» (مضاف إلى ياء المتكلم الضمير)، «قلم محمد» (إلى علم)، «قلم الطالب» (إلى معرف بأل)، «قلم هذا» (إلى إشارة)، «قلم الذي أحبه» (إلى موصول).","وأمثلتها من البيت السابق: «ذو الفتى»: ذو مضاف إلى الفتى المعرف بأل. تذكر: الإضافة إلى نكرة لا تعرف: قلم طالبٍ نكرة."],"examples":["هذا وهذه وهؤلاء وهنا وثم: إشارة","ذلك وتلك وأولئك: للبعيد","الذي والتي واللذان والذين واللائي: موصولات","الرجل: معرف بأل","حذف أل يعيد التنكير","قلم محمد: مضاف إلى معرفة"],"questions":[{"question":"عدّ أسماء الإشارة المحصورة:","options":["هذا وهذه وهذان وهاتان وهؤلاء وهنا وثم","الذي والتي","أنا وأنت","من وما"],"answer":0,"explanation":"أسماء الإشارة: هذا وهذه للمفرد، هذان وهاتان للمثنى، هؤلاء للجمع، وهنا وثم للمكان؛ وللبعيد ذلك وتلك وأولئك."},{"question":"أي أسماء الإشارة معرب؟","options":["المثنى: هذان وهاتان","هذا","هذه","هؤلاء"],"answer":0,"explanation":"كل أسماء الإشارة مبنية إلا المثنى هذان وهاتان فمعربان بالألف للرفع والياء للنصب والجر."},{"question":"لماذا سميت الموصولات موصولة؟","options":["لأنها لا تتم إلا بجملة صلة بعدها","لطولها","لكثرتها","لا سبب"],"answer":0,"explanation":"الذي لا يتم معناه إلا بصلة: الذي نجح؛ فسميت موصولة لاتصالها بجملة تتممها."},{"question":"ما فائدة قاعدة «حذف أل»؟","options":["التمييز بين أل التعريفية والزائدة","الزينة","الحذف مطلقًا","لا فائدة"],"answer":0,"explanation":"إن حذفت أل فعاد الاسم نكرة فهي تعريفية (الرجل → رجل)؛ وإن لم يصح الحذف فزائدة (الله والرحمن)."},{"question":"«قلم الذي أحبه» ما نوع معرفته؟","options":["مضاف إلى معرفة (موصول)","معرف بأل","علم","نكرة"],"answer":0,"explanation":"قلم أضيف إلى الذي الموصول المعرفة فصار معرفة بالإضافة؛ ولو أضيف إلى نكرة لبقي نكرة."}]},{"body":["تدريب: «هذا الكتابُ نافعٌ»: هذا: اسم إشارة مبني على السكون في محل رفع مبتدأ. الكتاب: نعت... بل بدل أو عطف بيان مرفوع (الأرجح بدل لأن الإشارة تختص بمعرفة). نافع: خبر مرفوع.","«الذين آمنوا»: الذين: اسم موصول مبني على الفتح... في محل رفع (مبتدأ أو نعت بحسب السياق). آمنوا: فعل ماض والواو فاعل؛ والجملة صلة الموصول لا محل لها من الإعراب.","«مررت بالرجلِ»: الرجل: اسم مجرور بالكسرة معرف بأل. لو حذفت أل قلت: مررت برجلٍ - نكرة؛ فأل هنا تعريفية.","«أولئك الفتيةُ»: أولئك اسم إشارة مبني في محل رفع مبتدأ للجمع البعيد؛ الفتية بدل أو نعت مرفوع.","الفرق بين اسم الإشارة والموصول: الإشارة تدل على محسوس تشير إليه بيدك: هذا قلم. والموصول يدل على معين بصفة في الصلة: الذي نجح. والإشارة أشهرها مبنية، والموصولات كلها مبنية.","الخلاصة: أربع معارف في هذا الدرس: الإشارة (هذا وأخواته)، الموصول (الذي وأخواته)، المعرف بأل (حذفها يعيد التنكير)، والمضاف إلى معرفة (قلمي وقلم محمد). وبه تمام المعارف الستة."],"examples":["هذا الكتاب نافع: إشارة مبتدأ","الذين آمنوا: موصول وصلة","مررت بالرجل: معرف بأل مجرور","أولئك الفتية: إشارة للجمع البعيد","الإشارة للمحسوس والموصول بصفة","قلمي: مضاف إلى ضمير"],"questions":[{"question":"أعرب «هذا» في «هذا الكتاب نافع»:","options":["اسم إشارة مبني في محل رفع مبتدأ","نعت","خبر","حرف"],"answer":0,"explanation":"هذا اسم إشارة مبني على السكون في محل رفع مبتدأ؛ والكتاب بدل منه مرفوع؛ ونافع خبر."},{"question":"ما حكم جملة صلة الموصول؟","options":["لا محل لها من الإعراب","في محل رفع","في محل نصب","في محل جر"],"answer":0,"explanation":"جملة الصلة متممة للموصول لا محل لها من الإعراب: الذي نجح - نجح صلة."},{"question":"ما الفرق بين اسم الإشارة والاسم الموصول؟","options":["الإشارة تدل على محسوس والموصول على معين بصفة في صلته","لا فرق","الموصول للبعيد","الإشارة معربة كلها"],"answer":0,"explanation":"هذا قلم: إشارة لمحسوس؛ الذي نجح: موصول دل على معين بجملة الصلة."},{"question":"«المدينة» قد تكون علمًا متى؟","options":["إذا أريدت بها طيبة مدينة النبي ﷺ","دائمًا علم","أبدًا لا تكون","إذا حذفت أل"],"answer":0,"explanation":"المدينة اسم جنس معرف بأل؛ وإذا أطلقت على طيبة خاصة صارت علمًا لها؛ والسياق يحدد."},{"question":"«قلمي» لماذا معرفة؟","options":["لأنه مضاف إلى ضمير معرفة","لأنه علم","لأنه معرف بأل","لأنه موصول"],"answer":0,"explanation":"الياء ضمير متصل معرفة؛ والمضاف إلى معرفة معرفة: قلمي = قلم + ياء المتكلم."}]}]},{"id":"wahi-sharh-059","title":"باب المعرب والمبني: التعريف والحصر وبناء الحروف","section":"شرح الكتاب: أحكام الكلمة - باب المعرب والمبني مفصلًا","order":59,"segments":[{"body":["الباب الثالث من أحكام الكلمة: المعرب والمبني. المعرب: «ما تغير آخرها بتغير إعرابها». المبني: «ما لزم آخرها حالة واحدة».","مثال المعرب: «محمد» في ثلاثة مواضع: جاء محمدُ (مرفوع بالضمة)، رأيت محمدًا (منصوب بالفتحة)، مررت بمحمدٍ (مجرور بالكسرة). الاسم واحد وآخره يتغير بحسب موقعه: هذا هو الإعراب.","مثال المبني: «هؤلاء» لزمت الكسر: جاء هؤلاءِ، رأيت هؤلاءِ، مررت بهؤلاءِ - لا تتغير مهما تغير موقعها. فهي مبنية على الكسر.","قاعدة الحصر الجامعة: «الحروف كلها مبنية، والأفعال الماضية وأفعال الأمر كلها مبنية؛ والأسماء والأفعال المضارعة: بعضها معرب وبعضها مبني».","فثلاثة أصناف مبنية بالكلية: الحروف (من وعن وهل...)، والماضي (كتبَ)، والأمر (اكتبْ). وصنفان فيهما الوجهان: الأسماء (أكثرها معرب، وعشرة أنواع مبنية) والمضارع (معرب غالبًا، مبني إذا اتصلت به نون النسوة أو نون التوكيد).","بناء الحروف: الحروف كلها مبنية على حركات أواخرها: مبني على السكون: منْ، عنْ، لنْ، لمْ، هلْ، نعمْ. مبني على الفتح: سوفَ، ثمَ، الواوُ للعطف، همزة الاستفهام. مبني على الكسر: لام الجحود ولام الأمر. ومبني على الضم: حتى (حتُّو في لغة).","علة بناء الحروف: لأنها كثيرة الاستعمال خفيفة، ولا تعلق لها بالعوامل، فاقتضى الأصل فيها الثبات.","فائدة عملية: المبني لا إعراب لفظي له؛ فإذا أعربته قلت: «مبني على كذا في محل كذا»: هو: مبني في محل رفع مبتدأ. والمعرب يوصف بإعرابه اللفظي: مرفوع بالضمة."],"examples":["المعرب: يتغير آخره بالإعراب","محمدُ محمدَ محمدٍ: معرب","هؤلاء: مبنية على الكسر","الحروف والماضي والأمر: مبنية كلها","الأسماء والمضارع: بعض معرب وبعض مبني","سكون وفتح وكسر وضم: أواخر الحروف"],"questions":[{"question":"ما تعريف المعرب والمبني؟","options":["المعرب يتغير آخره بالإعراب والمبني يلزم حالة واحدة","المعرب ثابت","المبني متغير","لا فرق"],"answer":0,"explanation":"المعرب: ما تغير آخرها بتغير إعرابها (محمدُ محمدَ محمدٍ)؛ والمبني: ما لزم آخرها حالة واحدة (هؤلاء)."},{"question":"ما الأصناف المبنية كلها؟","options":["الحروف والأفعال الماضية وأفعال الأمر","الأسماء كلها","المضارع كله","الموصولات فقط"],"answer":0,"explanation":"ثلاثة: الحروف كلها، والماضي كله، والأمر كله؛ أما الأسماء والمضارع فبعضها معرب وبعضها مبني."},{"question":"على ما تبنى الحروف؟","options":["على حركات أواخرها: سكون أو فتح أو كسر أو ضم","على الرفع","على النصب","لا تبنى"],"answer":0,"explanation":"الحروف مبنية على حركات: سكون (من وهل)، فتح (سوف وثم)، كسر (لام الجحود)، ضم (حتى في لغة)."},{"question":"كيف تعرب «هو» في «هو قائم»؟","options":["ضمير مبني في محل رفع مبتدأ","مرفوع بالضمة","منصوب","حرف"],"answer":0,"explanation":"المبني لا إعراب لفظي له: هو مبني في محل رفع مبتدأ؛ فالإعراب فيه محلي لا لفظي."},{"question":"لماذا بنيت الحروف؟","options":["لكثرة استعمالها وخفتها وعدم تعلقها بالعوامل","للزينة","لا علة","لطولها"],"answer":0,"explanation":"الحروف كثيرة الدوران خفيفة ولا يتعلق بها عامل؛ فاقتضى الأصل ثباتها على حالة واحدة."}]},{"body":["تدريب التمييز: «كتبَ»: فعل ماض مبني على الفتح. «اكتبْ»: فعل أمر مبني على السكون. «يكتبُ»: مضارع معرب (يكتبُ يكتبَ يكتبْ). «عنْ»: حرف مبني على السكون. «كتابٌ»: اسم معرب. «هذا»: اسم مبني.","المبني على السكون من الحروف: من عن لم لن هل نعم بلى. والمبني على الفتح: سوف ثم إذن الواو الفاء أو بل لولا همزة الاستفهام. والمبني على الكسر: لام الجحود ولام الأمر (لتفعلنَّ؟ لام الأمر تكسر).","تنبيه: المبني على السكون يسكن آخره دائمًا وإن وصلته بما بعده: «من جاءَ»؛ فإن التقى ساكنان فتح: «منِ الذي...» في بعض الاستعمالات... الأصل السكون.","فائدة: معرفة المبني توفر عليك عناء الإعراب: لا تبحث عن رفع ونصب في «هل» و«من»؛ قل: حرف مبني لا محل له من الإعراب. وتبحث عن المحل للمبني من الأسماء: ضمائر وإشارات وموصولات.","الأسماء المبنية عشرة أنواع ستأتي في الدرس القادم بتفصيلها: الضمائر كلها، وأسماء الإشارة سوى المثنى، والأسماء الموصولة، وأسماء الشرط والاستفهام والأفعال والأصوات...","الخلاصة: ثلاثة أصناف مبنية بالكلية: الحروف والماضي والأمر. وصنفان مشتركان: الأسماء والمضارع. والمبني على حركات أواخره، والمعرب تتبدل أواخره بالعوامل."],"examples":["كتبَ مبني على الفتح","اكتبْ مبني على السكون","يكتب: معرب بثلاث حركات","هل ومن: مبنيان لا محل لهما","هذا ونحن والذي: أسماء مبنية","المبني يوصف بالمحل"],"questions":[{"question":"صنف: «كتبَ» و«يكتبُ» و«عنْ»:","options":["ماض مبني ومضارع معرب وحرف مبني","كلها معربة","كلها مبنية","أسماء"],"answer":0,"explanation":"كتب ماض مبني على الفتح؛ يكتب مضارع معرب؛ عن حرف مبني على السكون."},{"question":"أي الحروف مبنية على الكسر؟","options":["لام الجحود ولام الأمر","من وعن","سوف وثم","هل"],"answer":0,"explanation":"لام الجحود ولام الأمر مبنيتان على الكسر؛ ومن وعن وهل على السكون؛ وسوف وثم على الفتح."},{"question":"هل للحروف محل من الإعراب؟","options":["لا؛ توصف بعملها فقط: حرف جر مبني","نعم مرفوعة","نعم منصوبة","أحيانًا"],"answer":0,"explanation":"الحروف مبنية لا محل لها من الإعراب؛ توصف بعملها: حرف جر، حرف نصب، حرف استفهام."},{"question":"ما فائدة معرفة المبني عمليًا؟","options":["توفير البحث عن إعراب لفظي والاكتفاء بالمحل","لا فائدة","للحفظ فقط","للزينة"],"answer":0,"explanation":"المبني لا تتغير صورته؛ فلا تبحث عن ضمة وفتحة فيه؛ بل تقول: مبني على كذا في محل كذا (للأسماء) أو لا محل له (للحروف)."},{"question":"كم نوعًا من الأسماء مبني؟","options":["عشرة أنواع ستفصل","ثلاثة","عشرون","لا شيء"],"answer":0,"explanation":"عشرة: الضمائر كلها، أسماء الإشارة سوى المثنى، الموصولات، أسماء الشرط والاستفهام والأفعال والأصوات والمركبات... وستأتي مفصلة."}]}]},{"id":"wahi-sharh-060","title":"بناء الأفعال: الماضي والأمر والمضارع","section":"شرح الكتاب: باب المعرب والمبني - بناء الأفعال مفصلًا","order":60,"segments":[{"body":["بناء الفعل الماضي: الماضي مبني كله، على ثلاث حالات: ١- على الفتح الظاهر: كتبَ، ذهبَ، علمَ. ٢- على الفتح المقدر: ما آخره ألف: دعا، رمى (الأصل رمَيَ)... أي ماضٍ آخره ألف فمبني على الفتح المقدر على الألف للتعذر.","٣- على الضم: إذا اتصلت به واو الجماعة: سجدوا - بني على الضم لاتصاله بواو الجماعة. ٤- وعلى السكون: إذا اتصل به ضمير رفع متحرك: تاء الفاعل (سجدتُ)، نا المتكلمين (سجدنا)، نون النسوة (سجدنَ) - مبني على السكون لاتصاله بضمير رفع متحرك.","بناء فعل الأمر: «يبنى على مثل حالة مضارعه في الجزم»: لأن الأمر فرع المضارع (اسجدْ من تسجد). فما يجزم بحذف النون يبنى أمره على حذفها: اسجدوا، اسجدا، اسجدي (الأفعال الخمسة).","وما يجزم بحذف حرف العلة يبنى أمره على حذفه: ادعُ (من تدعو)، اقضِ (من تقضي)، اخشَ (من تخشى). وما يجزم بالسكون يبنى أمره على السكون: اسجدْ، أكرمْ، انطلقْ.","وإن اتصلت به نون التوكيد بني على الفتح: اسجدنَّ. فبناء الأمر أربع حالات: حذف النون، حذف حرف العلة، الفتح مع نون التوكيد، والسكون فيما سوى ذلك.","المضارع: معرب في الأصل: يكتبُ يكتبَ يكتبْ. إلا في موضعين فيبنى: ١- إذا اتصلت به نون النسوة بني على السكون: يذهبنَ. ٢- إذا اتصلت به نون التوكيد بني على الفتح: لتسجدنَّ.","خلاصة البناء في الأفعال: الماضي: فتح ظاهر أو مقدر أو ضم أو سكون. الأمر: سكون أو حذف نون أو حذف علة أو فتح مع النون. المضارع: معرب إلا مع النونين (النسوة والتوكيد)."],"examples":["كتبَ: ماض مبني على الفتح","دعا: مبني على فتح مقدر","سجدوا: مبني على الضم","سجدتُ وسجدنا وسجدنَ: مبني على السكون","ادعُ اقضِ اخشَ: أمر بحذف العلة","يذهبنَ ولتسجدنَّ: مضارع مبني"],"questions":[{"question":"على ما يبنى الماضي إذا اتصلت به واو الجماعة؟","options":["على الضم","على الفتح","على السكون","على الكسر"],"answer":0,"explanation":"سجدوا: ماض مبني على الضم لاتصاله بواو الجماعة؛ والواو ضمير فاعل."},{"question":"متى يبنى الماضي على السكون؟","options":["إذا اتصل به ضمير رفع متحرك","إذا اتصلت به أل","إذا كان معتلًا","أبدًا"],"answer":0,"explanation":"مع تاء الفاعل (سجدتُ) ونا (سجدنا) ونون النسوة (سجدنَ): مبني على السكون لاتصاله بضمير رفع متحرك."},{"question":"ما ضابط بناء فعل الأمر؟","options":["يبنى على مثل حالة مضارعه في الجزم","على الفتح دائمًا","على السكون دائمًا","على الضم دائمًا"],"answer":0,"explanation":"الأمر فرع المضارع: ما جزم مضارعه بحذف النون بني على حذفها (اسجدوا)، وبحذف العلة (ادع)، وبالسكون (اسجد)."},{"question":"«ادعُ» على ما بني؟","options":["على حذف حرف العلة","على السكون","على الفتح","على حذف النون"],"answer":0,"explanation":"ادع أمر من يدعو معتل الآخر؛ جزم مضارعه بحذف العلة فبني الأمر على حذفها: ادعُ واقضِ واخشَ."},{"question":"متى يبنى المضارع؟","options":["إذا اتصلت به نون النسوة أو نون التوكيد","دائمًا معرب","دائمًا مبني","مع واو الجماعة"],"answer":0,"explanation":"مع نون النسوة يبنى على السكون (يذهبنَ) ومع نون التوكيد على الفتح (لتسجدنَّ)؛ وما عدا ذلك معرب."}]},{"body":["تدريب: «كتبتُ الدرسَ»: كتب: فعل ماض مبني على السكون لاتصاله بتاء الفاعل. التاء: ضمير متصل في محل رفع فاعل. الدرس: مفعول به منصوب.","«دعا المؤمنُ ربَّه»: دعا: ماض مبني على الفتح المقدر على الألف للتعذر. المؤمن: فاعل مرفوع. رب: مفعول به منصوب والهاء مضاف إليه.","«صلّوا في المسجدِ»: صلّوا: فعل أمر مبني على حذف النون (لأنه من الأفعال الخمسة: مضارعه يصلون). الواو: ضمير متصل في محل رفع فاعل. في المسجد: جار ومجرور.","«اكتبنَّ الدرسَ»: اكتبنَّ: فعل أمر مبني على الفتح لاتصاله بنون التوكيد الثقيلة؛ والنون حرف لا محل له. الدرس: مفعول به.","«المؤمناتُ يتعاونَّ على الخيرِ»: يتعاون: فعل مضارع مبني على السكون لاتصاله بنون النسوة؛ والنون ضمير متصل في محل رفع فاعل. المؤمنات: مبتدأ مرفوع بالضمة (جمع مؤنث سالم).","الخلاصة الجامعة لباب المعرب والمبني: المبني من الأفعال: الماضي والأمر كلهما، والمضارع مع النونين. والمعرب: المضارع فيما سوى ذلك. وبهذا تمت أحكام الكلمة مفصلة، وندخل بعدها على الأسماء المبنية العشرة ثم أحكام الكلام المفصلة."],"examples":["كتبتُ: مبني على السكون","دعا: فتح مقدر","صلوا: أمر بحذف النون","اكتبنَّ: أمر مبني على الفتح مع التوكيد","يتعاونَّ: مضارع مبني على السكون","النونان: نسوة وتوكيد"],"questions":[{"question":"أعرب «كتب» في «كتبتُ الدرسَ»:","options":["فعل ماض مبني على السكون لاتصاله بتاء الفاعل","مرفوع","مبني على الفتح","مضارع"],"answer":0,"explanation":"اتصلت به تاء الفاعل المتحركة فبني على السكون؛ والتاء ضمير متصل في محل رفع فاعل."},{"question":"«دعا» على ما بني ولماذا؟","options":["على الفتح المقدر على الألف للتعذر","على السكون","على الضم","على الفتح الظاهر"],"answer":0,"explanation":"آخره ألف؛ والحركات لا تظهر على الألف فتقدر: مبني على الفتح المقدر للتعذر."},{"question":"أعرب «صلوا» في «صلوا في المسجد»:","options":["فعل أمر مبني على حذف النون","مضارع مرفوع","ماض مبني على الضم","مبني على السكون"],"answer":0,"explanation":"أمر من الأفعال الخمسة (يصلون) بني على حذف النون؛ والواو ضمير متصل في محل رفع فاعل."},{"question":"أعرب «يتعاون» في «المؤمنات يتعاونَّ»:","options":["فعل مضارع مبني على السكون لاتصاله بنون النسوة","مرفوع بالضمة","ماض","أمر"],"answer":0,"explanation":"اتصلت به نون النسوة فبني على السكون؛ والنون ضمير فاعل؛ والمؤمنات مبتدأ مرفوع."},{"question":"متى يبنى الأمر على الفتح؟","options":["إذا اتصلت به نون التوكيد","مع واو الجماعة","مع تاء الفاعل","دائمًا"],"answer":0,"explanation":"اسجدنَّ: بني الأمر على الفتح لاتصال نون التوكيد؛ ومع النسوة... الأمر لا تتصل به نون النسوة إلا في ضمن الأفعال الخمسة."}]}]},{"id":"wahi-sharh-061","title":"الأسماء المبنية العشرة (١): أسماء الإشارة والموصولات","section":"شرح الكتاب: باب المعرب والمبني - الأسماء المبنية مفصلًا","order":61,"segments":[{"body":["انتهينا من بناء الأفعال، ونأتي الآن إلى الأسماء المبنية، وهي عشرة أنواع محصورة. نبدأ بالنوعين الأولين: أسماء الإشارة وأسماء الوصل.","النوع الأول: أسماء الإشارة سوى المثنى: «هذا» مبني على السكون: جاء هذا، وأكرمتُ هذا، ومررتُ بهذا - لا يتغير. و«هذه» مبنية على الكسر: جاءت هذه، وأكرمتُ هذه، ومررتُ بهذه.","و«هؤلاء» و«ذلك» و«تلك» و«أولئك» كلها مبنية كذلك. أما المثنى (هذان وهاتان) فمعربان إعراب المثنى: يرفعان بالألف وينصبان ويجران بالياء: جاء هذان، وأكرمت هذين، ومررت بهذين.","النوع الثاني: الأسماء الموصولة سوى المثنى: «الذي» مبني على السكون: جاء الذي عندك، وأكرمت الذي عندك، ومررت بالذي عندك. و«الذين» مبني على الفتح: جاء الذين عندك، وأكرمت الذين عندك، ومررت بالذين عندك.","و«التي» و«اللائي» و«اللاتي» و«اللواتي» كلها مبنية. أما المثنى (اللذان واللتان) فمعربان إعراب المثنى: جاء اللذان يدرسان، وأكرمت اللذين، ومررت باللذين.","القاعدة الجامعة: أسماء الإشارة والموصولات كلها مبنية، إلا المثنى منها فمعرب: يرفع بالألف وينصب ويجر بالياء. واسم الاستفهام «أيّ» واسم الشرط «أيّ» معربان بالحركات الأصلية: أيُّ رجلٍ عندك؟ (رفع بالضمة)، وأيَّ رجلٍ أكرمتَ؟ (نصب بالفتحة)، وبأيِّ رجلٍ مررتَ؟ (جر بالكسرة)."],"examples":["هذا: مبني على السكون","هذه: مبنية على الكسر","هذان وهذين: معربان إعراب المثنى","الذي: مبني على السكون","الذين: مبني على الفتح","أيُّ وأيَّ وأيِّ: معربة بالحركات"],"questions":[{"question":"ما حكم أسماء الإشارة من حيث البناء؟","options":["كلها مبنية إلا المثنى فمعرب","كلها معربة","كلها مبنية بلا استثناء","المفرد فقط مبني"],"answer":0,"explanation":"هذا وهذه وهؤلاء وذلك... كلها مبنية؛ إلا هذان وهاتان فمعربان إعراب المثنى بالألف والياء."},{"question":"«هذه» على ما بنيت؟","options":["على الكسر","على السكون","على الفتح","على الضم"],"answer":0,"explanation":"جاءت هذه وأكرمت هذه ومررت بهذه: هذه مبنية على الكسر في الأحوال الثلاثة."},{"question":"«الذين» على ما بني؟","options":["على الفتح","على السكون","على الكسر","على الضم"],"answer":0,"explanation":"الذين اسم موصول مبني على الفتح في الرفع والنصب والجر: جاء الذين ومررت بالذين."},{"question":"ما إعراب «هذين» في «مررت بهذين»؟","options":["اسم إشارة مبني في محل جر بالياء (إعراب المثنى)","مبني على الكسر","منصوب بالفتحة","مرفوع بالضمة"],"answer":0,"explanation":"هذان وهاتان معربان إعراب المثنى: يرفعان بالألف وينصبان ويجران بالياء؛ فهنا في محل جر بالياء."},{"question":"ما حكم «أيّ» الاستفهامية؟","options":["معربة بالحركات الأصلية","مبنية على السكون","مبنية على الفتح","ممنوعة من الصرف"],"answer":0,"explanation":"أيّ معربة: ترفع بالضمة (أيُّ رجل) وتنصب بالفتحة (أيَّ رجل) وتجر بالكسرة (بأيِّ رجل)."}]},{"body":["تدريب: «هذا مسجدٌ»: هذا: اسم إشارة مبني على السكون في محل رفع مبتدأ. مسجد: خبر مرفوع بالضمة.","«إن الذين آمنوا»: الذين: اسم موصول مبني على الفتح في محل نصب اسم إن. آمنوا: فعل ماض والواو فاعل، والجملة صلة الموصول لا محل لها.","«أكرمت اللذين نجحا»: اللذين: اسم موصول معرب إعراب المثنى في محل نصب بالياء مفعول به. نجحا: فعل ماض والألف فاعل، والجملة صلة.","لماذا استثني المثنى من البناء؟ لأنه كثير الاستعمال وله علامته الخاصة (الألف والياء) فأجري مجرى المعربات؛ أما المفرد والجمع من الإشارات والموصولات فثابتة الصورة.","فائدة: المبني من الإشارات والموصولات يعرب بالمحل: «هذا» في محل رفع (مبتدأ أو فاعل)، و«الذي» في محل نصب أو جر بحسب موقعه. فلا تبحث عن حركة متغيرة لن تجدها.","الخلاصة: النوعان الأولان من الأسماء المبنية: أسماء الإشارة سوى المثنى، والأسماء الموصولة سوى المثنى؛ والمثنى منها معرب بالألف والياء؛ و«أيّ» معربة بالحركات الأصلية في الاستفهام والشرط."],"examples":["هذا مسجد: مبتدأ مبني في محل رفع","إن الذين آمنوا: موصول في محل نصب","أكرمت اللذين نجحا: مثنى موصول بالياء","المثنى له علامته الخاصة","المبني يعرب بالمحل","أيّ في الاستفهام والشرط معربة"],"questions":[{"question":"أعرب «هذا» في «هذا مسجد»:","options":["اسم إشارة مبني على السكون في محل رفع مبتدأ","خبر مرفوع","حرف","فعل"],"answer":0,"explanation":"هذا مبني على السكون في محل رفع مبتدأ؛ ومسجد خبر مرفوع بالضمة."},{"question":"أعرب «الذين» في «إن الذين آمنوا»:","options":["اسم موصول مبني على الفتح في محل نصب اسم إن","مرفوع بالواو","فاعل","نعت"],"answer":0,"explanation":"الذين مبني على الفتح؛ دخلت عليه إن فهو في محل نصب اسمها؛ وآمنوا صلة لا محل لها."},{"question":"ما حكم جملة صلة الموصول؟","options":["لا محل لها من الإعراب","في محل رفع","في محل نصب","في محل جر"],"answer":0,"explanation":"جملة الصلة تتمم الموصول ولا محل لها من الإعراب: الذي نجح - نجح صلة."},{"question":"لماذا أُعرب المثنى من الإشارات والموصولات؟","options":["لكثرة استعماله وعلامته الخاصة الألف والياء","للزينة","لا سبب","لأنه حرف"],"answer":0,"explanation":"المثنى له علامته الخاصة فأجري مجرى المعربات: يرفع بالألف وينصب ويجر بالياء."},{"question":"أعرب «أيَّ» في «أيَّ رجل أكرمت؟»:","options":["اسم استفهام معرب منصوب بالفتحة","مبني على السكون","مرفوع","حرف استفهام"],"answer":0,"explanation":"أيّ معربة بالحركات الأصلية؛ هنا منصوبة بالفتحة وهي مضاف، ورجل مضاف إليه مجرور."}]}]},{"id":"wahi-sharh-062","title":"الأسماء المبنية العشرة (٢): أسماء الشرط والاستفهام وأسماء الأفعال","section":"شرح الكتاب: الأسماء المبنية مفصلًا","order":62,"segments":[{"body":["النوع الثالث والرابع: أسماء الشرط وأسماء الاستفهام عدا «أيّ»: «من وما ومهما ومتى وأين وكيفما وحيثما» كلها مبنية.","«من»: اسم شرط مبني على السكون: من يجتهد ينجح، ومن تكرم أكرمك، وعلى من تُدلِ تدلل. و«أين»: اسم شرط مبني على الفتح: أين تسكن أسكن، وإلى أين تذهب أذهب.","و«أيّ» في الشرط معربة كما تقدم: أيُّ طالبٍ يجتهد ينجح (مرفوع)، وأيَّ رجلٍ تكرم أكرمت (منصوب)، وعلى أيِّ رجلٍ تدل تدلل (مجرور).","النوع الخامس: أسماء الأفعال، وهي أسماء سماعية: ألفاظها أسماء ومعناها معنى الفعل. سماعية أي: تؤخذ عن العرب سماعًا لا قياسًا. وهي ثلاثة أنواع بحسب المعنى:","١- بمعنى فعل الأمر وهي الأكثر: «صَهْ»: اسم فعل أمر مبني على السكون بمعنى اسكت. و«آمينَ»: اسم فعل أمر مبني على الفتح بمعنى استجب. و«حَيَّ»: مبني على الفتح بمعنى أقبِل. و«هيَّا»: مبني على السكون بمعنى أسرِع. و«وكمْ»: مبني على السكون بمعنى دعْ.","٢- بمعنى الفعل الماضي: «مَيْهاتَ»: اسم فعل ماضٍ مبني على الفتح بمعنى بعُد. و«شَتانَ»: مبني على الفتح بمعنى افترق: شتان ما يدعون (أي: افترق).","٣- بمعنى الفعل المضارع: «أَفٍّ»: اسم فعل مضارع مبني على الكسر بمعنى أتضجر. و«وَيْ»: مبني على السكون بمعنى أتعجب."],"examples":["من: مبنية على السكون","أين: مبنية على الفتح","أيّ الشرطية: معربة","صه: اسم فعل أمر بمعنى اسكت","ميهات وشتان: بمعنى الماضي","أفٍّ ووي: بمعنى المضارع"],"questions":[{"question":"ما حكم أسماء الشرط عدا أيّ؟","options":["مبنية","معربة","مرفوعة","أفعال"],"answer":0,"explanation":"من وما ومهما ومتى وأين وكيفما وحيثما كلها أسماء شرط مبنية؛ وحدها أيّ معربة بالحركات."},{"question":"«أين» على ما بنيت؟","options":["على الفتح","على السكون","على الكسر","على الضم"],"answer":0,"explanation":"أين اسم شرط مبني على الفتح: أين تسكن أسكن؛ وإلى أين تذهب أذهب."},{"question":"ما أسماء الأفعال؟","options":["أسماء سماعية ألفاظها أسماء ومعناها معنى الفعل","أفعال ماضية","حروف جر","مصادر"],"answer":0,"explanation":"أسماء سماعية تؤخذ عن العرب: لفظها اسم ومعناها فعل؛ ثلاثة أنواع: أمر وماضٍ ومضارع."},{"question":"«آمين» ما هي وما معناها؟","options":["اسم فعل أمر مبني على الفتح بمعنى استجب","دعاء ختامي فقط بلا إعراب","فعل ماض","حرف"],"answer":0,"explanation":"آمين اسم فعل أمر مبني على الفتح بمعنى استجب؛ تقولها بعد الدعاء طلبًا للإجابة."},{"question":"«أفٍّ» في قوله تعالى «فلا تقل لهما أفٍّ» ما هي؟","options":["اسم فعل مضارع مبني على الكسر بمعنى أتضجر","حرف نفي","فعل أمر","اسم صوت"],"answer":0,"explanation":"أفٍّ اسم فعل مضارع مبني على الكسر بمعنى أتضجر؛ والنهي عنها نهي عن أدنى التضجر."}]},{"body":["تدريب: «من يزرع يحصد»: من: اسم شرط جازم مبني على السكون في محل رفع مبتدأ... الأدق عند المفصلين: في محل رفع على الابتداء. يزرع: فعل الشرط مجزوم بالسكون. يحصد: جواب الشرط مجزوم بالسكون.","«أين تقرأ تستفد»: أين: اسم شرط مبني على الفتح في محل نصب ظرف مكان. تقرأ: فعل الشرط مجزوم. تستفد: جواب الشرط مجزوم.","«صهْ يا ولد»: صه: اسم فعل أمر مبني على السكون لا محل له من الإعراب بمعنى اسكت. يا: حرف نداء. ولد: منادى.","«شتان ما يدعون»: شتان: اسم فعل ماضٍ مبني على الفتح بمعنى افترق، وهو مبتدأ... يعرب: مبتدأ مبني في محل رفع، وما مصدرية، وجملة يدعون في محل جر بالإضافة إلى المصدر المؤول.","تنبيه: أسماء الأفعال ليست أفعالًا حقيقة؛ فلا تتصرف (لا ماضي ولا مضارع لها) ولا تقبل ضوابط الأفعال؛ لكنها تقوم مقام الفعل في المعنى، وتعمل عمله أحيانًا: هيهاتَ العلمُ بلا عملٍ (هيهات رفعت الاسم بعدها فاعلًا).","الخلاصة: أسماء الشرط والاستفهام مبنية إلا أيّ، وأسماء الأفعال سماعية ثلاثة أنواع: بمعنى الأمر (صه وآمين وحيَّ وهيا) وبمعنى الماضي (ميهات وشتان) وبمعنى المضارع (أفٍّ ووي)."],"examples":["من يزرع يحصد: شرط كامل","أين تقرأ تستفد: أين ظرفية","صه يا ولد: اسم فعل أمر","شتان ما يدعون: بمعنى افترق","هيهات العلم بلا عمل: رفعت ما بعدها","أسماء الأفعال لا تتصرف"],"questions":[{"question":"أعرب «من» في «من يزرع يحصد»:","options":["اسم شرط جازم مبني على السكون في محل رفع","حرف شرط","فاعل","مفعول به"],"answer":0,"explanation":"من اسم شرط جازم مبني على السكون؛ يزرع فعل الشرط ويحصد جوابه وكلاهما مجزوم."},{"question":"أعرب «أين» في «أين تقرأ تستفد»:","options":["اسم شرط مبني على الفتح في محل نصب ظرف مكان","مبني على السكون","حرف جر","فعل"],"answer":0,"explanation":"أين للمكان مبنية على الفتح، محلها النصب على الظرفية؛ تقرأ فعل الشرط وتستفد جوابه."},{"question":"أعرب «صهْ» في «صه يا ولد»:","options":["اسم فعل أمر مبني على السكون لا محل له من الإعراب","فعل أمر مجزوم","حرف نداء","منادى"],"answer":0,"explanation":"صه اسم فعل أمر بمعنى اسكت مبني على السكون؛ وأسماء الأفعال لا محل لها من الإعراب كالأفعال."},{"question":"كيف عرفنا أن أسماء الأفعال ليست أفعالًا؟","options":["لأنها لا تتصرف ولا تقبل ضوابط الأفعال","لأنها تقبل التنوين دائمًا","لا دليل","لأنها حروف"],"answer":0,"explanation":"لا يتصرف منها ماضٍ ولا مضارع ولا أمر، ولا تقبل لم ولا تاء التأنيث؛ فهي أسماء بمعنى الأفعال."},{"question":"«هيهات» في «هيهات العلم بلا عمل» عملت عمل:","options":["الفعل الماضي فرفعت فاعلًا","حرف الجر","الناصب","الجازم"],"answer":0,"explanation":"هيهات بمعنى بعُد؛ قامت مقام الفعل الماضي فرفعت «العلم» فاعلًا؛ ولهذا سميت اسم فعل."}]}]},{"id":"wahi-sharh-063","title":"الأسماء المبنية العشرة (٣): العلم المختوم بـ«ويه» والأعداد والظروف المركبة","section":"شرح الكتاب: الأسماء المبنية مفصلًا - الخلاصة","order":63,"segments":[{"body":["النوع السادس: العلم المختوم بـ«ويه»: يبنى على الكسر، ويكون في الرجال نحو: سيبويه وخليلويه ونفطويه وعمرويه، وفي النساء نحو: هندويه وجمارويه. تقول: جاء سيبويه، وأكرمت سيبويه، ومررت بسيبويه - فيلزم الكسر في الرفع والنصب والجر.","النوع السابع: الأعداد المركبة أي: «أحد عشر» إلى «تسعة عشر»: تبنى على فتح الجزأين: جاء أحدَ عشرَ، وأكرمتُ أحدَ عشرَ رجلًا، وسلمت على أحدَ عشرَ رجلًا. فالجزءان مفتوحان في كل الأحوال.","إلا «اثنا عشر» فمعرب إعراب المثنى: جاء اثنا عشر رجلًا، وأكرمت اثني عشر رجلًا، ومررت باثني عشر رجلًا. (اثنا) معرب إعراب المثنى و(عشر) مبني على الفتح.","النوع الثامن: الظروف المركبة وتبنى على فتح الجزأين: «ليلةَ لئلٍّ نهارَ»: ظرف زمان مبني على فتح الجزأين. و«انتظرت صباحَ مساءَ»: ظرف زمان مبني على فتح الجزأين.","النوع التاسع: بعض الظروف المفردة: «إذا» و«إذْ» يبنيان على السكون. و«الآنَ» تبنى على الفتح. و«حيثُ» تبنى على الضم: آنئك إذا صلعت الشمس... اجلس حيث يجلس أخوك (حيث: ظرف مكان مبني على الضم).","النوع العاشر: «عُدْ» و«من حيثُ جئت»... وأمثالها من الأسماء السماعية المبنية. وبهذا تمت الأسماء المبنية العشرة.","ثم خلاصة المعربات: الكلمات من حيث كونها معربة أو مبنية قسمان: ١- المبنية كلها: الحروف والأفعال الماضية وأفعال الأمر. ٢- ما بعضها معرب وبعضها مبني: الأسماء والأفعال المضارعة."],"examples":["سيبويه: علم مبني على الكسر","أحدَ عشرَ: مبني على فتح الجزأين","اثنا عشر: معرب إعراب المثنى","صباحَ مساءَ: ظرف مركب","إذا وإذ على السكون، الآن على الفتح، حيث على الضم","المبنية كلها: الحروف والماضي والأمر"],"questions":[{"question":"العلم المختوم بـ«ويه» ما حكمه؟","options":["مبني على الكسر في الأحوال الثلاث","معرب","مبني على الفتح","ممنوع من الصرف"],"answer":0,"explanation":"سيبويه ونفطويه وهندويه: أعلام مختومة بويه تبنى على الكسر رفعًا ونصبًا وجرًا."},{"question":"«أحد عشر» كيف يبنى؟","options":["على فتح الجزأين في كل الأحوال","إعراب المثنى","على السكون","معرب بالحركات"],"answer":0,"explanation":"الأعداد المركبة من أحد عشر إلى تسعة عشر مبنية على فتح الجزأين؛ إلا اثنا عشر فمعرب إعراب المثنى."},{"question":"ما إعراب «اثني عشر» في «أكرمت اثني عشر رجلًا»؟","options":["عدد مركب معرب إعراب المثنى منصوب بالياء","مبني على فتح الجزأين","مبني على السكون","ممنوع"],"answer":0,"explanation":"اثنا معرب إعراب المثنى (يرفع بالألف وينصب ويجر بالياء) وعشر مبني على الفتح."},{"question":"«حيث» على ما بنيت؟","options":["على الضم","على السكون","على الفتح","على الكسر"],"answer":0,"explanation":"حيث ظرف مكان مبني على الضم: اجلس حيث يجلس أخوك؛ وإذا وإذ على السكون، والآن على الفتح."},{"question":"ما خلاصة المعرب والمبني في الكلمات؟","options":["الحروف والماضي والأمر مبنية كلها، والأسماء والمضارع بعضها معرب وبعضها مبني","كل الكلمات معربة","كلها مبنية","الأسماء كلها معربة"],"answer":0,"explanation":"قسمان: مبني بالكلية: الحروف والماضي والأمر؛ ومختلط: الأسماء والمضارع بعضها معرب وبعضها مبني."}]},{"body":["فائدة عزيزة من الكتاب - الفروق بين المعرب والمبني في المصطلح: ١- مصطلحات الحكم الإعرابي: المعرب يقال فيه: مرفوع ومنصوب ومجرور ومجزوم. والمبني إذا دخله حكم إعرابي يقال فيه: في محل رفع، في محل نصب، في محل جر، في محل جزم.","٢- مصطلحات أسماء الحركات: المعرب حركاته أسماء مؤنثة: ضمَّة وفتحة وكسرة وسكون. والمبني حركاته أسماء مجردة: ضمٌّ وفتحٌ وكسرٌ وسكون. تقول: مبني على الضم لا على الضمة.","تدريب: «هؤلاء إخوتك»: هؤلاء: اسم إشارة مبني على الكسر في محل رفع مبتدأ. إخوتك: خبر مرفوع بالضمة وهو مضاف، والكاف مضاف إليه.","«رأيت أحدَ عشرَ كوكبًا»: أحد عشر: عدد مركب مبني على فتح الجزأين في محل نصب مفعول به. كوكبًا: تمييز منصوب.","«سلمت على سيبويه»: سيبويه: اسم مبني على الكسر في محل جر بحرف الجر.","الخلاصة العامة للباب كله: المبني ثابت الصورة يوصف ببنائه (مبني على كذا) وبمحله إن كان اسمًا؛ والمعرب متغير الصورة يوصف بإعرابه وعلامته. واحفظ أن المبني من الأسماء عشرة أنواع درسناها كلها."],"examples":["المعرب: مرفوع منصوب مجرور مجزوم","المبني: في محل رفع ونصب وجر وجزم","ضمة فتحة كسرة للمعرب، وضم فتح كسر للمبني","رأيت أحد عشر كوكبا: مبني في محل نصب","سلمت على سيبويه: مبني في محل جر","المبني من الأسماء عشرة أنواع"],"questions":[{"question":"ما الفرق في المصطلح بين إعراب المعرب والمبني؟","options":["المعرب: مرفوع بالضمة؛ والمبني: في محل رفع مبني على كذا","لا فرق","المبني مرفوع","المعرب مبني"],"answer":0,"explanation":"المعرب يتغير لفظه فيوصف بإعرابه اللفظي؛ والمبني ثابت فيوصف بمحله: في محل رفع مبني على السكون."},{"question":"ما أسماء حركات المبني؟","options":["ضم وفتح وكسر وسكون (مجردة)","ضمة وفتحة وكسرة","رفع ونصب","لا حركات له"],"answer":0,"explanation":"حركات المعرب مؤنثة: ضمة وفتحة وكسرة؛ والمبني مجردة: ضم وفتح وكسر؛ تقول: مبني على الضم."},{"question":"أعرب «أحدَ عشرَ» في «رأيت أحد عشر كوكبًا»:","options":["عدد مركب مبني على فتح الجزأين في محل نصب مفعول به","مثنى بالياء","ممنوع من الصرف","فاعل"],"answer":0,"explanation":"الأعداد المركبة مبنية على فتح الجزأين؛ هنا في محل نصب مفعول به، وكوكبًا تمييز."},{"question":"أعرب «سيبويه» في «سلمت على سيبويه»:","options":["اسم مبني على الكسر في محل جر بحرف الجر","مجرور بالكسرة","مرفوع","فاعل"],"answer":0,"explanation":"سيبويه علم مختوم بويه مبني على الكسر؛ هنا في محل جر بحرف الجر على."},{"question":"أي الكلمات مبنية بالكلية؟","options":["الحروف والأفعال الماضية وأفعال الأمر","الأسماء","المضارعات","الأعلام"],"answer":0,"explanation":"ثلاثة أصناف مبنية بالكلية: الحروف والماضي والأمر؛ والأسماء والمضارع فيهما الوجهان."}]}]},{"id":"wahi-sharh-064","title":"الأحكام الإعرابية الأربعة وعلى من تدخل","section":"شرح الكتاب: فصل في الأحكام الإعرابية","order":64,"segments":[{"body":["فصل في الأحكام الإعرابية. الأحكام الإعرابية أربعة: ١- الرفع. ٢- والنصب. ٣- والجر (ويسمى الخفض). ٤- والجزم.","السؤال المهم: أتدخل هذه الأحكام على جميع الكلمات أم على بعضها؟ الجواب: تدخل على بعضها لا عليها كلها.","والسؤال الأهم: على من تدخل؟ الجواب: «تدخل على جميع الأسماء والأفعال المضارعة، معربة كانت أم مبنية؛ ولا تدخل على الحروف والفعل الماضي وفعل الأمر».","فالأسماء المعربة والمبنية يدخلها الرفع أو النصب أو الجر: محمدٌ (رفع)، يكرم محمدًا (نصب)، بحفادة... بل مررت بمحمدٍ (جر). وهذا (رفع)، يكرم هذا (نصب)، الذي (جر)... يعني: المعرب والمبني من الأسماء كلاهما يدخله الحكم، لكن المعرب يتغير لفظه والمبني يثبت ويكون الحكم محلًّا.","وكل الأفعال المضارعة المعربة والمبنية يدخلها رفع أو نصب أو جزم: أجتهدُ (رفع)، ولم أهملْ (جزم)، ولن أهملَ (نصب). وكذلك المضارع المبني: لا تلعبْ ولا تلعبنَّ.","أما الحروف والأفعال الماضية وأفعال الأمر فلا يدخلها حكم إعرابي؛ لأنها لا تُسبق بما يرفعها أو ينصبها أو يجرها أو يجزمها؛ ولذلك ليس لها حكم إعرابي: لا رفع ولا نصب ولا جر ولا جزم.","وقال الحريري في ملحة الإعراب يجمع ذلك: «ورفع ونصب بلا تمايع كذلِك الجزم للمضارع... والجر يختص بالأسماء والجر بالفعل بلا انتهاء»... المعنى: الرفع والنصب والجزم للمضارع والأسماء، والجر يختص بالأسماء."],"examples":["الأحكام الأربعة: رفع ونصب وجر وجزم","تدخل على الأسماء والمضارعات فقط","معربة كانت أم مبنية","لا تدخل على الحروف والماضي والأمر","الجر يختص بالأسماء","الجزم يختص بالمضارع"],"questions":[{"question":"ما الأحكام الإعرابية الأربعة؟","options":["الرفع والنصب والجر والجزم","الفتح والضم فقط","البناء والإعراب","الرسم والإملاء"],"answer":0,"explanation":"أربعة: الرفع، والنصب، والجر (ويسمى الخفض)، والجزم؛ وعليها يدور الإعراب كله."},{"question":"على من تدخل الأحكام الإعرابية؟","options":["على جميع الأسماء والأفعال المضارعة معربة كانت أم مبنية","على كل الكلمات","على الحروف فقط","على الماضي فقط"],"answer":0,"explanation":"تدخل على الأسماء والمضارعات كلها (معربة ومبنية)؛ ولا تدخل على الحروف والماضي والأمر."},{"question":"كيف يدخل الحكم على الاسم المبني؟","options":["يدخله محلًّا دون تغير في اللفظ","يغير آخره","لا يدخله","يحذف آخره"],"answer":0,"explanation":"المبني يثبت لفظه والحكم يكون في المحل: هذا فاعل مبني في محل رفع؛ بخلاف المعرب المتغير."},{"question":"لماذا لا يدخل الحكم على الحروف والماضي والأمر؟","options":["لأنها لا تسبق بما يوجب رفعًا أو نصبًا أو جرًا أو جزمًا","لأنها أفعال","لأنها أسماء","لا سبب"],"answer":0,"explanation":"الحكم الإعرابي ثمرة عامل يوجبه؛ وهذه الأصناف لا يسبقها ما يرفعها أو ينصبها أو يجرها أو يجزمها."},{"question":"أي الأحكام يختص بالأسماء وأيها يختص بالمضارع؟","options":["الجر يختص بالأسماء والجزم يختص بالمضارع","الرفع للمضارع فقط","النصب للأسماء فقط","كلها مشتركة"],"answer":0,"explanation":"الجر للأسماء وحدها، والجزم للمضارع وحده، والرفع والنصب مشتركان بينهما."}]},{"body":["تدريب من الكتاب: «ذهب محمدٌ»: محمد فاعل، والفاعل حكمه الرفع؛ فدخل الرفع على الاسم المعرب (محمد). «ذهب هذا»: هذا فاعل مبني؛ فدخل الرفع على الاسم المبني في المحل.","«لا تلعبْ»: تلعب فعل مضارع مسبوق بجازم؛ فحكمه الجزم؛ فدخل الجزم على المضارع المعرب. «لا تلعبنَّ»: دخل الجزم على المضارع المبني بنون التوكيد.","تنبيه: دخول الحكم على المبني لا يعني تغيره: بل يعني أن موقعه أوجب له حكمًا لو كان معربًا لظهر فيه؛ فنقول: مبني في محل رفع أو نصب أو جر أو جزم.","الحروف والماضي والأمر ليس لها حكم البتة: لا تقول «منْ مرفوعة» ولا «ذهبَ في محل رفع»؛ فهي قبل خط الإعراب كله كما سيأتي.","الخلاصة: الأحكام أربعة: رفع ونصب وجر وجزم؛ تدخل على الأسماء والمضارعات فقط، معربها ومبنيها؛ وما عدا ذلك فلا حكم له. احفظ هذه القاعدة فهي مفتاح باب الإعراب كله."],"examples":["ذهب محمد: رفع على معرب","ذهب هذا: رفع على مبني","لا تلعب: جزم على معرب","لا تلعبن: جزم على مبني","منْ وذهبَ واذهبْ: لا حكم لها","المفتاح: الحكم للأسماء والمضارعات"],"questions":[{"question":"«ذهب هذا»: كيف دخل الرفع على «هذا»؟","options":["دخله محلًّا لأنه فاعل مبني","غيّر آخره","لم يدخله","جرّه"],"answer":0,"explanation":"هذا فاعل وحكم الفاعل الرفع؛ فدخل الرفع على الاسم المبني محلًّا: مبني على السكون في محل رفع فاعل."},{"question":"«لا تلعبنَّ» ما حكم تلعب؟","options":["جزم دخل على مضارع مبني بنون التوكيد","رفع","نصب","لا حكم"],"answer":0,"explanation":"تلعبن مضارع مبني على الفتح لنون التوكيد؛ وسبقت بلا الناهية الجازمة فحكمه الجزم في المحل."},{"question":"هل نقول «منْ مرفوعة» أو «ذهبَ في محل رفع»؟","options":["لا؛ فلا حكم للحروف والماضي والأمر","نعم دائمًا","نعم أحيانًا","للماضي فقط"],"answer":0,"explanation":"الحروف والماضي والأمر لا يدخلها حكم إعرابي؛ فلا توصف برفع ولا محل رفع."},{"question":"ما ثمرة العامل؟","options":["الحكم الإعرابي في المعمول","البناء","التنوين","لا ثمرة"],"answer":0,"explanation":"العامل يوجب الحكم: الجازم يوجب الجزم، وحرف الجر يوجب الجر، والابتداء يوجب الرفع."},{"question":"أي الجمل يدخل فيها النصب على مبني؟","options":["أكرمت هذا","ذهب هذا","مررت بهذا","هذا قائم"],"answer":0,"explanation":"أكرمت هذا: هذا مفعول به مبني في محل نصب؛ ذهب هذا رفع، ومررت بهذا جر، وهذا قائم رفع مبتدأ."}]}]},{"id":"wahi-sharh-065","title":"خط الإعراب وإعراب ما قبله","section":"شرح الكتاب: فصل في خط الإعراب","order":65,"segments":[{"body":["فصل في خط الإعراب. خط الإعراب: خط وهمي يُسهل الإعراب، وهو غنيمة باردة لطالب اللغة؛ فاشدد عليه يدك تجد الإعراب به واضحًا سانحًا.","هذا الخط يقسم الكلمات - من حيث قبولها الأحكام الإعرابية - قسمين: قسم قبل خط الإعراب: ويشمل الكلمات التي لا تدخلها الأحكام الإعرابية، وهي: الحروف والأفعال الماضية وأفعال الأمر، وهي كلمات كلها مبنية. وقسم بعد خط الإعراب: ويشمل الكلمات التي تدخلها الأحكام: الأسماء والأفعال المضارعة.","إعراب ما قبل الخط له أركان ثلاثة: ١- بيان نوعها: فنقول: حرف كذا، أو فعل ماضٍ، أو فعل أمر. ٢- وبيان حركة بنائها: فنقول: مبني على السكون أو الفتح أو الكسر أو الضم أو حذف النون أو حذف حرف العلة. ٣- وبيان حكمها الإعرابي: فنقول: لا محل لها من الإعراب (بمعنى: ليس لها حكم إعرابي).","مثالها: «هل ذهبَ؟» و«اذهبْ»: هل: حرف استفهام مبني على السكون لا محل له من الإعراب. ذهب: فعل ماضٍ مبني على الفتح لا محل له من الإعراب. اذهب: فعل أمر مبني على السكون لا محل له من الإعراب.","لماذا «لا محل لها»؟ لأن المحل ثمرة الحكم؛ فمن لا حكم له لا محل له: الحروف والماضي والأمر لا يدخلها رفع ولا نصب ولا جر ولا جزم، فلا محل لها من الإعراب.","تدريبات الكتاب على ما قبل الخط: ذهب وكرّم وانطلق واستخرج: فعل ماضٍ مبني على الفتح. دعا وذهبوا ورموا: فعل ماضٍ مبني على الفتح المقدر... اذهب وانطلق واستخرج: فعل أمر مبني على السكون. اذهبا واذهبوا واذهبي: فعل أمر مبني على حذف النون. ادعُ وارمِ واعفُ: فعل أمر مبني على حذف حرف العلة. من وفي وعلى وعن: حرف جر مبني على السكون. هل: حرف استفهام مبني على السكون. نعم وبلى: حرف جواب."],"examples":["خط الإعراب: خط وهمي مقسم","قبله: الحروف والماضي والأمر","بعده: الأسماء والمضارعات","أركان إعراب ما قبله: النوع والبناء ولا محل","هل ذهب اذهب: ثلاثة أمثلة معربة","من وفي وعلى: حروف جر مبنية"],"questions":[{"question":"ما خط الإعراب؟","options":["خط وهمي يقسم الكلمات إلى ما يقبل الأحكام وما لا يقبلها","خط يكتب تحت الكلمة","حرف جر","علامة إعراب"],"answer":0,"explanation":"خط وهمي: قبله الكلمات التي لا تدخلها الأحكام (الحروف والماضي والأمر) وبعده ما يدخلها (الأسماء والمضارعات)."},{"question":"ما أركان إعراب ما قبل خط الإعراب؟","options":["بيان النوع وبيان البناء وبيان أن لا محل لها","الرفع والنصب والجر","التعريف والتنكير","لا أركان"],"answer":0,"explanation":"ثلاثة: بيان نوعها (حرف أو ماضٍ أو أمر)، وبيان حركة بنائها، وبيان حكمها: لا محل لها من الإعراب."},{"question":"أعرب «هل» في «هل ذهبت؟»:","options":["حرف استفهام مبني على السكون لا محل له من الإعراب","مبني في محل رفع","فعل أمر","مرفوع"],"answer":0,"explanation":"هل قبل الخط: حرف استفهام مبني على السكون لا محل له من الإعراب."},{"question":"أعرب «اذهبوا»:","options":["فعل أمر مبني على حذف النون لا محل له من الإعراب","مضارع مجزوم","ماض مبني على الضم","مبني على السكون"],"answer":0,"explanation":"اذهبوا أمر من الأفعال الخمسة: مبني على حذف النون لاتصاله بواو الجماعة؛ وقبل الخط فلا محل له."},{"question":"أعرب «ادعُ»:","options":["فعل أمر مبني على حذف حرف العلة لا محل له من الإعراب","مبني على السكون","ماض","مضارع"],"answer":0,"explanation":"ادع أمر معتل الآخر (من يدعو): مبني على حذف حرف العلة؛ مثله ارمِ واعفُ."}]},{"body":["لماذا سمي «خطًّا»؟ لأنه فاصل بين صنفين: كما يفصل الخط بين أرضين؛ فمن كان قبله فله وضع، ومن كان بعده فله وضع آخر. وسماه المؤلف «غنيمة باردة»: أي ربحًا سهلًا: بمجرد أن تعرف موضع الكلمة من الخط عرفت طريق إعرابها.","تطبيق سريع: صنّف الكلمات: «بلى»: حرف جواب مبني - قبل الخط. «كتبتُ»: ماضٍ - قبل الخط. «يكتبُ»: مضارع - بعد الخط. «كتابٌ»: اسم - بعد الخط. «اكتبْ»: أمر - قبل الخط. «على»: حرف - قبل الخط.","فائدة التقسيم: إذا أعطيت جملة فأول خطوة: حدد كل كلمة: أهي قبل الخط أم بعده؟ فإن كانت قبله فإعرابها سهل ثلاثي: النوع + البناء + لا محل لها. وإن كانت بعده فأنت بحاجة لمعرفة موقعها من الجملة: أرفع أم نصب أم جر أم جزم.","مثال جامع: «هل كتبَ الطالبُ الدرسَ؟»: هل: حرف استفهام مبني على السكون لا محل له. كتب: فعل ماضٍ مبني على الفتح لا محل له. الطالب: فاعل مرفوع بالضمة (بعد الخط). الدرس: مفعول به منصوب بالفتحة (بعد الخط).","ومثال الأمر: «اكتبْ درسَك بقلمك»: اكتب: فعل أمر مبني على السكون لا محل له (قبل الخط). درس: مفعول به منصوب والكاف مضاف إليه (بعد الخط). بقلمك: الباء حرف جر مبني (قبل الخط) وقلم مجرور والكاف مضاف إليه (بعد الخط).","الخلاصة: خط الإعراب ميزانك الأول: ما قبله (حروف وماضٍ وأمر) إعرابه: النوع + البناء + لا محل لها؛ وما بعده (أسماء ومضارعات) نبحث عن حكمه ومحله - وهو موضوع الدرس القادم."],"examples":["بلى وكتبت واكتب وعلى: قبل الخط","يكتب وكتاب: بعد الخط","هل كتب الطالب الدرس: مثال جامع","اكتب درسك بقلمك: أمر ومفعول وجار","قبل الخط: ثلاثي سهل","بعد الخط: يحتاج موقعًا"],"questions":[{"question":"صنف: «بلى» و«يكتب» و«على» من حيث الخط:","options":["بلى وعلى قبل الخط ويكتب بعده","كلها قبل الخط","كلها بعد الخط","بلى بعد الخط"],"answer":0,"explanation":"بلى حرف جواب وعلى حرف جر: قبل الخط؛ يكتب مضارع: بعد الخط لأنه يقبل الرفع والنصب والجزم."},{"question":"أعرب «كتب» في «هل كتب الطالب الدرس؟»:","options":["فعل ماض مبني على الفتح لا محل له من الإعراب","مرفوع","مبني في محل رفع","مجزوم"],"answer":0,"explanation":"كتب ماضٍ قبل الخط: مبني على الفتح لا محل له من الإعراب؛ والطالب فاعل والدرس مفعول به."},{"question":"أعرب «الباء» في «بقلمك»:","options":["حرف جر مبني لا محل له من الإعراب","مجرور","في محل جر","فعل"],"answer":0,"explanation":"الباء حرف قبل الخط: حرف جر مبني على السكون... وقلم بعد الخط: اسم مجرور بالباء."},{"question":"ما ثمرة تقسيم الكلمات بالخط؟","options":["تسهيل الإعراب: قبله ثلاثي وبعده بحث عن الموقع","لا ثمرة","للحفظ","للزينة"],"answer":0,"explanation":"من عرف موضع الكلمة من الخط عرف طريق إعرابها: قبله نوع وبناء ولا محل؛ وبعده حكم ومحل وعلامة."},{"question":"«درسك» في «اكتب درسك» ما إعرابها؟","options":["مفعول به منصوب والكاف مضاف إليه","فاعل","مبتدأ","حرف"],"answer":0,"explanation":"درس اسم بعد الخط: مفعول به منصوب بالفتحة مضاف؛ والكاف ضمير متصل في محل جر مضاف إليه."}]}]},{"id":"wahi-sharh-066","title":"إعراب ما بعد خط الإعراب وأركانه","section":"شرح الكتاب: إعراب ما بعد خط الإعراب","order":66,"segments":[{"body":["ما بعد خط الإعراب: الكلمات التي تدخلها الأحكام الإعرابية وهي: الأسماء والأفعال المضارعة. وإعرابها أكثره منضبط وبعضه مشكل؛ فاحرص على الضوابط واحدًا بعد واحد حتى تتقنها.","توزيع الأحكام على الأسماء: يدخل الاسمَ الرفعُ في مواضع: كالمبتدأ والخبر والفاعل ونائب الفاعل واسم كان وأخواتها وخبر إن وأخواتها والتابع للمرفوع. ويدخله الجر في: المجرور بحرف الجر والمضاف إليه والتابع للمجرور. ويدخله النصب فيما سوى ذلك: كالمفاعيل الخمسة (به وفيه وله ومعه والمطلق) والحال والتمييز والمستثنى في أكثر أحواله والمنادى وخبر كان واسم إن والتابع للمنصوب.","وأما الفعل المضارع: يدخله الرفع إذا لم يسبق بناصب ولا جازم؛ ويدخله النصب إذا سبق بناصب، ونواصبه أربعة: أن ولن وكي وإذن (وما في معناها مما تقدم)؛ ويدخله الجزم إذا سبق بجازم، وجوازمه خمسة: لم ولما ولام الأمر ولا الناهية وأدوات الشرط الجازمة.","أركان إعراب الاسم والمضارع: ١- بيان نوع المضارع وبيان موقع الاسم من الجملة: فالفعل يقال: فعل مضارع؛ والاسم يحدد موقعه: فإن وقع بحيث يدل على من قام بالفعل فهو فاعل، وإن وقع بحيث يدل على من وقع الفعل عليه فهو مفعول به، وإن وقع بحيث يدل على زمان الفعل أو مكانه فهو ظرف، وإن وقع بحيث يدل على الحال والهيئة فهو حال... وهكذا.","٢- وبيان الحكم الإعرابي. ٣- وبيان الحركة (العلامة): إن كان الاسم والمضارع معربين قل: مرفوع وعلامة رفعه الضمة... أو منصوب وعلامة نصبه الفتحة... أو مجرور وعلامة جره الكسرة... أو مجزوم وعلامة جزمه السكون. وإن كانا مبنيين قل: في محل رفع مبني على كذا... إلخ.","وقد نظم المؤلف ذلك: «أحكامنا في الاسم والمضارع # قد دخلت حيثما بلا مزاع - مرفوع أو منصوب أو مجرور # مجزوم المعرب يا بصير - مبنيها... في محل ولكل تسمية بين المجاز»."],"examples":["الأسماء: رفع ونصب وجر","المضارع: رفع ونصب وجزم","الموقع يحدد النوع: فاعل أو مفعول أو ظرف أو حال","أركان الإعراب: الموقع والحكم والعلامة","المعرب: علامة ظاهرة؛ المبني: محل وبناء","نظم المؤلف الخلاصة"],"questions":[{"question":"ما الكلمات التي بعد خط الإعراب؟","options":["الأسماء والأفعال المضارعة","الحروف","الماضي","الأمر"],"answer":0,"explanation":"بعد الخط: الأسماء والمضارعات؛ فهي التي تدخلها الأحكام الأربعة؛ وقبله الحروف والماضي والأمر."},{"question":"فيمَ يدخل الاسمَ الجرُ؟","options":["في المجرور بحرف الجر والمضاف إليه والتابع للمجرور","في المبتدأ","في الفاعل","في المفعول به"],"answer":0,"explanation":"الجر في ثلاثة: المجرور بالحرف (مررت بزيد)، والمضاف إليه (كتاب محمد)، والتابع للمجرور (نعته وعطفه...)."},{"question":"فيمَ يدخل الاسمَ النصبُ؟","options":["في المفاعيل والحال والتمييز والمنادى وخبر كان واسم إن والتابع للمنصوب","في المبتدأ","في الفاعل","في المضاف إليه"],"answer":0,"explanation":"النصب فيما سوى الرفع والجر: المفاعيل الخمسة والحال والتمييز والمستثنى في أكثر أحواله والمنادى وخبر كان واسم إن والتابع للمنصوب."},{"question":"كيف تعرف أن الاسم فاعل؟","options":["إذا وقع بحيث يدل على من قام بالفعل","إذا دل على زمان الفعل","إذا دل على الحال","إذا جر"],"answer":0,"explanation":"الموقع يحدد: دل على من قام بالفعل ففاعل؛ على من وقع عليه فمفعول به؛ على زمانه أو مكانه فظرف؛ على الهيئة فحال."},{"question":"ما أركان إعراب الاسم والمضارع؟","options":["بيان الموقع وبيان الحكم وبيان العلامة","النوع والبناء فقط","لا أركان","التعريف فقط"],"answer":0,"explanation":"ثلاثة: بيان الموقع من الجملة (فاعل مفعول...)، وبيان الحكم (رفع نصب جر جزم)، وبيان العلامة (ضمة فتحة... أو محل وبناء)."}]},{"body":["تدريب الكتاب المعرب: «ينصرُ (رفع) المسلمُ (رفع) الحقَّ (نصب)»: ينصر: فعل مضارع مرفوع وعلامة رفعه الضمة. المسلم: فاعل مرفوع وعلامة رفعه الضمة. الحق: مفعول به منصوب وعلامة نصبه الفتحة.","ومثال المبني: «هؤلاءِ (رفع) يكرمنَ (رفع) هذا (نصب)»: هؤلاء: مبتدأ في محل رفع مبني على الكسر. يكرمن: فعل مضارع مبني على السكون لاتصاله بنون النسوة... في محل رفع، والنون ضمير فاعل. هذا: مفعول به في محل نصب مبني على السكون.","خطوات عملية لإعراب أي جملة: ١- صنف كل كلمة: قبل الخط أم بعده؟ ٢- ما قبله: نوع + بناء + لا محل له. ٣- ما بعده: حدد موقعه بالسؤال: من فعل؟ (فاعل) من وقع عليه؟ (مفعول) متى وأين؟ (ظرف) كيف؟ (حال). ٤- اذكر الحكم ثم العلامة أو المحل والبناء.","«اجتهد الطلابُ في دروسهم»: اجتهد: فعل ماضٍ مبني على الفتح لا محل له (قبل الخط). الطلاب: فاعل مرفوع بالضمة (بعد الخط: دل على من قام بالفعل). في: حرف جر مبني (قبل الخط). دروسهم: اسم مجرور مضاف وهم مضاف إليه (بعد الخط).","نصيحة المؤلف: لا تجزع إن أخطأت في الإعراب حينًا؛ فإنك في أوله سوف تروب وتشوب... حتى يلين لك جانبه فيصير من لذائذ العلم؛ فما سمعت من ظريف الإعراب صعبًا إلا وقد صار لأهله من سروات الرجال ولهاميم الفرسان.","الخلاصة: ما بعد الخط يعرب بثلاثة أركان: الموقع (نوع الاسم من حيث عمله) ثم الحكم ثم العلامة للمعرب أو المحل والبناء للمبني. وهذه المواضع (المبتدأ والفاعل والمفاعيل...) هي فروع النحو التي ستأتي مشروحة في أحكام الكلام."],"examples":["ينصر المسلم الحق: ثلاثة أركان لكل كلمة","هؤلاء يكرمن هذا: مبنيات بالمحل","أربع خطوات عملية للإعراب","اجتهد الطلاب في دروسهم: تطبيق","الإعراب يصير لذيذًا مع التمرين","المواضع = فروع النحو القادمة"],"questions":[{"question":"أعرب «المسلم» في «ينصر المسلم الحق»:","options":["فاعل مرفوع وعلامة رفعه الضمة","مفعول به","مبتدأ","مجرور"],"answer":0,"explanation":"دل على من قام بالفعل: فاعل مرفوع بالضمة؛ وينصر مضارع مرفوع، والحق مفعول به منصوب بالفتحة."},{"question":"أعرب «هذا» في «هؤلاء يكرمن هذا»:","options":["مفعول به في محل نصب مبني على السكون","مرفوع بالضمة","فاعل","مبتدأ"],"answer":0,"explanation":"هذا اسم إشارة مبني على السكون؛ وقع مفعولًا به فهو في محل نصب."},{"question":"ما الخطوة الأولى لإعراب جملة؟","options":["تصنيف كل كلمة: قبل خط الإعراب أم بعده","الترجمة","الضبط","الحفظ"],"answer":0,"explanation":"أولًا: صنف الكلمات؛ فما قبل الخط إعرابه: نوع وبناء ولا محل له؛ وما بعده يبحث عن موقعه."},{"question":"أعرب «دروسهم» في «اجتهد الطلاب في دروسهم»:","options":["اسم مجرور بفي مضاف وهم ضمير مضاف إليه","فاعل","مفعول به","ظرف"],"answer":0,"explanation":"دروس: اسم مجرور بفي وعلامة جره الكسرة وهو مضاف؛ وهم: ضمير متصل في محل جر مضاف إليه."},{"question":"ما نصيحة المؤلف لمن يخطئ في الإعراب أولًا؟","options":["لا تجزع وواصل التمرين حتى يلين ويصير لذيذًا","اترك النحو","احفظ بلا فهم","اعتمد على غيرك"],"answer":0,"explanation":"الإعراب في أوله صعوبة ثم يلين بالتدريب حتى يصير من لذائذ العلم وفواكه المجالس."}]}]},{"id":"wahi-sharh-067","title":"علامات الإعراب الأصلية والعلامات المقدرة","section":"شرح الكتاب: فصل في علامات الإعراب - الظاهرة والمقدرة","order":67,"segments":[{"body":["فصل في علامات الإعراب. علامات الإعراب تكون في المعربات فقط، وقد سبق أن المعربات منحصرة في الأسماء والأفعال المضارعة.","العلامات الأصلية أربع: الضمة للرفع نحو: زيدٌ يذهبُ. والفتحة للنصب نحو: إن زيدًا لن يذهبَ. والكسرة للجر نحو: على زيدٍ. والسكون للجزم نحو: لا تَهملْ.","ولعلامات الإعراب تقسيمان. التقسيم الأول: انقسامها إلى ظاهرة ومقدرة. الأصل والأكثر أن تكون ظاهرة، وقد تكون مقدرة مستورة - أي مغطاة ممنوعة من الظهور - في خمسة مواضع:","١- الاسم المضاف إلى ياء المتكلم: علاماته مقدرة لحركة المناسبة (كثرة استعمال الياء): صديقي: مرفوع بالضمة المقدرة، منصوب بالفتحة المقدرة، مجرور بالكسرة المقدرة: جاء صديقي، أكرمت صديقي، سلمت على صديقي.","٢- الاسم المقصور: وهو الاسم المعرب المختوم بألف لازمة: الفتى والهدى وعصا والمستشفى. كل علامات إعرابه مقدرة للتعذر (الحركات لا تظهر على الألف): جاء الفتى (ضمة مقدرة)، أكرمت الفتى (فتحة مقدرة)، سلمت على الفتى (كسرة مقدرة).","٣- الاسم المنقوص: وهو الاسم المعرب المختوم بياء لازمة قبلها كسرة: القاضي والهادي والمهتدي. علامة رفعه ضمة مقدرة وعلامة جره كسرة مقدرة للثقل؛ عدا نصبه فعلامته ظاهرة وهي فتحة ظاهرة: جاء القاضي، وأكرمت القاضيَ (فتحة ظاهرة)، وسلمت على القاضي. تنبيه: إذا نون الاسم المنقوص حذفت ياؤه: قاضٍ.","٤- المضارع المختوم بألف: مثل يخشى ويرضى: رفعه ونصبه بالحركة المقدرة للتعذر، وجزمه ظاهر وهو حذف حرف العلة: المسلم لم يخشَ إلا ربه.","٥- المضارع المختوم بواو أو ياء: مثل يدعو ويرمي: علامة رفعه ضمة مقدرة، عدا نصبه ففتحة ظاهرة، وعدا جزمه فحذف حرف العلة ظاهر: لم يدعُ ولم يرمِ."],"examples":["الأصلية الأربع: ضمة فتحة كسرة سكون","المقدرة: مغطاة ممنوعة من الظهور","المضاف إلى ياء المتكلم: حركة المناسبة","المقصور: كل علاماته مقدرة للتعذر","المنقوص: نصبه ظاهر ورفعه وجره مقدران للثقل","المضارع المعتل: جزمه حذف العلة"],"questions":[{"question":"ما العلامات الأصلية الأربع؟","options":["الضمة للرفع والفتحة للنصب والكسرة للجر والسكون للجزم","الألف والياء","التنوين","الواو فقط"],"answer":0,"explanation":"الأصل: ضمة للرفع (زيد يذهب)، فتحة للنصب (إن زيدًا)، كسرة للجر (على زيد)، سكون للجزم (لا تهمل)."},{"question":"ما العلامة المقدرة؟","options":["علامة مستورة مغطاة ممنوعة من الظهور","علامة ظاهرة","حرف علة","تنوين"],"answer":0,"explanation":"المقدرة محذوفة الظهور لمانع: تعذر أو ثقل أو حركة المناسبة؛ تقدر في آخر الكلمة ولا تنطق."},{"question":"لماذا قدرت علامات المضاف إلى ياء المتكلم؟","options":["لحركة المناسبة لكثرة استعمال الياء","للتعذر","للثقل","بلا سبب"],"answer":0,"explanation":"صديقي: كثرة استعمال الياء أوجبت تقدير الحركات قبلها: رفعًا ونصبًا وجرًا لحركة المناسبة."},{"question":"ما الاسم المقصور وما حكم علاماته؟","options":["اسم مختوم بألف لازمة وكل علاماته مقدرة للتعذر","مختوم بياء","مختوم بتاء","مبني"],"answer":0,"explanation":"الفتى والهدى: مختومان بألف لازمة؛ والحركات لا تظهر على الألف فتقدر كلها للتعذر."},{"question":"ما علامة نصب الاسم المنقوص؟","options":["فتحة ظاهرة","فتحة مقدرة","كسرة مقدرة","الياء"],"answer":0,"explanation":"المنقوص (القاضي): رفعه وجره مقدران للثقل؛ عدا نصبه ففتحة ظاهرة: أكرمت القاضيَ؛ وإذا نون حذفت ياؤه."}]},{"body":["تدريب: «المسلم لن يخشى إلا ربه»: يخشى: فعل مضارع منصوب وعلامة نصبه الفتحة المقدرة على الألف للتعذر. «الرجل لم يخشَ إلا ربه»: يخش: فعل مضارع مجزوم وعلامة جزمه حذف حرف العلة (الألف).","«يدعو ويلمو... يرمي ويقضي»: المختوم بواو: يدعو ويغزو ويربو؛ والمختوم بياء: يهدي ويرمي ويقضي ويصلي ويستهدي. رفعهما بضمة مقدرة، ونصبهما بفتحة ظاهرة، وجزمهما بحذف حرف العلة: لم يدعُ، لم يرمِ.","«كرمت صديقي»: صديقي: مفعول به منصوب وعلامة نصبه الفتحة المقدرة منع من ظهورها حركة المناسبة. و«سلمت على صديقي»: اسم مجرور وعلامة جره الكسرة المقدرة منع من ظهورها حركة المناسبة.","«جاء الفتى»: الفتى: فاعل مرفوع وعلامة رفعه الضمة المقدرة منع من ظهورها التعذر. «أكرمت الفتى»: منصوب بالفتحة المقدرة. «سلمت على الفتى»: مجرور بالكسرة المقدرة. فالمقصور كل علاماته مقدرة.","متى تظهر حركات المقصور؟ إذا حذفت ألفه في الإضافة إلى ياء المتكلم أو نون: فتًى (بالتنوين) تظهر الحركة على التاء... المقصور إذا نون حذفت ألفه: فتًى.","الخلاصة: خمسة أبواب للعلامات المقدرة: المضاف إلى ياء المتكلم (مناسبة)، المقصور (تعذر)، المنقوص (ثقل إلا نصبه)، والمضارع المختوم بألف (تعذر) أو بواو وياء (رفعه مقدر فقط). واحفظ موانع الظهور الثلاثة: التعذر والثقل وحركة المناسبة."],"examples":["لم يخشَ: جزم بحذف العلة","لم يدعُ ولم يرمِ: حذف الواو والياء","كرمت صديقي: فتحة مقدرة مناسبة","جاء الفتى: ضمة مقدرة تعذر","فتًى: حذفت الألف بالتنوين","ثلاثة موانع: تعذر وثقل ومناسبة"],"questions":[{"question":"أعرب «يخشى» في «المسلم لن يخشى إلا ربه»:","options":["فعل مضارع منصوب وعلامة نصبه الفتحة المقدرة للتعذر","مرفوع بضمة ظاهرة","مجزوم بالسكون","مبني"],"answer":0,"explanation":"يخشى مضارع مختوم بألف؛ نصبته لن: منصوب بالفتحة المقدرة على الألف منع من ظهورها التعذر."},{"question":"أعرب «يخشَ» في «لم يخش إلا ربه»:","options":["فعل مضارع مجزوم وعلامة جزمه حذف حرف العلة","منصوب بفتحة مقدرة","مرفوع","مبني على السكون"],"answer":0,"explanation":"جزمته لم فحذف حرف العلة (الألف): مجزوم وعلامة جزمه حذف حرف العلة."},{"question":"ما علامات إعراب المضارع المختوم بواو أو ياء؟","options":["رفعه بضمة مقدرة ونصبه بفتحة ظاهرة وجزمه بحذف العلة","كلها ظاهرة","كلها مقدرة","بالسكون"],"answer":0,"explanation":"يدعو ويرمي: الرفع بضمة مقدرة للثقل، والنصب بفتحة ظاهرة، والجزم بحذف حرف العلة: لم يدعُ لم يرمِ."},{"question":"ما موانع ظهور الحركة الثلاثة؟","options":["التعذر والثقل وحركة المناسبة","الرفع والنصب والجر","الإضافة فقط","التنوين"],"answer":0,"explanation":"ثلاثة: التعذر (على الألف: الفتى)، والثقل (على الياء: القاضي)، وحركة المناسبة (قبل ياء المتكلم: صديقي)."},{"question":"ماذا يحدث إذا نون المقصور أو المنقوص؟","options":["تحذف الألف من المقصور والياء من المنقوص","تثبتان","يمنع التنوين","يبنيان"],"answer":0,"explanation":"فتًى: حذفت ألف المقصور للتنوين؛ وقاضٍ: حذفت ياء المنقوص للتنوين تخفيفًا."}]}]},{"id":"wahi-sharh-068","title":"العلامات الفرعية: الأسماء الخمسة والمثنى والجمعان","section":"شرح الكتاب: علامات الإعراب - الأصلية والفرعية","order":68,"segments":[{"body":["التقسيم الثاني: انقسام علامات الإعراب إلى أصلية وفرعية. الأصل والأكثر أن تكون أصلية كما سبق، وقد تكون فرعية تابعة في سبعة أبواب خمسة منها من الأسماء واثنان من الأفعال المضارعة.","الباب الأول: الأسماء الخمسة وهي: أبوك وأخوك وحمُوك وفُوك وذو علم. شرطها: أن تضاف إلى غير ياء المتكلم. مثالها: أبوك وأخوهم وفوه وأبو بكر وأبو الأولاد وذو فضل.","علامات إعرابها: ترفع بالواو وتنصب بالألف وتجر بالياء، نحو: كان أبو محمدٍ ذا فضلٍ على أخيك: أبو: اسم كان مرفوع وعلامة رفعه الواو. ذا: خبر كان منصوب وعلامة نصبه الألف. أخيك: اسم مجرور وعلامة جره الياء.","الباب الثاني: المثنى: هو كل اسم دل على اثنين أو اثنتين بزيادة ألف ونون أو ياء ونون: محمدان وهندان والمعلمان والمعلمتان والبابان. علاماته: يرفع بالألف ويجر وينصب بالياء: كان الخطان متقاطعين... الخطان: اسم كان مرفوع وعلامة رفعه الألف.","الباب الثالث: جمع المذكر السالم: هو كل اسم دل على أكثر من اثنين بزيادة واو ونون أو ياء ونون: محمدون والمعلمون والفائزون والمتساعدون وخالدون. علاماته: يرفع بالواو ويجر وينصب بالياء: كان المديرون مجتمعين بالمشرفين: المديرون: اسم كان مرفوع بالواو، مجتمعين: خبر منصوب بالياء، المشرفين: مجرور بالياء.","الباب الرابع: جمع المؤنث السالم: هو كل اسم دل على أكثر من اثنتين أو اثنين بزيادة ألف وتاء: هندات وزينبات ومعلمات والطالبات. علاماته: يرفع بالضمة وينصب بالكسرة ويجر بالكسرة. تنبيه: جمع المؤنث السالم فيه علامة فرعية واحدة وهي علامة النصب (الكسرة)؛ وأما علامتا الرفع والجر فأصليتان.","العلامات الفرعية إذن: الألف (رفع المثنى)، الواو (رفع الأسماء الخمسة وجمع المذكر)، الياء (نصب وجر الأبواب الثلاثة)، الكسرة (نصب جمع المؤنث السالم)، ثبوت النون وحذفها (الأفعال الخمسة - في الدرس القادم)."],"examples":["سبعة أبواب: خمسة أسماء واثنان أفعال","الأسماء الخمسة: أبو أخو حمو فو ذو","ترفع بالواو وتنصب بالألف وتجر بالياء","المثنى: بالألف والياء","جمع المذكر: بالواو والياء","جمع المؤنث: نصبه بالكسرة فرعية"],"questions":[{"question":"ما الأسماء الخمسة وما شرطها؟","options":["أبو وأخو وحمو وفو وذو بشرط الإضافة إلى غير ياء المتكلم","خمسة أفعال","خمسة حروف","الضمائر الخمسة"],"answer":0,"explanation":"أبوك وأخوك وحمك وفمك (فوك) وذو علم؛ بشرط أن تضاف إلى غير ياء المتكلم؛ وإلا أعربت بالحركات."},{"question":"ما علامات إعراب الأسماء الخمسة؟","options":["ترفع بالواو وتنصب بالألف وتجر بالياء","بالحركات","بالتنوين","بالسكون"],"answer":0,"explanation":"كان أبو محمد ذا فضل: أبو مرفوع بالواو، ذا منصوب بالألف، على أخيك: مجرور بالياء."},{"question":"ما تعريف المثنى وعلاماته؟","options":["كل اسم دل على اثنين بزيادة ألف ونون أو ياء ونون؛ يرفع بالألف وينصب ويجر بالياء","جمع كثرة","مفرد","مبني"],"answer":0,"explanation":"المعلمان والمعلمتان: دل على اثنين بزيادة ألف ونون (رفعًا) أو ياء ونون (نصبًا وجرًا)."},{"question":"ما تعريف جمع المذكر السالم وعلاماته؟","options":["كل اسم دل على أكثر من اثنين بزيادة واو ونون أو ياء ونون؛ يرفع بالواو وينصب ويجر بالياء","دل على اثنين","مبني","ممنوع"],"answer":0,"explanation":"المعلمون: جمع مذكر سالم؛ سمي سالمًا لسلامة مفرده من التغيير؛ يرفع بالواو وينصب ويجر بالياء."},{"question":"ما العلامة الفرعية الوحيدة في جمع المؤنث السالم؟","options":["النصب بالكسرة","الرفع بالضمة","الجر بالكسرة","الواو"],"answer":0,"explanation":"جمع المؤنث السالم: يرفع بالضمة ويجر بالكسرة (أصليتان) وينصب بالكسرة (فرعية): أكرمت الطالباتِ."}]},{"body":["تدريب: «كان المديرون مجتمعين بالمشرفين»: المديرون: اسم كان مرفوع وعلامة رفعه الواو. مجتمعين: خبر كان منصوب وعلامة نصبه الياء. المشرفين: اسم مجرور وعلامة جره الياء.","«كرمت الطالباتِ»: الطالبات: مفعول به منصوب وعلامة نصبه الكسرة (فرعية في جمع المؤنث السالم). و«الطالبات مجتهداتٌ»: الطالبات: مبتدأ مرفوع بالضمة (أصلية).","«جاء أخوك وسلمت على أبيك»: أخوك: فاعل مرفوع بالواو. أبيك: اسم مجرور بالياء؛ لو قلت: جاء أبي (بإضافة ياء المتكلم) لأعرب بالحركات المقدرة لانتفاء الشرط.","«المعلمان مجتهدان والمعلمون مجتهدون»: المعلمان: مبتدأ مرفوع بالألف (مثنى). المعلمون: مبتدأ مرفوع بالواو (جمع مذكر سالم).","تمييز مهم: «أبو بكر» مركب إضافي في العلم لكن «أبو» هنا من الأسماء الخمسة إعرابًا: جاء أبو بكر (مرفوع بالواو). و«فوه» أي فمه: سلمت على فيك؟ لا: على فمك... فو تستعمل مضافة: في فيهِ (فِي + هاء) رفعها: فُوه.","الخلاصة: أربعة أبواب من الأسماء بعلامات فرعية: الأسماء الخمسة (واو ألف ياء)، المثنى (ألف ياء)، جمع المذكر (واو ياء)، جمع المؤنث (كسرة للنصب فقط). والباقيان من الأفعال: الأفعال الخمسة والمضارع المعتل - في الدرس القادم."],"examples":["كان المديرون مجتمعين بالمشرفين: ثلاث علامات فرعية","كرمت الطالبات: نصب بالكسرة","أخوك بالواو وأبي بالحركات المقدرة","المعلمان والمعلمون: مثنى وجمع","أبو بكر: مرفوع بالواو","الباقي: الأفعال الخمسة والمعتل"],"questions":[{"question":"أعرب «مجتمعين» في «كان المديرون مجتمعين»:","options":["خبر كان منصوب وعلامة نصبه الياء","مرفوع بالواو","مجرور بالكسرة","فاعل"],"answer":0,"explanation":"خبر كان منصوب؛ وهو جمع مذكر سالم فعلامة نصبه الياء الفرعية."},{"question":"أعرب «الطالبات» في «كرمت الطالبات»:","options":["مفعول به منصوب وعلامة نصبه الكسرة","مرفوع بالضمة","مجرور بالياء","فاعل"],"answer":0,"explanation":"جمع مؤنث سالم ينصب بالكسرة نيابة عن الفتحة: منصوب وعلامة نصبه الكسرة."},{"question":"لماذا أعرب «أخي» بالحركات و«أخوك» بالواو؟","options":["لأن شرط الأسماء الخمسة الإضافة إلى غير ياء المتكلم","لا سبب","للزينة","خطأ"],"answer":0,"explanation":"أخي: أضيف إلى ياء المتكلم فبطل الشرط: مرفوع بالضمة المقدرة؛ وأخوك: مرفوع بالواو لتحقق الشرط."},{"question":"أعرب «المعلمان» في «المعلمان مجتهدان»:","options":["مبتدأ مرفوع وعلامة رفعه الألف لأنه مثنى","مرفوع بالواو","مرفوع بالضمة","منصوب"],"answer":0,"explanation":"المعلمان مثنى: يرفع بالألف وينصب ويجر بالياء؛ هنا مبتدأ مرفوع بالألف."},{"question":"ما وجه تسمية جمع المذكر «سالمًا»؟","options":["لسلامة مفرده من التغيير عند الجمع","لسلامته من العلل","لا سبب","لكثرته"],"answer":0,"explanation":"سالم: سلم مفرده من التغيير والتبديل: معلم → معلمون؛ بخلاف جمع التكسير: كتاب → كتب."}]}]},{"id":"wahi-sharh-069","title":"الممنوع من الصرف والأفعال الخمسة","section":"شرح الكتاب: علامات الإعراب - الممنوع من الصرف والأفعال الخمسة","order":69,"segments":[{"body":["الباب الخامس من أبواب العلامات الفرعية: الاسم الممنوع من الصرف. تعريفه: أحد عشر اسمًا منعتها العرب من الصرف أي: من التنوين والجر بالكسرة. منها:","١- الاسم الذي على صيغتي (مفاعل) أو (مفاعيل): مساجد وقناديل. ٢- العلم المؤنث غير الثلاثي: فاطمة وسعاد ومكة وحمزة. ٣- العلم الأعجمي غير الثلاثي: إبراهيم ويوسف وجورج.","علامات إعرابه: يرفع بالضمة وينصب ويجر بالفتحة، نحو: يضيء إبراهيمُ مصابيحَ جميلةً في مساجدَ كثيرةٍ: مساجد: اسم مجرور وعلامة جره الفتحة. ونقول: صلى الله وسلم على محمدٍ وإبراهيمَ وصالحٍ وإسماعيلَ.","تنبيه مهم: الاسم الممنوع من الصرف فيه علامة فرعية واحدة وهي علامة الجر (الفتحة) بشرط ألا يقترن بـ(أل) أو يضاف؛ وإلا جر بالكسرة: صليت في المساجدِ (كسرة لاقترانه بأل)؛ وفي مساجدِ الرياض (كسرة لأنه مضاف).","الباب السادس: الأفعال الخمسة. تعريفها: كل فعل مضارع اتصلت به: ألف الاثنين أو واو الجماعة أو ياء المخاطبة. مثالها: يذهبان ويذهبون وتذهبين، ويقولان ويقولون وتقولين.","علامات إعرابها: ترفع بثبوت النون وتنصب وتجزم بحذفها: أعمال يذهبون... مرفوع بثبوت النون. لن يذهبوا ولن يذهبا ولن تذهبي: منصوب بحذف النون. لم يذهبوا ولم تذهبوا ولم تذهبي: مجزوم بحذف النون.","تنبيه مهم: يجب التفريق بين الأفعال الخمسة والمثنى وجمع المذكر السالم: فالأفعال الخمسة أفعال مضارعة (يذهبون ويذهبان وتذهبين)، وأما المثنى وجمع المذكر فأسماء (ذاهبان وذاهبون ومجتهدان ومجتهدون). نقول: المجتهدون (جمع مذكر سالم) يجتهدون (من الأفعال الخمسة). والمجتهدان (مثنى) يجتهدان (من الأفعال الخمسة).","الباب السابع: المضارع المعتل الآخر وقد تقدم: يرفع بالضمة المقدرة وينصب بالفتحة (ظاهرة في الواو والياء مقدرة في الألف) ويجزم بحذف حرف العلة."],"examples":["الممنوع: من التنوين والجر بالكسرة","مساجد وقناديل: مفاعل ومفاعيل","فاطمة وإبراهيم: علم مؤنث وأعجمي","يجر بالفتحة إلا مع أل أو الإضافة","الأفعال الخمسة: ترفع بثبوت النون","يجتهدون فعل ومجتهدون اسم"],"questions":[{"question":"ما الممنوع من الصرف؟","options":["اسم منع من التنوين والجر بالكسرة","اسم مبني","فعل ماض","جمع مذكر"],"answer":0,"explanation":"أحد عشر اسمًا منعتها العرب من الصرف: لا تونن وتجر بالفتحة؛ مثل مساجد وفاطمة وإبراهيم."},{"question":"ما علامات إعراب الممنوع من الصرف؟","options":["يرفع بالضمة وينصب ويجر بالفتحة","كلها بالكسرة","مبني","بالتنوين"],"answer":0,"explanation":"يضيء إبراهيم مصابيح في مساجدَ كثيرة: مساجد مجرور بالفتحة نيابة عن الكسرة."},{"question":"متى يجر الممنوع من الصرف بالكسرة؟","options":["إذا اقترن بأل أو أضيف","أبدًا","دائمًا","إذا نصب"],"answer":0,"explanation":"صليت في المساجدِ (أل) وفي مساجدِ الرياض (إضافة): بالكسرة؛ والمنع للنكرة المجردة فقط."},{"question":"ما الأفعال الخمسة؟","options":["كل مضارع اتصلت به ألف الاثنين أو واو الجماعة أو ياء المخاطبة","خمسة أسماء","الماضي والأمر","الحروف"],"answer":0,"explanation":"يذهبان ويذهبون وتذهبين: مضارعات اتصل بها أحد الثلاثة؛ وسميت خمسة لأن الواو والتاء يتفرعان."},{"question":"كيف تفرق بين «يجتهدون» و«مجتهدون»؟","options":["الأولى فعل مضارع من الأفعال الخمسة والثانية اسم جمع مذكر سالم","كلتاهما أفعال","كلتاهما أسماء","لا فرق"],"answer":0,"explanation":"المجتهدون (اسم جمع) يجتهدون (فعل): الاسم يرفع بالواو كعلامة إعرابية، والفعل يرفع بثبوت النون."}]},{"body":["تدريبات الكتاب: «أهلَّ هلالُ رمضانَ ففرح المسلمون به واجتمعوا في المساجدِ يتلون الآياتِ ويصلون التراويحَ ركعتين ركعتين وكان أبونا ذا نصيبٍ وافرٍ من الطاعات»: المسلمون: فاعل مرفوع بالواو. المساجد: مجرور بالكسرة لأل. يصلون: مضارع مرفوع بثبوت النون.","«وكان أبونا ذا نصيب»: أبونا: اسم كان مرفوع بالواو (من الأسماء الخمسة مضافًا إلى نا). ذا: خبر كان منصوب بالألف. نصيب: مضاف إليه مجرور بالكسرة.","«ويأمرُ بالمعروفِ وينهى عن المنكرِ ولا يضيعُ لهم وعدًا»: يأمر وينهى ويضيع: أفعال مضارعة مرفوعة؛ ينهى معتل الآخر مختوم بألف: مرفوع بالضمة المقدرة.","«جاء أخٌ كريم / جاء أخي / جاء أخوك / جاء أخواي... جاء أخوَيّ وإخوتي»: أخوك: فاعل مرفوع بالواو؛ أخي: فاعل مرفوع بالضمة المقدرة (ياء المتكلم).","تدريب التمييز: «نجح المجتهدون في الاختبار»: المجتهدون: فاعل مرفوع بالواو (اسم). و«المجتهدون ينجحون»: ينجحون: مضارع مرفوع بثبوت النون والواو فاعل (فعل). نفس الصورة وإعرابان مختلفان!","الخلاصة: سبعة أبواب للعلامات الفرعية اكتملت: الأسماء الخمسة، المثنى، جمع المذكر السالم، جمع المؤنث السالم (للنصب)، الممنوع من الصرف (للجر)، الأفعال الخمسة (ثبوت النون وحذفها)، والمضارع المعتل الآخر. وبهذا تمام أحكام الكلمة مفصلة؛ وندخل على أحكام الكلام من الدرس القادم."],"examples":["المسلمون فرحوا واجتمعوا في المساجد","كان أبونا ذا نصيب: أسماء خمسة","يأمر بالمعروف وينهى عن المنكر","أخي بالمقدرة وأخوك بالواو","المجتهدون ينجحون: اسم وفعل بصورة واحدة","سبعة أبواب فرعية اكتملت"],"questions":[{"question":"أعرب «المساجد» في «اجتمعوا في المساجد»:","options":["اسم مجرور وعلامة جره الكسرة لاقترانه بأل","مجرور بالفتحة","مرفوع","منصوب"],"answer":0,"explanation":"المساجد ممنوع من الصرف لكنه اقترن بأل فجر بالكسرة؛ والمنع للنكرة المجردة."},{"question":"أعرب «أبونا» في «كان أبونا ذا نصيب»:","options":["اسم كان مرفوع وعلامة رفعه الواو","مرفوع بالضمة","خبر كان","منصوب"],"answer":0,"explanation":"أبونا من الأسماء الخمسة مضافًا إلى نا (غير ياء المتكلم): مرفوع بالواو؛ وذا خبر منصوب بالألف."},{"question":"أعرب «ينهى» في «ينهى عن المنكر»:","options":["فعل مضارع مرفوع وعلامة رفعه الضمة المقدرة على الألف للتعذر","مرفوع بضمة ظاهرة","مجزوم","مبني"],"answer":0,"explanation":"ينهى معتل الآخر بالألف: مرفوع بالضمة المقدرة منع من ظهورها التعذر."},{"question":"أعرب «ينجحون» في «المجتهدون ينجحون»:","options":["فعل مضارع مرفوع وعلامة رفعه ثبوت النون والواو فاعل","اسم مرفوع بالواو","مبني","مجزوم بحذف النون"],"answer":0,"explanation":"ينجحون من الأفعال الخمسة: مرفوع بثبوت النون؛ والواو ضمير متصل في محل رفع فاعل."},{"question":"كم بابًا للعلامات الفرعية وما آخرها؟","options":["سبعة آخرها الأفعال الخمسة والمضارع المعتل","خمسة","عشرة","ثلاثة"],"answer":0,"explanation":"سبعة: خمسة من الأسماء (الخمسة والمثنى والجمعان والممنوع) واثنان من المضارعات (الأفعال الخمسة والمعتل)."}]}]},{"id":"wahi-sharh-070","title":"أحكام الكلام: الجملة الفعلية وصورتاها","section":"شرح الكتاب: أحكام الكلام مفصلًا - الجملة الفعلية","order":70,"segments":[{"body":["نبدأ الآن أحكام الكلام مفصلة، وهي كثيرة تُدرس في أربعة فصول: الجملة الفعلية، والجملة الاسمية، ومكملات الجملتين، وإعراب الفعل المضارع رفعًا ونصبًا وجزمًا.","المكملات ثلاثة أضرب: المنصوبات (المفاعيل الخمسة والحال والتمييز والمستثنى والمنادى)، والمجرورات (المجرور بالحرف والمجرور بالإضافة)، والتوابع (النعت والمعطوف والتوكيد والبدل). وسيأتي كل باب مفصلًا.","الجملة الفعلية: هي الجملة المبدوءة بفعل: حقيقة نحو: جلس أخي على الكرسي، ويصلح المسلم بين الناس. أو حكمًا نحو: على الكرسي جلس أخي، وبين الناس يصلح المسلم؛ لأن (على الكرسي) و(بين الناس) مقدمان من تأخير، والأصل: جلس أخي على الكرسي.","ومن الجملة الفعلية: هل ذهبت؟ وقد ذهبتْ، ولم يذهبْ: لأن الجملة بعد حرف الاستفهام أو قد أو لم جملة فعلية مبدوءة بفعل.","من أهم المهمات في طلب العلم أن يحرص الطالب على الإحاطة بصور المسألة ثم يدرسها صورة صورة؛ فبذلك يتقن المسألة ويستطيع إعادة كل فرع فيها إلى أصله بسهولة وسرعة.","والجملة الفعلية لها صورتان: إحداهما: تكون من فعل مبني للمعلوم وفاعل، فهذه الصورة مذكور فيها فاعل الفعل: قرأ المعلم القرآن، وصلى الإمام بالناس، وتكرم الشركة المهندسين، واحفظوا ما ينفعكم.","والأخرى: تكون من فعل مبني للمجهول ونائب فاعل، فهذه الصورة لم يذكر فيها فاعل الفعل وأنيب غيره منابه: قُرئ القرآنُ، وصُلي بالناس، ويُكرم المهندسون. وسندرس الصورتين في بابي الفاعل ونائب الفاعل."],"examples":["أحكام الكلام: أربعة فصول","المكملات: منصوبات ومجرورات وتوابع","الفعلية: مبدوءة بفعل حقيقة أو حكمًا","على الكرسي جلس أخي: حكمًا","صورتان: للمعلوم بفاعل وللمجهول بنائب","قُرئ القرآن: مبني للمجهول"],"questions":[{"question":"في كم فصل تدرس أحكام الكلام؟","options":["أربعة: الفعلية والاسمية والمكملات وإعراب المضارع","ثلاثة","عشرة","فصل واحد"],"answer":0,"explanation":"أربعة: الجملة الفعلية، الجملة الاسمية، مكملات الجملتين، إعراب الفعل المضارع."},{"question":"ما تعريف الجملة الفعلية؟","options":["الجملة المبدوءة بفعل حقيقة أو حكمًا","المبدوءة باسم","المبدوءة بحرف","كل جملة"],"answer":0,"explanation":"حقيقة: جلس أخي؛ وحكمًا: على الكرسي جلس أخي لأن شبه الجملة مقدم من تأخير والأصل فعلية."},{"question":"لماذا «على الكرسي جلس أخي» جملة فعلية مع أنها بدئت بشبه جملة؟","options":["لأن شبه الجملة مقدم من تأخير والأصل البدء بالفعل","لأنها اسمية","خطأ في التصنيف","لا سبب"],"answer":0,"explanation":"الأصل: جلس أخي على الكرسي؛ فالشبه جملة متعلق بالفعل مقدم عليه حكمًا لا حقيقة."},{"question":"ما صورتا الجملة الفعلية؟","options":["فعل للمعلوم مع فاعل، وفعل للمجهول مع نائب فاعل","ماض ومضارع","أمر ونهي","خبر وإنشاء"],"answer":0,"explanation":"إما مبني للمعلوم وفاعله مذكور (قرأ المعلم)، أو مبني للمجهول ونائب الفاعل منيب (قُرئ القرآن)."},{"question":"«تُكرم الشركة المهندسين» أي صورة؟","options":["فعل مبني للمعلوم وفاعل","مبني للمجهول","اسمية","شبه جملة"],"answer":0,"explanation":"الشركة فاعل مذكور مرفوع والمهندسين مفعول به: فالجملة من فعل للمعلوم وفاعل."}]},{"body":["تدريب: صنف الجمل: «هل ذهبتَ؟»: فعلية لأن ما بعد هل جملة فعلية (ذهبت). «قد حضر المعلمُ»: فعلية (قد حرف تحقيق والجملة بعده فعلية). «الله ربنا»: اسمية (بدئت باسم).","«في المسجدِ صلى المسلمون»: فعلية حكمًا؛ لأن (في المسجد) شبه جملة متعلقة بصلى مقدمة عليه؛ الأصل: صلى المسلمون في المسجد.","«يصلح المسلم بين الناس»: فعلية حقيقة: يصلح فعل مضارع مرفوع، والمسلم فاعل، وبين الناس جار ومجرور متعلق بيصلح.","«قُرئ القرآنُ»: فعلية صورتها الثانية: قُرئ فعل ماضٍ مبني للمجهول، والقرآن نائب فاعل مرفوع؛ لم يذكر من قرأ.","فائدة معرفة الصورتين: تعينك على الإعراب: فإن رأيت فعلًا للمعلوم بحثت عن فاعل، وإن رأيته للمجهول بحثت عن نائب فاعل؛ فلا تخلط بينهما.","الخلاصة: الجملة الفعلية مبدوءة بفعل حقيقة أو حكمًا، ولها صورتان: للمعلوم مع فاعل، وللمجهول مع نائب فاعل. والبابان القادمان يشرحان الصورتين."],"examples":["هل ذهبت: فعلية","في المسجد صلى المسلمون: فعلية حكمًا","يصلح المسلم بين الناس: فعلية حقيقة","قُرئ القرآن: للمجهول","للمعلوم ابحث عن فاعل","للمجهول ابحث عن نائب"],"questions":[{"question":"صنف: «قد حضر المعلم»:","options":["جملة فعلية حقيقة","اسمية","شبه جملة","حرفية"],"answer":0,"explanation":"قد حرف تحقيق؛ والجملة بعده فعلية: حضر فعل ماض والمعلم فاعل."},{"question":"«في المسجد صلى المسلمون» لماذا فعلية؟","options":["لأن شبه الجملة متعلق بالفعل مقدم عليه والأصل فعلية","لأنها اسمية","لا سبب","لأن في حرف"],"answer":0,"explanation":"الأصل: صلى المسلمون في المسجد؛ فهي فعلية حكمًا وشبه الجملة خبر مقدم... لا بل متعلق بصلى."},{"question":"أعرب «القرآن» في «قُرئ القرآن»:","options":["نائب فاعل مرفوع وعلامة رفعه الضمة","فاعل","مفعول به","مبتدأ"],"answer":0,"explanation":"قُرئ مبني للمجهول فلم يذكر فاعله؛ والقرآن أنيب منابه: نائب فاعل مرفوع."},{"question":"ما فائدة معرفة صورتي الجملة الفعلية؟","options":["تعين على البحث عن فاعل أو نائب فاعل بلا خلط","لا فائدة","للحفظ","للزينة"],"answer":0,"explanation":"الفعل للمعلوم يقتضي فاعلًا، وللمجهول يقتضي نائب فاعل؛ فلا تبحث عن فاعل في جملة للمجهول."},{"question":"«يُكرم المهندسون» أي صورة وما إعراب المهندسين؟","options":["للمجهول: نائب فاعل مرفوع بالواو","للمعلوم: فاعل","مفعول به","مبتدأ"],"answer":0,"explanation":"يُكرم مضارع مبني للمجهول (ضم أوله وكسر ما قبل آخره)؛ والمهندسون نائب فاعل مرفوع بالواو."}]}]},{"id":"wahi-sharh-071","title":"باب الفاعل: تعريفه وضابطه وأنواعه","section":"شرح الكتاب: باب الفاعل مفصلًا","order":71,"segments":[{"body":["باب الفاعل. تعريفه: «هو الاسم الذي أُسند إليه فعلٌ قبله». «الاسم»: أي أن الفاعل لا يكون إلا اسمًا، ولا يكون فعلًا ولا حرفًا ولا جملة ولا شبه جملة. «الذي أسند إليه فعل»: سواء فعل الفاعل هذا الفعل حقيقة أم لا.","فالفاعل الذي فعل الفعل حقيقة: صلى الإمام بالناس (الإمام فعل الصلاة حقيقة)، ويسافر المهندسون. والفاعل الذي لم يفعله حقيقة بل قام به: مات الرجلُ، وبنى الأمير المدينة.","ضابطه: أنه جواب قولنا: من الذي فعل الفعل؟ وأدق منه: من الذي أسند إليه الفعل؟ من الذي صلى؟ الإمام. من الذي يسافر؟ المهندسون. من الذي مات؟ الرجل. من الذي بنى المدينة؟ الأمير.","حكمه الإعرابي: حكم الفاعل الرفع: إن كان معربًا فهو مرفوع، وإن كان مبنيًّا فهو في محل رفع: قرأ إنسٌ القرآن (مرفوع بالضمة)، وتفرق سيبويه ففرح هؤلاء (فاعل في محل رفع مبني على الكسر)، وجاء الذين دعوتهم ثم عاد منهم أحدَ عشرَ رجلًا (فاعل في محل رفع مبني على الفتح).","أنواع الفاعل ثلاثة: ١- اسمًا ظاهرًا (أي ليس ضميرًا): قرأ إنسٌ القرآن، وحفظت بيانُ القرآن، وخشع هذا في صلاته، وصلى الذي بجانبي صلاة طويلة.","٢- ضميرًا بارزًا نحو: قرأنا القرآنَ (نا)، واقرؤوا القرآن (واو الجماعة)، والطالبان ذهبا ويذهبان واذهبا (ألف الاثنين: فاعل في محل رفع مبني على السكون)، والطلاب ذهبوا ويذهبون واذهبوا (واو الجماعة)، ولم ينجح إلا أنتَ وما سافر إلا هو (ضمائر منفصلة بعد إلا).","٣- ضميرًا مستترًا نحو: قرأ القرآنَ (تقديره هو)، واقرأ القرآن (أنت)، ونجتهد في دروسنا (نحن). وقاعدة الفاعل: «فحذرة العامة لكل فعل فاعل بعده إن ظهر وإلا فهو ضمير مستتر فهو فاعل: سواء أكان ماضيًا أم مضارعًا أم أمرًا». «بعده»: سبق أن الفعل قبل الفاعل فالفاعل بعد الفعل."],"examples":["الفاعل: اسم أسند إليه فعل قبله","سواء فعله حقيقة أم قام به","ضابطه: جواب من الذي فعل؟","حكمه الرفع معربًا أو مبنيًّا","أنواعه: ظاهر وضمير بارز ومستتر","القاعدة: لكل فعل فاعل بعده ظاهر أو مستتر"],"questions":[{"question":"ما تعريف الفاعل؟","options":["الاسم الذي أسند إليه فعل قبله","الاسم المجرور","كل ضمير","الفعل نفسه"],"answer":0,"explanation":"الفاعل اسم (لا فعل ولا حرف ولا جملة) أسند إليه فعل قبله؛ سواء فعله حقيقة (صلى الإمام) أو قام به (مات الرجل)."},{"question":"ما ضابط الفاعل؟","options":["جواب: من الذي أسند إليه الفعل؟","جواب: ماذا فعل؟","أول الجملة","آخر الجملة"],"answer":0,"explanation":"اسأل: من الذي فعل الفعل؟ فالجواب فاعل: من الذي صلى؟ الإمام؛ من الذي مات؟ الرجل."},{"question":"ما حكم الفاعل الإعرابي؟","options":["الرفع: مرفوع إن كان معربًا وفي محل رفع إن كان مبنيًّا","النصب","الجر","الجزم"],"answer":0,"explanation":"قرأ إنس: مرفوع بالضمة؛ وجاء هؤلاء: فاعل مبني على الكسر في محل رفع."},{"question":"ما أنواع الفاعل الثلاثة؟","options":["اسم ظاهر وضمير بارز وضمير مستتر","مفرد وجمع","مذكر ومؤنث","ماض وحاضر"],"answer":0,"explanation":"ظاهر: قرأ إنس؛ بارز: قرأنا وذهبا وذهب واذهبوا ولم ينجح إلا أنت؛ مستتر: قرأ (هو) واقرأ (أنت)."},{"question":"ما قاعدة الفاعل العامة؟","options":["لكل فعل فاعل بعده: إن ظهر فهو وإلا فضمير مستتر","لا فاعل للماضي","الفاعل دائمًا ظاهر","الفاعل قبل الفعل"],"answer":0,"explanation":"كل فعل (ماضٍ أو مضارع أو أمر) له فاعل بعده: ظاهر أو ضمير بارز أو مستتر."}]},{"body":["ضابط الفاعل بحسب فعله: فعل الأمر للمفرد فاعله ضمير مستتر تقديره (أنت): اذهب. فعل الأمر للمفردة فاعله الضمير البارز ياء المخاطبة: اذهبي. والأمر للجماعة فاعله واو الجماعة: اذهبوا، وللمثنى ألف الاثنين: اذهبا.","الفعل المضارع المبدوء بهمزة المتكلم فاعله ضمير مستتر تقديره (أنا): أذهبُ. والمبدوء بنون المتكلمين فاعله ضمير مستتر تقديره (نحن): نذهبُ. ففاعل المضارع المبدوء بهمزة أو بنون منحصر لا يتجاوز: ضمير مستتر.","يبقى: المضارع المبدوء بالياء (يذهب) والمبدوء بالتاء (تذهب) والماضي (ذهب): فهذه تحتاج تأملًا؛ لأن فاعلها يكون: اسمًا ظاهرًا: يذهب خالد وتذهب هند وذهب خالد. أو ضميرًا بارزًا: يذهبون وتذهبون وذهبوا. أو ضميرًا مستترًا: يذهب وتذهب وذهب (تقديره هو أو هي).","وأما إن سبق الفعلَ اسمٌ قبله فالفاعل مستتر والاسم مبتدأ: الطالبُ نجحَ: فاعل نجح ضمير مستتر تقديره هو، والطالب مبتدأ. هندُ تكتبُ: فاعل تكتب مستتر تقديره هي، وهند مبتدأ. جاء الطالبُ يركضُ: فاعل يركض مستتر تقديره هو، والطالب فاعل الفعل جاء.","إعراب ضمائر (تواني) منحصر في ثلاثة أعاريب: ١- أن تكون اسمًا لكان وأخواتها إذا اتصلت بها: كنت مسافرًا، كونوا إخوة، كوني واثقة. ٢- أن تكون نائب فاعل إذا اتصلت بفعل مبني للمجهول: هؤلاء قُتلوا... ٣- أن تكون فاعلًا فيما سوى ذلك أي إذا اتصلت بفعل مبني للمعلوم: آمنوا ويؤمنون وآمنوا، تدرسين واسمعي، سمعا وتسمعان واسمعا.","فضمائر تواني على كثرتها الكاثرة في الكلام لا يخرج إعرابها عن هذه الأعاريب الثلاثة، وقد نظمها المؤلف: «الواني فاعل ثم اسم كان نائب ثم...» أي: الأصل الفاعلية، ثم مع كان اسمها، ثم مع المجهول نائب فاعل."],"examples":["اذهب: فاعله أنت مستتر","أذهب: أنا؛ نذهب: نحن مستتران","يذهب وتذهب وذهب: تحتاج تأملًا","الطالب نجح: نجح فاعله هو والطالب مبتدأ","تواني: فاعل أو اسم كان أو نائب فاعل","الأصل الفاعلية"],"questions":[{"question":"ما فاعل فعل الأمر للمفرد «اذهب»؟","options":["ضمير مستتر تقديره أنت","ضمير بارز","اسم ظاهر","لا فاعل"],"answer":0,"explanation":"الأمر للمفرد فاعله مستتر تقديره أنت؛ وللمفردة الياء بارزة (اذهبي) وللجماعة الواو وللمثنى الألف."},{"question":"ما فاعل «أذهب» و«نذهب»؟","options":["ضمير مستتر: أنا ونحن","ضمير بارز","اسم ظاهر","لا فاعل"],"answer":0,"explanation":"المضارع المبدوء بهمزة المتكلم فاعله مستتر تقديره أنا؛ والمبدوء بنون المتكلمين تقديره نحن."},{"question":"«الطالب نجح» ما فاعل نجح؟","options":["ضمير مستتر تقديره هو والطالب مبتدأ","الطالب فاعل","لا فاعل","ضمير بارز"],"answer":0,"explanation":"سبق الفعلَ اسمٌ فالفعل فاعله مستتر يعود على المبتدأ: الطالب مبتدأ وجملة نجح خبره."},{"question":"في كم إعراب تنحصر ضمائر تواني؟","options":["ثلاثة: فاعل واسم كان ونائب فاعل","واحد","خمسة","سبعة"],"answer":0,"explanation":"فاعل مع المعلوم (آمنوا)، واسم كان مع الناسخ (كنت)، ونائب فاعل مع المجهول (قُتلوا)."},{"question":"أعرب الواو في «يؤمنون»:","options":["ضمير متصل مبني في محل رفع فاعل","علامة رفع","نائب فاعل","اسم كان"],"answer":0,"explanation":"يؤمنون مبني للمعلوم فالواو فاعل؛ والنون علامة الرفع؛ ولو كان مبنيًّا للمجهول لكانت الواو نائب فاعل."}]}]},{"id":"wahi-sharh-072","title":"باب نائب الفاعل: تعريفه وبناء الفعل للمجهول","section":"شرح الكتاب: باب نائب الفاعل مفصلًا","order":72,"segments":[{"body":["باب نائب الفاعل. تعريفه: «هو المفعول به بعد حذف الفاعل وبناء الفعل للمجهول».","كيف؟ خذ: قرأ الإمامُ القرآنَ: فعل ماضٍ وفاعل مرفوع ومفعول به منصوب. نحذف الفاعل (الإمام)، ونقيم المفعول به مقام الفاعل ونعطيه حكمه وهو الرفع، ونبني الفعل (قرأ) للمجهول فنقول: قُرئ. فتكون الجملة: قُرئ القرآنُ. قُرئ: فعل ماضٍ مبني للمجهول مبني على الفتح لا محل له من الإعراب. القرآن: نائب فاعل مرفوع بالضمة.","بناء الفعل للمجهول: يبنى الفعل الماضي والفعل المضارع للمجهول؛ وأما فعل الأمر فلا يبنى للمجهول.","الماضي: يبنى بضم أوله وكسر ما قبل آخره: قرأ - قُرئ... يعني قُرِئَ: ضمت القاف وكسرت الراء: كتب - كُتِب. وإن كان قبل آخره ألف قلبت ياء: باع - بِيع، وغاض - غِيض، وصام - صِيم، واختار - اختير، واتفق - اتفق.","المضارع: يبنى بضم أوله وكسر ما قبل آخره: يقرأ - يُقرأ، ويفتح - يُفتح، ويرمي - يُرمى، ويدحرج - يُدحرج، ويستخرج - يُستخرج. وإذا كان قبل آخره ياء أو واو قلبتا ألفًا: بيع - يُباع، ويصوم - يُصام، ويقول - يُقال، ويعيب - يُعاب.","حكمه الإعرابي: حكم نائب الفاعل الرفع: فإن كان معربًا فهو مرفوع وإن كان مبنيًّا فهو في محل رفع: أُكرم المهندسون (مرفوع بالواو)، وأُكرم هذا ويُنصح الذي يخطئ (مبنيان في محل رفع).","أنواعه: اسمًا ظاهرًا: قُرئ القرآن. وضميرًا بارزًا: الآيات تُتلى (تاء... نون النسوة نائب فاعل)، ورُزقتَ مولودًا ونحن أُكرمنا واللصوص أُخذوا والبيتان بِيعا. وضميرًا مستترًا: القرآن قُرئ (هو)، والباب فُتح، والحق أُخذ، والبيت بِيع، وهند كُرمت (هي)."],"examples":["نائب الفاعل: مفعول به بعد حذف الفاعل","قرأ الإمام القرآن → قُرئ القرآن","الماضي: ضم أوله وكسر ما قبل آخره","باع بيع وصام صيم: الألف ياء","المضارع: يقرأ يقرأ ويقول يقال","الأمر لا يبنى للمجهول"],"questions":[{"question":"ما تعريف نائب الفاعل؟","options":["المفعول به بعد حذف الفاعل وبناء الفعل للمجهول","الفاعل نفسه","المبتدأ","الحال"],"answer":0,"explanation":"حذف الفاعل وأقيم المفعول به مقامه وأعطي الرفع وبني الفعل للمجهول: قرأ الإمام القرآن → قُرئ القرآن."},{"question":"كيف يبنى الماضي للمجهول؟","options":["بضم أوله وكسر ما قبل آخره","بفتح أوله","بالسكون","بحذف أوله"],"answer":0,"explanation":"كتب كُتِب وقرأ قُرِئ؛ وإن كان قبل آخره ألف قلبت ياء: باع بيع وصام صيم."},{"question":"كيف يبنى المضارع للمجهول؟","options":["بضم أوله وكسر ما قبل آخره وقلب الواو والياء ألفًا","بالفتح","بالسكون","بحذف النون"],"answer":0,"explanation":"يقرأ يُقرأ؛ وإن كان قبل آخره واو أو ياء قلبتا ألفًا: يصوم يُصام ويقول يُقال."},{"question":"لماذا لا يبنى الأمر للمجهول؟","options":["لأن الأمر طلب موجه لا يستقيم مع حذف الفاعل","لأنه مبني","لأنه معرب","لا سبب"],"answer":0,"explanation":"يبنى الماضي والمضارع فقط للمجهول؛ وأما فعل الأمر فلا يبنى للمجهول."},{"question":"ما حكم نائب الفاعل وأنواعه؟","options":["الرفع؛ ويكون اسمًا ظاهرًا وضميرًا بارزًا ومستترًا","النصب","الجر","اسمًا ظاهرًا فقط"],"answer":0,"explanation":"مرفوع معربًا وفي محل رفع مبنيًّا: قُرئ القرآن (ظاهر)، وأُكرمنا (بارز)، وفُتح (مستتر هو)."}]},{"body":["مسألة: إن لم يكن في الجملة مفعول به فإنه ينوب عن الفاعل واحد من ثلاثة: ١- الجار والمجرور: جلس الطالبُ على الكرسي، فنقول: جُلس على الكرسي (فالجار والمجرور نابا). ٢- الظرف: صام المسلمون رمضانَ، فنقول: صِيمَ رمضانُ؛ وصليت خلف الإمام، فنقول: صُلي خلف الإمام. ٣- المفعول المطلق: قرأ المسلم قراءةً خاشعة، فنقول: قُرئت قراءةٌ خاشعةٌ (قراءة: نائب فاعل، وخاشعة: نعت مرفوع).","تدريبات الكتاب - استخراج الفاعل ونائب الفاعل: «قال ذا مالٍ وصديق وصنف»: ذا: فاعل (اسم إشارة مبني في محل رفع). «فكُسروا وكُسروا»: الواو نائب فاعل. «أعبدُ ما تعبدون»: ما موصولة... أعبد: فاعلها مستتر أنا.","تدريب الحذف: «فهم الطالبُ الدرسَ» احذف الفاعل وغير ما يلزم: فُهِمَ الدرسُ: فُهِم ماضٍ للمجهول، والدرس نائب فاعل مرفوع. «أكرمني الأستاذُ»: أُكرمتُ: بني للمجهول والتاء نائب فاعل (ضمير بارز في محل رفع). «تكرم الشركة المهندسين»: تُكرم المهندسون: نائب فاعل مرفوع بالواو. «أعان الرجلُ أخاك»: أُعين أخوك (من الأسماء الخمسة: نائب فاعل مرفوع بالواو).","«جلس الطالبُ أمام الأستاذ»: جُلس أمام الأستاذ (الظرف ناب). «جلس الطالب جلوسًا طويلًا»: جُلس جلوسٌ طويلٌ (المطلق ناب، وطويل نعت مرفوع).","متى نبني للمجهول؟ إذا أردنا إخفاء الفاعل لجهالة أو تعظيم أو تقبيح أو اختصار: «غُفر الذنبُ» (تعظيم الغافر) و«فُتح البابُ» (لا يهم من فتح).","الخلاصة: نائب الفاعل مفعول به أقيم مقام فاعله المحذوف، حكمه الرفع، والفعل يبنى للمجهول: الماضي بضم أوله وكسر ما قبل آخره، والمضارع كذلك مع قلب الواو والياء ألفًا؛ وإن لم يوجد مفعول ناب الجار والمجرور أو الظرف أو المفعول المطلق."],"examples":["جُلس على الكرسي: الجار والمجرور نابا","صِيم رمضان: الظرف ناب","قُرئت قراءة خاشعة: المطلق ناب","فُهم الدرس: تدريب الحذف","أُعين أخوك: نائب فاعل من الأسماء الخمسة","غُفر الذنب: إخفاء الفاعل"],"questions":[{"question":"إذا لم يوجد مفعول به فمن ينوب عن الفاعل؟","options":["الجار والمجرور أو الظرف أو المفعول المطلق","لا أحد","المبتدأ","الحال"],"answer":0,"explanation":"ثلاثة تنوب: جُلس على الكرسي (جار ومجرور)، صيم رمضان (ظرف)، قُرئت قراءة (مطلق)."},{"question":"حوّل «فهم الطالب الدرس» إلى المجهول:","options":["فُهِم الدرسُ: نائب فاعل مرفوع","فُهم الطالب","فهم الدرس","فَهِم الدرسَ"],"answer":0,"explanation":"حذف الفاعل (الطالب) وبني الفعل للمجهول (فُهِم) ورفع المفعول به: الدرس نائب فاعل مرفوع بالضمة."},{"question":"أعرب «أخوك» في «أُعين أخوك»:","options":["نائب فاعل مرفوع وعلامة رفعه الواو لأنه من الأسماء الخمسة","مفعول به منصوب","مضاف إليه","فاعل"],"answer":0,"explanation":"بني أُعين للمجهول فأقيم أخوك مقام الفاعل: نائب فاعل مرفوع بالواو؛ والكاف مضاف إليه."},{"question":"أعرب «قراءة» في «قُرئت قراءة خاشعة»:","options":["نائب فاعل مرفوع وخاشعة نعت مرفوع","مفعول مطلق منصوب","فاعل","حال"],"answer":0,"explanation":"المفعول المطلق ناب عن الفاعل: قراءة نائب فاعل مرفوع بالضمة، وخاشعة نعت مرفوع."},{"question":"لماذا نبني الفعل للمجهول أحيانًا؟","options":["لإخفاء الفاعل لجهالة أو تعظيم أو اختصار","للزينة فقط","لا سبب","للإطالة"],"answer":0,"explanation":"غُفر الذنب (تعظيم الغافر سبحانه)، فُتح الباب (لا يهم الفاعل): البناء للمجهول لحاجة الكلام."}]}]},{"id":"wahi-sharh-073","title":"الجملة الاسمية والمبتدأ والخبر","section":"شرح الكتاب: الجملة الاسمية مفصلًا - باب المبتدأ والخبر","order":73,"segments":[{"body":["الجملة الاسمية: هي الجملة المبدوءة باسم: حقيقة نحو: الله ربنا، ومحمد رسولنا، ومحمد جالس، وتحت الشجرة... بل: أنا أصلي في المسجد. أو حكمًا نحو: تحت الشجرة محمد جالس... لا: الأدق: (تحت الشجرة) و(في المسجد) مقدمان من تأخير في جملة بدئت بها حكمًا.","ومن الجملة الاسمية: هل زيد جالس؟ وما زيد جالس، ولزيد جالس: لأن الجملة بعد حرف الاستفهام أو النافية أو اللام جملة اسمية مبدوءة باسم.","والجملة الاسمية لها صورتان: إحداهما: الجملة الاسمية الأصلية غير المنسوخة وتكون من مبتدأ وخبر مرفوعين: العلم نافع. والأخرى: المنسوخة بدخول ناسخ: كان وأخواتها ترفع المبتدأ ويسمى اسمها وتنصب الخبر ويسمى خبرها: كان محمد كريمًا. وإن وأخواتها تنصب المبتدأ ويسمى اسمها وترفع الخبر ويسمى خبرها: إن محمدًا كريمٌ. وظننت وأخواتها تنصب المبتدأ مفعولًا به أول وتنصب الخبر مفعولًا به ثانيًا: ظننت محمدًا كريمًا.","تعريف المبتدأ: اسم مرفوع لم يسبق بعامل لفظي. والخبر: المسند إليه الذي يخبر به عن المبتدأ؛ والخبر لا يشترط فيه كونه اسمًا بل يكون اسمًا وجملة وشبه جملة.","والمراد بالعامل اللفظي ثلاثة أشياء: ١- الأفعال كلها. ٢- والحروف العاملة كحروف الجر وإن وأخواتها. ٣- والاسم المضاف (يعني: الاسم الذي يعمل عمل فعله كاسم الفاعل). فإذا وجدت اسمًا لم يسبق بشيء من هذه الثلاثة فهو مبتدأ؛ فإذا وجدت المبتدأ فابحث عن خبره: محمد قائم: (محمد) لم يسبق بعامل لفظي فهو مبتدأ؛ ثم اسأل: أخبر عن محمد بأنه ماذا؟ الجواب: بأنه قائم؛ إذن (قائم) هو الخبر.","حكمهما الإعرابي: حكمهما الرفع: إن كانا معربين فهما مرفوعان: العلم نافع: العلم مبتدأ مرفوع بالضمة، ونافع خبر مرفوع بالضمة. وإن كانا مبنيين فهما في محل رفع: هذا سيبويه: هذا مبتدأ في محل رفع مبني على السكون، وسيبويه خبر في محل رفع مبني على الكسر.","تدريبات: المسلم أمين: مبتدأ وخبر مرفوعان بالضمة. هو الفائز: هو مبتدأ في محل رفع مبني على الفتح، والفائز خبر مرفوع بالضمة."],"examples":["الاسمية: مبدوءة باسم حقيقة أو حكمًا","صورتان: أصلية ومنسوخة","النواسخ: كان وإن وظننت وأخواتها","المبتدأ: اسم مرفوع لم يسبق بعامل لفظي","العامل اللفظي: فعل أو حرف عامل أو اسم عامل","حكمهما الرفع"],"questions":[{"question":"ما تعريف الجملة الاسمية؟","options":["الجملة المبدوءة باسم حقيقة أو حكمًا","المبدوءة بفعل","المبدوءة بحرف","كل جملة"],"answer":0,"explanation":"الله ربنا (حقيقة)؛ وهل زيد جالس وما زيد جالس (الجملة بعد الحرف اسمية)؛ وحكمًا ما قدم فيه شبه الجملة."},{"question":"ما صورتا الجملة الاسمية؟","options":["أصلية غير منسوخة ومنسوخة بناسخ","فعلية واسمية","خبرية وإنشائية","طويلة وقصيرة"],"answer":0,"explanation":"أصلية: مبتدأ وخبر مرفوعان (العلم نافع)؛ ومنسوخة بدخول كان أو إن أو ظننت وأخواتها."},{"question":"ما تعريف المبتدأ؟","options":["اسم مرفوع لم يسبق بعامل لفظي","كل اسم أول الجملة","كل معرفة","الفعل الماضي"],"answer":0,"explanation":"اسم مرفوع لم يسبق بعامل لفظي (فعل أو حرف عامل أو اسم عامل)؛ فإن وجدته فابحث عن خبره."},{"question":"ما العامل اللفظي الذي يمنع الابتداء؟","options":["الأفعال كلها والحروف العاملة والاسم العامل","التنوين","أل","النداء"],"answer":0,"explanation":"ثلاثة: الأفعال (جاء محمد: فاعل لا مبتدأ)، والحروف العاملة (مررت بمحمد، إن محمدًا)، والاسم العامل كاسم الفاعل."},{"question":"أعرب «هذا سيبويه»:","options":["هذا مبتدأ مبني في محل رفع وسيبويه خبر مبني في محل رفع","مرفوعان بالضمة","منصوبان","مجروران"],"answer":0,"explanation":"كلاهما مبني: هذا على السكون وسيبويه على الكسر؛ وحكمهما الرفع فهما في محل رفع."}]},{"body":["تدريب على استخراج المبتدأ والخبر: «جاء أبوه كريمٌ»: (أبوه) سبقه الفعل جاء فهو فاعل لا مبتدأ. «في البيتِ محمدٌ»: (في البيت) شبه جملة فليست مبتدأ؛ (محمد) لم يسبق بعامل لفظي فهو مبتدأ، وأخبر عنه بأنه (في البيت) خبر مقدم.","«محمد ثوبه نظيف»: (محمد) مبتدأ؛ (ثوبه) ليس خبر محمد فلم نخبر عن محمد بأنه ثوبه؛ ثم ننظر فنجد (ثوبه) لم يسبق بعامل لفظي فهو مبتدأ ثانٍ وأخبر عنه بأنه (نظيف)؛ وأخبر عن محمد بالجملة الاسمية (ثوبه نظيف).","«قام رجل خُلقه كريم»: (رجل) اسم مسبوق بالفعل قام فليس مبتدأ بل فاعل... وخلقه مبتدأ وكريم خبره.","أنواع الخبر: ١- اسم مفرد (أي ليس جملة ولا شبه جملة): القمر زينةُ السماء، والقمر أصغر من الشمس، والنجوم كثيرة. ٢- شبه جملة (جار ومجرور أو ظرف): القمر في السماء، ومحمد عندك. ٣- جملة: فعلية: القمر يدير... يثير السماء، ومحمد نجح أخوه؛ واسمية: القمر نوره جميل، ومحمد أخوه ناجح.","مسألة حذف المبتدأ: يكثر حذف المبتدأ في العناوين وما في حكمها: الأخبار (أي هذه الأخبار)، المكتبة (هذه المكتبة)، مسجد الإيمان (هذا مسجد الإيمان)، جامعة الإمام (هذه جامعة الإمام)، تموينات فلان (هذه تموينات فلان)، زاد المعاد (هذا زاد المعاد)، كتاب الصلاة (هذا كتاب الصلاة)، فصل (هذا فصل).","مسألة تقديم الخبر: إذا كان الخبر شبه جملة فتقديمه على المبتدأ المعرفة كثير، وتقديمه على المبتدأ النكرة واجب: في البيت محمد ومحمد في البيت؛ في المسجد أخي وأخي في المسجد؛ في المدرسة المعلمون والطلاب والمعلمون والطلاب في المدرسة؛ في البيت رجل (واجب التقديم: لا تقول رجل في البيت في أول كلام)؛ في المسجد مصلون.","ويجوز تعدد الخبر: إنه لعزيز ذو انتقام: عزيز خبر أول مرفوع بالضمة، وذو خبر ثانٍ مرفوع بالواو لأنه من الأسماء الخمسة. جاري عالم يساعدني: عالم خبر أول مرفوع، ويساعدني جملة فعلية (فعل مضارع ونون الوقاية ومفعول به وفاعل مستتر) وهي خبر ثانٍ في محل رفع. ومحمد كريم رؤوف: خبران مرفوعان."],"examples":["جاء أبوه: أبوه فاعل لا مبتدأ","محمد ثوبه نظيف: مبتدآن","الخبر: مفرد أو شبه جملة أو جملة","العناوين: مبتدأ محذوف (هذا)","تقديم شبه الجملة على النكرة واجب","إنه لعزيز ذو انتقام: خبران"],"questions":[{"question":"«محمد ثوبه نظيف» ما إعراب ثوبه؟","options":["مبتدأ ثان ونظيف خبره والجملة خبر محمد","خبر محمد","نعت","مفعول به"],"answer":0,"explanation":"ثوبه لم يسبق بعامل لفظي: مبتدأ ثانٍ؛ نظيف خبره؛ والجملة الاسمية خبر المبتدأ الأول محمد."},{"question":"ما أنواع الخبر الثلاثة؟","options":["اسم مفرد وشبه جملة وجملة","مرفوع فقط","نكرة فقط","معرفة فقط"],"answer":0,"explanation":"مفرد: القمر زينة السماء؛ شبه جملة: القمر في السماء؛ جملة: القمر نوره جميل أو محمد نجح أخوه."},{"question":"ما تقدير «مسجد الإيمان» في العنوان؟","options":["هذا مسجد الإيمان: مبتدأ محذوف","مسجد مبتدأ","لا تقدير","خبر محذوف"],"answer":0,"explanation":"حذف المبتدأ يكثر في العناوين: التقدير هذا مسجد الإيمان؛ ومثله: الأخبار أي هذه الأخبار."},{"question":"متى يجب تقديم الخبر شبه الجملة؟","options":["إذا كان المبتدأ نكرة","مع المعرفة","دائمًا","أبدًا"],"answer":0,"explanation":"في البيت رجل: وجب التقديم؛ ومع المعرفة يجوز الوجهان: في البيت محمد ومحمد في البيت."},{"question":"أعرب «ذو» في «إنه لعزيز ذو انتقام»:","options":["خبر ثان مرفوع وعلامة رفعه الواو لأنه من الأسماء الخمسة","مبتدأ","نعت","مفعول به"],"answer":0,"explanation":"تعدد الخبر جائز: عزيز خبر أول بالضمة، وذو خبر ثان مرفوع بالواو مضاف إلى انتقام."}]}]},{"id":"wahi-sharh-074","title":"كان وأخواتها","section":"شرح الكتاب: باب كان وأخواتها مفصلًا","order":74,"segments":[{"body":["باب كان وأخواتها. ألفاظها: وهي ثلاثة عشر فعلًا: ١- كان نحو: كان الجدع... جبلًا. ٢- وأصبح نحو: أصبح النش... حمرة. ٣- وأضحى نحو: أضحى الولد مسرورًا. ٤- وظل نحو: ظل الرجل... قائمًا. ٥- وأمسى نحو: أمسى الرجل مهمومًا. ٦- وبات نحو: «يبيت جرحها». ٧- وصار نحو: صار الطين حجرًا.","٨- وليس نحو: ليست المسلمة مترجلة. ٩- وما زال نحو: «ولا يزالون مختلفين». ١٠- وما انفك نحو: ما انفك المطر هاطلًا. ١١- وما فتئ نحو: ما فتئ زيد منتظرًا. ١٢- وما برح نحو: «لا يزالون... لا يبرحون». ١٣- وما دام نحو: «ما دامت حياة».","عملها وإعرابها: وهي ترفع المبتدأ ويعرب اسمها، وتنصب الخبر ويعرب خبرها؛ وأما هي في نفسها فتعرب إعراب الفعل ماضيًا ومضارعًا وأمرًا. مثالها: كان البلال مؤذنًا: كان: فعل ماضٍ ناسخ مبني على الفتح لا محل له من الإعراب... (في التفصيل: فعل ماض ناسخ)، والبلال: اسم كان مرفوع، ومؤذنًا: خبر كان منصوب.","«ما زال صابرًا» و«صار مؤذنًا»: ما: حرف نفي مبني على السكون لا محل له. زال وصار: فعل ماضٍ ناسخ مبني على الفتح لا محل له، واسمها ضمير مستتر تقديره هو. صابرًا ومؤذنًا: خبر زال وصار منصوب بالفتحة.","«وتصير البنات أمهات»: تصير: فعل مضارع ناسخ مرفوع بالضمة. البنات: اسم تصير مرفوع بالضمة (جمع مؤنث سالم). أمهات: خبر تصير منصوب بالكسرة (جمع مؤنث سالم).","وقد يتأخر اسمها عنها: «كان الرجل مسرورًا» و«الرجل كان مسرورًا»: الفعل وإعرابه بحسب فعله... والتصريف: كن وكوني وكونا وكونوا وكنَّ وأكون ونكون وتكون ويكون وكان.","وكما أن الاسم والخبر في هذا الباب يجريان مجرى المبتدأ والخبر: فالاسم لا يكون إلا اسمًا، والخبر يكون اسمًا مفردًا (كان الرجل مسرورًا) وشبه جملة (كان الرجل في البيت) وجملة (كان الرجل يركض، كان الرجل أخوه كريم)."],"examples":["ثلاثة عشر فعلًا ناسخًا","كان وأصبح وأضحى وظل وأمسى وبات وصار","وليس وما زال وما انفك وما فتئ وما برح وما دام","ترفع المبتدأ اسمًا وتنصب الخبر خبرًا","تصير البنات أمهات: منصوب بالكسرة","خبرها: مفرد وشبه جملة وجملة"],"questions":[{"question":"كم عدد كان وأخواتها وما عملها؟","options":["ثلاثة عشر فعلًا ترفع المبتدأ اسمًا وتنصب الخبر خبرًا","خمسة","عشرة أحرف","ثلاثة"],"answer":0,"explanation":"كان وأصبح وأضحى وظل وأمسى وبات وصار وليس وما زال وما انفك وما فتئ وما برح وما دام: ترفع الاسم وتنصب الخبر."},{"question":"أعرب «كان» في «كان البلال مؤذنًا»:","options":["فعل ماض ناسخ مبني على الفتح لا محل له من الإعراب","مرفوع","حرف نسخ","مبتدأ"],"answer":0,"explanation":"كان ناسخ من قبل خط الإعراب: فعل ماض مبني على الفتح لا محل له؛ والبلال اسمها ومؤذنًا خبرها."},{"question":"أعرب «أمهات» في «تصير البنات أمهات»:","options":["خبر تصير منصوب وعلامة نصبه الكسرة","مرفوع بالضمة","فاعل","مجرور"],"answer":0,"explanation":"أمهات جمع مؤنث سالم خبر الناسخ: منصوب وعلامة نصبه الكسرة نيابة عن الفتحة."},{"question":"على ما يكون خبر كان؟","options":["اسمًا مفردًا وشبه جملة وجملة","اسمًا فقط","جملة فقط","ظرفًا فقط"],"answer":0,"explanation":"كان الرجل مسرورًا (مفرد)، كان الرجل في البيت (شبه جملة)، كان الرجل يركض / أخوه كريم (جملة)."},{"question":"هل يتأخر اسم كان عنها؟","options":["يجوز: كان الرجل مسرورًا والرجل كان مسرورًا","لا يجوز","يلزم التأخير","يلزم التقديم"],"answer":0,"explanation":"يجوز تقديم الاسم وتأخيره: كان الرجل مسرورًا = الرجل كان مسرورًا؛ والإعراب واحد."}]},{"body":["معاني كان وأخواتها: كان: للمطلق الماضي. أصبح وأضحى وظل وأمسى وبات: أفعال الأوقات: أصبح (في الصباح) وأضحى (في الضحى) وظل (النهار كله أو الاستمرار) وأمسى (في المساء) وبات (في الليل) - وتستعمل لمجرد الحدوث ولو بلا زمن.","صار: للتحول من حال إلى حال: صار الطين حجرًا، وتصير البنات أمهات. ليس: للنفي في الحاضر: ليست المسلمة مترجلة. وما زال وما انفك وما فتئ وما برح وما دام: للاستمرار مع النفي أو الشرط: ما زال صابرًا أي مستمر على الصبر.","تدريب تحويلي: «العلم نافع» أدخل كان: كان العلم نافعًا: العلم اسم كان مرفوع بالضمة، ونافعًا خبر كان منصوب بالفتحة. أدخل ليس: ليس العلم ثقيلًا... ليس العلمُ بلا فائدة: ليس فعل ماض ناسخ جامد للنفي، والعلم اسمها مرفوع.","«أمسى الجو جميلًا»: أمسى فعل ماض ناسخ مبني على الفتح، والجو اسمها مرفوع، وجميلًا خبرها منصوب. «بات الصائمون ساهرين»: بات ناسخ، والصائمون اسمها مرفوع بالواو، وساهرين خبرها منصوب بالياء.","تنبيه: كان وأخواتها تسمى الأفعال الناقصة؛ لأنها لا تكتفي بفاعلها بل تحتاج خبرًا: لا يتم المعنى بـ«كان العلم» حتى تقول «كان العلم نافعًا»؛ بخلاف الفعل التام: قام زيد.","الخلاصة: كان وأخواتها ثلاثة عشر فعلًا ناسخًا ترفع المبتدأ (اسمها) وتنصب الخبر (خبرها)، وتعرب هي إعراب الأفعال، واسمها وخبرها يجريان مجرى المبتدأ والخبر في الأنواع."],"examples":["أصبح وأمسى وبات: أفعال أوقات","صار: للتحول","ليس: نفي الحاضر","ما زال: للاستمرار","كان العلم نافعًا: تحويل من الأصل","ناقصة: تحتاج خبرًا"],"questions":[{"question":"ما معنى «صار» من بين الأخوات؟","options":["التحول من حال إلى حال","النفي","الاستمرار","الوقت"],"answer":0,"explanation":"صار للتحول: صار الطين حجرًا؛ وليس للنفي، وما زال وأخواتها للاستمرار، وأصبح وأخواتها للأوقات."},{"question":"أعرب «الصائمون» في «بات الصائمون ساهرين»:","options":["اسم بات مرفوع وعلامة رفعه الواو","خبر بات","فاعل بالضمة","منصوب"],"answer":0,"explanation":"الصائمون جمع مذكر سالم: اسم الناسخ بات مرفوع بالواو؛ وساهرين خبره منصوب بالياء."},{"question":"لماذا سميت كان وأخواتها أفعالًا ناقصة؟","options":["لأنها لا تكتفي باسمها بل تحتاج خبرًا","لأنها ناقصة الحروف","لأنها مبنية","لأنها حروف"],"answer":0,"explanation":"لا يتم المعنى بـ«كان العلم» حتى يأتي الخبر: كان العلم نافعًا؛ بخلاف التام: قام زيد."},{"question":"حوّل «الجو جميل» بإدخال أمسى:","options":["أمسى الجو جميلًا: الجو اسم أمسى مرفوع وجميلًا خبره منصوب","أمسى الجو جميل","الجو أمسى جميل","أمسى جميل الجو"],"answer":0,"explanation":"الناسخ ينصب الخبر: أمسى الجو جميلًا: اسم مرفوع وخبر منصوب."},{"question":"«ما زال صابرًا» ما اسم زال؟","options":["ضمير مستتر تقديره هو","صابر","ما","لا اسم"],"answer":0,"explanation":"ما حرف نفي، وزال فعل ناسخ واسمه مستتر تقديره هو، وصابرًا خبره منصوب."}]}]},{"id":"wahi-sharh-075","title":"إن وأخواتها","section":"شرح الكتاب: باب إن وأخواتها مفصلًا","order":75,"segments":[{"body":["باب إن وأخواتها. ألفاظها ومعانيها: وهي ستة أحرف: ١- (إنَّ وأنَّ) للتوكيد نحو: «إن لكل...» وعلمت أنك مجتهد. ٢- وكأن للتشبيه نحو: كأنه بدر... ٣- ولكن للاستدراك. ٤- وليت للتمني. ٥- ولعل للترجي في المحبوب نحو: لعل المطر هاطل، وللإشفاق في المكروه نحو: لعل العدو قريب.","عملها وإعرابها: وهي تنصب المبتدأ ويعرب اسمها، وترفع الخبر ويعرب خبرها؛ وأما هي في نفسها فتعرب إعراب الحروف: مبنية لا محل لها من الإعراب.","مثالها: إن نورًا جميلةٌ: إن: حرف توكيد ينصب اسمه ويرفع خبره، مبني على الفتح لا محل له من الإعراب. نورًا: اسم إن منصوب وعلامة نصبه الفتحة. جميلة: خبر إن مرفوع وعلامة رفعه الضمة.","«وكأنها بدر»: كأن: حرف تشبيه ينصب اسمه ويرفع خبره، مبني على الفتح لا محل له... و«ليت الصيف...»: الصيف: اسم ليت منصوب وعلامة نصبه الفتحة.","التفصيل في المعاني: إن وأن للتوكيد؛ وإن في أول الكلام وأن في وسطه بعد القول ونحوه: علمت أن العلم نافع. كأن للتشبيه: كأن محمدًا أسدٌ. لكن للاستدراك: خرج القوم لكن محمدًا مقيمٌ. ليت للتمني: ليت الشباب عائد. لعل للترجي في المحبوب وللإشفاق في المكروه.","خبر إن وأخواتها يجري مجرى خبر المبتدأ: يكون مفردًا وشبه جملة وجملة: إن العلم نافع (مفرد)، وإن المعلم في المدرسة (شبه جملة)، وإن الطالب يجتهد / أخوه مجتهد (جملة).","وقد تتقدم إن على جملة فعلية مع اللام: إن الله ليرحم... الأصل في بابها الجملة الاسمية، ودخولها على الفعلية لأحكام خاصة."],"examples":["ستة أحرف: إن وأن وكأن ولكن وليت ولعل","تنصب المبتدأ اسمًا وترفع الخبر خبرًا","إن للتوكيد وكأن للتشبيه ولكن للاستدراك","ليت للتمني ولعل للترجي والإشفاق","إن نورا جميلة: مثال معرب","خبرها مفرد وشبه جملة وجملة"],"questions":[{"question":"كم عدد إن وأخواتها وما عملها؟","options":["ستة أحرف تنصب المبتدأ اسمًا وترفع الخبر خبرًا","ثلاثة عشر","أربعة","عشرة"],"answer":0,"explanation":"إن وأن وكأن ولكن وليت ولعل: تنصب المبتدأ ويعرب اسمها وترفع الخبر ويعرب خبرها."},{"question":"ما معنى «لعل»؟","options":["الترجي في المحبوب والإشفاق في المكروه","التمني","التشبيه","الاستدراك"],"answer":0,"explanation":"لعل المطر هاطل (ترجٍّ)، ولعل العدو قريب (إشفاق)؛ وليت للتمني وكأن للتشبيه ولكن للاستدراك."},{"question":"أعرب «إن» في «إن نورًا جميلة»:","options":["حرف توكيد مبني على الفتح لا محل له من الإعراب","فعل ناسخ","مرفوع","حرف جر"],"answer":0,"explanation":"إن حرف ناسخ قبل خط الإعراب: مبني على الفتح لا محل له؛ نورًا اسمها منصوب، وجميلة خبرها مرفوع."},{"question":"ما الفرق بين «إن» و«أن»؟","options":["إن في أول الكلام وأن في وسطه بعد القول ونحوه","لا فرق","أن للتشبيه","إن للتمني"],"answer":0,"explanation":"إن تفتتح الكلام للتوكيد؛ وأن تأتي وسطًا: علمت أن العلم نافع؛ وكلتاهما للتوكيد."},{"question":"على ما يكون خبر إن وأخواتها؟","options":["مفردًا وشبه جملة وجملة","مفردًا فقط","شبه جملة فقط","جملة فقط"],"answer":0,"explanation":"إن العلم نافع (مفرد)، إن المعلم في المدرسة (شبه جملة)، إن الطالب يجتهد أو أخوه مجتهد (جملة)."}]},{"body":["تدريب تحويلي: «المطر منهمر» أدخل إن: إن المطر منهمرٌ: المطر اسم إن منصوب بالفتحة، ومنهمر خبر إن مرفوع بالضمة. أدخل ليت: ليت المطر منهمر. أدخل لعل: لعل المطر منهمر.","«كأن القمر مصباح»: كأن حرف تشبيه مبني على الفتح لا محل له؛ والقمر اسمها منصوب بالفتحة؛ ومصباح خبرها مرفوع بالضمة.","«لكن المجتهد ناجح»: لكن حرف استدراك مبني لا محل له؛ والمجتهد اسمها منصوب؛ وناجح خبرها مرفوع.","«ليت الشباب عائد»: ليت حرف تمنٍّ مبني لا محل له؛ والشباب اسمها منصوب؛ وعائد خبرها مرفوع.","تنبيه: إن وأخواتها تسمى الحروف الناسخة أو الحروف المشبهة بالفعل؛ لأنها تنصب كما ينصب الفعل، وتنصب اسمًا واحدًا وترفع آخر. وعملها عكس عمل كان: كان ترفع الأول وتنصب الثاني، وإن تنصب الأول وترفع الثاني.","الخلاصة: إن وأخواتها ستة أحرف ناسخة: إن وأن (توكيد)، كأن (تشبيه)، لكن (استدراك)، ليت (تمنٍّ)، لعل (ترجٍّ وإشفاق)؛ تنصب المبتدأ اسمها وترفع الخبر خبرها، وهي مبنية لا محل لها من الإعراب. والقادم: لا النافية للجنس وظن وأخواتها."],"examples":["إن المطر منهمر: اسم منصوب وخبر مرفوع","كأن القمر مصباح: تشبيه","لكن المجتهد ناجح: استدراك","ليت الشباب عائد: تمنٍّ","عكس كان: تنصب الأول وترفع الثاني","حروف مشبهة بالفعل"],"questions":[{"question":"حوّل «المطر منهمر» بإدخال لعل:","options":["لعل المطر منهمر: المطر اسم لعل منصوب ومنهمر خبرها مرفوع","لعل المطر منهمرًا","المطر لعل منهمر","لعل منهمر المطر"],"answer":0,"explanation":"لعل تنصب الاسم وترفع الخبر: المطر منصوب بالفتحة، ومنهمر مرفوع بالضمة."},{"question":"أعرب «القمر» في «كأن القمر مصباح»:","options":["اسم كأن منصوب وعلامة نصبه الفتحة","مرفوع","خبر","فاعل"],"answer":0,"explanation":"كأن حرف تشبيه ناسخ: القمر اسمها منصوب بالفتحة، ومصباح خبرها مرفوع بالضمة."},{"question":"ما معنى «لكن» وموقعها؟","options":["للاستدراك: خرج القوم لكن محمدًا مقيم","للتمني","للترجي","للتشبيه"],"answer":0,"explanation":"لكن للاستدراك: تستثني أو تستدرك ما بعدها عمّا قبلها؛ وتعمل عمل إن: تنصب الاسم وترفع الخبر."},{"question":"لماذا سميت إن وأخواتها مشبهة بالفعل؟","options":["لأنها تنصب كما ينصب الفعل","لأنها أفعال","لأنها أسماء","لأنها ترفع"],"answer":0,"explanation":"تعمل عمل الفعل في النصب مع كونها حروفًا: تنصب المبتدأ؛ فشبهت بالفعل."},{"question":"ما عكس عمل كان في باب إن؟","options":["كان ترفع الأول وتنصب الثاني وإن تنصب الأول وترفع الثاني","لا عكس","كلتاهما تنصبان","كلتاهما ترفعان"],"answer":0,"explanation":"كان العلم نافعًا (رفع الأول ونصب الثاني)؛ إن العلم نافع (نصب الأول ورفع الثاني): عكس تام."}]}]},{"id":"wahi-sharh-076","title":"لا النافية للجنس","section":"شرح الكتاب: باب لا النافية للجنس مفصلًا","order":76,"segments":[{"body":["مسألة لا النافية للجنس. تعمل لا النافية للجنس عمل إنَّ: تنصب المبتدأ ويعرب اسمها، وترفع الخبر ويعرب خبرها؛ وأن اسمها لا يُنوَّن؛ بأربعة شروط:","١- بشرط كون اسمها وخبرها نكرتين. ٢- وأن تتصل باسمها (لا يفصل بينهما). ٣- وألا تتفرق بغير فاء. ٤- وألا يزاد الباء في خبرها.","مثالها: لا كريمَ مذمومٌ: لا النافية للجنس: حرف نفي ينصب اسمه ويرفع خبره، مبني على السكون لا محل له من الإعراب. كريم: اسم لا النافية للجنس منصوب وعلامة نصبه الفتحة. مذموم: خبر لا النافية للجنس مرفوع وعلامة رفعه الضمة.","أمثلة بالعلامات الفرعية: «لا خطانِ متقاطعانِ متوازيين...»: الأدق: مكوا...: متوازيين: اسم لا النافية للجنس منصوب وعلامة نصبه الياء (مثنى)؛ ومقاطعان: خبر لا النافية للجنس مرفوع وعلامة رفعه الألف.","«لا مؤمنينَ كذابونَ»: مؤمنين: اسم لا منصوب وعلامة نصبه الياء (جمع مذكر سالم)؛ وكذابون: خبر لا مرفوع وعلامة رفعه الواو. «لا طالباتٍ مهملاتٌ»: طالبات: اسم لا منصوب وعلامة نصبه الكسرة (جمع مؤنث سالم)؛ ومهملات: خبر لا مرفوع بالضمة.","فإن كان اسم لا النافية للجنس معرفة أو لم تتصل باسمها بطل عملها وبقي الاسم على ما كان عليه قبل دخولها. «لا حول ولا قوة إلا بالله» تكرر: «لا قلم ولا مسطرة في الحقيبة».","سميت نافية للجنس لأنها تنفي الحكم عن الجنس كله: «لا إله إلا الله» تنفي الألوهية عن كل ما سوى الله؛ وليست كلا النافية العادية التي تنفي عن معين."],"examples":["تعمل عمل إن بأربعة شروط","لا كريم مذموم: اسم منصوب وخبر مرفوع","لا مؤمنين كذابون: بالياء والواو","لا طالبات مهملات: بالكسرة","الشرط: نكرتان متصلتان","لا إله إلا الله: نفي الجنس كله"],"questions":[{"question":"ما عمل لا النافية للجنس؟","options":["تنصب المبتدأ اسمها وترفع الخبر خبرها عمل إن","ترفع الاثنين","تنصب الاثنين","لا عمل لها"],"answer":0,"explanation":"تعمل عمل إن: تنصب الاسم وترفع الخبر؛ واسمها لا ينون بأربعة شروط."},{"question":"ما شروط عمل لا النافية للجنس؟","options":["كون اسمها وخبرها نكرتين واتصالها باسمها وعدم تفرقها وعدم زيادة الباء","لا شروط","كونهما معرفتين","الفصل بينهما"],"answer":0,"explanation":"أربعة: نكرتان، واتصال لا باسمها، ولا تتفرق بغير فاء، ولا تزاد الباء في خبرها."},{"question":"أعرب «مؤمنين» في «لا مؤمنين كذابون»:","options":["اسم لا النافية للجنس منصوب وعلامة نصبه الياء","مرفوع بالواو","فاعل","مبتدأ"],"answer":0,"explanation":"مؤمنين جمع مذكر سالم: اسم لا منصوب بالياء؛ وكذابون خبرها مرفوع بالواو."},{"question":"أعرب «طالبات» في «لا طالبات مهملات»:","options":["اسم لا منصوب وعلامة نصبه الكسرة","مرفوع بالضمة","مجرور","خبر"],"answer":0,"explanation":"طالبات جمع مؤنث سالم: اسم لا منصوب بالكسرة؛ ومهملات خبرها مرفوع بالضمة."},{"question":"متى يبطل عمل لا النافية للجنس؟","options":["إذا كان اسمها معرفة أو لم تتصل باسمها","إذا كان نكرة","دائمًا تعمل","إذا اتصلت"],"answer":0,"explanation":"يبطل عملها بمعرفة الاسم أو بانفصالها عنه؛ فإذا بطل عملها بقي الاسم على حكمه قبل دخولها."}]},{"body":["تدريب تحويلي: «كريمٌ محمودٌ»: أدخل لا النافية للجنس: لا كريمَ مذمومٌ ولا كريمَ محمودٌ... الأصل: نفي الجنس: لا كريمَ مذمومٌ = كل كريم غير مذموم.","«لا مسبِّبَ للأسبابِ إلا الله»: مسبب: اسم لا منصوب بالفتحة وهو مضاف؛ للأسباب: جار ومجرور متعلق بمسبب؛ وإلا أداة استثناء؛ والله مستثنى.","الفرق بين لا الناهية ولا النافية ولا النافية للجنس: الناهية تجزم المضارع: لا تكسلْ. والنافية لا تعمل: لا يكسلُ. والنافية للجنس تنصب الاسم النكرة وترفع خبره: لا كسلانَ ناجحٌ.","من فوائدها البيانية: إفادة العموم والاستغراق في النفي: «لا حول ولا قوة إلا بالله» نفي الحول والقوة عن كل أحد إلا بتوفيق الله؛ فهي أبلغ من لا النافية العادية.","تدريب بالأعلام: هل تعمل لا مع العلم؟ «لا محمدُ مذمومٌ»: لا تعمل لأن محمد معرفة؛ فيعرب محمد مبتدأ ولا نافية لا عمل لها... في هذا الباب يشترط النكرة.","الخلاصة: لا النافية للجنس حرف ينصب الاسم النكرة المتصل ويرفع خبره بشروط أربعة؛ واسمها لا ينون؛ وتنفي الجنس كله؛ وأمثلتها بالعلامات الأصلية والفرعية معروفة."],"examples":["لا كريم مذموم: نفي جنس","لا مسبب للأسباب إلا الله","ثلاث لاءات: ناهية ونافية ونافية للجنس","الاستغراق في النفي أبلغ","لا محمد مذموم: لا تعمل","اسمها لا ينون"],"questions":[{"question":"ما الفرق بين لا النافية ولا النافية للجنس؟","options":["النافية لا تعمل والنافية للجنس تنصب الاسم وترفع الخبر","لا فرق","النافية تنصب","النافية للجنس تجزم"],"answer":0,"explanation":"لا يكسل: نافية لا عمل لها؛ لا كسلان ناجح: نافية للجنس تنصب الاسم وترفع الخبر."},{"question":"ماذا تفيد لا النافية للجنس بلاغيًّا؟","options":["العموم والاستغراق في نفي الجنس كله","نفي معين","التخصيص","الإثبات"],"answer":0,"explanation":"لا إله إلا الله: نفي الألوهية عن كل ما سواه؛ فهي أبلغ من نفي معين."},{"question":"«لا مسبِّب للأسباب إلا الله» ما إعراب مسبب؟","options":["اسم لا النافية للجنس منصوب بالفتحة مضاف","فاعل","مبتدأ مرفوع","مجرور"],"answer":0,"explanation":"مسبب اسم لا منصوب بالفتحة وهو مضاف؛ والأسباب مضاف إليه؛ وإلا أداة استثناء والله مستثنى."},{"question":"هل ينون اسم لا النافية للجنس؟","options":["لا ينون بشروط العمل","ينون دائمًا","ينون أحيانًا","لا يقبل الحركات"],"answer":0,"explanation":"شرط من شروط عملها أن اسمها لا ينون: لا كريم مذموم بلا تنوين."},{"question":"«لا كسلان ناجح» ما إعراب ناجح؟","options":["خبر لا النافية للجنس مرفوع بالضمة","اسم لا","نعت","حال"],"answer":0,"explanation":"كسلان اسم لا منصوب؛ وناجح خبرها مرفوع بالضمة؛ والمعنى: كل كسلان غير ناجح."}]}]},{"id":"wahi-sharh-077","title":"ظننت وأخواتها","section":"شرح الكتاب: باب ظننت وأخواتها مفصلًا","order":77,"segments":[{"body":["باب ظننت وأخواتها. ألفاظها: وهي أفعال كثيرة بمعنى الظن أو العلم أو التصيير.","منها بلفظ الظن: ظن نحو: ظننت الفرج قريبًا. وبمعناه: حسب نحو: حسبتك صديقًا. وخال نحو: خال المهمل النجاح هينًا. ومنها بمعنى العلم: علم نحو: يعلم المسلم الصدق منجيًا. وبمعناه: رأى نحو: رأيت العلم نافعًا. ووعد نحو: يعد المؤمن الصلاح سر النجاح. وألفى نحو: ألفينا حائرًا. ومنها بمعنى التصيير: صيَّر نحو: صيِّر الصلصال تُحفة. وبمعناها: جعل نحو: «ما تثعب... تدعيًا»، واتخذ نحو: «واتخذ...». ","عملها وإعرابها: وهي تنصب المبتدأ ويعرب مفعولًا به أول، وتنصب الخبر ويعرب مفعولًا به ثانيًا؛ وأما هي في نفسها فتعرب إعراب الفعل ماضيًا ومضارعًا وأمرًا. وهي لا تعمل على المبتدأ والخبر حتى تتوفر فاعلها.","مثالها: «ظن قيسٌ معاذًا مسافرًا»: ظن: فعل ماضٍ ينصب مفعولين مبني على الفتح لا محل له من الإعراب. قيس: فاعل مرفوع. معاذًا: مفعول به أول منصوب. مسافرًا: مفعول به ثانٍ منصوب.","«حسبتك صديقًا»: حسب: فعل ماضٍ ينصب مفعولين مبني على الفتح المقدر لا محل له. التاء: تاء المتكلم وهو فاعل في محل رفع مبني على الضم. الكاف: كاف المخاطب وهو مفعول به أول في محل نصب مبني على الفتح. صديقًا: مفعول به ثانٍ منصوب بالفتحة.","«وعلمت الله عظيمًا»: تاء المتكلم: فاعل في محل رفع مبني على الضم. اسم الله: مفعول به أول منصوب بالفتحة. عظيمًا: مفعول به ثانٍ منصوب بالفتحة. و«ألفى حائرًا»: ألفى: فعل ماضٍ ينصب مفعولين مبني على الفتح المقدر...","«السواك يجعل فاك نظيفًا»: السواك: مبتدأ مرفوع بالضمة. يجعل: فعل مضارع مرفوع وفاعله مستتر تقديره هو يعود إلى السواك؛ والفعل والفاعل خبر المبتدأ في محل رفع. فاك: مفعول به أول منصوب بالألف لأنه من الأسماء الخمسة وهو مضاف والكاف مضاف إليه في محل جر مبني على الفتح. نظيفًا: مفعول به ثانٍ منصوب بالفتحة.","ويجوز في هذا الباب أن تسد (أنَّ) ومعمولاها (اسمها وخبرها) مسد المفعولين الأول والثاني: ظننت أن معاذًا مسافرٌ، وعلم الطالب أن العلم نافعٌ: فنقول: أن ومعمولاها سدت مسد المفعولين."],"examples":["أفعال بمعنى الظن والعلم والتصيير","تنصب المبتدأ والخبر مفعولين","ظن قيس معاذًا مسافرًا","حسبتك صديقًا","السواك يجعل فاك نظيفًا","أن ومعمولاها تسد مسد المفعولين"],"questions":[{"question":"ما ألفاظ ظننت وأخواتها؟","options":["ظن وحسب وخال وعلم ورأى ووعد وألفى وصير وجعل واتخذ","كان وأصبح","إن وأن","لم ولما"],"answer":0,"explanation":"أفعال بمعنى الظن (ظن وحسب وخال) وبمعنى العلم (علم ورأى ووعد وألفى) وبمعنى التصيير (صير وجعل واتخذ)."},{"question":"ما عمل ظننت وأخواتها؟","options":["تنصب المبتدأ مفعولًا به أول والخبر مفعولًا به ثانيًا","ترفع الاثنين","تنصب المبتدأ وترفع الخبر","لا تعمل"],"answer":0,"explanation":"عكس إن تمامًا: تنصب الاثنين: المبتدأ مفعول أول والخبر مفعول ثانٍ؛ ولا تعمل حتى تتوفر فاعلها."},{"question":"أعرب «صديقًا» في «حسبتك صديقًا»:","options":["مفعول به ثان منصوب وعلامة نصبه الفتحة","خبر مرفوع","حال","تمييز"],"answer":0,"explanation":"حسب ينصب مفعولين: الكاف مفعول أول، وصديقًا مفعول به ثانٍ منصوب بالفتحة."},{"question":"أعرب «فاك» في «السواك يجعل فاك نظيفًا»:","options":["مفعول به أول منصوب وعلامة نصبه الألف لأنه من الأسماء الخمسة","مرفوع بالواو","فاعل","مبتدأ"],"answer":0,"explanation":"فو من الأسماء الخمسة ينصب بالألف: فاك مفعول أول؛ والكاف مضاف إليه؛ ونظيفًا مفعول ثانٍ."},{"question":"ما موضع «أن معاذًا مسافر» في «ظننت أن معاذًا مسافر»؟","options":["أن ومعمولاها سدت مسد المفعولين","فاعل","مبتدأ","حال"],"answer":0,"explanation":"يجوز أن تسد أن ومعمولاها (اسمها وخبرها) مسد المفعولين: ظننت أن معاذًا مسافر = ظننت معاذًا مسافرًا."}]},{"body":["الفرق بين النواسخ الثلاثة في الجملة الاسمية: كان ترفع الأول (اسمها) وتنصب الثاني (خبرها): كان العلم نافعًا. إن تنصب الأول وترفع الثاني: إن العلم نافع. ظن تنصبهما معًا: ظننت العلم نافعًا. فاحفظ: رفع ونصب، ثم نصب ورفع، ثم نصب ونصب.","تصريف أفعال الباب: هي أفعال تامة التصريف ماضيًا ومضارعًا وأمرًا: ظن يظن اظنن... وتعمل في أحوالها الثلاث إذا توفر فاعلها.","متى تتعدد المفاعيل؟ هذه الأفعال متعدية إلى مفعولين أصلهما المبتدأ والخبر؛ فإذا وردت في نص فارجعهما إلى الأصل لتفهم: «رأيت العلم نافعًا» = العلم نافع.","تدريب: «وجدت الصدق منجيًا»: وجد (ألفى) ينصب مفعولين: الصدق مفعول أول، ومنجيًا مفعول ثانٍ. و«اتخذ الله إبراهيم خليلًا»: إبراهيم مفعول أول، وخليلًا مفعول ثانٍ.","تنبيه: قد تأتي هذه الأفعال لازمة أو بمعنى آخر فلا تعمل عمل بابها: «علم بالدرس»... الميزان المعنى: إن كان بمعنى الظن أو العلم القلبي أو التصيير ونصب مفعولين أصلهما مبتدأ وخبر فهو من هذا الباب.","الخلاصة: ظننت وأخواتها أفعال تنصب المبتدأ والخبر مفعولين، ألفاظها بمعانٍ ثلاثة (ظن وعلم وتصيير)، ويجوز أن تسد أن ومعمولاها مسد المفعولين، وبهذا تمت نواسخ الجملة الاسمية."],"examples":["كان: رفع ونصب؛ إن: نصب ورفع؛ ظن: نصب ونصب","تعمل في الأزمنة الثلاثة","ارجع المفعولين إلى مبتدأ وخبر","وجدت الصدق منجيًا","اتخذ الله إبراهيم خليلًا","المعنى ميزان العمل"],"questions":[{"question":"لخص عمل النواسخ الثلاثة:","options":["كان: رفع ونصب؛ إن: نصب ورفع؛ ظن: نصب ونصب","كلها نصب","كلها رفع","لا فرق"],"answer":0,"explanation":"كان ترفع الاسم وتنصب الخبر؛ إن بالعكس؛ وظن تنصبهما معًا مفعولين أصلهما مبتدأ وخبر."},{"question":"«وجدت الصدق منجيًا» ما إعراب الصدق ومنجيًا؟","options":["الصدق مفعول أول ومنجيًا مفعول ثانٍ منصوبان","مبتدأ وخبر","فاعل ومفعول","نعت وحال"],"answer":0,"explanation":"وجد بمعنى ألفى من أخوات ظن: ينصب مفعولين أصلهما: الصدق منجي (مبتدأ وخبر)."},{"question":"متى تعمل أفعال هذا الباب عملها؟","options":["إذا تولى فاعلها وتعدت إلى مفعولين أصلهما مبتدأ وخبر","دائمًا","في الماضي فقط","إذا جرت"],"answer":0,"explanation":"لا تعمل على المبتدأ والخبر حتى تتوفر فاعلها؛ ويعتبر معناها: ظن أو علم أو تصيير."},{"question":"ما أصل «رأيت العلم نافعًا»؟","options":["العلم نافع (مبتدأ وخبر)","لا أصل","جملة فعلية","استثناء"],"answer":0,"explanation":"المفعولان أصلهما المبتدأ والخبر: العلم نافع؛ نسختهما رأى فنصبتهما."},{"question":"أعرب «خليلًا» في «اتخذ الله إبراهيم خليلًا»:","options":["مفعول به ثان منصوب بالفتحة","نعت","حال","بدل"],"answer":0,"explanation":"اتخذ من أخوات ظن: إبراهيم مفعول أول منصوب (بالفتحة المقدرة: ممنوع من الصرف)، وخليلًا مفعول ثانٍ."}]}]},{"id":"wahi-sharh-078","title":"باب المكملات والمفعول به","section":"شرح الكتاب: باب المكملات - المفاعيل: المفعول به مفصلًا","order":78,"segments":[{"body":["باب المكملات: وهي مكملات يؤتى بها بعد اكتمال ركني الجملتين الفعلية والاسمية. فالجملة الفعلية لها ركنان: الفعل (مبني للمعلوم أو للمجهول) ومرفوعه (فاعل أو نائب فاعل)؛ والجملة الاسمية لها ركنان: المبتدأ وخبره. فما سوى تلك الأركان يسمى مكملات.","وهذه المكملات ثلاثة أضرب: منصوبات وهي: المفاعيل الخمسة والحال والتمييز والمستثنى والمنادى. ومجرورات وهي: المجرور بالحرف والمجرور بالإضافة. وتوابع وهي: النعت والمعطوف والتوكيد والبدل.","المفاعيل خمسة: المفعول به، والمفعول فيه، والمفعول له، والمفعول معه، والمفعول المطلق. وكلها حكمها النصب: فإن كانت معربة فمنصوبة وإن كانت مبنية ففي محل نصب. وقد جمعها الشبراوي في لاميته بالأمثلة: «شربت ضرب عمرًا ...».","باب المفعول به. تعريفه: هو الاسم الدال على الذي وقع عليه الفعل: قرأت الكتاب: فالكتاب مفعول به؛ لأنه اسم يبين الذي وقعت القراءة عليه. و«قرأته»: فالهاء مفعول به؛ لأنها اسم يبين الذي وقعت القراءة عليه.","ضابطه: أنه جواب قولنا: على ماذا وقع الفعل؟ فتح الحارس الباب: على ماذا وقع الفعل فتح؟ على الباب فهو مفعول به، والحارس هو الفاعل. يقرأ أخي القرآن: على ماذا وقع الفعل يقرأ؟ على القرآن. يأكل التفاحة الولد: على التفاحة فهي مفعول به مقدم والولد فاعل مؤخر. أكرمتك: على المخاطب الذي تدل عليه الكاف.","وهناك ضابط آخر للمفعول به والفاعل: أن تسأل: من الفاعل والمفعول؟ من الفاتح؟ الحارس. وما المفتوح؟ الباب. من القارئ؟ أخي. وما المقروء؟ القرآن. من الآكل؟ الولد. وما المأكول؟ التفاحة.","حكمه الإعرابي: المفعول به حكمه النصب: فإن كان معربًا فهو منصوب وإن كان مبنيًّا فهو في محل نصب: «وأحب نورًا»: مفعول به منصوب بالفتحة. و«الصر... أعال»: مفعول به منصوب وعلامة نصبه الألف لأنه من الأسماء الخمسة. أكرمت محمدًا: بالفتحة. أكرمتك: الكاف كاف المخاطب وهو مفعول به في محل نصب مبني على الفتح."],"examples":["المكملات: ما سوى أركان الجملتين","أضربها: منصوبات ومجرورات وتوابع","المفاعيل خمسة كلها منصوبة","المفعول به: من وقع عليه الفعل","الضابط: على ماذا وقع الفعل؟","من الفاعل وما المفعول؟"],"questions":[{"question":"ما المكملات؟","options":["ما يؤتى به بعد اكتمال ركني الجملتين","أركان الجمل","الأفعال","الحروف"],"answer":0,"explanation":"الفعلية ركناها الفعل ومرفوعه، والاسمية المبتدأ والخبر؛ فما سوى ذلك مكملات: منصوبات ومجرورات وتوابع."},{"question":"ما المفاعيل الخمسة؟","options":["به وفيه وله ومعه والمطلق","الفاعل ونائبه","المبتدأ والخبر","الحال والنعت"],"answer":0,"explanation":"خمسة: المفعول به والمفعول فيه والمفعول له والمفعول معه والمفعول المطلق؛ وكلها منصوبة."},{"question":"ما تعريف المفعول به وضابطه؟","options":["الاسم الدال على من وقع عليه الفعل؛ جواب: على ماذا وقع الفعل؟","جواب: من فعل؟","جواب: متى؟","جواب: لماذا؟"],"answer":0,"explanation":"قرأت الكتاب: الكتاب مفعول به؛ اسأل: على ماذا وقعت القراءة؟ فالجواب هو المفعول به."},{"question":"أعرب «التفاحة» في «يأكل التفاحة الولد»:","options":["مفعول به مقدم منصوب والولد فاعل مؤخر","فاعل","مبتدأ","حال"],"answer":0,"explanation":"يجوز تقديم المفعول على الفاعل: التفاحة مفعول به منصوب بالفتحة؛ والولد فاعل مرفوع بالضمة."},{"question":"أعرب الكاف في «أكرمتك»:","options":["كاف المخاطب مفعول به في محل نصب مبني على الفتح","فاعل","مضاف إليه","اسم إن"],"answer":0,"explanation":"الكاف ضمير متصل من (هيك) اتصل بفعل: مفعول به في محل نصب؛ والتاء فاعل."}]},{"body":["ضابط إعراب ضمائر (هيك): ضمائر النصب والجر المتصلة (هيك) هي: ياء المتكلم وكاف المخاطب وهاء الغائب. ولها أربعة أعاريب: اثنان في النصب: ١- مفعول به إذا اتصلت بفعل نحو: أكرمني، يعرفك. ٢- اسم إن وأخواتها إذا اتصلت بها نحو: إني، إنك، إنه. واثنان في الجر: ٣- مضاف إليه إذا اتصل باسم نحو: كتابي وكتابك. ٤- مجرور بحرف الجر... متصل بحرف نحو: بي وبك وبه. وقلما تخرج عن الأربعة.","ضابط إعراب (إياي وأخواتها): ضمائر النصب المنفصلة ثلاثة: إياي وإياك وإياه وفروعها؛ قلما يخرج إعرابها عن كونها مفعولًا به: «إياك نعبد وإياك نستعين»: إياك: مفعول به مقدم والأصل: نعبدك ونستعينك. و«بل إياه تدعون»: مفعول به مقدم والأصل: تدعونه. و«إياك أعني»: مفعول به مقدم.","«يحفظني الله»: على ماذا وقع الفعل يحفظ؟ على المتكلم الذي تدل عليه ياء المتكلم؛ فياء المتكلم مفعول به مقدم، واسم الله هو الفاعل.","تدريب التمييز بين الفاعل والمفعول بالضمائر: «أكرمني أخوك»: الياء مفعول به (المتكلم مُكرَّم) وأخوك فاعل. و«أكرمتك»: التاء فاعل والكاف مفعول به. الضمير نفسه قد يكون فاعلًا أو مفعولًا بحسب الفعل!","فائدة: الضابط الثاني (من الفاعل وما المفعول) يعين في المشتبهات: من المكرِم؟ ومن المكرَّم؟ من الحافظ؟ الله. من المحفوظ؟ المتكلم.","الخلاصة: المفعول به أشهر المفاعيل: من وقع عليه الفعل، حكمه النصب، ويقدم ويؤخر، وضمائر هيك أعاريبها أربعة (مفعول به، اسم إن، مضاف إليه، مجرور بحرف)، وإياي وأخواتها مفعول به في الغالب."],"examples":["هيك: أربعة أعاريب","أكرمني: مفعول به؛ إني: اسم إن","كتابي: مضاف إليه؛ بي: مجرور بحرف","إياك نعبد: مفعول مقدم","يحفظني الله: الياء مفعول والله فاعل","الضمير فاعل أو مفعول بحسب الفعل"],"questions":[{"question":"ما أعاريب ضمائر هيك الأربعة؟","options":["مفعول به واسم إن ومضاف إليه ومجرور بحرف الجر","فاعل فقط","مبتدأ وخبر","نعت وحال"],"answer":0,"explanation":"اتصلت بفعل فمفعول به (أكرمني)، وبإن فاسمها (إني)، وباسم فمضاف إليه (كتابي)، وبحرف جر فمجرور (بي)."},{"question":"ما إعراب إياي وأخواتها في الغالب؟","options":["مفعول به","فاعل","مبتدأ","خبر"],"answer":0,"explanation":"ضمائر النصب المنفصلة قلما تخرج عن كونها مفعولًا به: إياك نعبد (مقدم والأصل نعبدك)."},{"question":"أعرب الياء في «يحفظني الله»:","options":["ياء المتكلم مفعول به مقدم والله فاعل","فاعل","مضاف إليه","اسم إن"],"answer":0,"explanation":"الياء تدل على من وقع عليه الحفظ: مفعول به؛ واسم الله فاعل مرفوع بالضمة... اسم (الله) فاعل."},{"question":"أعرب «إني» في «إني مجتهد»:","options":["ياء المتكلم اسم إن في محل نصب","مفعول به","فاعل","مضاف إليه"],"answer":0,"explanation":"اتصلت الياء بإن فهي اسمها في محل نصب؛ ومجتهد خبر إن مرفوع."},{"question":"أعرب «هم» في «سلمت عليهم»:","options":["هاء الغائب اسم مجرور بحرف الجر في محل جر","مفعول به","فاعل","اسم إن"],"answer":0,"explanation":"اتصلت الهاء بحرف الجر على: ضمير متصل مبني في محل جر اسم مجرور بعلى."}]}]},{"id":"wahi-sharh-079","title":"ظرفا الزمان والمكان (المفعول فيه)","section":"شرح الكتاب: باب الظرفين الزمان والمكان مفصلًا","order":79,"segments":[{"body":["باب الظرفين (المفعول فيه): وهما ظرف الزمان وظرف المكان؛ وتعريف الظرف: هو الاسم الذي يذكر زمان الفعل أو مكانه؛ سمي مفعولًا فيه لأنه يجري مجرى (في) وما يتعلق بها.","ظرف الزمان: وهو الاسم الذي يدل على زمان وقوع الفعل بمعنى (في)، وضابطه: أنه جواب قولنا: متى وقع الفعل؟ نحو: صليت الفجر: متى صليت؟ في الفجر، فالفجر ظرف زمان. و«استلمت تكليف... الإمام...»: العصر ظرف زمان. «ختمت القرآن يوم الجمعة»: يوم ظرف زمان.","ومنه يوم وليلة وشهر وسنة وصباح ومساء وأمس وغد وأسبوع وصلاة كما في حديث: «بين المغرب والعشاء».","أمثلة: «يجتهد الطالب صباحًا ومساءً»: صباح ظرف زمان منصوب وعلامة نصبه الفتحة؛ ومساء معطوف منصوب. «تعمل في مدرسة... نهارًا»: نهار ظرف زمان. «استيقظت الساعة السادسة»: الساعة ظرف زمان منصوب بالفتحة وهو مضاف والسادسة نعت له...","ظرف المكان: وهو الاسم المبهم الدال على مكان وقوع الفعل، وضابطه: أنه جواب قولنا: أين وقع الفعل؟ نحو: تعالي معنا السبت: أين؟ (المكان المذكور)؛ والضابط: اسم يدل على مكان يجري مجرى في بمعنى في.","«وقد صلى... قدام...»: قدام ظرف مكان منصوب بالفتحة. «وأتصل...»: عند ظرف مكان... «وقفت أمام المحاضر»: أمام ظرف مكان. «وقفت وراء الطابور»: وراء ظرف مكان. «انتظرتك أمام المسجد»: أمام ظرف مكان.","ومن أسماء المكان يمين وشمال وتحت وفوق وخلف وأمام وداخل وخارج... و«غدًا إن شاء الله»: غد ظرف زمان... ولا ينتصب على الظرفية من أسماء المكان إلا المبهم (لا المسجد ولا بيت: فهما يجوز فيهما الجر بالحرف).","ومنها أسماء المقادير: متر وكيلو...: «قطعت مسافة كيلو...»: الظرف... وأقرب أحكامهما: ظرف الزمان اسم يدل على الزمان وظرف المكان اسم مبهم يدل على المكان يجريان مجرى في بمعنى في."],"examples":["الظرف: زمان الفعل أو مكانه","ضابط الزمان: متى وقع الفعل؟","يوم وليلة وشهر وصباح ومساء","ضابط المكان: أين؟ وشرطه الإبهام","يمين وشمال وفوق وتحت وقدام ووراء","استيقظت الساعة السادسة"],"questions":[{"question":"ما الظرف ولم سمي مفعولًا فيه؟","options":["اسم يذكر زمان الفعل أو مكانه يجري مجرى في","جواب لماذا","جواب من","نعت"],"answer":0,"explanation":"الظرف اسم يبين زمان الفعل أو مكانه بمعنى في: صليت الفجر = صليت في الفجر."},{"question":"ما ضابط ظرف الزمان؟","options":["جواب: متى وقع الفعل؟","جواب: أين؟","جواب: لماذا؟","جواب: كيف؟"],"answer":0,"explanation":"صليت الفجر: متى؟ في الفجر؛ فيوم وليلة وشهر وصباح ومساء ظروف زمان منصوبة."},{"question":"ما شرط انتصاب اسم المكان ظرفًا؟","options":["أن يكون مبهمًا","أن يكون معرفة","أن يكون مثنى","لا شرط"],"answer":0,"explanation":"لا ينتصب من أسماء المكان إلا المبهم: قدام ووراء وفوق... أما المسجد وبيت فيجران بالحرف."},{"question":"أعرب «الساعة» في «استيقظت الساعة السادسة»:","options":["ظرف زمان منصوب بالفتحة مضاف والسادسة مضاف إليه","مفعول به","نعت","تمييز"],"answer":0,"explanation":"الساعة ظرف زمان منصوب بالفتحة وهي مضاف؛ والسادسة مضاف إليه مجرور بالكسرة."},{"question":"أعرب «صباحًا ومساءً» في «يجتهد الطالب صباحًا ومساءً»:","options":["ظرفا زمان منصوبان بالفتحة والثاني معطوف","مفعول به","حال","مستثنى"],"answer":0,"explanation":"صباحًا ظرف زمان منصوب؛ ومساءً معطوف عليه منصوب مثله؛ والمعنى: يجتهد في الصباح والمساء."}]},{"body":["أمثلة قرآنية وشعرية: «يا حماديُّ حُمَّ الغداةَ ركابها»: الغداة ظرف زمان منصوب بالفتحة. «لقيتك آخرَ الليلِ»: آخر ظرف زمان منصوب بالفتحة وهو مضاف والليل مضاف إليه مجرور.","«نجلس على المنصةِ في النادي مساءَ الاثنينِ»: مساء ظرف زمان منصوب بالفتحة وهو مضاف والاثنين مضاف إليه مجرور بالكسرة.","«البحارة متر والعلوم در»: أسماء المقادير والمسافات: «سرنا فرسخين»: فرسخان من مقادير المسافة؛ فالمعنى سرنا في مسافة فرسخين. وكذلك «شربت ضرب... كيلو». فهذه تجرى مجرى الظروف وتسمى من الظرف أو من المفاعيل.","أسماء الجهات الست: فوق وتحت وأمام وخلف ويمين وشمال: «قاتل المسلم الكفار خلف ظهره...»: وهي ظروف مكان منصوبة إذا كانت مبهمة: صليت خلف الإمام: خلف ظرف مكان منصوب بالفتحة وهو مضاف والإمام مضاف إليه.","تنبيه: عند ولدى ولدن وقبل وبعد: قد تكون ظروفًا وقد تكون أسماء مجرورة بالإضافة بحسب المعنى: جلست عند زيد: عند ظرف مكان مضاف... وتعال قبل الظهر: قبل ظرف زمان... وقد يجر بعضها بالحرف: تسجد في قبل...","موازنة نافعة بين المفعول به والظرف: «المؤمن يخاف يوم القيامة»: يوم مفعول به (يخاف اليوم نفسه). «الكافر يخاف يومَ القيامةَ»: يخاف يومها: الظرف هنا: يوم القيامة ظرف زمان (الخوف الواقع يومها)... التمييز بالمعنى: ما وقع عليه الفعل = مفعول به؛ وما كان زمانًا أو مكانًا له = ظرف.","الخلاصة: الظرفان من المكملات المنصوبة: الزمان جواب متى والمكان جواب أين بشرط الإبهام؛ وأمثلتهما كثيرة: يوم وليلة وفوق وخلف وأسماء المقادير، وكلها مجراها معنى (في)."],"examples":["لقيتك آخر الليل","مساء الاثنين: مضاف ومضاف إليه","أسماء المقادير تجرى مجرى الظرف","الجهات الست ظروف مبهمة","عند وقبل وبعد: ظرف أو مجرور","يوم القيامة: مفعول به أو ظرف بالمعنى"],"questions":[{"question":"أعرب «الغداة» في «حمَّ الغداةَ ركابها»:","options":["ظرف زمان منصوب بالفتحة","مفعول به","فاعل","نعت"],"answer":0,"explanation":"الغداة (الصباح) ظرف زمان منصوب بالفتحة: متى حُمَّت الركاب؟ في الغداة."},{"question":"ما حكم أسماء المقادير كالمتر والفرسخ؟","options":["تجرى مجرى الظرف منصوبة","أفعال","حروف","مستثناة"],"answer":0,"explanation":"سرنا فرسخين: من أسماء مقادير المسافة؛ المعنى في مسافة فرسخين؛ فتنصب نصب الظروف."},{"question":"«المؤمن يخاف يوم القيامة» متى يكون يوم مفعولًا به ومتى ظرفًا؟","options":["مفعول به إذا خاف اليوم نفسه وظرف إذا خاف فيه","ظرف دائمًا","مفعول دائمًا","نعت"],"answer":0,"explanation":"يخاف المؤمن يومَ القيامة: مفعول به (يخاف اليوم نفسه)؛ وقد يكون ظرفًا: يخاف في ذلك اليوم."},{"question":"أعرب «خلف» في «صليت خلف الإمام»:","options":["ظرف مكان منصوب بالفتحة مضاف والإمام مضاف إليه","مفعول به","حرف جر","حال"],"answer":0,"explanation":"خلف من الجهات الست: ظرف مكان منصوب بالفتحة مضاف؛ والإمام مضاف إليه مجرور بالكسرة."},{"question":"أعرب «آخر» في «لقيتك آخر الليل»:","options":["ظرف زمان منصوب بالفتحة مضاف","نعت مجرور","مفعول به","خبر"],"answer":0,"explanation":"آخر ظرف زمان منصوب بالفتحة مضاف؛ والليل مضاف إليه مجرور بالكسرة: متى اللقاء؟ في آخر الليل."}]}]},{"id":"wahi-sharh-080","title":"المفعول لأجله والمفعول معه","section":"شرح الكتاب: باب المفعول له والمفعول معه مفصلًا","order":80,"segments":[{"body":["المفعول لأجله (المفعول له): وهو المصدر المنصوب الواقع بعد الفعل جوابًا لسؤال: لماذا فُعل الفعل؟ أي ما الدافع والباعث عليه؟ نحو: جئتك شوقًا: لماذا جئت؟ شوقًا إليك؛ فشوقًا مفعول له منصوب.","ضابطه: أن يكون جواب (لم) بمعنى لماذا فعل الفاعل الفعل. «قمت إجلالًا لك»: قمت من أجل الإجلال. «جئت الكتابة حرصًا على العلم»: حرص مفعول له. «حفظت القرآن طلبًا لرضا الله»: طلب مفعول له.","وهو مصدر: لأن الباعث إنما يصح أن يكون مصدرًا (معنى) لا عينًا: جئتك شوقًا = من أجل الشوق. و«ابتغاء وجه الله»: ابتغاء مصدر منصوب على أنه مفعول له.","أمثلة: «وأفشي السلام محبةً للمؤمنين»: محبة مفعول له منصوب بالفتحة (الباعث المحبة). «أعطيت المحتاج رحمةً به»: رحمة مفعول له. «أذاكر الدروس حرصًا على التفوق»: حرص مفعول له.","تنبيه الكتاب: قولك «جئت الكتب بل للكتب»... إذا قلت: جئت للكتب: فالكتب مجرور باللام وليس مفعولًا له؛ لأن المفعول له مصدر منصوب وليس اسم عين مجرورًا. فلا يكون المفعول له إلا مصدرًا منصوبًا يعلل الفعل.","فاللام يقوم مقام المفعول له أحيانًا: «ما خلقنا السماء والأرض لعبًا»: لعب مفعول له (من أجل اللعب)؛ ويقال خلقناهم لنعمتهم: اللام للتعليل تنوب عنه؛ لكن المصدر المنصوب هو مفعول له صريح.","الخلاصة: المفعول له مصدر منصوب يجيب عن لماذا وقع الفعل؛ يبين علة الفعل وباعثه؛ وشرطه أن يكون مصدرًا؛ ولا يكون اسم عين مجرورًا باللام."],"examples":["المفعول له: علة الفعل وباعثه","الضابط: جواب لماذا فعل؟","شرطه: أن يكون مصدرًا منصوبًا","جئتك شوقًا وقمت إجلالًا","حفظت القرآن طلبًا لرضا الله","للتعليل ليست مفعولًا له"],"questions":[{"question":"ما المفعول لأجله وضابطه؟","options":["مصدر منصوب جواب لماذا فعل الفاعل الفعل","جواب متى","جواب أين","جواب من"],"answer":0,"explanation":"جئتك شوقًا: لماذا جئت؟ من أجل الشوق؛ فشوق مفعول له منصوب بالفتحة."},{"question":"ما شرط المفعول له؟","options":["أن يكون مصدرًا","أن يكون عينًا","أن يكون جمعًا","أن يكون معرفة"],"answer":0,"explanation":"الباعث لا يصح إلا مصدرًا (معنى كالشوق والحرص)؛ أما اسم العين المجرور باللام فليس مفعولًا له."},{"question":"أعرب «محبة» في «أفشي السلام محبة للمؤمنين»:","options":["مفعول له منصوب بالفتحة","مفعول به","حال","نعت"],"answer":0,"explanation":"محبة مصدر منصوب يعلل إفشاء السلام: مفعول له؛ وللمؤمنين جار ومجرور."},{"question":"أعرب الكتب في «جئت للكتب»:","options":["اسم مجرور باللام وليس مفعولًا له","مفعول له","مفعول به","فاعل"],"answer":0,"explanation":"الكتب اسم عين مجرور باللام للتعليل؛ والمفعول له مصدر منصوب فقط: جئتك شوقًا."},{"question":"أعرب «طلبًا» في «حفظت القرآن طلبًا لرضا الله»:","options":["مفعول له منصوب بالفتحة","مفعول به","حال","تمييز"],"answer":0,"explanation":"طلب مصدر منصوب جواب: لماذا حفظت؟ طلبًا لرضا الله: مفعول له؛ واللام جارة رضا."}]},{"body":["المفعول معه: وهو الاسم المنصوب الواقع بعد الواو بمعنى (مع): «جاء الأميرُ والجيشُ»: أي جاء الأمير مع الجيش؛ فالجيش مفعول معه منصوب بالفتحة... بالواو.","ضابطه: أنه اسم يأتي بعد واو بمعنى (مع) يدل على من وقع الفعل معه... «استوى الماء والخشبة»: الخشبة مفعول معه: استوى الماء معها. «سرت والليل»: الليل مفعول معه: سرت معه.","قسمان من المفعول معه: ١- ما لم يفعل الفعل كـ«تمشيت والشاطئ»: الشاطئ لم يمشِ معك لكنك مشيت على طوله: فهو مفعول معه مجازًا. ٢- وما فعل الفعل مع العامل كـ«جاء الأمير والجيش»: الجيش فعل المجيء مع الأمير.","أمثلة: «خرج القمر والنجوم»: النجوم مفعول معه: خرجت مع القمر. «تبدى الشمس والضياء»: الضياء مفعول معه. «وصلنا الصبحَ والطيرُ...»: مفعول معه... وفي حديث: «صليت وأصحابي» أي معهم.","الفرق بين واو المعية وواو العطف: العطف يتبع ما قبله إعرابًا ويجوز تقديم المعطوف: جاء الجيش والأمير. والمعية: الواو بمعنى مع وما بعدها منصوب دائمًا: جاء الأمير والجيشَ... ولا يصح التقديم بالمعنى.","فائدة بلاغية: يفيد المفعول معه الصحبة في الفعل أو المصاحبة: «والصبح إذا تنفس»: الواو للمعية... والنحويون يجعلون الاسم بعدها منصوبًا على المفعول معه.","الخلاصة: المفعول معه اسم منصوب بعد واو بمعنى مع؛ قسمان: فاعل وغير فاعل؛ ويخالف المعطوف في النصب اللازم والمعنى."],"examples":["المفعول معه: بعد واو بمعنى مع","جاء الأمير والجيش: الجيش منصوب","قسمان: فاعل وغير فاعل","تمشيت والشاطئ: مجاز","استوى الماء والخشبة","واو المعية غير واو العطف"],"questions":[{"question":"ما المفعول معه وضابطه؟","options":["اسم منصوب بعد واو بمعنى مع يدل على من وقع الفعل معه","جواب لماذا","جواب متى","نعت"],"answer":0,"explanation":"جاء الأمير والجيش: الجيش مفعول معه منصوب بالفتحة؛ المعنى: جاء الأمير مع الجيش."},{"question":"ما قسما المفعول معه؟","options":["ما فعل الفعل مع العامل وما لم يفعله","مضارع وماضٍ","مبني ومعرب","لا قسمة"],"answer":0,"explanation":"جاء الأمير والجيش: الجيش جاء معه؛ وتمشيت والشاطئ: الشاطئ لم يمشِ لكنه مجاز المعية."},{"question":"ما الفرق بين واو المعية وواو العطف؟","options":["المعية تنصب ما بعدها دائمًا والعطف يتبع إعراب ما قبله","لا فرق","العطف ينصب دائمًا","المعية تجر"],"answer":0,"explanation":"جاء الأمير والجيش (معية): الجيش منصوب؛ وجاء الأمير والجيش (عطف): الجيش مرفوع تبع للأمير."},{"question":"أعرب «الخشبة» في «استوى الماء والخشبة»:","options":["مفعول معه منصوب بالفتحة","معطوف مرفوع","فاعل","مفعول به"],"answer":0,"explanation":"الواو بمعنى مع: استوى الماء مع الخشبة؛ فالخشبة مفعول معه منصوب بالفتحة."},{"question":"«تمشيت والشاطئ» لم يجز المفعول معه هنا؟","options":["لأن الشاطئ لم يفعل المشي معي","لأنه معطوف","لأنه فاعل","لأنه ظرف"],"answer":0,"explanation":"الشاطئ لم يمشِ: فهو مفعول معه مجازًا: مشيت على امتداده؛ وهذا القسم الذي لم يفعل الفعل."}]}]},{"id":"wahi-sharh-081","title":"المفعول المطلق","section":"شرح الكتاب: باب المفعول المطلق مفصلًا","order":81,"segments":[{"body":["المفعول المطلق: وهو المصدر المنصوب الواقع بعد فعله: «شكر اللهَ شكرًا»: شكرًا مصدر شكر منصوب بعد فعله؛ فهو مفعول مطلق. وسمي مطلقًا لأنه غير مقيد بالزمان ولا بعلة ولا بمعية.","ضابطه: أنه مصدر مأخوذ من الفعل المذكور قبله يؤكده أو يبين نوعه أو عدده: «نجحت نجاحًا»: نجاح مصدر نجح منصوب: مفعول مطلق. «فهمت فهمًا»: مفعول مطلق.","تصريف ثالث الفعل: من المهارة أن تصرف ثالث الفعل لتعرف المصدر: ضرب يضرب ضربًا؛ جلس يجلس جلوسًا؛ قام يقوم قيامًا؛ سعى يسعى سعيًا؛ وقف يقف وقوفًا... فالمصدر المأخوذ من الفعل هو الذي يقع مفعولًا مطلقًا.","فوائد المفعول المطلق ثلاث: ١- بيان النوع: بنعته أو إضافته: جلست جلوس الملوك، قرأت قراءة خاشعة: فيبين نوع الجلوس والقراءة. ٢- بيان العدد: ضربته ضربتين، قرأتها قراءتين: فيبين عدد مرات الفعل. ٣- التوكيد: نجحت نجاحًا: مجرد تقوية الفعل وتقريره بلا نعت ولا عدد.","أمثلة التوكيد: «حمدت الله حمدًا»: توكيد. «شكر الله شكرًا»: مفعول مطلق منصوب بالفتحة مؤكد للفعل. «صمت صومًا»: يبين تقرير الصوم.","وقد يجيء المفعول المطلق من فعل محذوف: فيدل عليه المصدر: «سبحان الله» أي أسبح الله تسبيحًا... و«حمدًا لله وشكرًا» أي حمدت حمدًا وشكرت شكرًا. و«شكرًا» المجردة: مصدر دل على فعل محذوف تقديره: شكرت شكرًا؛ فيعرب المصدر مفعولًا مطلقًا لفعل محذوف.","ومنه «صبرًا»: أي اصبر صبرًا؛ والمصدر هنا بمعنى الأمر؛ و«مهلًا»: أي أمهل مهلًا. فالمنادى بالمصدر: نداء بمعنى الأمر يعرب مفعولًا مطلقًا لفعل محذوف وجوبًا.","الخلاصة: المفعول المطلق مصدر منصوب من لفظ فعله قبله؛ فوائده: بيان النوع بالنعت أو الإضافة، وبيان العدد، والتوكيد؛ وقد يدل المصدر على فعل محذوف فيعرب مفعولًا مطلقًا لفعل مقدر."],"examples":["مصدر منصوب بعد فعله","شكر الله شكرًا","الفوائد: النوع والعدد والتوكيد","ضربت ضربتين: بيان العدد","جلست جلوس الملوك: بيان النوع","سبحان الله: مفعول لفعل محذوف"],"questions":[{"question":"ما المفعول المطلق ولم سمي مطلقًا؟","options":["مصدر منصوب بعد فعله غير مقيد بزمان ولا علة","مفعول به","ظرف","حال"],"answer":0,"explanation":"شكر الله شكرًا: شكرًا مصدر شكر منصوب بعد فعله: مفعول مطلق؛ مطلق لخلوه من قيود الزمان والعلة والمعية."},{"question":"ما فوائد المفعول المطلق الثلاث؟","options":["بيان النوع وبيان العدد والتوكيد","النفي","الاستفهام","النداء"],"answer":0,"explanation":"جلست جلوس الملوك (النوع)، وضربت ضربتين (العدد)، ونجحت نجاحًا (التوكيد)."},{"question":"أعرب «حمدًا» في «حمدًا لله»:","options":["مفعول مطلق لفعل محذوف تقديره أحمد","مفعول به","فاعل","خبر"],"answer":0,"explanation":"حمدًا مصدر دل على فعل محذوف: أحمد الله حمدًا؛ فيعرب مفعولًا مطلقًا منصوبًا لفعل محذوف."},{"question":"أعرب «جلوس» في «جلست جلوس الملوك»:","options":["مفعول مطلق منصوب مضاف بين نوع الجلوس","مفعول به","نعت","تمييز"],"answer":0,"explanation":"جلوس مصدر منصوب بعد فعله أضيف إلى الملوك فبين نوع الجلوس: مفعول مطلق مضاف."},{"question":"«ضربت ضربتين» أي فائدة تحققت؟","options":["بيان العدد","بيان النوع","التوكيد فقط","النفي"],"answer":0,"explanation":"ضربتين مفعول مطلق بين عدد الضربات: اثنتان؛ وهو منصوب بالكسرة لأنه مثنى... بالياء لأنه مثنى."}]},{"body":["من تدريبات الكتاب: «تتلى علينا آيات ربنا تلاوة خاشعة»: تلاوة مفعول مطلق منصوب بالفتحة بين نوع التلاوة بنعته (خاشعة). «ذاكرت دروسي مذاكرة متقنة»: مذاكرة مفعول مطلق بين النوع.","«السلام عليكم سلامًا»: سلام مصدر منصوب: مفعول مطلق لفعل محذوف تقديره: أسلم عليكم سلامًا أو سلمت تسليمًا. وكذلك «مرحبًا وأهلًا»: مصدران منصوبان على فعلين محذوفين: رحبت مرحبًا... وهذا من أدب الاستقبال.","ضابط تمييزه عن سائر المفاعيل: إن وجدت مصدرًا منصوبًا بعد فعل من لفظه فهو مفعول مطلق؛ وإن كان بعد واو فمفعول معه؛ وإن أجاب عن لماذا فمفعول له؛ وإن وقع عليه الفعل فمفعول به.","التفريق بين التوكيد بالمصدر والمفعول المطلق المؤكد: نجحت نجاحًا: المصدر هنا مفعول مطلق غرضه التوكيد؛ والتوكيد اللفظي تكرار اللفظ نفسه: جاء جاء؛ فالمصدر لا يكون توكيدًا لفظيًّا لأنه ليس تكرارًا للفعل بل اسم من لفظه.","من شواهد النوع: «فشكر الله شكر العابدين»: بإضافة المصدر إلى العابدين تبين النوع؛ ومن شواهد العدد: «ثلاث مرات»: مرات مفعول مطلق (منصوب بالكسرة لأنه جمع مؤنث سالم) بين العدد.","الخلاصة العملية: صرف ثالث الفعل؛ فما وجدت منه مصدرًا منصوبًا بعد فعله فهو مفعول مطلق؛ ثم انظر فائدته: نعت أو إضافة = نوع؛ عدد = عدد؛ مجرد = توكيد؛ وقد يحذف الفعل ويبقى المصدر دالًّا عليه."],"examples":["تتلى آيات ربنا تلاوة خاشعة","مرحبًا وأهلًا: لفعل محذوف","المصدر بعد واو = مفعول معه","نجحت نجاحًا: توكيد لا تكرار لفظ","شكر العابدين: بيان النوع","ثلاث مرات: بيان العدد"],"questions":[{"question":"أعرب «تلاوة» في «تتلى علينا آيات ربنا تلاوة خاشعة»:","options":["مفعول مطلق منصوب بين نوع التلاوة بنعته","مفعول به","نائب فاعل","حال"],"answer":0,"explanation":"تلاوة مصدر تلى منصوب بعد فعله نعتها خاشعة: مفعول مطلق لبيان النوع؛ وآيات نائب فاعل."},{"question":"ما تقدير «مرحبًا وأهلًا»؟","options":["مفعولان مطلقان لفعلين محذوفين: رحبت مرحبًا وأتيت أهلًا","فاعلان","مبتدآن","حالان"],"answer":0,"explanation":"مصدران منصوبان دلا على فعلين محذوفين للترحيب: مفعولان مطلقان؛ وهذا من آداب الاستقبال."},{"question":"كيف تميز المفعول المطلق من المفعول له؟","options":["المطلق من لفظ فعله والله يجيب عن لماذا وهو علة","لا فرق","المطلق مجرور","المعية مطلقة"],"answer":0,"explanation":"نجحت نجاحًا: مطلق (من لفظ الفعل)؛ جئتك شوقًا: مفعول له (علة الفعل وإن كان مصدرًا)."},{"question":"لم لا يكون «نجحت نجاحًا» توكيدًا لفظيًّا؟","options":["لأن المصدر اسم من لفظ الفعل لا تكرار للفعل نفسه","لأنه منصوب","لأنه معرفة","لأنه جمع"],"answer":0,"explanation":"التوكيد اللفظي تكرار اللفظ عينه: جاء جاء؛ أما نجاحًا فمصدر مفعول مطلق غرضه تقوية الفعل."},{"question":"أعرب «مرات» في «قرأتها ثلاث مرات»:","options":["مفعول مطلق منصوب بالكسرة لأنه جمع مؤنث سالم بين العدد","ظرف","نعت","مضاف إليه"],"answer":0,"explanation":"مرات مصدر عددي: مفعول مطلق بين عدد مرات القراءة؛ وعلامة نصبه الكسرة لأنه جمع مؤنث سالم."}]}]},{"id":"wahi-sharh-082","title":"الحال والنعت","section":"شرح الكتاب: باب الحال مفصلًا","order":82,"segments":[{"body":["باب الحال. الحال والنعت أخوان: كلاهما وصف يبين صفة؛ لكن الحال وصف نكرة يبين حال صاحبه المعرفة زمن وقوع الفعل، والنعت وصف يبين صفة موصوفه مطلقًا زمن الثبوت.","تعريف الحال: وصف نكرة يذكر ليبين هيئة صاحبه المعرفة وقت الفعل: جاء الطالب ضاحكًا: ضاحك وصف نكرة بين هيئة الطالب (معرفة) وقت المجيء؛ فضاحك حال منصوب بالفتحة وصاحبه الطالب.","ضابط الحال: تضع قبلها (حالة كونه): جاء الطالب ضاحكًا = جاء حالة كونه ضاحكًا. فإن صح الكلام فهي حال: قرأت القرآن واقفًا = قرأت حالة كوني واقفًا: واقف حال منصوب.","ضابط النعت: النعت يوافق موصوفه في التعريف والتنكير: هذا رجل كريم (معرفتان)؛ ورأيت رجلًا كريمًا (نكرتان)... «رجلٌ كريمٌ»: كريم نعت مرفوع بالضمة. والحال نكرة وصاحبه معرفة.","فقاعدة: بعد المعارف أحوال وبعد النكرات نعوت (في الجمل وأشباهها): جاء الطالب وهو ضاحك: (وهو ضاحك) جملة حالية؛ ورأيت رجلًا ضاحكًا: ضاحكًا نعت... الميزان: النكرة بعد المعرفة حال.","قلب الحال نعتًا والعكس: «جاء الطالب الضاحك»: بالألف واللام صارت نعتًا (وصف لازم)؛ و«جاء طالب ضاحك»: طالب نكرة فضاحك نعت. فبالتعريف والتنكير تعرف الحال من النعت.","أمثلة: «وأشهد أن لا إله إلا الله... محمد رسولَ الله»: رسول خبر... «قرأت القرآن تاليًا»: تالي حال: قرأت حالة كوني تاليًا. «شربت الماء صافيًا»: صافيًا نعت للماء (نكرتان)... أو حال بمعنى شربته وهو صافٍ: نكرة بعد معرفة: حال.","الخلاصة: الحال نكرة بعد معرفة يبين حال صاحبه وقت الفعل؛ منصوب؛ ضابطه حالة كونه؛ والنعت يتبع موصوفه تعريفًا وتنكيرًا وإعرابًا؛ وبالتعريف والتنكير تنقلب إحداهما الأخرى."],"examples":["الحال والنعت أخوان","الحال: نكرة بعد معرفة زمن الفعل","ضابطه: حالة كونه","النعت يوافق موصوفه تعريفًا وتنكيرًا","بعد المعارف أحوال وبعد النكرات نعوت","جاء الطالب ضاحكًا"],"questions":[{"question":"ما الحال وما ضابطه؟","options":["وصف نكرة بعد معرفة يبين هيئة صاحبه زمن الفعل؛ تضع قبله حالة كونه","وصف معرفة","نعت","ظرف"],"answer":0,"explanation":"جاء الطالب ضاحكًا: ضاحك نكرة بعد معرفة: جاء حالة كونه ضاحكًا: حال منصوب بالفتحة."},{"question":"ما الفرق بين الحال والنعت؟","options":["الحال نكرة بعد معرفة زمن الفعل والنعت يوافق موصوفه تعريفًا وتنكيرًا","لا فرق","النعت منصوب","الحال مرفوع دائمًا"],"answer":0,"explanation":"جاء الطالب ضاحكًا: حال (نكرة بعد معرفة)؛ وجاء الطالب الضاحك: نعت (معرفة بعد معرفة)."},{"question":"أعرب «واقفًا» في «قرأت القرآن واقفًا»:","options":["حال منصوب بالفتحة صاحبه التاء (أو القرآن بحسب المعنى)","نعت","مفعول به","خبر"],"answer":0,"explanation":"قرأت حالة كوني واقفًا: واقف حال منصوب بالفتحة؛ والقرآن مفعول به."},{"question":"«بعد المعارف أحوال وبعد النكرات نعوت» في ماذا؟","options":["في الجمل وأشباهها","في المفردات","في الأفعال","في الحروف"],"answer":0,"explanation":"جاء الطالب وهو ضاحك: جملة حالية بعد معرفة؛ ورأيت رجلًا ضاحكًا: نعت مفرد بعد نكرة."},{"question":"«جاء طالب ضاحك» ما إعراب ضاحك؟","options":["نعت لنكرة قبله","حال","خبر","مستثنى"],"answer":0,"explanation":"طالب نكرة؛ والوصف بعد النكرة نعت يتبعها: ضاحك نعت مرفوع بالضمة؛ فانعكس الضابط بتنكير صاحبه."}]},{"body":["تعدد الحال والنعت: يجوز تعدد الحال لصاحب واحد: جاء الطالب ضاحكًا مزهوًّا مسرعًا: ثلاث أحوال؛ ويعدد النعت أيضًا: هذا رجل كريم تقي عفيف: ثلاثة نعوت تتبع الرجل.","الحال من الجمل: يكون صاحب الحال معرفة والجملة بعده حالًا: «لا تسخر منهم وهم يتعبون»: جملة يتعبون في محل نصب حال (نكرة معنى: حالة كونهم يتعبون)... وتنصب الجملة الحالية بالواو أو بتقديمها.","أشباه الجمل حالًا أيضًا: الظرف والجار والمجرور بعد معرفة: جاء الطالب في يده كتاب: (في يده) شبه جملة في محل نصب حال.","الحال بالوصف والتمييز بالجامد: الحال وصف مشتق (ضاحك، واقف، قائم) يقبل التصريف؛ فإن جاء بعده اسم جامد فهو تمييز: «طاب زيد نفسًا»: نفس جامد: تمييز لا حال. فالحال وصف والتمييز جامد مفسر للإبهام.","مواقع الحال: تكون من المبتدأ والخبر والفاعل والمفعول به واسم كان وخبره واسم إن وخبرها ومن المجرور بالحرف وبالإضافة... «وإذا رأيتهم تعجبك أجسامهم»؛ فالحال يجوز من المعارف كلها تقريبًا.","تدريب شامل: «رأيت أسدًا هصورًا»: هصور نعت (نكرة بعد نكرة). «رأيت الأسد هصورًا»: حال (نكرة بعد معرفة). «رأيت أسدًا هصورًا مفترسًا»: نعتان... فغيّر التعريف والتنكير تغير الإعراب.","الخلاصة: يتعدد الحال والنعت؛ والحال جملة أو شبهها بعد معرفة؛ والحال وصف مشتق فإن جامد فتمييز؛ ومواقع الحال المعارف في أنواعها؛ وضابط القلب بالتعريف والتنكير مقياس ثابت."],"examples":["تعدد الحال: ضاحكًا مزهوًّا مسرعًا","الجمل بعد المعارف أحوال","في يده كتاب: شبه جملة حال","الحال وصف والتمييز جامد","الحال من كل معرفة تقريبًا","رأيت أسدًا هصورًا: نعت"],"questions":[{"question":"هل يتعدد الحال والنعت؟","options":["نعم يتعددان لصاحب واحد","لا يتعددان","الحال فقط","النعت فقط"],"answer":0,"explanation":"جاء الطالب ضاحكًا مسرعًا: حالان؛ ورجل كريم تقي: نعتان؛ وكلهما صحيح لاتحاد الصاحب والموصوف."},{"question":"أعرب «وهو ضاحك» في «جاء الطالب وهو ضاحك»:","options":["جملة في محل نصب حال","نعت","خبر","مفعول"],"answer":0,"explanation":"الجملة بعد المعرفة حال: جاء حالة كونه ضاحكًا؛ وواو الحال مع ضمير يعود على صاحبها."},{"question":"أعرب «في يده كتاب» في «جاء الطالب في يده كتاب»:","options":["شبه جملة في محل نصب حال","نعت","ظرف","مفعول فيه"],"answer":0,"explanation":"الجار والمجرور بعد المعرفة (الطالب) شبه جملة حال: جاء وحاله أن في يده كتاب."},{"question":"«طاب زيد نفسًا» لم نفس تمييز لا حال؟","options":["لأنها جامد والحال وصف مشتق","لأنها معرفة","لأنها نكرة فحسب","لأنها جمع"],"answer":0,"explanation":"الحال وصف كضاحك؛ ونفس جامد فسر إبهام (طاب) على معنى من: فهو تمييز نسبة لا حال."},{"question":"«رأيت أسدًا هصورًا» ما إعراب هصورًا؟","options":["نعت منصوب تبع لأسد النكرة","حال","مفعول به","بدل"],"answer":0,"explanation":"أسد نكرة؛ والوصف النكرة بعد النكرة نعت يتبعها في النصب والتنكير: هصور نعت منصوب بالفتحة."}]}]},{"id":"wahi-sharh-083","title":"التمييز","section":"شرح الكتاب: باب التمييز مفصلًا","order":83,"segments":[{"body":["باب التمييز: وهو اسم نكرة يفسر إبهامًا قبله على معنى (من): «عشرون رجلًا»: رجل نكرة فسرت إبهام العدد (عشرون من؟ رجل)؛ فرجل تمييز منصوب بالفتحة على معنى من.","أنواعه نوعان: ١- تمييز الذات (الملحوظ): وهو على معنى (من): عشرون رجلًا أي عشرون من الرجال؛ صاع أرزًا أي صاع من الأرز. ٢- وتمييز النسبة (المنقول): وهو على معنى (من جهة): طاب زيد نفسًا أي طاب من جهة نفسه: نفس زيد طابت.","تمييز الذات يكون بعد الأعداد وأسماء المقادير والمكاييل والموازين: «خمسة عشر صاعًا من زروع»: صاع تمييز... «تبرعت بمائة جنيه»: جنيه تمييز منصوب بالفتحة. «أو ما ملكت أيمانكم»... و«شربت كوب ماء»: ماء تمييز (كوب من الماء)... في قوله: صاع أرز وكيلو لحم وذراع قماش.","تمييز النسبة: يذكر ليبين إبهامًا في الجملة: «طاب المؤمن طبعًا»: طبع تمييز نسبة منصوب بالفتحة: طاب المؤمن من جهة طبعه (طبع المؤمن طاب). و«ازداد البحر ماء»: ازداد من جهة مائه. «اجتهد الطالب نفسًا»: أي نفسه اجتهدت.","المنصوب بعد اسم التفضيل وبعد نعم وبئس: «وأفضل الصحابة أبو بكر»: اسم التفضيل يعمل عمل ظن ينصب مفعولين... وبعدها ما يبين التفضيل تمييز: «أفضل الناس علمًا أتقاهم»: علمًا تمييز نسبة منصوب بالفتحة: أفضلهم من جهة العلم. و«نعم الرجل خالد»: الرجل تمييز بعد نعم منصوب: يبين المخصوص بالمدح. و«بئس العادة الغش»: العادة تمييز.","ضابط الحال والتمييز: الحال بالوصف المشتق (جاء راكبًا) والتمييز بالجامد المفسر للإبهام (عشرون رجلًا، طاب زيد نفسًا). فالوصف حال والجامد المبهم تمييز.","الخلاصة: التمييز نكرة منصوبة تفسر إبهامًا: ذات على معنى من (بعد الأعداد والمقادير)، ونسبة على معنى من جهة (بعد الجمل المبهمة وأسماء التفضيل ونعم وبئس)."],"examples":["التمييز: نكرة تفسر إبهامًا","الذات: على معنى من بعد الأعداد والمقادير","عشرون رجلًا وصاع أرز","النسبة: من جهة؛ طاب زيد نفسًا","اسم التفضيل ونعم وبئس يتبعها تمييز","الحال وصف والتمييز جامد"],"questions":[{"question":"ما التمييز وما نوعاه؟","options":["نكرة تفسر إبهامًا؛ ذات على معنى من ونسبة على معنى من جهة","نعت","حال","بدل"],"answer":0,"explanation":"عشرون رجلًا: ذات (من الرجال)؛ طاب زيد نفسًا: نسبة (من جهة نفسه)؛ وكلهما منصوب."},{"question":"مم يكون تمييز الذات؟","options":["بعد الأعداد والمقادير والمكاييل والموازين","بعد المعارف","بعد الأفعال","بعد الحروف"],"answer":0,"explanation":"عشرون رجلًا، صاع أرز، كيلو لحم، ذراع قماش، مائة جنيه: التمييز يفسر إبهام العدد والمقدار."},{"question":"أعرب «نفسًا» في «طاب زيد نفسًا»:","options":["تمييز نسبة منصوب بالفتحة","حال","مفعول به","نعت"],"answer":0,"explanation":"نفس جامد فسر إبهام طاب على معنى من جهة: طابت نفس زيد: تمييز نسبة منصوب."},{"question":"ما إعراب «علمًا» في «أفضل الناس علمًا أتقاهم»؟","options":["تمييز منصوب بالفتحة بعد اسم التفضيل","نعت","حال","بدل"],"answer":0,"explanation":"بعد اسم التفضيل يأتي ما يبين وجه التفضيل تمييزًا: أفضلهم من جهة العلم: علم تمييز منصوب."},{"question":"أعرب «الرجل» في «نعم الرجل خالد»:","options":["تمييز منصوب بالفتحة","مبتدأ","خبر","فاعل"],"answer":0,"explanation":"بعد نعم وبئس يأتي تمييز يبين المخصوص بالمدح أو الذم: نعم الرجل: الرجل تمييز منصوب بالفتحة."}]},{"body":["تدريبات الكتاب على التمييز: «واشتريت كِراسين...»، «وصليت في المسجد ثلاثة أيام»: أيام تمييز عدد... «أو ما ملكت أيمانكم»... «تبرعت بمائة جنيه»: جنيه تمييز منصوب بالفتحة؛ ومائة معربة (مبتدأ أو نحوه) ولا ينصب بعدها الجار والمجرور.","ضابط المائة وألف: «بمائة جنيه»: مائة اسم معرب يأخذ حكم ما قبله (مجرور بالباء) وجنيه تمييز منصوب؛ فالعدد المركب نحوها يعرب معربًا والمعدود يميز.","تمييز النسبة منقول أصله جملة: «اشتد العظم ألمًا»: الأصل: اشتد ألم العظم؛ فنقل الفاعل (ألم العظم) إلى تمييز: ألمًا منصوب؛ والعظم مبتدأ... «اشتد الجوع بالبلدة» = اشتد جوعها... فلذلك سمي منقولًا.","الفرق بين تمييز الذات والنسبة بالمثال المحكم: اجتمع عشرون رجلًا: ذات (الرجال محل الإحصاء)؛ وطاب الرجل خلقًا: نسبة (الخلق نسبة إلى الرجل: خلقه طاب). الذات يحصي والنسبة ينسب.","تنبيه على كيلو وأمثالها: «اشتريت كيلو لحم»: لحم تمييز ذات (كيلو من اللحم)؛ ولو قلت اشتريت اللحم: مفعول به. فاسم المقدار ينصب ما بعده تمييزًا لا مفعولًا به.","الخلاصة العملية: انظر ما قبل النكرة المنصوبة: عدد أو مقدار؟ فتمييز ذات على معنى من. جملة فيها إبهام أو اسم تفضيل أو نعم وبئس؟ فتمييز نسبة على معنى من جهة. واجعل معنى (من) ميزانًا ثابتًا."],"examples":["مائة جنيه: مائة معرب وجنيه تمييز","صليت ثلاثة أيام: تمييز","اشتد العظم ألمًا = اشتد ألم العظم","الذات يحصي والنسبة ينسب","كيلو لحم: لحم تمييز لا مفعول به","ميزان من ومن جهة"],"questions":[{"question":"أعرب «جنيه» في «تبرعت بمائة جنيه»:","options":["تمييز منصوب بالفتحة","مضاف إليه","مفعول به","نعت"],"answer":0,"explanation":"مائة اسم معرب أخذ حكم الجر بالباء؛ وجنيه نكرة فسرت إبهام المائة: تمييز منصوب بالفتحة."},{"question":"ما أصل «اشتد العظم ألمًا»؟","options":["اشتد ألم العظم ثم نقل الفاعل تمييزًا","لا أصل","استثناء","نداء"],"answer":0,"explanation":"ألم العظم: فاعل أصلًا؛ نقل العظم مبتدأ والألم نصب تمييزًا منقولًا: من هنا سمي المنقول."},{"question":"ما الفرق بين تمييزي الذات والنسبة؟","options":["الذات يحصي بعد الأعداد والنسبة ينسب بعد الجمل المبهمة","لا فرق","النسبة للأعداد","الذات للجمل"],"answer":0,"explanation":"عشرون رجلًا: إحصاء (ذات)؛ طاب زيد نفسًا: تفسير نسبة (من جهة نفسه) بعد جملة مبهمة."},{"question":"أعرب «لحم» في «اشتريت كيلو لحم»:","options":["تمييز ذات منصوب بالفتحة","مفعول به","مضاف إليه","نعت"],"answer":0,"explanation":"كيلو اسم مقدار مفعول به؛ وما بعده منصوب تمييزًا على معنى من: كيلو من اللحم: لحم تمييز."},{"question":"أعرب «أيام» في «صليت في المسجد ثلاثة أيام»:","options":["تمييز منصوب بالفتحة","مضاف إليه","ظرف","مفعول به"],"answer":0,"explanation":"ثلاثة اسم عدد؛ والمعدود بعدها نكرة منصوبة على التمييز: ثلاثة من الأيام: أيام تمييز."}]}]},{"id":"wahi-sharh-084","title":"الاستثناء","section":"شرح الكتاب: باب الاستثناء مفصلًا","order":84,"segments":[{"body":["باب الاستثناء: وهو إخراج بعض الحكم من عمومه بأداة: «نجح الطلاب إلا كسلانًا»: أخرجنا كسلانًا من عموم الناجحين.","أركانه ثلاثة: ١- مستثنى منه (الطلاب). ٢- أداة استثناء (إلا). ٣- مستثنى (كسلان).","أدواته: إلا (حرف)، وغير وسوى (اسمان)، وعدا وخلا وحاشا (تكون أحرف جر وأفعالًا).","حالات المستثنى بإلا: ١- إذا كان الكلام تامًّا موجبًا (ثبت الحكم للمستثنى منه): وجب نصب المستثنى: نجح الطلاب إلا كسلانًا: كسلان مستثنى منصوب وجوبًا بالفتحة. «قام القوم إلا زيدًا»: زيد مستثنى منصوب وجوبًا.","٢- وإذا كان الكلام تامًّا منفيًّا (أو فيه نهي أو استفهام إنكاري): جاز في المستثنى وجهان: البدل من المستثنى منه والنصب على الاستثناء: «ما نجح إلا مجتهدٌ/مجتهدًا»: مجتهد: بدل مرفوع أو مستثنى منصوب. «ما رأيت أحدًا إلا زيدًا/زيدٌ»: زيد: مستثنى منصوب أو بدل مجرور.","٣- وإذا كان الكلام ناقصًا منقطعًا (المنقطع: ما ليس المستثنى منه من جنس المستثنى): جاز إعراب المستثنى حسب موقعه في الكلام: «ما جاء القوم إلا حمارٌ/حمارًا»: الحمار ليس من جنس القوم (منقطع) والكلام ناقص (لولا إلا ما تم): فيعرب حسب موقعه: مبتدأ مرفوع (ما جاء إلا حمار = لم يجأ إلا حمار) ويجوز نصبه على الاستثناء.","إعراب غير: وهي اسم بمعنى إلا يعرب مستثنى منصوبًا في التام الموجب: نجح الطلاب غيرَ كسلانٍ: غير مستثنى منصوب بالفتحة مضاف وكسلان مضاف إليه مجرور. ويجوز البدلية في المنفي: ما نجح غيرُ مجتهدٍ. وسوى مثلها.","إعراب ما بعد عدا وخلا وحاشا: إذا جعلتها أحرف جر جررت ما بعدها: جاء القوم عدا زيدٍ: زيد اسم مجرور بعدا... وإذا جعلتها أفعالًا نصبت ما بعدها: جاء القوم عدا زيدًا: عدا فعل ماض وزيد مفعول به منصوب (فاعله مستتر). «حاشا كرمك»: كرمك مفعول به بعد حاشا الفعل (أو مجرور بعد حاشا الحرف).","الخلاصة: الاستثناء إخراج بعض من كل؛ أركانه ثلاثة؛ إلا حرف ينصب في التام الموجب ويخير في التام المنفي ويعرب حسب الموقع في الناقص المنقطع؛ وغير وسوى اسمان؛ وعدا وخلا وحاشا حرف جر وفعل."],"examples":["الاستثناء: إخراج بعض من كل","أركانه: مستثنى منه وأداة ومستثنى","إلا حرف وغير وسوى اسمان","عدا وخلا وحاشا: جر وفعل","تام موجب: نصب وجوبًا","تام منفي: بدل أو نصب؛ ناقص منقطع: حسب الموقع"],"questions":[{"question":"ما أركان الاستثناء وأدواته؟","options":["مستثنى منه وأداة ومستثنى؛ إلا وغير وسوى وعدا وخلا وحاشا","ركنان","إلا فقط","غير فقط"],"answer":0,"explanation":"نجح الطلاب إلا كسلان: الطلاب مستثنى منه، إلا أداة، كسلان مستثنى؛ وغير وسوى اسمان وعدا وخلا وحاشا جر وفعل."},{"question":"ما حكم المستثنى بإلا في التام الموجب؟","options":["النصب وجوبًا","الرفع","الجر","التخيير"],"answer":0,"explanation":"نجح الطلاب إلا كسلانًا: الكلام تم بإثبات النجاح للطلاب؛ فوجب نصب كسلان على الاستثناء."},{"question":"ما حكم المستثنى في التام المنفي؟","options":["يجوز البدل من المستثنى منه والنصب على الاستثناء","النصب وجوبًا","الرفع وجوبًا","الجر"],"answer":0,"explanation":"ما نجح إلا مجتهد: بدل مرفوع (ما نجح مجتهد)؛ أو مجتهدًا مستثنى منصوب."},{"question":"ما حكم المستثنى في الناقص المنقطع؟","options":["يعرب حسب موقعه في الكلام ويجوز نصبه","النصب وجوبًا","الرفع وجوبًا","الجر وجوبًا"],"answer":0,"explanation":"ما جاء القوم إلا حمار: الحمار ليس من جنس القوم: منقطع ناقص: مبتدأ مرفوع ويجوز نصبه."},{"question":"أعرب «غير» وما بعدها في «نجح الطلاب غير كسلان»:","options":["غير مستثنى منصوب بالفتحة مضاف وكسلان مضاف إليه","نعت","حال","بدل مرفوع وجوبًا"],"answer":0,"explanation":"غير اسم بمعنى إلا: مستثنى منصوب في التام الموجب مضاف؛ وكسلان مضاف إليه مجرور بالكسرة."}]},{"body":["تدريبات الكتاب: «وفق الجميع إلا مهملًا»: مهمل مستثنى منصوب وجوبًا (تام موجب). «وقرأت السورة إلا آية»: آية مستثنى منصوب وجوبًا.","«ما حضر إلا محسنٌ/محسنًا»: منفي تام: محسن بدل مرفوع بالضمة (الأصل: حضر محسن) أو مستثنى منصوب بالفتحة.","«لم يقرأ الكتاب إلا الطالبُ»: الطالب بدل من الكتاب مرفوع (لأن الكتاب نائب فاعل) أو مستثنى منصوب.","«ما قام إلا المجتهدون»: المجتهدون بدل مرفوع بالواو... ويجوز النصب بالياء على الاستثناء.","منقطع: «ما رأيت أحدًا إلا أسدًا/أسدٌ»: الأسد ليس من جنس أحد (منقطع)؛ فيجوز أسدٌ بدل من أحد مجرور بالكسرة، وأسدًا مستثنى منصوب بالفتحة.","«جاء القوم خلا زيدًا»: خلا فعل ماض (خلت القافلة عن زيد) وزيد مفعول به منصوب؛ أو خلا حرف جر: زيدٍ مجرور بالكسرة. و«عدا زيدًا/زيدٍ» كذلك.","الخلاصة العملية: اسأل ثلاثة: هل الكلام موجب أم منفي؟ هل هو تام أم ناقص؟ هل المستثنى من جنس المستثنى منه (متصل) أم لا (منقطع)؟ ثم طبق: موجب تام: نصب وجوبًا؛ منفي تام: تخيير؛ منقطع ناقص: حسب الموقع مع جواز النصب."],"examples":["وفق الجميع إلا مهملًا: نصب وجوبًا","ما حضر إلا محسن: تخيير","لم يقرأ الكتاب إلا الطالب: بدل نائب فاعل","ما قام إلا المجتهدون: واو أو ياء","ما رأيت أحدًا إلا أسد: منقطع","جاء القوم خلا زيد: فعل أو حرف"],"questions":[{"question":"أعرب «مهملًا» في «وفق الجميع إلا مهملًا»:","options":["مستثنى منصوب وجوبًا بالفتحة","بدل مرفوع","نعت","حال"],"answer":0,"explanation":"الكلام تام موجب (ثبت التوفيق للجميع): فوجب نصب المستثنى مهمل على الاستثناء."},{"question":"أعرب «الطالب» في «لم يقرأ الكتاب إلا الطالب»:","options":["بدل من الكتاب مرفوع أو مستثنى منصوب","فاعل وجوبًا","مفعول به","نعت"],"answer":0,"explanation":"منفي تام: الكتاب نائب فاعل لم يقرأ؛ فالطالب بدل مرفوع بالضمة أو مستثنى منصوب."},{"question":"«ما رأيت أحدًا إلا أسد» ما نوع الاستثناء؟","options":["منقطع (الأسد ليس من جنس أحد)","متصل","موجب","باطل"],"answer":0,"explanation":"الأسد ليس من الآحاد البشر: منقطع ناقص: يعرب أسد بدلًا من أحد مجرورًا بالكسرة أو مستثنى منصوبًا."},{"question":"ما إعراب زيد بعد خلا؟","options":["مفعول به إذا كانت خلا فعلًا ومجرور إذا كانت حرف جر","مرفوع دائمًا","منصوب دائمًا","مجرور دائمًا"],"answer":0,"explanation":"خلا وأخواتها: جاء القوم خلا زيدًا (فعل ومفعول) أو خلا زيدٍ (حرف جر ومجرور)."},{"question":"أعرب «المجتهدون» في «ما قام إلا المجتهدون»:","options":["بدل مرفوع بالواو أو مستثنى منصوب بالياء","مستثنى منصوب وجوبًا","فاعل","مبتدأ"],"answer":0,"explanation":"منفي تام متصل: التخيير بين البدل (مرفوع بالواو: جمع مذكر سالم) والاستثناء (منصوب بالياء)."}]}]},{"id":"wahi-sharh-085","title":"المنادى","section":"شرح الكتاب: باب المنادى مفصلًا","order":85,"segments":[{"body":["باب المنادى: النداء طلب إقبال المخاطب بحرف من حروف النداء. حروف النداء خمسة: يا والهمزة وآيا وأي وهيا؛ وأكثرها استعمالًا يا: يا محمد.","أنواع المنادى نوعان: ١- ما كان اسمًا واحدًا يدل على معين: فهو مبني على ما يرفع به في محل نصب: يا محمدُ: محمد منادى مبني على الضمة في محل نصب (علم مفرد). يا محمدانِ: مبني على الألف (مثنى). يا محمدونَ: مبني على الواو (جمع). وكذلك النكرة المقصودة (نكرة تعين منها شخص): يا رجلُ ويا طلابُ: مبني على الضمة في محل نصب.","٢- وما سوى ذلك فمعرب منصوب: وهو ثلاثة: المضاف: يا عبدَ الله: عبد منادى منصوب بالفتحة مضاف. والشبيه بالمضاف: يا كريمَ خلقِه: كريم منادى منصوب بالفتحة شبيه بالمضاف (لأن خلقه من تمام معناه: كريم الخلق). والنكرة غير المقصودة: يا غافلًا تب: غافل نكرة لا يقصد بها معين: منادى منصوب بالفتحة.","أمثلة: «يا محمد صلِّ»: محمد منادى مبني على الضمة في محل نصب. «يا عبد الله اتق ربك»: عبد منادى منصوب بالفتحة مضاف واسم الله مضاف إليه. «يا مسافرًا إلى الله اخشَ الله»: مسافر نكرة غير مقصودة منصوب بالفتحة.","«يا زيدان اتقيا الله»: زيدان منادى مبني على الألف في محل نصب (مثنى). «يا طالبان العلم»: طالبان مبني على الألف. «يا طلاب العلم»: طلاب جمع مبني على الضمة... أو منصوب شبيه بالمضاف.","ضابط العلم: العلم المفرد والمثنى والجمع (المعين) مبني؛ والمضاف والشبيه به والنكرة غير المقصودة منصوبة بالفتحة؛ والنكرة المقصودة (يقصد بها فرد بعينه: يا رجل أمسك) مبنية على الضمة.","الخلاصة: حروف النداء خمسة أشهرها يا؛ والمنادى إما معين باسم واحد فمبني على ما يرفع به في محل نصب، وإما مضاف أو شبيه به أو نكرة غير مقصودة فمنصوب بالفتحة."],"examples":["حروف النداء خمسة أشهرها يا","المعين باسم واحد: مبني في محل نصب","يا محمدُ ويا محمدانِ ويا محمدونَ","المضاف والشبيه والنكرة غير المقصودة: منصوبة","يا عبد الله: منصوب مضاف","يا غافلًا تب: نكرة غير مقصودة"],"questions":[{"question":"كم حروف النداء وما أشهرها؟","options":["خمسة: يا والهمزة وآيا وأي وهيا؛ وأشهرها يا","ثلاثة","سبعة","واحد"],"answer":0,"explanation":"خمسة حروف للنداء: يا محمد، والهمزة: أزيدُ أقبل، وآيا وأي للنكرة المقصودة، وهيا للبعيد."},{"question":"ما إعراب العلم المفرد منادًى؟","options":["مبني على الضمة في محل نصب","منصوب بالفتحة","مرفوع","مجرور"],"answer":0,"explanation":"يا محمدُ: علم مفرد معين: منادى مبني على الضمة (ما يرفع به) في محل نصب."},{"question":"أعرب «عبد» في «يا عبد الله»:","options":["منادى منصوب بالفتحة مضاف","مبني على الضمة","فاعل","مبتدأ"],"answer":0,"explanation":"عبد مضاف إلى اسم الله: فهو من الأسماء المضافة: منادى منصوب بالفتحة مضاف والله مضاف إليه."},{"question":"أعرب «غافلًا» في «يا غافلًا تب»:","options":["منادى منصوب بالفتحة نكرة غير مقصودة","مبني على الضمة","نعت","حال"],"answer":0,"explanation":"غافل نكرة لا يعين شخصًا بعينه: نكرة غير مقصودة: منادى منصوب بالفتحة."},{"question":"أعرب «رجل» في «يا رجل أمسك»:","options":["منادى مبني على الضمة في محل نصب نكرة مقصودة","منصوب بالفتحة","فاعل","نعت"],"answer":0,"explanation":"نكرة قصد بها شخص معين (رجل بعينه): نكرة مقصودة: مبنية على الضمة في محل نصب."}]},{"body":["نداء النكرة المقصودة بأي: أي وأية يستعملان لنداء النكرة المقصودة وهما مبنيان على الضم، وها حرف تنبيه يزاد قبلهما: «أيها الرجل أقبل»: أي: منادى نكرة مقصودة مبني على الضم في محل نصب؛ وها: حرف تنبيه لا محل له؛ والرجل: نعت أو عطف بيان مرفوع بالضمة.","«وأيها المؤمنون بالله أنفقوا»: أيها: منادى مبني على الضم؛ والمؤمنون: نعت مرفوع بالواو. و«أيتها النفس المطمئنة ارجعي»: أية مبنية على الضم والنفس نعتها.","إعراب يا: حرف نداء مبني على السكون لا محل له من الإعراب: «يا رسول الله»: يا حرف نداء؛ ورسول منادى منصوب بالفتحة مضاف؛ والله مضاف إليه.","الندبة: إذا ندب الميت أو المصاب زيدت الواو أو الألف بعد يا: «وا محمداه»: محمد اسم منصوب بالفتحة ندبة... «وا إسلاماه». فالندبة نوع من النداء حكمه النصب في علم المحزون عليه.","تدريبات: «يا مسلمون اتقوا الله»: مسلمون منادى مبني على الواو في محل نصب. «يا أخا الحق استمع»: أخا منادى منصوب بالألف (من الأسماء الخمسة) مضاف. «يا راكبًا أمسك»: راكب نكرة غير مقصودة منصوب.","الخلاصة العملية: انظر المنادى: علم أو معين باسم واحد؟ مبني على ما يرفع به. مضاف أو شبيه أو نكرة لا تقصد معينًا؟ منصوب بالفتحة. نكرة مقصودة؟ مبنية على الضمة أو مناداة بأيها المبنية على الضم."],"examples":["أيها: مبني على الضم للنكرة المقصودة","الرجل بعد أيها: نعت أو عطف بيان","يا: حرف نداء لا محل له","وا محمداه: ندبة منصوبة","يا أخا الحق: بالألف","يا مسلمون: مبني على الواو"],"questions":[{"question":"كيف ينادى النكرة المقصودة بأي؟","options":["أي وأية مبنيان على الضم وتزاد ها تنبيه والاسم بعدهما نعت","منصوبان بالفتح","معربان","حرفان"],"answer":0,"explanation":"أيها الرجل: أي منادى نكرة مقصودة مبني على الضم في محل نصب؛ وها حرف تنبيه؛ والرجل نعت مرفوع."},{"question":"ما إعراب حرف النداء يا؟","options":["حرف نداء مبني على السكون لا محل له من الإعراب","منادى","فعل","اسم"],"answer":0,"explanation":"يا حرف لا يعرب؛ والإعراب للمنادى بعده: يا رسول الله: رسول منادى منصوب مضاف."},{"question":"ما الندبة وما حكمها؟","options":["نداء المحزون عليه بوا أو آه والاسم منصوب","نداء عادي","استثناء","تعجب"],"answer":0,"explanation":"وا محمداه: ندبة: محمد منصوب بالفتحة على الندبة (حزن على مصاب أو ميت)."},{"question":"أعرب «أخا» في «يا أخا الحق»:","options":["منادى منصوب بالألف لأنه من الأسماء الخمسة مضاف","مبني على الضمة","مرفوع بالواو","نعت"],"answer":0,"explanation":"أخو من الأسماء الخمسة: ينصب بالألف: أخا منادى منصوب مضاف؛ والحق مضاف إليه مجرور."},{"question":"أعرب «المؤمنون» في «أيها المؤمنون»:","options":["نعت لأي مرفوع بالواو","منادى","فاعل","خبر"],"answer":0,"explanation":"الاسم بعد أيها وأيتها نعت أو عطف بيان: المؤمنون نعت مرفوع بالواو لأنه جمع مذكر سالم."}]}]},{"id":"wahi-sharh-086","title":"المجرور بحرف الجر وحروف القسم","section":"شرح الكتاب: باب المجرورات: المجرور بالحرف مفصلًا","order":86,"segments":[{"body":["باب المجرورات: وهي نوعان: الاسم المجرور بحرف جر، والاسم المجرور بالإضافة.","تعريف المجرور بالحرف: وهو الاسم الواقع بعد حرف جر: حروف الجر هي: من وإلى وعن وعلى وفي واللام والباء والكاف ورب ومذ ومنذ وحتى. وأحرف القسم وهي: الباء والواو والتاء.","مثال الكتاب: «والله العظيمِ إلى الصلاةِ في الظلمِ بسكينةٍ متعةٌ للمؤمنينَ»: الواو: حرف قسم وجر مبني على الفتح لا محل له من الإعراب. الله: اسم مجرور بالواو وعلامة جره الكسرة. العظيم: نعت مجرور. إلى: حرف جر. الصلاة: اسم مجرور بإلى وعلامة جره الكسرة. في: حرف جر. الظلم: اسم مجرور بفي وعلامة جره الكسرة. الباء: حرف جر. سكينة: اسم مجرور بالباء وعلامة جره الكسرة. متعة: خبر مرفوع (ومبتدأ مقدر: الصلاة متعة). اللام: حرف جر. للمؤمنين: اسم مجرور باللام وعلامة جره الياء لأنه جمع مذكر سالم.","فالاسم بعد حرف الجر مجرور: إن كان مفردًا أو جمع تكسير فبالكسرة: في البيتِ، إلى المسجدِ؛ وإن كان مثنى أو جمع مذكر سالم فبالياء: للمؤمنينَ، بالمسلمَينِ؛ وإن كان جمع مؤنث سالم فبالكسرة: بالمؤمناتِ؛ وإن كان ممنوعًا من الصرف فبالفتحة: عن مساجدَ.","وظيفة حروف الجر المعنوية: من للابتداء: جئت من البيت. إلى للانتهاء: سافرت إلى القاهرة. عن للمجاوزة. على للاستعلاء. في للظرفية. الباء للإلصاق: أمسكت بالحبل. اللام للاختصاص والتعليل: الكتاب لك. الكاف للتشبيه: أنت كالبدر. رب للتقليل.","ومن حروف الجر مذ ومنذ بمعنى من لابتداء الزمان: لم أره مذ يوم الجمعة: يوم اسم مجرور بمذ (أو مضاف إليه بعد ظرف) وعلامة جره الكسرة؛ وحتى بمعنى إلى للانتهاء: سرت حتى النهاية: النهاية اسم مجرور بحتى وعلامة جره الكسرة... وحتى قد تكون عطفًا: أكلت السمك حتى رأسه (فهنا للغاية والعطف).","الخلاصة: الاسم بعد حرف الجر مجرور؛ وحروف الجر المشهورة: من إلى عن على في اللام الباء الكاف رب مذ منذ حتى؛ ولكل معناه؛ والمجرور بالكسرة أو الياء أو الفتحة بحسب علته."],"examples":["المجرورات نوعان: بالحرف وبالإضافة","حروف الجر: من إلى عن على في اللام الباء الكاف رب مذ منذ حتى","والله العظيم: مجرور بواو القسم","للمؤمنين: مجرور بالياء","عن مساجد: بالفتحة للمنع من الصرف","لكل حرف معناه"],"questions":[{"question":"ما المجرور بحرف الجر وما أشهر حروف الجر؟","options":["الاسم بعد حرف جر؛ من إلى عن على في اللام الباء الكاف رب مذ منذ حتى","بعد فعل","بعد يا","بعد إن"],"answer":0,"explanation":"في البيت: البيت اسم مجرور بفي؛ وحروف الجر المشهورة اثنا عشر حرفًا لكل منها معناه."},{"question":"أعرب «المؤمنين» في «للمؤمنين»:","options":["اسم مجرور باللام وعلامة جره الياء لأنه جمع مذكر سالم","بالكسرة","مرفوع","منصوب"],"answer":0,"explanation":"جمع المذكر السالم يجر بالياء: للمؤمنين؛ واللام حرف جر لا محل له."},{"question":"أعرب «مساجد» في «عن مساجد»:","options":["اسم مجرور بعن وعلامة جره الفتحة لأنه ممنوع من الصرف","بالكسرة","بالياء","منصوب"],"answer":0,"explanation":"مساجد جمع على صيغة منتهى الجموع: ممنوع من الصرف يجر بالفتحة نيابة عن الكسرة."},{"question":"ما معنى الباء والكاف ورب؟","options":["الباء للإلصاق والكاف للتشبيه ورب للتقليل","للقسم فقط","للاستفهام","للنفي"],"answer":0,"explanation":"أمسكت بالحبل: إلصاق؛ أنت كالبدر: تشبيه؛ رب كريم في القوم: تقليل."},{"question":"أعرب «يوم» في «لم أره مذ يوم الجمعة»:","options":["اسم مجرور بمذ وعلامة جره الكسرة (أو مضاف إليه بعد ظرف)","ظرف","فاعل","نعت"],"answer":0,"explanation":"مذ ومنذ من حروف الجر بمعنى من لابتداء الزمان: يوم مجرور بالكسرة؛ والجمعة مضاف إليه."}]},{"body":["حروف القسم: وهي ثلاثة: الباء والواو والتاء؛ نحو: «بالله لأجتهدن»، «والله لأنصرنك»، «تالله ما حملت أمتي». فالواو حرف قسم وجر مبني على الفتح لا محل له من الإعراب؛ واسم الجلالة بعدها مجرور بالواو وعلامة جره الكسرة: واللهِ.","التاء للقسم خاصة بالله: تالله: التاء حرف قسم وجر مبني على الفتح؛ واسم الله مجرور بها. والباء للقسم وغيره: بالله لأجتهدن: بالله: الباء حرف قسم وجر مبني على الكسر؛ والله اسم مجرور بالباء.","القسم وجوابه: القسم جملة مؤكدة بجواب: والله لأجتهدنَّ: اللام واو القسم... لأجتهدن: اللام لام القسم (متوعدة) وأجتهد مضارع مقسم به مقترن باللام مبني على الفتح والنون للتوكيد. وقد يقترن الجواب بإن: والله إن كاذبًا.","تدريبات الكتاب: «والله العظيم لأعملن بما أمر الله»: الواو حرف قسم؛ والله اسم مجرور بالواو؛ والعظيم نعت مجرور. «وبالله وتالله»: حرفا قسم.","تنبيه: واو القسم مفتوحة والتاء مقصورة عن غير الله غالبًا: لا يقال تالكعبة عند الجمهور... والقسم لا يكون إلا بمعظم عند المسلمين: فلا يحلف بغير الله.","الخلاصة: حروف القسم ثلاثة: الواو والتاء والباء؛ يجررن اسم الجلالة ونحوه؛ ويقترن جواب القسم باللام أو إن؛ والواو للقسم وغيره والتاء للقسم بالله خاصة."],"examples":["حروف القسم: الواو والتاء والباء","والله لأجتهدن: واو قسم ولام جواب","تالله: التاء لله خاصة","بالله لأنصرنك","العظيم بعد والله: نعت مجرور","جواب القسم باللام أو إن"],"questions":[{"question":"ما حروف القسم؟","options":["الباء والواو والتاء","من وإلى","حتى وكي","لم ولن"],"answer":0,"explanation":"والله وبالله وتالله: ثلاثة أحرف للقسم تجر الاسم بعدها؛ والتاء خاصة بالله عند الجمهور."},{"question":"أعرب الواو والله في «والله العظيم»:","options":["الواو حرف قسم وجر لا محل له والله اسم مجرور بها بالكسرة","عطف","معية","استئناف"],"answer":0,"explanation":"والله العظيم: قسم: الواو حرف قسم مبني على الفتح؛ واسم الله مجرور بها؛ والعظيم نعت مجرور."},{"question":"أعرب «لأجتهدن» في «والله لأجتهدن»:","options":["اللام لام جواب القسم وأجتهد مضارع مبني على الفتح لاتصاله بنون التوكيد","مجزوم بلم","منصوب بلن","مرفوع"],"answer":0,"explanation":"جواب القسم يقترن باللام: لأجتهدن؛ والنون نون التوكيد؛ والفعل مقسم به."},{"question":"بم يقترن جواب القسم؟","options":["باللام أو بإن","بما","بلا","بلن"],"answer":0,"explanation":"والله لأجتهدن (اللام)؛ والله إن كاذبًا (إن المشددة)؛ وكله توكيد لجواب القسم."},{"question":"لم خصت تاء القسم بالله؟","options":["لأنها لا تستعمل إلا للقسم بالله عند الجمهور","لأنها حرف عطف","لأنها نفي","لأنها استفهام"],"answer":0,"explanation":"تالله: تاء القسم مختصة باسم الجلالة؛ فلا يقال تالكعبة؛ بخلاف الواو والباء."}]}]},{"id":"wahi-sharh-087","title":"المجرور بالإضافة","section":"شرح الكتاب: باب المجرور بالإضافة مفصلًا","order":87,"segments":[{"body":["باب المجرور بالإضافة. تعريف المضاف إليه: هو الاسم الذي أضيف إليه اسم قبله: قلم الأستاذ: الأستاذ مضاف إليه. وتعريف الإضافة: كل اسمان يدلان على شيء واحد.","فالإضافة لا تقع إلا بين اسمين: قلم الأستاذ وباب البيت وصديق محمد؛ ولا تقع بين غيرهما: كفعلين أو حرفين أو مختلفين. والأصل أن كل اسم يدل على مسمى: قلم يدل على آلة الكتابة والأستاذ يدل على من يعلم؛ فإذا قيل قلم الأستاذ صار الاسمان يدلان على شيء واحد: القلم الذي مع الأستاذ؛ والذي جعلهما يدلان على شيء واحد هو الإضافة.","والمضاف إليه دائمًا مجرور: قلمُ الأستاذِ: الأستاذ مضاف إليه مجرور بالكسرة. باب البيتِ. كتاب الطالبِ. مسرح المدرسةِ. لجام الفرسِ.","وتكون الإضافة على معنى ثلاثة أحرف جر: ١- (في): صلاة الليل (صلاة في الليل) وصوم النهار ونوم الضحى. ٢- و(من): باب خشب (باب من خشب) وثوب قطن ونافذة زجاج وخاتم ذهب. ٣- واللام ومن الاختصاص: سيارة ظافر وكتاب الطالب ومفتاح الباب (سيارة لظافر).","ويحذف من المضاف ما فيه من تنوين: قلمٌ أستاذٍ (بالتنوين) إذا أضفت قلت: قلمُ أستاذٍ (بلا تنوين)؛ فالتنوين يحذف بالإضافة. وكذلك نون المثنى والجمع: مهندسانِ البيتِ: حذفت النون بالإضافة (مهندسا البيت).","مسألة: الضمائر وأسماء الإشارة لا تقع مضافة، وكذا الأسماء الموصولة وأسماء الاستفهام وأسماء الشرط، باستثناء (أي) من هذه الثلاثة: أيُّ طالبٍ نجح. فهذه لا يتصور أن تكون مضافة ولا يكون ما بعدها مضافًا إليه... لأنها معرفة محضة لا تكتسب تعريفًا بالإضافة.","الخلاصة: الإضافة اسمان يدلان على شيء واحد؛ الثاني مضاف إليه مجرور دائمًا؛ والإضافة بمعنى في أو من أو اللام؛ ويحذف تنوين المضاف ونون المثنى والجمع؛ والضمائر وأسماء الإشارة والموصولات والاستفهام والشرط لا تضاف إلا أي."],"examples":["المضاف إليه: الثاني المجرور دائمًا","الإضافة: اسمان يدلان على شيء واحد","بمعنى في: صلاة الليل","بمعنى من: خاتم ذهب؛ وبمعنى اللام: كتاب الطالب","يحذف التنوين ونون المثنى والجمع","الضمائر لا تضاف إلا أي من الشرط"],"questions":[{"question":"ما الإضافة وما المضاف إليه؟","options":["كل اسمان يدلان على شيء واحد؛ الثاني مضاف إليه مجرور دائمًا","اسم وحرف","فعلان","نعت"],"answer":0,"explanation":"قلم الأستاذ: اسمان لشيء واحد؛ الأستاذ مضاف إليه مجرور بالكسرة دائمًا أبدًا."},{"question":"على معاني أي أحرف تكون الإضافة؟","options":["في ومن واللام","عن وعلى","الباء والكاف","مذ ومنذ"],"answer":0,"explanation":"صلاة الليل (في)؛ وخاتم ذهب (من: للجنس)؛ وكتاب الطالب (لام الاختصاص: للطالب)."},{"question":"ماذا يحذف من المضاف؟","options":["التنوين ونون المثنى وجمع المذكر السالم","لا شيء","الكسرة","الألف واللام"],"answer":0,"explanation":"قلم أستاذ (حذف التنوين)؛ مهندسا البيت (حذفت نون المثنى)؛ مهندسو المشروع (حذفت نون الجمع)."},{"question":"أي الأسماء لا تقع مضافة؟","options":["الضمائر وأسماء الإشارة والموصولات وأسماء الاستفهام والشرط إلا أي","كلها تضاف","الأعلام","النكرات"],"answer":0,"explanation":"لأنها معارف محضة لا تكتسب شيئًا بالإضافة؛ وأي من أسماء الشرط مستثناة: أي طالب نجح."},{"question":"أعرب «المدرسة» في «مسرح المدرسة»:","options":["مضاف إليه مجرور بالكسرة","نعت","مجرور بحرف","فاعل"],"answer":0,"explanation":"مسرح مضاف والمدرسة مضاف إليه مجرور بالكسرة؛ واسمان لشيء واحد: مسرح خاص بالمدرسة."}]},{"body":["أسماء لا تقع إلا مضافة: ومنها عند ولدى ولدن وبين وكلا وكلتا وسوى وذو وذات: جلست عند زيد: عند ظرف مكان مضاف وزيد مضاف إليه. وجلست عندك: عند مضاف والكاف مضاف إليه. «ذو علم»: ذو مضاف. «كلا الطالبين»: كلا مضاف (مثنى) والطالبين مضاف إليه.","أسماء يجوز حذف مضافها إليها: قبل وبعد ودون وفوق وأمام وخلف ووراء ويمين وشمال وتلقاء وتجاه وكل وبعض وغير وأي: تعال قبل الظهر؛ تعال قبله؛ تعال قبلًا (حذف المضاف إليه ونصب قبل على الظرفية). صليت خلف الإمام؛ صليت خلفه؛ صليت خلفًا. كل الطلاب نجحوا؛ كلهم نجحوا؛ كلٌّ نجحوا.","مسألة الضمائر: كل ضمير اتصل باسم فهما مضاف ومضاف إليه في محل جر: كتابي: كتاب مضاف والياء مضاف إليه في محل جر مبني على السكون. كتابك وكتابه وكتابهم: الكاف والهاء مضاف إليه. كيدهم وصدرك ووزرك وظهرك وذكرك وربك.","فكل مضاف إليه مجرور ولو كان ضميرًا مبنيًّا: كتابي: الياء في محل جر؛ وكتابنا: النون في محل جر. فضابط: الضمير بعد اسم = مضاف إليه.","تدريبات الكتاب: «استخرج الاسم المجرور وأعربه»: بالعلم نفع...: العلم مجرور بالباء. «وما فضله»... «الأمثال لكم»: الكاف مضاف إليه. «على الداعي أن يصبر على المدعوين»: الداعي مجرور بعلى بالكسرة المقدرة؛ والمدعوين مجرور بعلى بالياء.","«مثل بكلمة مهندس»: مفرد مجرور بحرف جر: سلمت على مهندسٍ. مثنى مجرور بالإضافة: سلمت على مهندسَي المشروعِ. جمع مجرور بحرف جر: سلمت على مهندسينَ.","الخلاصة: من الأسماء ما لا يقع إلا مضافًا (عند وذو وكلا)؛ ومنها ما يجوز حذف مضافه إليه (قبل وبعد وكل)؛ وكل ضمير بعد اسم مضاف إليه في محل جر؛ والمضاف إليه مجرور أبدًا."],"examples":["عند وذو وكلا لا تقع إلا مضافة","قبل وبعد يحذف مضافهما إليها","كل ضمير بعد اسم مضاف إليه","كتابي: الياء في محل جر","مهندسا المشروع: مثنى بلا نون","المضاف إليه مجرور أبدًا"],"questions":[{"question":"اذكر أسماء لا تقع إلا مضافة:","options":["عند ولدى ولدن وبين وكلا وكلتا وسوى وذو وذات","قلم وباب","ضرب وقام","من وإلى"],"answer":0,"explanation":"جلست عند زيد: عند مضاف دائمًا؛ وذو علم وكلا الطالبين: كلها أسماء لا تفارق الإضافة."},{"question":"ما حكم قبل وبعد ونحوهما؟","options":["يجوز حذف مضافها إليها ونصبها على الظرفية","لا تحذف","أفعال","حروف"],"answer":0,"explanation":"تعال قبل الظهر / قبله / قبلًا: قبل ظرف مضاف يجوز حذف مضافه إليه فينصب بالفتحة مفردًا."},{"question":"أعرب الياء في «كتابي»:","options":["ضمير متصل مبني في محل جر مضاف إليه","فاعل","مفعول به","نعت"],"answer":0,"explanation":"كل ضمير اتصل باسم: مضاف إليه في محل جر: كتاب مضاف والياء مضاف إليه مبني على السكون في محل جر."},{"question":"أعرب «مهندسي» في «سلمت على مهندسي المشروع»:","options":["اسم مجرور بعلى وعلامة جره الياء لأنه مثنى مضاف حذفت نونه","بالكسرة","مرفوع","منصوب"],"answer":0,"explanation":"المثنى يجر بالياء: مهندسي؛ وحذفت النون بالإضافة؛ والمشروع مضاف إليه مجرور بالكسرة."},{"question":"أعرب الكاف في «ربك»:","options":["ضمير متصل مبني على الفتح في محل جر مضاف إليه","فاعل","نعت","حال"],"answer":0,"explanation":"رب اسم مضاف؛ والكاف ضمير المخاطب مضاف إليه في محل جر؛ ومن أمثلة الكتاب: صدرك ووزرك وظهرك وذكرك وربك."}]}]},{"id":"wahi-sharh-088","title":"التوابع: العطف والتوكيد","section":"شرح الكتاب: باب التوابع: المعطوف والتوكيد مفصلًا","order":88,"segments":[{"body":["التوابع: وهي ألفاظ تتبع ما قبلها في الإعراب رفعًا ونصبًا وجرًّا وجزمًا، وهي أربعة: النعت والمعطوف والتوكيد والبدل. وقد سبق شرح النعت مع الحال.","باب المعطوف: وهو اللاحق بحرف من حروف العطف. حروف العطف تسعة: ١- الواو: وهي لمطلق الجمع: جاء الولد وأبوه؛ والقرآن والتوراة والإنجيل. ٢- والفاء: وهي للترتيب بلا مهلة: جاء الولد فأبوه (فأبوه مباشرة). ٣- وثم: للترتيب مع مهلة: جاء الولد ثم أبوه (بعد مدة). ٤- وأو: وهي لاختيار أحد الشيئين: تزوج هندًا أو أختها؛ سجل في كلية الشريعة أو كلية الدعوة؛ أو للإباحة: كل تفاحة أو تينًا؛ ادرس نحوًا أو صرفًا.","٥- وأم: وهي للتعيين: أمحمد جاء أم خالد؟ سواء أقمت أم قعدت. ٦- وحتى: وهي للغاية: جاء الحجاج حتى المشاة؛ والمعلم الخير يستغفر له كل شيء حتى الحيتان في البحار.","و٧- لا و٨- لكن و٩- بل: من حروف العطف أيضًا: جاء الطلاب لا المعلم... جاء خالد لكن محمد... ما جاء علي بل أخوه.","حكمه: يعرب المعطوف معطوفًا على ما قبله ويتبعه في الإعراب رفعًا ونصبًا وجرًّا وجزمًا: «سلمت على محمد وخالدٍ»: خالد معطوف على محمد مجرور بالكسرة. «وأكرمت النحو والصرفَ»: الصرف معطوف منصوب بالفتحة. «وسهل النحو والصرفُ»: الصرف معطوف مرفوع بالضمة. «محمد لم يسجد ويركعْ لغير الله»: يركع فعل مضارع معطوف على يسجد مجزوم بالسكون.","والواو حرف عطف مبني على الفتح لا محل له من الإعراب؛ وكذلك سائر الحروف: مبنية لا محل لها.","الخلاصة: المعطوف تابع يلحق بحرف من تسعة أحرف ويتبع المعطوف عليه في إعرابه الأربعة: رفعًا ونصبًا وجرًّا وجزمًا؛ ولكل حرف معناه من الجمع المطلق إلى الترتيب والتعيين والغاية."],"examples":["التوابع أربعة تتبع ما قبلها","حروف العطف تسعة","الواو مطلق الجمع والفاء بلا مهلة وثم مع مهلة","أو للاختيار وأم للتعيين وحتى للغاية","لا ولكن وبل من حروف العطف","يتبع رفعًا ونصبًا وجرًّا وجزمًا"],"questions":[{"question":"ما التوابع وما أقسامها؟","options":["ألفاظ تتبع ما قبلها إعرابًا؛ أربعة: النعت والمعطوف والتوكيد والبدل","ثلاثة","خمسة","واحد"],"answer":0,"explanation":"التوابع أربعة تتبع ما قبلها في الرفع والنصب والجر والجزم: النعت والمعطوف والتوكيد والبدل."},{"question":"ما معنى الفاء وثم؟","options":["الفاء للترتيب بلا مهلة وثم للترتيب مع مهلة","لا فرق","الفاء للاختيار","ثم للغاية"],"answer":0,"explanation":"جاء الولد فأبوه: عقب بلا فاصل؛ وجاء الولد ثم أبوه: بعد مهلة؛ فالفاء أسرع ترتيبًا."},{"question":"ما معنى أو وأم وحتى في العطف؟","options":["أو لاختيار أحد الشيئين أو الإباحة وأم للتعيين وحتى للغاية","كلها للجمع","للنفي","للاستثناء"],"answer":0,"explanation":"تزوج هندًا أو أختها؛ أمحمد جاء أم خالد؟ جاء الحجاج حتى المشاة (وصل العطف إلى نهايته)."},{"question":"أعرب «خالد» في «سلمت على محمد وخالد»:","options":["معطوف على محمد مجرور بالكسرة","مفعول به","فاعل","نعت"],"answer":0,"explanation":"خالد لحق بالواو فهو معطوف يتبع محمدًا في الجر: معطوف مجرور بالكسرة؛ والواو حرف عطف لا محل له."},{"question":"أعرب «يركع» في «لم يسجد ويركع»:","options":["فعل مضارع معطوف على يسجد مجزوم بالسكون","منصوب","مرفوع","ماضٍ"],"answer":0,"explanation":"العطف يجري في الجزم أيضًا: يركع معطوف على المجزوم بلم: مجزوم بالسكون."}]},{"body":["باب التوكيد. نوعان: لفظي ومعنوي. الأول: التوكيد اللفظي: وهو تكرار اللفظ المراد توكيده: «وسلّمت على الأمير الأمير»: الثاني توكيد لفظي مجرور. «وتخرجت تخرجت»: توكيد لفظي للفعل السابق. «جاء السيل جاء السيل». «لا لا تذهب».","النوع الآخر: التوكيد المعنوي: وهو بألفاظ مخصوصة: ١- النفس والعين مضافين لضمير المؤكد، ويؤكد بهما المفرد والمثنى والجمع: جاء الطالب نفسه؛ والطالبة عينها؛ وجاء الطالبان أعينهما والطالبتان أنفسهما؛ وجاء الطلاب أنفسهم والطالبات أعينهن.","٢- وكلا وكلتا مضافين لضمير المؤكد المثنى: جاء الرجلان كلاهما والمرأتان كلتاهما. ٣- وكل وجميع مضافين لضمير جمع أو مفرد له أجزاء: جاء الطلاب كلهم؛ قرأت الكتاب كله؛ وجاء الطلاب جميعهم؛ قرأت الكتاب جميعه.","٤- وأجمع وفروعه: ويؤكد بها ما له أجزاء، والأكثر كونه بعد كل: جاء الجيش كله أجمع؛ والكتيبة كلها جمعاء؛ والجنود كلهم أجمعون؛ والممرضات كلهن مجمعات... «ترك الكتاب أجمع»؛ وجاء الأطباء أجمعون.","إعرابه: «نجح معن نفسه»: نفس توكيد معنوي مرفوع بالضمة مضاف والهاء مضاف إليه. «وأكرمت محمدًا نفسه»: نفس توكيد معنوي منصوب بالفتحة. «وسلمت على محمد نفسه»: نفس توكيد معنوي مجرور بالكسرة.","فائدة التوكيد: تقرير المؤكد ورفع توهم غير الظاهر عنه إما باحتمال تجوز أو سهو: جاء الأمير نفسه (لا رسوله ولا نائبه)؛ فالتوكيد يقطع الاحتمال.","حكمه: يجعل التوكيد في حكم المؤكد في الإعراب: رفعًا: جاء محمد نفسه والطلاب أجمعون. ونصبًا: أكرمت محمدًا نفسه والطلاب أجمعين. وجرًّا: سلمت على محمد نفسه والطلاب أجمعين.","الخلاصة: التوكيد لفظي (بتكرار اللفظ) ومعنوي (بالنفس والعين وكلا وكل وأجمع وفروعه مضافة لضمير المؤكد)؛ يتبع المؤكد إعرابًا؛ وفائدته تقرير الحكم ورفع الاحتمال."],"examples":["لفظي: تكرار اللفظ","معنوي: النفس والعين وكلا وكل وأجمع","جاء الطالبان كلاهما","قرأت الكتاب كله","جاء الجيش كله أجمع","يتبع المؤكد ويقطع الاحتمال"],"questions":[{"question":"ما نوعا التوكيد وما ضابطهما؟","options":["لفظي بتكرار اللفظ ومعنوي بألفاظ مخصوصة مضافة لضمير المؤكد","أصلي وفرعي","جلي وخفي","صريح وضمني"],"answer":0,"explanation":"سلمت على الأمير الأمير: لفظي؛ وجاء الأمير نفسه: معنوي بالنفس مضافة لضمير المؤكد."},{"question":"بم يؤكد التوكيد المعنوي؟","options":["النفس والعين وكلا وكلتا وكل وجميع وأجمع وفروعه","بالحروف","بالأفعال","بالأعداد"],"answer":0,"explanation":"النفس والعين للجميع؛ وكلا وكلتا للمثنى؛ وكل وجميع وأجمع وأمثالها للجموع وذوات الأجزاء."},{"question":"أعرب «نفسه» في «أكرمت محمدًا نفسه»:","options":["نفس توكيد معنوي منصوب بالفتحة مضاف والهاء مضاف إليه","نعت","بدل","مفعول به"],"answer":0,"explanation":"يتبع التوكيد مؤكده: محمد منصوب فنفس منصوبة بالفتحة مضافة؛ والهاء ضمير مضاف إليه."},{"question":"ما فائدة التوكيد؟","options":["تقرير المؤكد ورفع توهم المجاز أو السهو","الزخرفة فقط","النفي","الاستفهام"],"answer":0,"explanation":"جاء الأمير نفسه: تقرير أنه الأمير بذاته لا رسوله؛ فالتوكيد يقطع احتمال التجوز أو السهو."},{"question":"أعرب «أجمعون» في «جاء الأطباء أجمعون»:","options":["توكيد معنوي مرفوع بالواو","فاعل","نعت","حال"],"answer":0,"explanation":"أجمع وفروعه توكد ما له أجزاء: أجمعون توكيد معنوي مرفوع بالواو لأنه جمع مذكر سالم تبع للأطباء."}]}]},{"id":"wahi-sharh-089","title":"البدل وخلاصة إعراب الاسم","section":"شرح الكتاب: باب البدل وخلاصة إعراب الاسم مفصلًا","order":89,"segments":[{"body":["باب البدل. تعريفه: هو التابع المقصود بالحكم: أكلت التفاحة نصفها: فالمقصود بالأكل نصف التفاحة لا التفاحة كلها؛ فيكون (نصفها) بدلًا من التفاحة، والتفاحة مبدل منه؛ ويصح حذف المبدل منه: أكلت نصف التفاحة.","أنواعه أربعة: ١- بدل كل من كل (البدل المطابق): ويكون حين تكون العلاقة بين البدل والمبدل منه علاقة كلية: جاء أخي وائل: وائل بدل كل من أخي مرفوع بالضمة؛ ورضي الله عن علي أبي الحسن: أبو بدل مجرور بالياء.","ومن بدل الكل أعلام الشيء الواحد إذا تتابعت فالثاني بدل: رضي الله عن الصديق أبي بكر: أبو بدل... وأكرمت أبا خالد ماهرًا: ماهر بدل. ومنه الموصوف إذا تأخر عن صفته: نجح المجتهد ماهر: ماهر بدل... وزرت عاصمة العراق بغداد: بغداد بدل. ومنه الاسم بعد اسم الإشارة إذا جاز حذف اسم الإشارة: جاء هذا الرجل: الرجل بدل من هذا... أكرمت هؤلاء الرجال؛ ومررت بهذه المرأة.","٢- وبدل بعض من كل (البدل الجزئي): ويكون حين تكون العلاقة جزئية: أعجبني وائل وجهه: وجه بدل بعض من وائل مرفوع بالضمة؛ ونظفت المسجد فناءه: فناء بدل بعض من المسجد منصوب بالفتحة؛ وقرأت الكتاب مقدمته؛ وطاب المؤمن قلبه؛ وأعجبتني المدينة مبانيها وأنهارها؛ وانكسر ماهر قدمه.","٣- وبدل اشتمال: ويكون حين لا تكون العلاقة كلية ولا جزئية بل تضمن وارتباط: أعجبني وائل خلقه: خلق بدل اشتمال مرفوع بالضمة؛ وختمت المرأة حجابها: حجاب بدل اشتمال منصوب بالفتحة؛ وأعجبني الولد ذكاؤه؛ وبهرني ماهر علمه.","٤- وبدل الغلط: وهو ما ذكر مصححًا لما قبله من غلط أو سهو: وأفضل الصحابة عمر أبو بكر: أبو بكر بدل غلط من عمر مرفوع بالواو؛ وعندي خمسون ستون قلمًا: ستون بدل غلط من خمسين.","حكمه: البدل يتبع المبدل منه في الإعراب: رفعًا: قال أبو الحسن علي رضي الله عنه (علي بدل مرفوع). ونصبًا: أحب أبا الحسن عليًّا. وجرًّا: رضي الله عن أبي الحسن عليٍّ. وجزمًا: من يأت يطلب خدمة أساعده.","مسألة: من البدل بدل التفصيل: فإن ذكرت كل المفصل كان بدل كل: جاء إخوتي ماهر وخالد وفهد وسمير (إن كانوا أربعة)؛ وإن ذكرت بعضهم كان بدل بعض: جاء إخوتي ماهر وخالد وفهد؛ وإن لم يكن البدل كل المبدل منه ولا بعضه فهو بدل اشتمال: إن المدرسة طلابها ومعلميها حاضرون.","وملخص: المعطوف والتوكيد اللفظي والبدل في حكم تابع في الاسم؛ وأما النعت والتوكيد المعنوي فلا يقعان في الفعل... والعطف يقع في الأفعال: لا تُهمل وتقصر في دروسك: تقصر فعل مضارع معطوف مجزوم."],"examples":["البدل: التابع المقصود بالحكم","أربعة: كل من كل وبعض من كل واشتمال وغلط","جاء أخي وائل: مطابق","أعجبني وائل وجهه: جزئي؛ خلقه: اشتمال","أفضل الصحابة عمر أبو بكر: غلط","البدل يتبع مبدله رفعًا ونصبًا وجرًّا وجزمًا"],"questions":[{"question":"ما البدل وما أنواعه؟","options":["التابع المقصود بالحكم؛ أربعة: كل من كل وبعض من كل واشتمال وغلط","نوعان","ثلاثة","خمسة"],"answer":0,"explanation":"أكلت التفاحة نصفها: المقصود نصفها؛ والأنواع أربعة بحسب العلاقة: كلية أو جزئية أو تضمن أو تصحيح."},{"question":"ما بدل الكل وما أمثلته؟","options":["ما عين المبدل منه؛ الأعلام المتتابعة والموصوف بعد صفته والاسم بعد الإشارة","الجزء","الغلط","الاشتمال"],"answer":0,"explanation":"جاء أخي وائل: وائل هو الأخ؛ ورضي الله عن الصديق أبي بكر؛ وجاء هذا الرجل: كلها بدل كل."},{"question":"ما الفرق بين بدل البعض وبدل الاشتمال؟","options":["البعض جزء مادي من الكل والاشتمال علاقة تضمن لا جزئية","لا فرق","الاشتمال جزء","البعض أعم"],"answer":0,"explanation":"أعجبني وائل وجهه: الوجه جزء؛ وأعجبني وائل خلقه: الخلق ليس جزءًا ماديًّا بل ملتبس به: اشتمال."},{"question":"أعرب «حجابها» في «ختمت المرأة حجابها»:","options":["بدل اشتمال من المرأة منصوب بالفتحة","مفعول به","نعت","حال"],"answer":0,"explanation":"الحجاب ليس جزءًا من المرأة ولا عينها لكنه ملتبس بها: بدل اشتمال منصوب بالفتحة تبع لمفعولية المرأة."},{"question":"أعرب «ستون» في «عندي خمسون ستون قلمًا»:","options":["بدل غلط من خمسون","معطوف","نعت","مفعول به"],"answer":0,"explanation":"ذكر المتكلم خمسون ثم صحح بستون: بدل غلط يتبع المبدل منه في الإعراب؛ وقلم تمييز."}]},{"body":["خلاصة إعراب الاسم من الكتاب: اتضح مما سبق أن الاسم يدخله الرفع والنصب والجر؛ وأن الاسم إذا كان معربًا قيل: مرفوع ومنصوب ومجرور، وإذا كان مبنيًّا قيل: في محل رفع أو نصب أو جر.","وأن الاسم يرفع في سبعة مواضع: ١- الفاعل: نزل القرآن من الله. ٢- ونائب الفاعل: قرئ القرآن. ٣- والمبتدأ وخبره: القرآن نور. ٤- واسم كان وأخواتها: صار القرآن نورًا. ٥- وخبر إن وأخواتها: إن القرآن نور. ٦- والتابع للمرفوع.","ويجر في ثلاثة مواضع: ١- الاسم المسبوق بحرف جر: صلى الله على محمدٍ. ٢- والاسم إذا كان مضافًا إليه: أبو القاسم رسول اللهِ. ٣- والتابع للمجرور: رضي الله عن الخلفاء الراشدين أجمعين أبي بكر وعمر وعثمان وعليٍّ.","وينصب في مواضع: منها ١- المفاعيل الخمسة: المفعول به: أكرم والديك؛ والمفعول فيه: انتظرتك اليوم أمام المسجد؛ والمفعول له: ارحم المساكين رجاء رحمة الله؛ والمفعول معه والمفعول المطلق. ومنها ٢- الحال و٣- التمييز و٤- المستثنى و٥- المنادى و٦- التابع للمنصوب.","وكذلك خبر كان وأخواتها منصوب: كان العلم نافعًا؛ واسم إن وأخواتها منصوب: إن العلم نافع؛ واسم لا النافية للجنس منصوب: لا كريم مذموم.","فهذه الخلاصة تجمع أبواب الاسم كلها في لوحة واحدة: سبعة مواضع رفع وثلاثة جر ومواضع النصب الكثيرة؛ وهي مفتاح إعراب أي اسم في أي نص.","تدريب على الخلاصة: «نزل القرآن من الله هدى للناس»: القرآن فاعل مرفوع؛ من حرف جر والله مجرور بها؛ هدى حال أو مفعول به ثانٍ... «هدى للناس»: هدى مفعول به ثان أو حال منصوب بالفتحة المقدرة؛ وللناس جار ومجرور."],"examples":["الاسم: رفع ونصب وجر لا جزم","المعرب مرفوع والمبني في محل رفع","سبعة مواضع للرفع","ثلاثة مواضع للجر","مواضع النصب: المفاعيل والحال والتمييز والمستثنى والمنادى والتابع","الخلاصة مفتاح الإعراب"],"questions":[{"question":"بم يعرب الاسم وكم مواضع رفعه؟","options":["بالرفع والنصب والجر؛ ويرفع في سبعة مواضع","ثلاثة","خمسة","عشرة"],"answer":0,"explanation":"الفاعل ونائبه والمبتدأ وخبره واسم كان وخبر إن والتابع للمرفوع: سبعة مواضع يرفع فيها الاسم."},{"question":"في كم موضع يجر الاسم؟","options":["ثلاثة: بعد حرف الجر وإضافة وتابع لمجرور","سبعة","خمسة","واحد"],"answer":0,"explanation":"صلى الله على محمد (حرف)؛ ورسول الله (إضافة)؛ ورضي الله عن علي ولده (تابع لمجرور)."},{"question":"ما الفرق بين قولنا مرفوع وفي محل رفع؟","options":["مرفوع للمعرب وفي محل رفع للمبني","لا فرق","بالعكس","للجمع فقط"],"answer":0,"explanation":"الاسم المعرب يقال مرفوع ومنصوب ومجرور؛ والمبني لا تظهر عليه العلامة فيقال في محل رفع أو نصب أو جر."},{"question":"اذكر خمسة من منصوبات الاسم:","options":["المفاعيل الخمسة والحال والتمييز والمستثنى والمنادى وخبر كان واسم إن واسم لا","الفاعل والمبتدأ","المضاف إليه","لا شيء"],"answer":0,"explanation":"مواضع النصب كثيرة: المفاعيل الخمسة والحال والتمييز والمستثنى والمنادى والتابع للمنصوب وخبر كان واسم إن واسم لا."},{"question":"أعرب «هدى» في «نزل القرآن من الله هدى للناس»:","options":["حال منصوب بالفتحة المقدرة أو مفعول به ثان","فاعل","مبتدأ","مضاف إليه"],"answer":0,"explanation":"نزل بمعنى أنزل متعدٍّ: القرآن فاعل وهدى مفعول به ثانٍ منصوب بالفتحة المقدرة منع من ظهورها التعذر؛ أو حال."}]}]},{"id":"wahi-sharh-090","title":"إعراب المضارع وخاتمة الكتاب","section":"شرح الكتاب: إعراب الفعل المضارع مفصلًا وخاتمة الكتاب","order":90,"segments":[{"body":["القسم الرابع: إعراب الفعل المضارع. الفعل المضارع يدخله الرفع والنصب والجزم دون الجر: فيرفع وينصب ويجزم؛ ينصب إذا سبق بناصب ويجزم إذا سبق بجازم ويرفع إذا لم يسبق بناصب ولا جازم: المسلم لن يعبدَ إلا الله: مضارع منصوب بلن؛ والمسلم لم يعبدْ إلا الله: مجزوم بلم؛ والمسلم يعبدُ الله: مرفوع إذ لم يسبق بناصب ولا جازم.","نواصب المضارع عشرة: ١- أن: حرف مصدري ناصب: «إن الدين عند الله الإسلام... أن تصوموا»: أن مبنية على السكون لا محل لها؛ تصوموا مضارع منصوب بحذف النون وواو الجماعة فاعل. ٢- ولن: حرف نفي ونصب: لن أهملَ؛ لن تسافروا؛ لن أخذل أمتي ولن أخذل عدوي.","٣- وكي: حرف تعليل: أتعلم كي أعلمَ؛ سافروا كي تستفيدوا. ٤- وإذن: حرف جواب ونصب: إذن تنجحَ (لمن قال سوف أجتهد)؛ إذن ننتصرَ. ٥- ولام العلة (لام كي): حرف تعليل: سافرت لأتعلم؛ سافروا لتستفيدوا. ٦- ولام الجحود: وهي لام تقع بعد ما كان ولم يكن: ما كان قيس ليسافرَ؛ لم يكن أخوك ليتأخرَ.","٧- وحتى: حرف تعليل وغاية: جئت حتى أتعلم؛ صم حتى تغيبَ الشمس. ٨- وأو التي بمعنى إلى أن أو بمعنى إلا أن: سأجتهد أو أنجحَ (إلى أن)؛ وسأفتح الباب أو ينكسرَ (إلا أن)؛ سأضربك أو تعترفَ. ٩- وفاء السببية و١٠- وواو المعية إذا وقعتا بعد نفي أو طلب: اجتهد فتنجحَ؛ لم تجتهد تنجحَ؛ لا تترك الصلاة وترجوَ راحة البال؛ ليتني غني فأتصدقَ.","مسألة: الأحرف الأربعة الأولى (أن ولن وكي وإذن) تنصب المضارع بنفسها؛ والأحرف الستة الباقية تنصب المضارع بعدها بأن مضمرة محذوفة: جئت حتى أتعلم أي حتى أن أتعلم.","جوازم المضارع خمسة: نوعان: أحدهما ما يجزم فعلًا واحدًا وهي أربعة أحرف: ١- لم: حرف نفي وجزم: لم يكن النحو صعبًا. ٢- ولما: حرف نفي للأمر المتوقع حدوثه: لما أذهب بعد؛ وجاء الوفد إلى الكلية ولما يدخلوا القاعة. ٣- ولا الناهية: حرف نهي: لا تتأخر عن الصلاة ولا تركض في المسجد؛ لا تقطعوا أرحامكم. ٤- ولام الأمر: لتفتح بيتك ولتكرم ضيوفك؛ لتسمع مني قبل أن تحكم.","إعرابها: لم يذهبْ: مضارع مجزوم بالسكون؛ لم يذهبوا: مجزوم بحذف النون؛ ولا تذمَّ: مجزوم بالسكون؛ ولا تلغوا: مجزوم بحذف النون؛ ولتذهبْ: مجزوم بالسكون (لام الأمر)؛ ولتتقوا: مجزوم بحذف النون.","والنوع الآخر ما يجزم فعلين: الأول يسمى فعل الشرط والثاني يسمى جواب الشرط؛ وهي أدوات الشرط الجازمة: اثنتا عشرة أداة: ١- إن و٢- إذما: إن تجتهد تنجح. ٣- ومن للعاقل: من يجتهد ينجح. ٤- وما و٥- مهما لغير العاقل: ما تعمل يكتب؛ مهما تعمل يكتب. ٦- ومتى و٧- أيان للزمان: متى تسافر أسافر معك؛ أيان تعمل توفق. ٨- وأين و٩- أنى و١٠- حيثما للمكان: أين تسكن أسكن بجوارك؛ حيثما تمم أزرك. ١١- وأي: وتكون بحسب ما تضاف إليه: أي طالب يجتهد ينجح (مبتدأ)؛ أي كتاب تقرأ أقرأ (مفعول به)؛ أي يوم تصم أصم (ظرف زمان). ١٢- وإذما... وقد تقدمت مع إن.","إعراب الشرط: إن تأتِ أكرمْك: تأت: فعل الشرط مضارع مجزوم بحذف حرف العلة؛ وأكرم: جواب الشرط مضارع مجزوم بالسكون. من يدعُ يسمعه الله: يدع فعل الشرط مجزوم بحذف حرف العلة؛ ويسمعه جواب الشرط مجزوم بالسكون.","رفع المضارع: الفعل المضارع ينصب في عشرة مواضع ويجزم في خمسة مواضع ويرفع فيما سوى ذلك: يعمل الموظف بجد؛ والموظف يعمل: مضارع مرفوع؛ وأعوذ بالله: أعوذ مضارع مرفوع بالضمة؛ ويبارك الله في عملنا: مرفوع."],"examples":["المضارع: رفع ونصب وجزم لا جر","النواصب عشرة: أن لن كي إذن لام العلة لام الجحود حتى أو الفاء والواو بعد نفي أو طلب","أربعة تنصب بنفسها والستة بأن مضمرة","الجوازم خمسة: لم ولما ولا الناهية ولام الأمر وأدوات الشرط","الشرط يجزم فعلين","يرفع فيما سوى النصب والجزم"],"questions":[{"question":"بم يعرب الفعل المضارع؟","options":["بالرفع والنصب والجزم دون الجر","بالجر","بالبناء فقط","بالتنوين"],"answer":0,"explanation":"المضارع معرب يرفع وينصب ويجزم: يعبد مرفوع؛ ولن يعبد منصوب؛ ولم يعبد مجزوم."},{"question":"عدد نواصب المضارع:","options":["أن ولن وكي وإذن ولام العلة ولام الجحود وحتى وأو بمعنييها وفاء السببية وواو المعية بعد نفي أو طلب","خمسة","ثلاثة","عشرون"],"answer":0,"explanation":"عشرة مواضع للنصب؛ الأربعة الأولى تنصب بنفسها والستة الباقية بأن مضمرة محذوفة."},{"question":"ما لام الجحود؟","options":["لام تعليل تقع بعد ما كان ولم يكن تنصب المضارع","لام الأمر","لام الابتداء","لام التوكيد"],"answer":0,"explanation":"ما كان قيس ليسافر؛ ولم يكن أخوك ليتأخر: اللام بعد النفي الجاحد تنصب المضارع."},{"question":"عدد جوازم المضارع:","options":["لم ولما ولا الناهية ولام الأمر وأدوات الشرط الجازمة","عشرة","ثلاثة","سبعة"],"answer":0,"explanation":"خمسة: أربعة تجزم فعلًا واحدًا وأدوات الشرط تجزم فعلين: فعل الشرط وجوابه."},{"question":"أعرب «تأت» و«أكرمك» في «إن تأت أكرمك»:","options":["تأت فعل الشرط مجزوم بحذف حرف العلة وأكرم جواب الشرط مجزوم بالسكون","مرفوعان","منصوبان","ماضيان"],"answer":0,"explanation":"إن من أدوات الشرط الجازمة: تجزم فعلين: تأتِ مجزوم بحذف الياء (حرف العلة)؛ وأكرم مجزوم بالسكون."}]},{"body":["تدريبات الكتاب على المضارع: أدخل لن ولم: الولد يخشى المطر ويفتح المظلة → الولد لن يخشى المطر ولن يفتح المظلة (منصوبان بلن)؛ الولد لم يخشَ المطر ولم يفتح المظلة (مجزومان بلم بحذف حرف العلة في يخشى). وأنت تخشين وتفتحين → لن تخشي ولم تخشي (بحذف النون: تخشين أصلها من الأفعال الخمسة).","تذكير بالأفعال الخمسة: كل مضارع اتصلت به واو الجماعة أو ألف الاثنين أو ياء المخاطبة: ترفع بثبوت النون وتنصب وتجزم بحذفها: لن تصوموا: منصوب بحذف النون؛ ولم يذهبوا: مجزوم بحذف النون.","خاتمة النحو الصغير: والحمد لله الذي يهدي للصالحات، والصلاة والسلام على نبينا محمد وعلى آله وأصحابه أجمعين. أتم المؤلف شرحه في آخر يوم من شهر رمضان المبارك سنة أربع وأربعين وأربعمائة وألف من هجرة المصطفى عليه أفضل الصلاة وأكمل السلام (١٤٤٤هـ)، وسماه شرح النحو الصغير، والحمد لله حمدًا كثيرًا أولًا وآخرًا.","ثم الإعراب التطبيقي: وهو روح النحو وتطبيق وتمرين لجميع أبوابه، وفيه يتمرن الطالب على: ١- تحليل الجمل إلى كلمات، ٢- ثم معرفة الحكم النحوي لكل كلمة، ٣- ثم إعرابها. وأنت بعد أن سلكت جادة الشرح إلى آخره صرت بإذن الله أهلًا للإعراب.","نموذج منه: إعراب الاستعاذة «أعوذ بالله من الشيطان الرجيم»: أعوذ: فعل مضارع مرفوع بالضمة وفاعله مستتر تقديره أنا؛ بالله: الباء حرف جر والله اسم مجرور بالباء؛ من: حرف جر؛ الشيطان: اسم مجرور بمن؛ الرجيم: نعت مجرور.","وبهذا تم شرح الكتاب كله: نظمًا وفتحًا مختصرًا وشرحًا مفصلًا وتطبيقًا؛ فالحمد لله الذي بنعمته تتم الصالحات."],"examples":["أدخل لن فانصب ولم فاجزم","الأفعال الخمسة: رفع بثبوت النون","أتم المؤلف الشرح في رمضان ١٤٤٤هـ","الإعراب التطبيقي: تحليل ثم حكم ثم إعراب","أعوذ بالله من الشيطان الرجيم","تم الكتاب نظمًا وشرحًا وتطبيقًا"],"questions":[{"question":"كيف تدخل لن ولم على «يخشى»؟","options":["لن يخشى (منصوب بالفتحة) ولم يخشَ (مجزوم بحذف حرف العلة)","كلاهما رفع","كلاهما جر","لن تجزم"],"answer":0,"explanation":"لن ناصبة: لن يخشى منصوب وعلامة نصبه الفتحة؛ ولم جازمة: لم يخشَ مجزوم بحذف الألف حرف العلة."},{"question":"ما حكم الأفعال الخمسة مع النواصب والجوازم؟","options":["ترفع بثبوت النون وتنصب وتجزم بحذفها","تبنى","تجر","لا تتغير"],"answer":0,"explanation":"لن تصوموا: منصوب بحذف النون؛ ولم يذهبوا: مجزوم بحذف النون؛ ويصومون: مرفوع بثبوت النون."},{"question":"متى أتم المؤلف شرح النحو الصغير؟","options":["في آخر يوم من رمضان سنة ١٤٤٤هـ","١٤٤٠هـ","١٤٥٠هـ","لم يذكر"],"answer":0,"explanation":"جاء في الخاتمة: آخر يوم من شهر رمضان المبارك سنة أربع وأربعين وأربعمائة وألف من الهجرة."},{"question":"ما خطوات الإعراب التطبيقي الثلاث؟","options":["تحليل الجمل إلى كلمات ثم معرفة حكم كل كلمة ثم إعرابها","حفظ المتن","الترجمة","الإملاء"],"answer":0,"explanation":"الإعراب روح النحو: تحلل الجملة كلمات، ثم تعرف الحكم النحوي لكل كلمة، ثم تعربها واحدة واحدة."},{"question":"أعرب «الرجيم» في «أعوذ بالله من الشيطان الرجيم»:","options":["نعت للشيطان مجرور بالكسرة","حال","بدل","تمييز"],"answer":0,"explanation":"الشيطان اسم مجرور بمن؛ والرجيم صفة له: نعت مجرور بالكسرة تبع له في الجر."}]}]}]};
